// ==========================================
// BANCO DE QUESTÕES OFICIAL (ESTRUTURADO POR SÉRIE)
// ==========================================
const banco = {
    // ------------------------------------------
    // 6º ANO
    // ------------------------------------------
    "6": {
        "Matemática": [
            // ==================== FÁCEIS (20 QUESTÕES) ====================
              { id: "6ANO-MAT-F01", p: "No sistema de numeração decimal, qual é o valor posicional do algarismo 7 no número 3.742?", o: [{ t: "700", c: true }, { t: "70", c: false }, { t: "7", c: false }, { t: "7.000", c: false }], pts: 2, exp: "O algarismo 7 ocupa a ordem das centenas, portanto seu valor posicional é 700." },
              { id: "6ANO-MAT-F02", p: "Qual das alternativas apresenta um número que é par e múltiplo de 2?", o: [{ t: "15", c: false }, { t: "28", c: true }, { t: "33", c: false }, { t: "41", c: false }], pts: 2, exp: "Números pares terminam em 0, 2, 4, 6 ou 8. O número 28 é par e divisível por 2." },
              { id: "6ANO-MAT-F03", p: "Qual é o único número primo que é par?", o: [{ t: "0", c: false }, { t: "1", c: false }, { t: "2", c: true }, { t: "4", c: false }], pts: 2, exp: "O número 2 possui exatamente dois divisores (1 e 2), sendo o único primo par." },
              { id: "6ANO-MAT-F04", p: "Qual é o resultado da adição de 1.250 com 850?", o: [{ t: "2.000", c: false }, { t: "2.100", c: true }, { t: "2.150", c: false }, { t: "2.200", c: false }], pts: 2, exp: "$1.250 + 850 = 2.100$." },
              { id: "6ANO-MAT-F05", p: "Uma pizza foi dividida em 4 partes iguais e João comeu 1 pedaço. Qual fração representa o pedaço comido?", o: [{ t: "1/2", c: false }, { t: "1/3", c: false }, { t: "1/4", c: true }, { t: "3/4", c: false }], pts: 2, exp: "A fração representa 1 parte de um total de 4 partes iguais, ou seja, $1/4$." },
              { id: "6ANO-MAT-F06", p: "Qual é o resultado do cálculo $45 \\times 100$?", o: [{ t: "450", c: false }, { t: "4.500", c: true }, { t: "45.000", c: false }, { t: "450.000", c: false }], pts: 2, exp: "Para multiplicar um número natural por 100, acrescentam-se dois zeros à direita: $45 \\times 100 = 4.500$." },
              { id: "6ANO-MAT-F07", p: "Qual figura geométrica plana possui exatamente 3 lados e 3 vértices?", o: [{ t: "Quadrado", c: false }, { t: "Retângulo", c: false }, { t: "Triângulo", c: true }, { t: "Pentágono", c: false }], pts: 2, exp: "Por definição, o triângulo é o polígono de 3 lados e 3 vértices." },
              { id: "6ANO-MAT-F08", p: "Qual unidade padronizada é mais adequada para medir o comprimento de uma caneta?", o: [{ t: "Quilômetro", c: false }, { t: "Metro", c: false }, { t: "Centímetro", c: true }, { t: "Litro", c: false }], pts: 2, exp: "O centímetro é a unidade padronizada mais adequada para pequenas medidas de comprimento como canetas e lápis." },
              { id: "6ANO-MAT-F09", p: "Quantas faces possui um cubo?", o: [{ t: "4", c: false }, { t: "6", c: true }, { t: "8", c: false }, { t: "12", c: false }], pts: 2, exp: "O cubo é um hexaedro regular e possui 6 faces quadradas." },
              { id: "6ANO-MAT-F10", p: "Qual é a medida, em graus, de um ângulo reto?", o: [{ t: "45°", c: false }, { t: "90°", c: true }, { t: "180°", c: false }, { t: "360°", c: false }], pts: 2, exp: "O ângulo reto é definido por ter uma medida exata de 90°." },
              { id: "6ANO-MAT-F11", p: "Em uma turma com 30 alunos, 18 são meninas. Quantos são os meninos?", o: [{ t: "10", c: false }, { t: "12", c: true }, { t: "14", c: false }, { t: "18", c: false }], pts: 2, exp: "Subtrai-se o total pelo número de meninas: $30 - 18 = 12$ meninos." },
              { id: "6ANO-MAT-F12", p: "Como se escreve a fração $1/10$ em forma decimal?", o: [{ t: "0,01", c: false }, { t: "0,1", c: true }, { t: "1,0", c: false }, { t: "10,0", c: false }], pts: 2, exp: "A fração um décimo equivale ao número decimal 0,1." },
              { id: "6ANO-MAT-F13", p: "O que representa o perímetro de uma figura plana?", o: [{ t: "A medida do espaço interno", c: false }, { t: "A soma das medidas de todos os lados", c: true }, { t: "A quantidade de vértices", c: false }, { t: "A multiplicação da base pela altura", c: false }], pts: 2, exp: "Perímetro é o contorno de uma figura plana, obtido pela soma de seus lados." },
              { id: "6ANO-MAT-F14", p: "Qual dos seguintes números é divisível por 5?", o: [{ t: "124", c: false }, { t: "237", c: false }, { t: "340", c: true }, { t: "412", c: false }], pts: 2, exp: "Um número é divisível por 5 quando termina em 0 ou 5." },
              { id: "6ANO-MAT-F15", p: "A metade de uma quantia em dinheiro corresponde a qual porcentagem?", o: [{ t: "10%", c: false }, { t: "25%", c: false }, { t: "50%", c: true }, { t: "100%", c: false }], pts: 2, exp: "A metade representa $1/2$ do total, o que equivale a 50%." },
              { id: "6ANO-MAT-F16", p: "Quantos lados possui qualquer polígono classificado como quadrilátero?", o: [{ t: "3", c: false }, { t: "4", c: true }, { t: "5", c: false }, { t: "6", c: false }], pts: 2, exp: "Quadriláteros são polígonos de 4 lados." },
              { id: "6ANO-MAT-F17", p: "Qual é o resultado da subtração $5,5 - 2,3$?", o: [{ t: "3,2", c: true }, { t: "3,5", c: false }, { t: "7,8", c: false }, { t: "3,8", c: false }], pts: 2, exp: "Alinhando as vírgulas: $5,5 - 2,3 = 3,2$." },
              { id: "6ANO-MAT-F18", p: "No plano cartesiano, qual das coordenadas representa o ponto de origem?", o: [{ t: "(1, 1)", c: false }, { t: "(0, 1)", c: false }, { t: "(0, 0)", c: true }, { t: "(1, 0)", c: false }], pts: 2, exp: "A origem do plano cartesiano fica no cruzamento dos eixos, no ponto $(0,0)$." },
              { id: "6ANO-MAT-F19", p: "Como são chamadas duas retas mantidas em um mesmo plano que nunca se cruzam?", o: [{ t: "Concorrentes", c: false }, { t: "Perpendiculares", c: false }, { t: "Paralelas", c: true }, { t: "Transversais", c: false }], pts: 2, exp: "Retas paralelas mantêm a mesma distância entre si e não possuem ponto em comum." },
              { id: "6ANO-MAT-F20", p: "Quantos minutos há em uma hora e meia?", o: [{ t: "60 minutos", c: false }, { t: "75 minutos", c: false }, { t: "90 minutos", c: true }, { t: "100 minutos", c: false }], pts: 2, exp: "1 hora = 60 minutos; meia hora = 30 minutos. Total = $60 + 30 = 90$ minutos." },

              
            // ==================== MÉDIAS (20 QUESTÕES) ====================
              { id: "6ANO-MAT-M01", p: "Qual dos números a seguir é divisível por 3 segundo o critério de divisibilidade?", o: [{ t: "121", c: false }, { t: "241", c: false }, { t: "312", c: true }, { t: "502", c: false }], pts: 3, exp: "Um número é divisível por 3 quando a soma dos seus algarismos é múltiplo de 3. Em 312: $3 + 1 + 2 = 6$ (divisível por 3)." },
              { id: "6ANO-MAT-M02", p: "Qual é o Menor Múltiplo Comum (MMC) entre os números 4 e 6?", o: [{ t: "12", c: true }, { t: "18", c: false }, { t: "24", c: false }, { t: "2", c: false }], pts: 3, exp: "Múltiplos de 4: 0, 4, 8, 12... Múltiplos de 6: 0, 6, 12... O menor múltiplo comum não nulo é 12." },
              { id: "6ANO-MAT-M03", p: "Dada a sentença matemática $x + 15 = 40$, qual é o valor do termo desconhecido $x$?", o: [{ t: "15", c: false }, { t: "25", c: true }, { t: "35", c: false }, { t: "55", c: false }], pts: 3, exp: "Utilizando a operação inversa: $x = 40 - 15 = 25$." },
              { id: "6ANO-MAT-M04", p: "Qual fração é equivalente a $3/4$ com denominador igual a 12?", o: [{ t: "6/12", c: false }, { t: "8/12", c: false }, { t: "9/12", c: true }, { t: "10/12", c: false }], pts: 3, exp: "Multiplicando o numerador e o denominador por 3: $3 \\times 3 = 9$ e $4 \\times 3 = 12$, gerando $9/12$." },
              { id: "6ANO-MAT-M05", p: "Qual é o resultado da soma de frações $2/7 + 3/7$?", o: [{ t: "5/14", c: false }, { t: "5/7", c: true }, { t: "6/7", c: false }, { t: "6/14", c: false }], pts: 3, exp: "Em frações com denominadores iguais, somam-se os numeradores e conserva-se o denominador: $(2+3)/7 = 5/7$." },
              { id: "6ANO-MAT-M06", p: "Um prisma reto possui base triangular. Quantos vértices ele possui no total?", o: [{ t: "5", c: false }, { t: "6", c: true }, { t: "8", c: false }, { t: "9", c: false }], pts: 3, exp: "Um prisma de base triangular tem 3 vértices na base inferior e 3 na superior, totalizando 6 vértices." },
              { id: "6ANO-MAT-M07", p: "Qual é a área de um terreno retangular que mede 12 metros de largura por 15 metros de comprimento?", o: [{ t: "54 m²", c: false }, { t: "180 m²", c: true }, { t: "225 m²", c: false }, { t: "270 m²", c: false }], pts: 3, exp: "A área do retângulo é dada por base $\\times$ altura: $12 \\times 15 = 180\\text{ m}^2$." },
              { id: "6ANO-MAT-M08", p: "Quanto é 25% de R$ 200,00?", o: [{ t: "R$ 25,00", c: false }, { t: "R$ 40,00", c: false }, { t: "R$ 50,00", c: true }, { t: "R$ 100,00", c: false }], pts: 3, exp: "25% equivale à quarta parte do valor: $200 \\div 4 = 50$, logo R$ 50,00." },
              { id: "6ANO-MAT-M09", p: "Como é classificado um triângulo que possui um ângulo interno medindo 120°?", o: [{ t: "Acutângulo", c: false }, { t: "Retângulo", c: false }, { t: "Obtusângulo", c: true }, { t: "Equilátero", c: false }], pts: 3, exp: "Triângulos que possuem um ângulo obtuso (maior que 90°) são classificados como obtusângulos." },
              { id: "6ANO-MAT-M10", p: "Qual é o valor da potência $2^4$?", o: [{ t: "8", c: false }, { t: "12", c: false }, { t: "16", c: true }, { t: "32", c: false }], pts: 3, exp: "$2^4 = 2 \\times 2 \\times 2 \\times 2 = 16$." },
              { id: "6ANO-MAT-M11", p: "Qual é a média aritmética simples das notas 6, 7 e 8?", o: [{ t: "6", c: false }, { t: "7", c: true }, { t: "8", c: false }, { t: "21", c: false }], pts: 3, exp: "Soma das notas: $6 + 7 + 8 = 21$. Divisão pelo número de notas: $21 \\div 3 = 7$." },
              { id: "6ANO-MAT-M12", p: "Qual é o resultado da multiplicação $1,5 \\times 4$?", o: [{ t: "4,5", c: false }, { t: "6,0", c: true }, { t: "6,5", c: false }, { t: "7,0", c: false }], pts: 3, exp: "$1,5 \\times 4 = 6,0$." },
              { id: "6ANO-MAT-M13", p: "Ao lançar um dado comum de 6 faces, qual é a probabilidade de sair o número 5?", o: [{ t: "1/5", c: false }, { t: "1/6", c: true }, { t: "5/6", c: false }, { t: "1/2", c: false }], pts: 3, exp: "Há 1 caso favorável em um espaço amostral de 6 resultados possíveis, resultando em $1/6$." },
              { id: "6ANO-MAT-M14", p: "Como se chama um triângulo que possui todos os três lados com medidas diferentes?", o: [{ t: "Equilátero", c: false }, { t: "Isósceles", c: false }, { t: "Escaleno", c: true }, { t: "Retângulo", c: false }], pts: 3, exp: "Triângulo escaleno possui os três lados com comprimentos distintos." },
              { id: "6ANO-MAT-M15", p: "Um ângulo cuja medida é maior que 0° e menor que 90° recebe qual nome?", o: [{ t: "Agudo", c: true }, { t: "Obtuso", c: false }, { t: "Raso", c: false }, { t: "Reto", c: false }], pts: 3, exp: "Todo ângulo com abertura entre 0° e 90° é classificado como agudo." },
              { id: "6ANO-MAT-M16", p: "Dois irmãos dividiram R$ 60,00 de modo que o mais velho recebeu o dobro do mais novo. Quanto recebeu o mais novo?", o: [{ t: "R$ 15,00", c: false }, { t: "R$ 20,00", c: true }, { t: "R$ 30,00", c: false }, { t: "R$ 40,00", c: false }], pts: 3, exp: "Dividindo em 3 partes iguais ($1 + 2 = 3$): $60 \\div 3 = 20$. O mais novo recebe 1 parte (R$ 20,00) e o mais velho 2 partes (R$ 40,00)." },
              { id: "6ANO-MAT-M17", p: "Quantos gramas existem em 2,5 quilogramas?", o: [{ t: "250 g", c: false }, { t: "2.050 g", c: false }, { t: "2.500 g", c: true }, { t: "25.000 g", c: false }], pts: 3, exp: "Como $1\\text{ kg} = 1.000\\text{ g}$, multiplica-se $2,5 \\times 1.000 = 2.500\\text{ g}$." },
              { id: "6ANO-MAT-M18", p: "Em uma divisão euclidiana, o dividendo é 27 e o divisor é 4. Qual é o resto?", o: [{ t: "1", c: false }, { t: "2", c: false }, { t: "3", c: true }, { t: "6", c: false }], pts: 3, exp: "$27 = 4 \\times 6 + 3$. Portanto, o quociente é 6 e o resto é 3." },
              { id: "6ANO-MAT-M19", p: "Qual é o ponto médio entre os números 10 e 20 na reta numérica?", o: [{ t: "12", c: false }, { t: "14", c: false }, { t: "15", c: true }, { t: "16", c: false }], pts: 3, exp: "O ponto médio é a média aritmética: $(10 + 20) \\div 2 = 30 \\div 2 = 15$." },
              { id: "6ANO-MAT-M20", p: "Se o perímetro de um quadrado é 36 cm, qual é a medida de cada um dos seus lados?", o: [{ t: "6 cm", c: false }, { t: "8 cm", c: false }, { t: "9 cm", c: true }, { t: "12 cm", c: false }], pts: 3, exp: "O quadrado possui 4 lados iguais. Assim, $36 \\div 4 = 9\\text{ cm}$." },




           // ==================== DIFÍCEIS (20 QUESTÕES) ====================
              { id: "6ANO-MAT-D01", p: "Uma professora tem 24 canetas azuis e 36 canetas vermelhas e quer dividi-las em estojos iguais com o maior número possível de canetas em cada um. Quantas canetas haverá por estojo?", o: [{ t: "6", c: false }, { t: "8", c: false }, { t: "12", c: true }, { t: "18", c: false }], pts: 4, exp: "Calcula-se o MDC entre 24 e 36. Os divisores comuns são 1, 2, 3, 4, 6 e 12. O Maior Divisor Comum é 12." },
              { id: "6ANO-MAT-D02", p: "Qual é o valor da expressão numérica $5 + 3 \\times (2^3 - 4)$?", o: [{ t: "17", c: true }, { t: "20", c: false }, { t: "32", c: false }, { t: "12", c: false }], pts: 4, exp: "Resolve-se primeiro a potência e parênteses: $2^3 - 4 = 8 - 4 = 4$. Depois a multiplicação: $3 \\times 4 = 12$. Por fim a adição: $5 + 12 = 17$." },
              { id: "6ANO-MAT-D03", p: "Qual é o resultado simplificado da operação com frações $1/2 + 2/3$?", o: [{ t: "3/5", c: false }, { t: "7/6", c: true }, { t: "5/6", c: false }, { t: "3/6", c: false }], pts: 4, exp: "Reduzindo ao mesmo denominador (MMC = 6): $1/2 = 3/6$ e $2/3 = 4/6$. Soma: $3/6 + 4/6 = 7/6$." },
              { id: "6ANO-MAT-D04", p: "Uma figura plana é formada pela junção de dois retângulos: um de $4\\text{ cm} \\times 5\\text{ cm}$ e outro de $3\\text{ cm} \\times 2\\text{ cm}$. Qual é a área total dessa figura?", o: [{ t: "20 cm²", c: false }, { t: "26 cm²", c: true }, { t: "30 cm²", c: false }, { t: "32 cm²", c: false }], pts: 4, exp: "Área 1: $4 \\times 5 = 20\\text{ cm}^2$. Área 2: $3 \\times 2 = 6\\text{ cm}^2$. Área total: $20 + 6 = 26\\text{ cm}^2$." },
              { id: "6ANO-MAT-D05", p: "Um produto que custava R$ 80,00 sofreu um aumento de 10% e, em seguida, teve um desconto de 10% sobre o novo valor. Qual é o preço final?", o: [{ t: "R$ 79,20", c: true }, { t: "R$ 80,00", c: false }, { t: "R$ 81,00", c: false }, { t: "R$ 88,00", c: false }], pts: 4, exp: "Aumento de 10% em 80: $80 + 8 = 88$. Desconto de 10% em 88: $88 - 8,80 = 79,20$." },
              { id: "6ANO-MAT-D06", p: "Se a medida do lado de um quadrado for dobrada, o que acontecerá com a sua área?", o: [{ t: "Dobrará (ficará 2 vezes maior)", c: false }, { t: "Triplicará (ficará 3 vezes maior)", c: false }, { t: "Quadruplicará (ficará 4 vezes maior)", c: true }, { t: "Permanecerá igual", c: false }], pts: 4, exp: "Se o lado passa de $L$ para $2L$, a nova área é $(2L)^2 = 4L^2$, ou seja, quadruplica." },
              { id: "6ANO-MAT-D07", p: "Mariana leu $2/5$ de um livro no sábado e $1/3$ do livro no domingo. Qual fração do livro ainda falta para ela ler?", o: [{ t: "3/15", c: false }, { t: "4/15", c: true }, { t: "11/15", c: false }, { t: "7/15", c: false }], pts: 4, exp: "Total lido: $2/5 + 1/3 = 6/15 + 5/15 = 11/15$. Falta ler: $1 - 11/15 = 4/15$." },
              { id: "6ANO-MAT-D08", p: "Como se escreve o número 450.000 em notação científica?", o: [{ t: "45 × 10⁴", c: false }, { t: "4,5 × 10⁵", c: true }, { t: "4,5 × 10⁴", c: false }, { t: "0,45 × 10⁶", c: false }], pts: 4, exp: "Em notação científica, o número inicial deve estar entre 1 e 10: $4,5 \\times 10^5$." },
              { id: "6ANO-MAT-D09", p: "Qual é o volume de um bloco retangular de dimensões 5 cm, 4 cm e 3 cm?", o: [{ t: "12 cm³", c: false }, { t: "24 cm³", c: false }, { t: "60 cm³", c: true }, { t: "120 cm³", c: false }], pts: 4, exp: "O volume do paralelepípedo retângulo é $V = a \\times b \\times c = 5 \\times 4 \\times 3 = 60\\text{ cm}^3$." },
              { id: "6ANO-MAT-D10", p: "Em qualquer triângulo, qual é a soma das medidas de seus três ângulos internos?", o: [{ t: "90°", c: false }, { t: "180°", c: true }, { t: "270°", c: false }, { t: "360°", c: false }], pts: 4, exp: "A soma das medidas dos ângulos internos de todo e qualquer triângulo é sempre $180^\\circ$." },
              { id: "6ANO-MAT-D11", p: "Lucas tem 3 camisetas de cores diferentes e 4 calças diferentes. De quantas maneiras distintas ele pode se vestir combinando 1 camiseta e 1 calça?", o: [{ t: "7", c: false }, { t: "12", c: true }, { t: "14", c: false }, { t: "16", c: false }], pts: 4, exp: "Pelo Princípio Multiplicativo da contagem: $3 \\times 4 = 12$ combinações diferentes." },
              { id: "6ANO-MAT-D12", p: "Qual é a fração geratriz da dízima periódica simples $0,333...$?", o: [{ t: "1/3", c: true }, { t: "3/10", c: false }, { t: "3/100", c: false }, { t: "1/30", c: false }], pts: 4, exp: "A dízima $0,333... = 3/9$, que simplificada por 3 resulta em $1/3$." },
              { id: "6ANO-MAT-D13", p: "Um veículo percorreu a distância de 240 quilômetros em exatamente 3 horas. Qual foi a sua velocidade média nesse trajeto?", o: [{ t: "70 km/h", c: false }, { t: "80 km/h", c: true }, { t: "90 km/h", c: false }, { t: "720 km/h", c: false }], pts: 4, exp: "A velocidade média é a razão entre distância e tempo: $240 \\div 3 = 80\\text{ km/h}$." },
              { id: "6ANO-MAT-D14", p: "O triplo de um número adicionado a 8 é igual a 29. Qual é esse número?", o: [{ t: "5", c: false }, { t: "7", c: true }, { t: "8", c: false }, { t: "9", c: false }], pts: 4, exp: "Montando a equação: $3x + 8 = 29 \\Rightarrow 3x = 21 \\Rightarrow x = 7$." },
              { id: "6ANO-MAT-D15", p: "Ao lançar duas moedas honestas simultaneamente, qual é a probabilidade de obter exatamente duas caras?", o: [{ t: "1/2", c: false }, { t: "1/4", c: true }, { t: "3/4", c: false }, { t: "1/3", c: false }], pts: 4, exp: "O espaço amostral é {(Cara, Cara), (Cara, Coroa), (Coroa, Cara), (Coroa, Coroa)} (4 casos). Apenas 1 caso tem duas caras, logo $1/4$." },
              { id: "6ANO-MAT-D16", p: "Um reservatório em formato cúbico possui 1 metro de aresta interna. Quantos litros de água cabem nesse reservatório?", o: [{ t: "100 litros", c: false }, { t: "500 litros", c: false }, { t: "1.000 litros", c: true }, { t: "10.000 litros", c: false }], pts: 4, exp: "O volume é $1\\text{ m} \\times 1\\text{ m} \\times 1\\text{ m} = 1\\text{ m}^3 = 1.000\\text{ dm}^3$. Como $1\\text{ dm}^3 = 1\\text{ litro}$, cabem $1.000\\text{ litros}$." },
              { id: "6ANO-MAT-D17", p: "Em um mapa desenhado na escala $1 : 100$, uma parede mede 5 centímetros. Qual é o comprimento real dessa parede em metros?", o: [{ t: "0,5 metro", c: false }, { t: "5 metros", c: true }, { t: "50 metros", c: false }, { t: "500 metros", c: false }], pts: 4, exp: "Comprimento real: $5\\text{ cm} \\times 100 = 500\\text{ cm} = 5\\text{ metros}$." },
              { id: "6ANO-MAT-D18", p: "Quantas arestas possui uma pirâmide cuja base é um pentágono (5 lados)?", o: [{ t: "5", c: false }, { t: "6", c: false }, { t: "10", c: true }, { t: "12", c: false }], pts: 4, exp: "Uma pirâmide de base $n$-gonal possui $2n$ arestas ($n$ na base + $n$ laterais). Para $n=5$: $2 \\times 5 = 10$ arestas." },
              { id: "6ANO-MAT-D19", p: "Em uma pesquisa de opinião escolar, 120 alunos responderam à pergunta. Se o gráfico de setores mostra que a opção A ocupa um ângulo central de 90°, quantos alunos escolheram essa opção?", o: [{ t: "20 alunos", c: false }, { t: "30 alunos", c: true }, { t: "40 alunos", c: false }, { t: "60 alunos", c: false }], pts: 4, exp: "Um ângulo de 90° equivale a $90^\\circ / 360^\\circ = 1/4$ do total. Calculando $120 \\div 4 = 30$ alunos." },
              { id: "6ANO-MAT-D20", p: "Considere o algoritmo: 'Escolha um número natural $N$. Multiplique por 2. Somar 6. Divida por 2. Subtraia $N$'. Qual é o resultado final obtido para qualquer número $N$ escolhido?", o: [{ t: "1", c: false }, { t: "2", c: false }, { t: "3", c: true }, { t: "N", c: false }], pts: 4, exp: "Acompanhando a expressão: $[(2N + 6) \\div 2] - N = (N + 3) - N = 3$." }


        ],






        "Português": [
            
        // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
              { id: "6ANO-PORT-F01", p: "Qual classe gramatical indica ações, estados ou fenômenos da natureza?", o: [{t:"Verbo",c:true}, {t:"Substantivo",c:false}, {t:"Adjetivo",c:false}, {t:"Advérbio",c:false}], pts: 2, exp: "O verbo é a palavra que flexiona para indicar ação, estado ou fenômeno natural." },
              { id: "6ANO-PORT-F02", p: "Qual sinal de pontuação deve ser utilizado ao final de uma pergunta direta?", o: [{t:"Ponto de interrogação (?)",c:true}, {t:"Ponto final (.)",c:false}, {t:"Ponto de exclamação (!)",c:false}, {t:"Vírgula (,)",c:false}], pts: 2, exp: "O ponto de interrogação indica expressamente uma pergunta direta." },
              { id: "6ANO-PORT-F03", p: "Em uma narrativa, como é chamado o lugar onde os fatos acontecem?", o: [{t:"Espaço ou Cenário",c:true}, {t:"Tempo",c:false}, {t:"Enredo",c:false}, {t:"Foco narrativo",c:false}], pts: 2, exp: "O espaço/cenário é a ambientação física ou psicológica da narrativa." },
              { id: "6ANO-PORT-F04", p: "Qual das opções apresenta um sinônimo para a palavra 'alegre'?", o: [{t:"Contente",c:true}, {t:"Triste",c:false}, {t:"Apressado",c:false}, {t:"Bravo",c:false}], pts: 2, exp: "Sinônimos são palavras com significados semelhantes; alegre e contente são equivalentes." },
              { id: "6ANO-PORT-F05", p: "Qual é o antônimo da palavra 'corajoso'?", o: [{t:"Covarde",c:true}, {t:"Forte",c:false}, {t:"Esperto",c:false}, {t:"Calmo",c:false}], pts: 2, exp: "Antônimos são palavras de sentidos opostos; o oposto de corajoso é covarde." },
              { id: "6ANO-PORT-F06", p: "Qual classe gramatical atribui qualidades ou características aos substantivos?", o: [{t:"Adjetivo",c:true}, {t:"Numeral",c:false}, {t:"Pronome",c:false}, {t:"Preposição",c:false}], pts: 2, exp: "O adjetivo caracteriza e qualifica o substantivo." },
              { id: "6ANO-PORT-F07", p: "Na oração 'O menino comprou um livro', qual é o sujeito?", o: [{t:"O menino",c:true}, {t:"comprou",c:false}, {t:"um livro",c:false}, {t:"livro",c:false}], pts: 2, exp: "O sujeito é o termo sobre o qual se declara algo: quem comprou o livro foi 'O menino'." },
              { id: "6ANO-PORT-F08", p: "Nas Histórias em Quadrinhos, qual recurso gráfico indica a fala direta das personagens?", o: [{t:"Balão de fala",c:true}, {t:"Onomatopeia",c:false}, {t:"Legenda inferior",c:false}, {t:"Calpino de nota",c:false}], pts: 2, exp: "Os balões de fala contêm o discurso direto das personagens nas HQs." },
              { id: "6ANO-PORT-F09", p: "O que caracteriza a linguagem não verbal?", o: [{t:"O uso exclusivo de imagens, cores e gestos",c:true}, {t:"O uso exclusivo de palavras escritas",c:false}, {t:"O uso de gravações em áudio",c:false}, {t:"O uso de regras gramaticais formais",c:false}], pts: 2, exp: "Linguagem não verbal utiliza signos visuais e sonoros sem o emprego de palavras." },
              { id: "6ANO-PORT-F10", p: "Qual é a função do ponto final em um texto?", o: [{t:"Encerrar uma frase declarativa",c:true}, {t:"Indicar uma dúvida",c:false}, {t:"Expressar admiração",c:false}, {t:"Introduzir uma fala",c:false}], pts: 2, exp: "O ponto final sinaliza a terminação de um período ou frase declarativa." },
              { id: "6ANO-PORT-F11", p: "Como é chamado o título principal que se destaca no topo de uma notícia?", o: [{t:"Manchete",c:true}, {t:"Lide",c:false}, {t:"Legenda",c:false}, {t:"Subtítulo",c:false}], pts: 2, exp: "A manchete é o título em destaque que resume o fato noticioso." },
              { id: "6ANO-PORT-F12", p: "Qual pronome pessoal do caso reto substitui corretamente 'Ana e Maria'?", o: [{t:"Elas",c:true}, {t:"Nós",c:false}, {t:"Vós",c:false}, {t:"Eles",c:false}], pts: 2, exp: "'Elas' é o pronome da 3ª pessoa do plural do gênero feminino." },
              { id: "6ANO-PORT-F13", p: "Como chamamos um texto estruturado em versos e estrofes?", o: [{t:"Poema",c:true}, {t:"Notícia",c:false}, {t:"Conto",c:false}, {t:"Verbete",c:false}], pts: 2, exp: "Poemas têm sua forma composicional estruturada em versos e estrofes." },
              { id: "6ANO-PORT-F14", p: "Em um texto narrativo impresso, qual sinal introduz a fala direta de uma personagem?", o: [{t:"Travessão",c:true}, {t:"Ponto e vírgula",c:false}, {t:"Parênteses",c:false}, {t:"Ponto de interrogação",c:false}], pts: 2, exp: "O travessão indica o início do discurso direto nas falas do texto." },
              { id: "6ANO-PORT-F15", p: "Atribuir ações humanas a seres inanimados ou animais é uma figura de linguagem chamada:", o: [{t:"Personificação ou Prosopopeia",c:true}, {t:"Hipérbole",c:false}, {t:"Metáfora",c:false}, {t:"Antítese",c:false}], pts: 2, exp: "Personificação dá qualidades e ações humanas a seres não humanos." },
              { id: "6ANO-PORT-F16", p: "Na frase 'O cão latiu alto', a palavra 'alto' funciona como advérbio de:", o: [{t:"Modo",c:true}, {t:"Lugar",c:false}, {t:"Tempo",c:false}, {t:"Intensidade",c:false}], pts: 2, exp: "'Alto' indica a maneira/modo como o cão latiu." },
              { id: "6ANO-PORT-F17", p: "Como é chamada a voz que conta a história em um texto narrativo?", o: [{t:"Narrador",c:true}, {t:"Autor",c:false}, {t:"Personagem principal",c:false}, {t:"Leitor",c:false}], pts: 2, exp: "O narrador é a entidade ficcional criada para relatar os fatos da história." },
              { id: "6ANO-PORT-F18", p: "Qual das opções apresenta uma afirmação baseada em OPINIÃO e não em um FATO?", o: [{t:"Este filme é o melhor do ano.",c:true}, {t:"O filme dura 90 minutos.",c:false}, {t:"O filme foi lançado em maio.",c:false}, {t:"O filme teve três atores principais.",c:false}], pts: 2, exp: "Dizer que um filme é o 'melhor' reflete um juízo de valor subjetivo (opinião)." },
              { id: "6ANO-PORT-F19", p: "Qual é o plural correto do substantivo 'jardim'?", o: [{t:"Jardins",c:true}, {t:"Jardines",c:false}, {t:"Jardims",c:false}, {t:"Jardinze",c:false}], pts: 2, exp: "Substantivos terminados em 'm' fazem o plural em 'ns'." },
              { id: "6ANO-PORT-F20", p: "Qual é a principal função comunicativa do gênero notícia?", o: [{t:"Informar o leitor sobre fatos reais e recentes",c:true}, {t:"Emocionar com uma história inventada",c:false}, {t:"Vender um produto ou serviço",c:false}, {t:"Ensinar a fazer uma receita culinária",c:false}], pts: 2, exp: "A notícia pertence ao campo jornalístico e tem função informativa de fatos reais." },



          // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
              { id: "6ANO-PORT-M01", p: "Qual modo verbal expressa uma ordem, um pedido ou um conselho?", o: [{t:"Modo Imperativo",c:true}, {t:"Modo Indicativo",c:false}, {t:"Modo Subjuntivo",c:false}, {t:"Forma Nominal",c:false}], pts: 3, exp: "O modo imperativo é empregado para orientar, ordenar, pedir ou aconselhar." },
              { id: "6ANO-PORT-M02", p: "Na frase 'Os alunos estudaram muito ontem', o verbo está flexionado em qual tempo?", o: [{t:"Pretérito Perfeito do Indicativo",c:true}, {t:"Presente do Indicativo",c:false}, {t:"Futuro do Presente",c:false}, {t:"Pretérito Imperfeito",c:false}], pts: 3, exp: "'Estudaram' indica uma ação concluída no passado (Pretérito Perfeito)." },
              { id: "6ANO-PORT-M03", p: "Qual frase faz uso da linguagem conotativa (sentido figurado)?", o: [{t:"Aquele homem tem um coração de pedra.",c:true}, {t:"O médico examinou o coração do paciente.",c:false}, {t:"A pedra caiu no chão da sala.",c:false}, {t:"A casa foi construída com tijolos.",c:false}], pts: 3, exp: "'Coração de pedra' é uma expressão conotativa para indicar insensibilidade." },
              { id: "6ANO-PORT-M04", p: "No gênero notícia, quais informações essenciais compõem o Lide (1º parágrafo)?", o: [{t:"O quê, quem, quando, onde, como e por quê",c:true}, {t:"A opinião do jornalista e a conclusão",c:false}, {t:"A biografia do autor e o preço do jornal",c:false}, {t:"Apenas a data e a cidade do fato",c:false}], pts: 3, exp: "O Lide responde às perguntas básicas que contextualizam o fato principal." },
              { id: "6ANO-PORT-M05", p: "Em 'O menino e a menina chegaram cedo', por que o verbo está no plural?", o: [{t:"Concorda com o sujeito composto formado por dois núcleos",c:true}, {t:"Porque é uma regra opcional da gramática",c:false}, {t:"Porque o advérbio 'cedo' exige o plural",c:false}, {t:"Porque o verbo está no imperativo",c:false}], pts: 3, exp: "Sujeito composto posposto ou anteposto com dois núcleos leva o verbo ao plural." },
              { id: "6ANO-PORT-M06", p: "Qual destas palavras foi formada pelo acréscimo de um prefixo que indica negação?", o: [{t:"Infeliz",c:true}, {t:"Infelizmente",c:false}, {t:"Felicidade",c:false}, {t:"Feirante",c:false}], pts: 3, exp: "O prefixo 'in-' em 'infeliz' adiciona a ideia de 'não feliz' (negação)." },
              { id: "6ANO-PORT-M07", p: "Em 'Choveu um rio de lágrimas após a partida', qual figura indica exagero intencional?", o: [{t:"Hipérbole",c:true}, {t:"Metáfora",c:false}, {t:"Eufemismo",c:false}, {t:"Ironia",c:false}], pts: 3, exp: "Hipérbole é a figura de linguagem que expressa uma ideia com exagero." },
              { id: "6ANO-PORT-M08", p: "Na frase 'Alguns alunos faltaram', a palavra 'Alguns' classifica-se como pronome:", o: [{t:"Indefinido",c:true}, {t:"Demonstrativo",c:false}, {t:"Pessoal do caso reto",c:false}, {t:"Possessivo",c:false}], pts: 3, exp: "'Alguns' refere-se à 3ª pessoa gramatical de modo vago/indefinido." },
              { id: "6ANO-PORT-M09", p: "Quando o narrador reproduz a fala exata do personagem com aspas ou travessão, temos o:", o: [{t:"Discurso Direto",c:true}, {t:"Discurso Indireto",c:false}, {t:"Discurso Indireto Livre",c:false}, {t:"Discurso Poético",c:false}], pts: 3, exp: "No discurso direto, a fala da personagem é citada fielmente." },
              { id: "6ANO-PORT-M10", p: "Na oração 'A garota parecia triste', qual termo é o núcleo do predicado nominal?", o: [{t:"triste",c:true}, {t:"parecia",c:false}, {t:"garota",c:false}, {t:"A garota",c:false}], pts: 3, exp: "Em predicados nominais com verbo de ligação (parecer), o núcleo é o predicativo ('triste')." },
              { id: "6ANO-PORT-M11", p: "Em 'Fui à feira e comprei maçãs, laranjas, bananas e uvas', qual a função das vírgulas?", o: [{t:"Separar elementos de uma enumeração",c:true}, {t:"Isolar um vocativo",c:false}, {t:"Indicar a omissão de um verbo",c:false}, {t:"Separar uma explicação longa",c:false}], pts: 3, exp: "Emprega-se a vírgula para listar/enumerar itens de mesma função sintática." },
              { id: "6ANO-PORT-M12", p: "Qual das frases a seguir possui um verbo intransitivo (que não exige complemento)?", o: [{t:"O bebê dormiu.",c:true}, {t:"O menino comprou um brinquedo.",c:false}, {t:"Ela gosta de música.",c:false}, {t:"Nós enviamos a carta.",c:false}], pts: 3, exp: "'Dormir' é intransitivo pois tem sentido completo e não exige objeto." },
              { id: "6ANO-PORT-M13", p: "Qual elemento de texto digital permite ao leitor clicar e ser redirecionado a outra página?", o: [{t:"Hiperlink",c:true}, {t:"Rodapé",c:false}, {t:"Parágrafo",c:false}, {t:"Sumário impresso",c:false}], pts: 3, exp: "Hiperlink é o recurso hipertextual de navegação em textos digitais na Web." },
              { id: "6ANO-PORT-M14", p: "Em 'O atleta é rápido como um leopardo', qual figura de linguagem usa o termo 'como'?", o: [{t:"Comparação",c:true}, {t:"Metáfora",c:false}, {t:"Metonímia",c:false}, {t:"Ironia",c:false}], pts: 3, exp: "A comparação aproxima dois elementos usando conectivo comparativo explícito ('como')." },
              { id: "6ANO-PORT-M15", p: "A propriedade de uma palavra ter múltiplos significados conforme o contexto chama-se:", o: [{t:"Polissemia",c:true}, {t:"Sinonímia",c:false}, {t:"Antonímia",c:false}, {t:"Homofonia",c:false}], pts: 3, exp: "Polissemia é a multiplicidade de sentidos de uma mesma palavra no contexto." },
              { id: "6ANO-PORT-M16", p: "Na oração 'Talvez nós sejamos aprovados', qual a ideia expressa por 'Talvez'?", o: [{t:"Dúvida",c:true}, {t:"Certeza",c:false}, {t:"Afirmação",c:false}, {t:"Lugar",c:false}], pts: 3, exp: "'Talvez' é um advérbio que exprime circunstância de dúvida." },
              { id: "6ANO-PORT-M17", p: "A norma-padrão da língua portuguesa deve ser empregada prioritariamente em:", o: [{t:"Documentos oficiais, provas e artigos científicos",c:true}, {t:"Conversas informais entre amigos no WhatsApp",c:false}, {t:"Diálogos cotidianos em família",c:false}, {t:"Rascunhos pessoais não publicados",c:false}], pts: 3, exp: "A norma-padrão é exigida em situações formais de comunicação oral e escrita." },
              { id: "6ANO-PORT-M18", p: "Qual das alternativas atende corretamente às regras de concordância nominal?", o: [{t:"A aluna mesma disse: 'Muito obrigada!'",c:true}, {t:"A aluna mesmo disse: 'Muito obrigado!'",c:false}, {t:"A aluna mesmo disse: 'Muito obrigada!'",c:false}, {t:"A aluna mesma disse: 'Muito obrigado!'",c:false}], pts: 3, exp: "'Mesma' concorda com aluna; 'obrigada' concorda com o emissor feminino." },
              { id: "6ANO-PORT-M19", p: "No jornalismo, a frase curta localizada logo abaixo da manchete para detalhá-la é o(a):", o: [{t:"Linha fina",c:true}, {t:"Epígrafe",c:false}, {t:"Lide",c:false}, {t:"Olho da matéria",c:false}], pts: 3, exp: "A linha fina complementa e expande as informações contidas na manchete." },
              { id: "6ANO-PORT-M20", p: "Qual modo verbal expressa uma dúvida, possibilidade ou hipótese não garantida?", o: [{t:"Modo Subjuntivo",c:true}, {t:"Modo Indicativo",c:false}, {t:"Modo Imperativo",c:false}, {t:"Modo Infinitivo",c:false}], pts: 3, exp: "O subjuntivo é o modo verbal das incertezas, hipóteses e possibilidades." },




          // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
             { id: "6ANO-PORT-D01", p: "No sintagma nominal 'O jovem estudante de medicina', qual palavra é o núcleo?", o: [{t:"estudante",c:true}, {t:"jovem",c:false}, {t:"medicina",c:false}, {t:"O",c:false}], pts: 4, exp: "O substantivo principal 'estudante' é o núcleo; 'jovem' funciona como adjetivo adnominal." },
             { id: "6ANO-PORT-D02", p: "Em 'O professor entregou o prêmio ao aluno', como se classificam os complementos verbais?", o: [{t:"Objeto direto ('o prêmio') e objeto indireto ('ao aluno')",c:true}, {t:"Dois objetos diretos",c:false}, {t:"Dois objetos indiretos",c:false}, {t:"Objeto indireto ('o prêmio') e objeto direto ('ao aluno')",c:false}], pts: 4, exp: "'Entregar' exige objeto direto (sem preposição) e objeto indireto (com preposição 'a')." },
              { id: "6ANO-PORT-D03", p: "Na frase 'Cheguei, vi, venci', como é classificado o período composto?", o: [{t:"Período composto por coordenação assindética",c:true}, {t:"Período composto por subordinação adjetiva",c:false}, {t:"Período simples com verbos no infinitivo",c:false}, {t:"Período composto por coordenação explicativa",c:false}], pts: 4, exp: "Orações coordenadas ligadas por vírgulas sem conjunção são assindéticas." },
              { id: "6ANO-PORT-D04", p: "Como escolhas lexicais e adjetivações podem comprometer a neutralidade de uma notícia?", o: [{t:"Expressando julgamentos implícitos do autor sobre o fato",c:true}, {t:"Impedindo que a notícia seja lida rapidamente",c:false}, {t:"Tornando o texto incompreensível para o leitor",c:false}, {t:"Garantindo a veracidade total dos dados apresentados",c:false}], pts: 4, exp: "Adjetivos valorativos e termos opinativos revelam a parcialidade do enquadramento." },
              { id: "6ANO-PORT-D05", p: "Em 'Ela leu Machado de Assis no fim de semana', que figura ocorre ao trocar a obra pelo autor?", o: [{t:"Metonímia",c:true}, {t:"Metáfora",c:false}, {t:"Hipérbole",c:false}, {t:"Antítese",c:false}], pts: 4, exp: "Metonímia é a substituição de um termo por outro dada a relação de contiguidade (autor pela obra)." },
              { id: "6ANO-PORT-D06", p: "Em 'Carlos comprou um carro. O veículo é azul', a palavra 'veículo' atua como recurso de:", o: [{t:"Coesão anafórica por substituição lexical",c:true}, {t:"Coesão catafórica por pronome relativo",c:false}, {t:"Incoerência textual",c:false}, {t:"Concordância verbal imprópria",c:false}], pts: 4, exp: "'Veículo' retoma o hiperônimo 'carro' já citado (coesão anafórica)." },
              { id: "6ANO-PORT-D07", p: "Na frase 'O menino de Fortaleza venceu a olimpíada', qual a função de 'de Fortaleza'?", o: [{t:"Adjunto adnominal do substantivo 'menino'",c:true}, {t:"Objeto direto do verbo vencer",c:false}, {t:"Predicativo do sujeito",c:false}, {t:"Complemento nominal do verbo",c:false}], pts: 4, exp: "A locução adjetiva 'de Fortaleza' especifica o núcleo substantivo 'menino'." },
              { id: "6ANO-PORT-D08", p: "Em 'Se eu estudasse mais, tiraria nota dez', quais os tempos verbais de 'estudasse' e 'tiraria'?", o: [{t:"Pretérito imperfeito do subjuntivo e futuro do pretérito do indicativo",c:true}, {t:"Presente do subjuntivo e futuro do presente do indicativo",c:false}, {t:"Pretérito perfeito do indicativo e imperativo afirmativo",c:false}, {t:"Pretérito mais-que-perfeito e futuro do pretérito",c:false}], pts: 4, exp: "A correlação verbal se dá entre o imperfeito do subjuntivo e o futuro do pretérito." },
              { id: "6ANO-PORT-D09", p: "Em um artigo de opinião, como é definida a Tese?", o: [{t:"A ideia principal e o posicionamento crítico defendido pelo autor",c:true}, {t:"A introdução imparcial de fatos sem tomar partido",c:false}, {t:"A conclusão gramatical do texto",c:false}, {t:"A biografia da pessoa entrevistada no texto",c:false}], pts: 4, exp: "A tese é o posicionamento central sustentado por argumentos ao longo do texto." },
              { id: "6ANO-PORT-D10", p: "O conceito de 'preconceito linguístico' refere-se a:", o: [{t:"Discriminar falantes pelo uso de variedades linguísticas de menor prestígio social",c:true}, {t:"Obrigatório uso de gírias em ambientes formais",c:false}, {t:"Proibir a leitura de textos poéticos nas escolas",c:false}, {t:"Corrigir ortografia apenas em dicionários",c:false}], pts: 4, exp: "Preconceito linguístico é a discriminação contra variantes populares ou regionais." },
              { id: "6ANO-PORT-D11", p: "Na oração 'A professora ofereceu livros aos alunos', o verbo 'ofereceu' é classificado como:", o: [{t:"Transitivo direto e indireto",c:true}, {t:"Transitivo direto apenas",c:false}, {t:"Transitivo indireto apenas",c:false}, {t:"Intransitivo",c:false}], pts: 4, exp: "Quem oferece, oferece algo ('livros' - OD) a alguém ('aos alunos' - OI)." },
              { id: "6ANO-PORT-D12", p: "Qual o efeito de sentido gerado na frase 'Que pessoa educada!', dita após uma grosseria?", o: [{t:"Ironia",c:true}, {t:"Metáfora",c:false}, {t:"Pleonasmo",c:false}, {t:"Eufemismo",c:false}], pts: 4, exp: "Ironia consiste em dizer o oposto do que se pretende expressar no contexto." },
              { id: "6ANO-PORT-D13", p: "Em 'Embora estivesse chovendo, fomos ao passeio', a conjunção 'Embora' estabelece ideia de:", o: [{t:"Concessão (oposição que não impede a ação principal)",c:true}, {t:"Causa",c:false}, {t:"Consequência imediata",c:false}, {t:"Condição necessária",c:false}], pts: 4, exp: "As conjunções concessivas introduzem uma ideia de contraste/quebra de expectativa." },
              { id: "6ANO-PORT-D14", p: "Qual a diferença de sentido entre o Pretérito Perfeito e o Pretérito Imperfeito do indicativo?", o: [{t:"O perfeito indica ação concluída no passado; o imperfeito indica ação contínua ou habitual",c:true}, {t:"O perfeito indica o futuro; o imperfeito indica o presente",c:false}, {t:"O imperfeito é usado apenas em perguntas; o perfeito em frases afirmativas",c:false}, {t:"Não há diferença de sentido entre eles",c:false}], pts: 4, exp: "Perfeito é ação pontual finalizada; imperfeito marca duratividade/fatos habituais no passado." },
              { id: "6ANO-PORT-D15", p: "No período 'O sol nasceu E os pássaros cantaram', a palavra 'E' funciona como conectivo de:", o: [{t:"Adição / Coordenação aditiva",c:true}, {t:"Oposição / Coordenação adversativa",c:false}, {t:"Alternância / Coordenação alternativa",c:false}, {t:"Explicação / Coordenação explicativa",c:false}], pts: 4, exp: "A conjunção 'e' une orações somando fatos coordenados." },
              { id: "6ANO-PORT-D16", p: "Na frase 'A aluna, atenta à aula, compreendeu tudo', qual termo é o predicativo do sujeito?", o: [{t:"atenta à aula",c:true}, {t:"compreendeu tudo",c:false}, {t:"A aluna",c:false}, {t:"tudo",c:false}], pts: 4, exp: "'Atenta' qualifica o estado momentâneo do sujeito 'A aluna'." },
              { id: "6ANO-PORT-D17", p: "Qual das opções exemplifica a figura da Metáfora?", o: [{t:"Os olhos dela são duas jabuticabas reluzentes.",c:true}, {t:"Os olhos dela são pretos como jabuticabas.",c:false}, {t:"Ela tem olhos que enxergam longe.",c:false}, {t:"Ela piscou os olhos duas vezes.",c:false}], pts: 4, exp: "A metáfora é uma comparação implícita, sem o conectivo 'como'." },
              { id: "6ANO-PORT-D18", p: "O que caracteriza o sintagma verbal de uma oração?", o: [{t:"Ter como núcleo um verbo e abarcar seus complementos e modificadores",c:true}, {t:"Ter como núcleo obrigatoriamente um adjetivo ou substantivo",c:false}, {t:"Ser composto exclusivamente por advérbios de tempo",c:false}, {t:"Ser a parte da frase que não contém verbos",c:false}], pts: 4, exp: "O sintagma verbal (predicado) articula-se a partir de um verbo núcleo e seus termos agregados." },
              { id: "6ANO-PORT-D19", p: "Na transposição do discurso direto 'Maria disse: — Eu irei hoje!' para o indireto, temos:", o: [{t:"Maria disse que ela iria naquele dia.",c:true}, {t:"Maria disse que eu irei hoje.",c:false}, {t:"Maria disse: — Ela vai hoje!",c:false}, {t:"Maria disse que eu vá amanhã.",c:false}], pts: 4, exp: "No discurso indireto, alteram-se os pronomes ('eu' -> 'ela') e tempos verbais/adverbiais ('irei/hoje' -> 'iria/naquele dia')." },
              { id: "6ANO-PORT-D20", p: "Em um texto de divulgação científica, o recurso da impessoalização é obtido por meio de:", o: [{t:"Uso da 3ª pessoa do verbo e construção da voz passiva",c:true}, {t:"Uso excessivo da 1ª pessoa do singular ('Eu acho')",c:false}, {t:"Emprego frequente de gírias e regionalismos",c:false}, {t:"Exclamações e opiniões pessoais no texto",c:false}], pts: 4, exp: "A 3ª pessoa e construções passivas conferem neutralidade e objetividade ao texto científico." }




        ],
        "História": [
                
         // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
              { id: "6ANO-HIST-F01", p: "Qual das opções a seguir é um exemplo de fonte histórica escrita?", o: [{t:"Carta antiga",c:true}, {t:"Pintura rupestre",c:false}, {t:"Machado de pedra",c:false}, {t:"Depoimento oral",c:false}], pts: 2, exp: "Documentos gravados em papel ou suporte com texto escrito são fontes históricas escritas." },
              { id: "6ANO-HIST-F02", p: "Qual instrumento é utilizado para organizar e medir o tempo em dias, semanas, meses e anos?", o: [{t:"Calendário",c:true}, {t:"Bússola",c:false}, {t:"Termômetro",c:false}, {t:"Balança",c:false}], pts: 2, exp: "O calendário marca as divisões astronômicas e sociais do tempo ao longo dos anos." },
              { id: "6ANO-HIST-F03", p: "Em qual continente foram encontrados os fósseis mais antigos dos primeiros ancestrais humanos?", o: [{t:"África",c:true}, {t:"Europa",c:false}, {t:"América",c:false}, {t:"Oceania",c:false}], pts: 2, exp: "A África é considerada o berço da humanidade devido às evidências fósseis mais antigas." },
              { id: "6ANO-HIST-F04", p: "O que caracteriza o modo de vida nômade dos primeiros grupos humanos?", o: [{t:"Mudar constantemente em busca de alimentos",c:true}, {t:"Construir grandes cidades de pedra",c:false}, {t:"Praticar a agricultura em grandes propriedades",c:false}, {t:"Morar fixamente em um mesmo lugar",c:false}], pts: 2, exp: "Nômades não tinham habitação fixa e deslocavam-se buscando caça e coleta." },
              { id: "6ANO-HIST-F05", p: "Qual transformação no Neolítico permitiu a fixação dos grupos humanos em um único local?", o: [{t:"Desenvolvimento da agricultura",c:true}, {t:"Invenção do computador",c:false}, {t:"Criação das moedas de ouro",c:false}, {t:"Uso do motor a vapor",c:false}], pts: 2, exp: "A prática agrícola permitiu produzir alimento no mesmo local, gerando o sedentarismo." },
              { id: "6ANO-HIST-F06", p: "Como são chamadas as pinturas feitas pelos seres humanos nas paredes das cavernas na Pré-História?", o: [{t:"Pinturas rupestres",c:true}, {t:"Quadros renascentistas",c:false}, {t:"Iluminuras medievais",c:false}, {t:"Afrescos modernos",c:false}], pts: 2, exp: "Pinturas rupestres são desenhos grafados em rochas ou interiores de cavernas." },
              { id: "6ANO-HIST-F07", p: "Qual civilização antiga da Mesopotâmia desenvolveu a escrita cuneiforme?", o: [{t:"Sumérios",c:true}, {t:"Astecas",c:false}, {t:"Gregos",c:false}, {t:"Incas",c:false}], pts: 2, exp: "Os sumérios inventaram a escrita cuneiforme gravando símbolos em placas de argila." },
              { id: "6ANO-HIST-F08", p: "Qual importante rio garantiu a sobrevivência e o desenvolvimento da civilização do Egito Antigo?", o: [{t:"Rio Nilo",c:true}, {t:"Rio Amazonas",c:false}, {t:"Rio Danúbio",c:false}, {t:"Rio Amarelo",c:false}], pts: 2, exp: "As cheias férteis do Rio Nilo permitiam a agricultura e o abastecimento no Egito." },
              { id: "6ANO-HIST-F09", p: "Qual era a função principal das grandes pirâmides construídas no Egito Antigo?", o: [{t:"Túmulos para os faraós",c:true}, {t:"Mercados públicos de grãos",c:false}, {t:"Escolas para a população",c:false}, {t:"Bibliotecas comunitárias",c:false}], pts: 2, exp: "As pirâmides eram monumentos funerários erguidos para abrigar o corpo e tesouros do faraó." },
              { id: "6ANO-HIST-F10", p: "O que era a pólis na Grécia Antiga?", o: [{t:"Cidade-Estado autônoma",c:true}, {t:"Um tipo de barco de guerra",c:false}, {t:"Um templo religioso unificado",c:false}, {t:"Um império centralizado",c:false}], pts: 2, exp: "A pólis grega funcionava como uma cidade-Estado independente com seu próprio governo." },
              { id: "6ANO-HIST-F11", p: "Em qual cidade-Estado grega nasceu a forma de governo conhecida como democracia?", o: [{t:"Atenas",c:true}, {t:"Esparta",c:false}, {t:"Tróia",c:false}, {t:"Tebas",c:false}], pts: 2, exp: "Atenas desenvolveu a democracia direta, onde cidadãos participavam das decisões na ágora." },
              { id: "6ANO-HIST-F12", p: "Qual era o principal objetivo da educação na cidade-Estado de Esparta?", o: [{t:"Formar cidadãos soldados para a guerra",c:true}, {t:"Desenvolver filosofar e poesias",c:false}, {t:"Estimular o comércio marítimo",c:false}, {t:"Formar artesãos e escultores",c:false}], pts: 2, exp: "A sociedade espartana era militarizada e educava seus jovens focando na preparação física e na guerra." },
              { id: "6ANO-HIST-F13", p: "De acordo com a mitologia grega, onde habitavam os principais deuses?", o: [{t:"Monte Olimpo",c:true}, {t:"Pirâmide de Gizé",c:false}, {t:"Coliseu de Roma",c:false}, {t:"Rio Tigre",c:false}], pts: 2, exp: "Na religião grega, o Monte Olimpo era considerado a morada dos deuses do panteão." },
              { id: "6ANO-HIST-F14", p: "Qual era a língua oficial falada no Império Romano?", o: [{t:"Latim",c:true}, {t:"Inglês",c:false}, {t:"Espanhol",c:false}, {t:"Alemão",c:false}], pts: 2, exp: "O latim era o idioma oficial de Roma, dando origem às línguas neolatinas modernas." },
              { id: "6ANO-HIST-F15", p: "Na Roma Antiga, quem constituía a maioria da população formada por comerciantes e camponeses?", o: [{t:"Plebeus",c:true}, {t:"Patrícios",c:false}, {t:"Senadores",c:false}, {t:"Imperadores",c:false}], pts: 2, exp: "Os plebeus eram os cidadãos livres comuns, sem os privilégios da nobreza patrícia." },
              { id: "6ANO-HIST-F16", p: "Como é chamado o sistema social e econômico que predominou na Europa ocidental durante a Idade Média?", o: [{t:"Feudalismo",c:true}, {t:"Capitalismo industrial",c:false}, {t:"Mercantilismo marítimo",c:false}, {t:"Socialismo",c:false}], pts: 2, exp: "O feudalismo organizou a Europa medieval com base na posse da terra (feudo) e servidão." },
              { id: "6ANO-HIST-F17", p: "No sistema feudal, quem realizava o trabalho agrícola diretamente na terra?", o: [{t:"Servos",c:true}, {t:"Senhores feudais",c:false}, {t:"Reis",c:false}, {t:"Sacerdotes",c:false}], pts: 2, exp: "Os servos eram trabalhadores camponeses presos à terra e obrigados a pagar tributos ao senhor." },
              { id: "6ANO-HIST-F18", p: "Qual instituição possuía maior poder religioso, político e cultural na Europa medieval?", o: [{t:"Igreja Católica",c:true}, {t:"Exército romano",c:false}, {t:"Sindicato de operários",c:false}, {t:"Câmara de comerciantes",c:false}], pts: 2, exp: "A Igreja Católica dominava a vida espiritual, ideológica e política durante a Idade Média." },
              { id: "6ANO-HIST-F19", p: "Qual mar interligava a Europa, a África e o Oriente Médio no mundo antigo?", o: [{t:"Mar Mediterrâneo",c:true}, {t:"Oceano Pacífico",c:false}, {t:"Mar Báltico",c:false}, {t:"Mar das Caraíbas",c:false}], pts: 2, exp: "O Mar Mediterrâneo era a grande via de navegação, comércio e trocas culturais do mundo antigo." },
              { id: "6ANO-HIST-F20", p: "Como são chamados os objetos materiais do passado preservados e estudados pelos historiadores?", o: [{t:"Fontes históricas materiais",c:true}, {t:"Documentos orais digitais",c:false}, {t:"Contos de fadas",c:false}, {t:"Leis do presente",c:false}], pts: 2, exp: "Artefatos, ferramentas e edifícios do passado constituem fontes materiais para a história." },
        
         // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
        
              { id: "6ANO-HIST-M01", p: "Como a oralidade atua na preservação da memória para comunidades indígenas e quilombolas?", o: [{t:"Transmitem histórias e valores entre gerações pela fala",c:true}, {t:"Registram suas leis em livros impressos de papel",c:false}, {t:"Utilizam apenas redes sociais e mídias virtuais",c:false}, {t:"Substituem totalmente o tempo presente pelo futuro",c:false}], pts: 3, exp: "A tradição oral é vital na manutenção da cultura, ancestralidade e saberes dessas comunidades." },
              { id: "6ANO-HIST-M02", p: "Qual a importância dos sítios arqueológicos como os da Serra da Capivara (Piauí) no Brasil?", o: [{t:"Revelam vestígios da presença humana antiga na América",c:true}, {t:"Mostram a chegada dos colonizadores europeus no século XIX",c:false}, {t:"Comprovam o surgimento das indústrias modernas",c:false}, {t:"Apenas guardam réplicas de vegetação atual",c:false}], pts: 3, exp: "A Serra da Capivara possui arte rupestre e vestígios que comprovam ocupação humana milenar na América." },
              { id: "6ANO-HIST-M03", p: "De acordo com a teoria do Estreito de Bering, como os primeiros humanos chegaram à América?", o: [{t:"Atravessando uma ponte de gelo entre a Ásia e a América",c:true}, {t:"Navegando em caravelas europeias durante o século XV",c:false}, {t:"Utilizando aviões comerciais vindos da Oceania",c:false}, {t:"Caminhando pela Antártida até chegarem ao Brasil",c:false}], pts: 3, exp: "A hipótese do Estreito de Bering aponta a passagem terrestre/glaciar da Ásia para a América do Norte." },
              { id: "6ANO-HIST-M04", p: "Como a sociedade maia registrava suas informações astronômicas, rituais e históricas?", o: [{t:"Utilizando um sistema de escrita hieroglífica em códices",c:true}, {t:"Usando máquinas de datilografar de metal",c:false}, {t:"Dependendo exclusivamente da gravação de áudios",c:false}, {t:"Escrevendo com o alfabeto latino trazido pelos romanos",c:false}], pts: 3, exp: "Os maias desenvolveram escrita hieroglífica complexa registrada em livros de casca de árvore (códices)." },
              { id: "6ANO-HIST-M05", p: "O que eram os quipus utilizados pelos Incas na região dos Andes?", o: [{t:"Cordões com nós para contagem de dados e registros",c:true}, {t:"Monedas de ferro usadas no comércio com a Europa",c:false}, {t:"Armas de fogo usadas no exército inca",c:false}, {t:"Livros de papelão com ilustrações coloridas",c:false}], pts: 3, exp: "Os quipus eram cordas coloridas com nós usadas para contabilidade e registro de informações incas." },
              { id: "6ANO-HIST-M06", p: "Qual o papel político e religioso do Faraó na sociedade do Egito Antigo?", o: [{t:"Considerado um deus vivo e governante absoluto",c:true}, {t:"Um presidente eleito pelo voto popular a cada quatro anos",c:false}, {t:"Um chefe militar sem poder sobre as leis da religião",c:false}, {t:"Um funcionário público subordinado aos camponeses",c:false}], pts: 3, exp: "A teocracia egípcia considerava o Faraó a encarnação divina no comando político e religioso." },
              { id: "6ANO-HIST-M07", p: "O famoso Código de Hamurábi na Mesopotâmia fundamentava-se em qual princípio jurídico?", o: [{t:"Lei do Talião (olho por olho, dente por dente)",c:true}, {t:"Direitos humanos universais para todos",c:false}, {t:"Pagamento exclusivo de cestas básicas como pena",c:false}, {t:"Anistia total para qualquer crime cometido",c:false}], pts: 3, exp: "A Lei do Talião estabelecia uma punição proporcional e idêntica ao dano provocado." },
              { id: "6ANO-HIST-M08", p: "Quem podia exercer o direito de cidadania na democracia de Atenas na Antiguidade?", o: [{t:"Apenas homens livres, adultos, atenienses e proprietários",c:true}, {t:"Todas as mulheres, crianças e imigrantes sem exceção",c:false}, {t:"Apenas as pessoas escravizadas vindas de outras regiões",c:false}, {t:"Todos os habitantes nascidos no continente africano",c:false}], pts: 3, exp: "A democracia ateniense era excludente; mulheres, escravos e estrangeiros (metecos) não eram cidadãos." },
              { id: "6ANO-HIST-M09", p: "Quem eram os patrícios na estrutura social da República Romana?", o: [{t:"Grandes proprietários de terras e membros da elite nobre",c:true}, {t:"Estrangeiros sem direitos civis no Império",c:false}, {t:"Pessoas escravizadas capturadas em guerras",c:false}, {t:"Pequenos artesãos sem acesso ao Senado",c:false}], pts: 3, exp: "Os patrícios detinham privilégios políticos, terras e ocupavam os principais cargos no Senado romano." },
              { id: "6ANO-HIST-M10", p: "Qual órgão de governo concentrava maior poder na República Romana?", o: [{t:"Senado romano",c:true}, {t:"Assembleia popular de plebeus",c:false}, {t:"Tribunal da Inquisição",c:false}, {t:"Conselho de bispos",c:false}], pts: 3, exp: "O Senado, composto por patrícios, controlava as finanças, política externa e leis em Roma." },
              { id: "6ANO-HIST-M11", p: "Uma das consequências econômicas do processo de expansão territorial do Império Romano foi:", o: [{t:"Aumento do número de pessoas escravizadas por conquistas",c:true}, {t:"Fim total do comércio de mercadorias no Mar Mediterrâneo",c:false}, {t:"Eliminação da cobrança de impostos nas províncias",c:false}, {t:"Divisão das terras agrícolas igualmente entre os servos",c:false}], pts: 3, exp: "As guerras de conquista romanas traziam milhares de prisioneiros transformados em mão de obra escrava." },
              { id: "6ANO-HIST-M12", p: "O que caracterizava a política da Pax Romana no início do período imperial?", o: [{t:"Estabilidade interna e expansão das rotas comerciais",c:true}, {t:"Fim de todas as leis e desintegração do exército",c:false}, {t:"Libertação imediata de todos os escravos rurais",c:false}, {t:"Mudança da capital romana para a América do Sul",c:false}], pts: 3, exp: "A Pax Romana foi um período de relativa paz interna, centralização do poder e prosperidade econômica." },
              { id: "6ANO-HIST-M13", p: "A transição do mundo antigo para o mundo medieval europeu foi marcada por qual evento histórico?", o: [{t:"Desagregação do Império Romano do Ocidente e invasões germânicas",c:true}, {t:"Independência das colônias americanas",c:false}, {t:"Revolução Industrial nas grandes fábricas urbanas",c:false}, {t:"Invenção da imprensa de tipos móveis por Gutenberg",c:false}], pts: 3, exp: "A queda de Roma em 476 d.C. e as migrações germânicas deram origem à ruralização feudal." },
              { id: "6ANO-HIST-M14", p: "Como funcionava o vínculo de suserania e vassalagem entre nobres na Idade Média?", o: [{t:"Aliança de fidelidade e proteção em troca de terras",c:true}, {t:"Venda de títulos nobres em mercados abertos na cidade",c:false}, {t:"Eleição por voto secreto a cada cinco anos",c:false}, {t:"Relação de trabalho escravo entre um nobre e um camponês",c:false}], pts: 3, exp: "O suserano doava terras (feudos) ao vassalo, que jurava lealdade e ajuda militar nas guerras." },
              { id: "6ANO-HIST-M15", p: "Qual a diferença central entre o escravo no mundo antigo e o servo feudal medieval?", o: [{t:"O servo não era propriedade do senhor e estava preso à terra",c:true}, {t:"O servo recebia salário fixo semanal em moedas de ouro",c:false}, {t:"O escravo tinha pleno acesso aos cargos políticos de Roma",c:false}, {t:"O servo podia vender a terra do feudo quando quisesse",c:false}], pts: 3, exp: "Ao contrário do escravo (visto como posse), o servo medieval estava vinculado à terra com deveres fixos." },
              { id: "6ANO-HIST-M16", p: "De que forma a Igreja Católica exercia controle social e cultural na Idade Média?", o: [{t:"Definindo normas morais, condutas e monopolizando a escrita",c:true}, {t:"Criando leis que proibiam a prática da religião cristã",c:false}, {t:"Incentivando a liberdade total de culto de deuses gregos",c:false}, {t:"Transferindo as decisões de fé para os reis germânicos",c:false}], pts: 3, exp: "A Igreja controlava o conhecimento letrado (cópia de manuscritos nos mosteiros) e a conduta moral." },
              { id: "6ANO-HIST-M17", p: "Qual era a condição social geral reservada às mulheres na maioria das pólis gregas clássicas?", o: [{t:"Restritas ao espaço doméstico e sem direitos políticos",c:true}, {t:"Líderes exclusivas do exército e do Senado grego",c:false}, {t:"Únicas responsáveis por votar nas assembleias de Atenas",c:false}, {t:"Iguais aos homens em salários e funções governamentais",c:false}], pts: 3, exp: "A mulher grega clássica era tutelada pelo pai ou marido e excluída da participação política." },
              { id: "6ANO-HIST-M18", p: "Qual o papel dos mosteiros medievais na preservação da cultura letrada?", o: [{t:"Os monges copistas preservavam e traduziam manuscritos antigos",c:true}, {t:"Fabricavam armas de fogo para os reis feudais",c:false}, {t:"Queimavam todos os livros trazidos da antiguidade",c:false}, {t:"Promoviam encontros de navegação de longa distância",c:false}], pts: 3, exp: "Nos mosteiros, monges copistas reproduziam textos religiosos e filosóficos garantindo sua preservação." },
              { id: "6ANO-HIST-M19", p: "Como os povos originários do Ceará se relacionavam com o meio ambiente antes da colonização?", o: [{t:"Praticavam manejo sustentável com caça, pesca e agricultura itinerante",c:true}, {t:"Promoviam desmatamento industrial para exportar madeira",c:false}, {t:"Construíam grandes usinas poluidoras nas margens dos rios",c:false}, {t:"Criavam rebanhos bovinos em grande escala comercial",c:false}], pts: 3, exp: "Os povos originários do Ceará viviam de forma integrada à natureza sem exaurir os recursos naturais." },
              { id: "6ANO-HIST-M20", p: "Por que a periodização quadripartite tradicional (Antiga, Medieval, Moderna e Contemporânea) recebe críticas historiográficas?", o: [{t:"Por ser focada na história europeia e ignorar outras regiões",c:true}, {t:"Por utilizar datas baseadas exclusivamente na América",c:false}, {t:"Por negar o papel dos reis e de grandes monumentos",c:false}, {t:"Por ter sido elaborada por povos originários indígenas",c:false}], pts: 3, exp: "A divisão quadripartite é eurocêntrica, tomando marcos da Europa como universais para a humanidade." },
        
         // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================     
              { id: "6ANO-HIST-D01", p: "De acordo com o DCRFor, o que propõe o paradigma da decolonialidade no ensino de História?", o: [{t:"Questionar narrativas eurocêntricas e valorizar saberes indígenas e africanos",c:true}, {t:"Reforçar a supremacia das teorias europeias sobre o mundo",c:false}, {t:"Eliminar totalmente o estudo dos povos do passado",c:false}, {t:"Aprender apenas as datas comemorativas dos reis europeus",c:false}], pts: 4, exp: "A decolonialidade busca desconstruir a visão eurocêntrica e dar visibilidade a sujeitos historicamente silenciados." },
              { id: "6ANO-HIST-D02", p: "Por que a atribuição de significância histórica a um acontecimento envolve escolhas no presente?", o: [{t:"Porque o historiador seleciona fatos segundo perguntas e visões do seu tempo",c:true}, {t:"Porque os fatos históricos são eventos neutros e imutáveis",c:false}, {t:"Porque apenas os governantes decidem o que é verdade absoluta",c:false}, {t:"Porque todos os acontecimentos têm exatamente o mesmo impacto",c:false}], pts: 4, exp: "A significância é uma construção analítica onde escolhas determinam o que ganha destaque na narrativa." },
              { id: "6ANO-HIST-D03", p: "Como a Filosofia Ubuntu das sociedades Banto na África compreende a existência humana?", o: [{t:"Pelo princípio comunitário de que 'eu sou porque nós somos'",c:true}, {t:"Pelo individualismo absoluto focado no acúmulo de moedas",c:false}, {t:"Pela separação total entre o indivíduo e sua comunidade",c:false}, {t:"Pela dominação militar de outros povos sem diálogo",c:false}], pts: 4, exp: "O conceito Ubuntu enfatiza a cooperação, a coletividade e o respeito mútuo entre as pessoas." },
              { id: "6ANO-HIST-D04", p: "O que eram as sociedades linhageiras da África antes do processo de colonização europeia?", o: [{t:"Comunidades organizadas em parentesco e laços familiares sem Estado centralizado",c:true}, {t:"Impérios absolutistas que copiavam as leis dos reis franceses",c:false}, {t:"Cidades modernas governadas por indústrias multinacionais",c:false}, {t:"Sociedades sem cultura ou forma de organização social",c:false}], pts: 4, exp: "Sociedades linhageiras fundamentavam sua organização política nas linhagens familiares e alianças de parentesco." },
              { id: "6ANO-HIST-D05", p: "Em que a escravidão do mundo antigo diferi do conceito de escravidão moderna nas Américas?", o: [{t:"A antiga decorria de guerras/dívidas, a moderna ligou-se ao racismo estrutural",c:true}, {t:"A escravidão antiga era exclusivamente baseada na cor da pele das pessoas",c:false}, {t:"A escravidão moderna garantia direitos trabalhistas plenos aos cativos",c:false}, {t:"Não havia nenhuma diferença entre os dois modelos de escravização",c:false}], pts: 4, exp: "A escravidão moderna esteve associada à exploração mercantil capitalista e à racialização dos corpos." },
              { id: "6ANO-HIST-D06", p: "Qual o objetivo das propostas de reforma agrária apresentadas pelos irmãos Graco na República Romana?", o: [{t:"Distribuir terras aos plebeus empobrecidos reduzindo tensões sociais",c:true}, {t:"Entregar todas as fazendas exclusivamente aos patrícios do Senado",c:false}, {t:"Abolir o exército romano e transformar Roma em uma colônia grega",c:false}, {t:"Proibir o cultivo de alimentos nas áreas rurais italianas",c:false}], pts: 4, exp: "Os tribunos Tibério e Caio Graco tentaram diminuir a miséria urbana distribuindo terras públicas à plebe." },
              { id: "6ANO-HIST-D07", p: "Mesmo divididas politicamente em cidades-Estado, o que garantia a unidade cultural entre os gregos?", o: [{t:"Língua comum, religião e participação nos Jogos Olímpicos",c:true}, {t:"Um único rei absoluto que governava todas as cidades",c:false}, {t:"Submissão completa às leis criadas pelo Império Egípcio",c:false}, {t:"Uso de uma mesma moeda impressa em banco central",c:false}], pts: 4, exp: "O pertencimento ao mundo helênico era definido pela fala do idioma grego e pelas práticas religiosas compartilhadas." },
              { id: "6ANO-HIST-D08", p: "O conceito de 'bárbaro' utilizado por gregos e romanos tinha como intenção original:", o: [{t:"Diferenciar e inferiorizar quem não compartilhava sua língua e cultura",c:true}, {t:"Elogiar o desenvolvimento tecnológico de povos vizinhos",c:false}, {t:"Definir cidadãos que possuíam mais direitos políticos no Senado",c:false}, {t:"Identificar apenas pessoas diplomadas nas universidades antigas",c:false}], pts: 4, exp: "Bárbaro era todo aquele fora do mundo helênico/romano, usado para reforçar a superioridade de sua civilização." },
              { id: "6ANO-HIST-D09", p: "Qual foi o impacto socioeconômico da Peste Negra (século XIV) na estrutura do feudalismo europeu?", o: [{t:"A escassez de mão de obra fortaleceu a exigência de melhores condições pelos camponeses",c:true}, {t:"Aumentou a população servil acabando com as revoltas camponesas",c:false}, {t:"Fortaleceu o poder de dominação absoluta dos senhores feudais",c:false}, {t:"Causou a imediata conversão de toda a Europa ao islamismo",c:false}], pts: 4, exp: "A queda demográfica gerou escassez de trabalhadores, abrindo espaço para revoltas e enfraquecimento da servidão." },
              { id: "6ANO-HIST-D10", p: "De que modo a rede comercial do Mar Mediterrâneo propiciava aculturações na Antiguidade?", o: [{t:"Pelo intercâmbio constante de produtos, tecnologias, ideias e religiões entre povos",c:true}, {t:"Pela proibição absoluta de contato cultural entre comerciantes de áreas distintas",c:false}, {t:"Pela destruição de todas as mercadorias trazidas da África para a Europa",c:false}, {t:"Pelo isolamento de cada civilização sem trocas linguísticas",c:false}], pts: 4, exp: "A navegação fenícia, grega e egípcia no Mediterrâneo promovia difusão cultural e linguística contínua." },
              { id: "6ANO-HIST-D11", p: "A sedentarização do Neolítico e o surgimento das primeiras vilas provocaram qual mudança nas relações sociais?", o: [{t:"Surgimento da divisão do trabalho e início da propriedade privada",c:true}, {t:"Fim das rivalidades e desaparecimento completo das guerras",c:false}, {t:"Extinção de todas as formas de liderança ou autoridade política",c:false}, {t:"Abandono imediato do uso de fogo e de ferramentas de pedra",c:false}], pts: 4, exp: "O excedente agrícola gerou diferenciação social, especialização do trabalho e disputas por posse de terras." },
              { id: "6ANO-HIST-D12", p: "Como as lutas da plebe (Conflito das Ordens) em Roma resultaram em avanços jurídicos como a Lei das Doze Tábuas?", o: [{t:"Registraram leis por escrito impedindo abusos nas interpretações dos patrícios",c:true}, {t:"Eliminaram totalmente as diferenças sociais entre patrícios e plebeus",c:false}, {t:"Proibiram plebeus de possuírem propriedades e bens materiais",c:false}, {t:"Transferiram o controle do governo para reis estrangeiros",c:false}], pts: 4, exp: "A fixação das leis por escrito (Doze Tábuas) evitou a manipulação oral do direito pelos patrícios." },
              { id: "6ANO-HIST-D13", p: "Qual a contradição entre a noção de 'democracia' e a estrutura social da Atenas Clássica?", o: [{t:"Apesar de discursar sobre igualdade, baseava-se na exclusão e na escravidão",c:true}, {t:"Não havia assembleias públicas para debates no espaço da ágora",c:false}, {t:"Todos os reis mantinham poder absoluto sem votar nas decisões",c:false}, {t:"Apenas estrangeiros podiam candidatar-se aos cargos de governo",c:false}], pts: 4, exp: "A democracia ateniense apoiava-se na exclusão de mulheres, metecos e no trabalho de escravizados." },
              { id: "6ANO-HIST-D14", p: "Por que os registros produzidos sobre mulheres na Idade Média devem ser analisados criticamente?", o: [{t:"Porque foram escritos majoritariamente por homens clérigos sob visões morais da época",c:true}, {t:"Porque as mulheres medievais escreviam todos os livros oficiais da época",c:false}, {t:"Porque não existe qualquer documento medieval que mencione figuras femininas",c:false}, {t:"Porque a Igreja proibia qualquer representação de mulheres na arte",c:false}], pts: 4, exp: "As fontes históricas medievais escritas pela elite clerical refletiam estereótipos religiosos do discurso masculino." },
              { id: "6ANO-HIST-D15", p: "De que forma as rotas comerciais transarianas impulsionaram reinos africanos como o Império do Mali?", o: [{t:"Conectaram o comércio de ouro e sal às redes do Norte da África e do Oriente",c:true}, {t:"Isolaram a África ocidental impedindo o contato com a religião islâmica",c:false}, {t:"Provocaram o empobrecimento imediato das cidades comerciais como Tombouctou",c:false}, {t:"Dependiam da navegação europeia a vapor para cruzar os desertos",c:false}], pts: 4, exp: "O comércio de ouro, sal e saberes fortaleceu politicamente e culturalmente centros urbanos como Tombouctou." },
              { id: "6ANO-HIST-D16", p: "O que distingue o conceito histórico de 'acontecimento' na visão historiográfica contemporânea?", o: [{t:"Um evento que altera a realidade presente e rompe com a normalidade social",c:true}, {t:"Qualquer fato corriqueiro que acontece sem gerar consequências",c:false}, {t:"Apenas grandes guerras travadas por imperadores europeus",c:false}, {t:"Um dado estático que pode ser previsto matematicamente",c:false}], pts: 4, exp: "Acontecimento é a ruptura que produz transformações significativas nas trajetórias individuais ou coletivas." },
              { id: "6ANO-HIST-D17", p: "Como a historiografia recente compreende o povoamento do continente americano antes da colonização?", o: [{t:"Como resultado de múltiplas rotas de migração em diferentes ondas temporais",c:true}, {t:"Como um evento único de migração ocorrido no século XV por navios",c:false}, {t:"Como a chegada simultânea de povos que já dominavam a escrita latina",c:false}, {t:"Como uma história sem diversidade de línguas e culturas originárias",c:false}], pts: 4, exp: "Estudos arqueológicos e genéticos apontam para múltiplos fluxos migratórios (terrestres e marítimos) na América." },
              { id: "6ANO-HIST-D18", p: "Qual o papel dos rituais religiosos no Império Asteca no período pré-colombiano?", o: [{t:"Legitimar a autoridade política do imperador e manter o equilíbrio do universo",c:true}, {t:"Copiar as tradições cristãs trazidas pelos navegadores do Mediterrâneo",c:false}, {t:"Eliminar a divisão social promovendo a igualdade econômica",c:false}, {t:"Proibir a construção de monumentos e templos de pedra",c:false}], pts: 4, exp: "A religião asteca integrava o poder político e militar, justificando a expansão e o controle sobre outros povos." },
              { id: "6ANO-HIST-D19", p: "Por que o papel dos Griôs (jalis) na África Ocidental é reconhecido pela ciência histórica?", o: [{t:"Eles guardam rigorosamente a memória e genealogias através da tradição oral",c:true}, {t:"Eles inventaram a imprensa de papel no século XII",c:false}, {t:"Eles eram sacerdotes romanos instalados no continente africano",c:false}, {t:"Eles escreviam diários em latim para reis europeus",c:false}], pts: 4, exp: "Os griôs são guardiões da memória comunitária cuja tradição oral é fonte de preservação do passado." },
              { id: "6ANO-HIST-D20", p: "O que significa analisar as fontes históricas compreendendo sua 'intencionalidade'?", o: [{t:"Questionar quem produziu o documento, para quem e com quais interesses",c:true}, {t:"Acreditar que os documentos antigos mostram a verdade pura e sem desvios",c:false}, {t:"Aceitar que os textos escritos são superiores a relatos orais e objetos",c:false}, {t:"Ignorar o contexto em que a fonte foi produzida e preservada",c:false}], pts: 4, exp: "Documentos não são neutros; expressam a visão do autor, seu grupo social, época e objetivos." }
        
        ],




        "Ciências": [
          // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
              { id: "6ANO-CIEN-F01", p: "O que é a célula na biologia?", o: [{t:"A unidade básica da vida",c:true}, {t:"A camada de ar do planeta",c:false}, {t:"Um mineral das rochas",c:false}, {t:"Um fluido corporal",c:false}], pts: 2, exp: "A célula é a menor unidade estrutural e funcional que forma os seres vivos." },
              { id: "6ANO-CIEN-F02", p: "Qual mistura é considerada homogênea?", o: [{t:"Água com sal totalmente dissolvido",c:true}, {t:"Água com areia",c:false}, {t:"Água com óleo",c:false}, {t:"Salada de frutas",c:false}], pts: 2, exp: "Misturas homogêneas apresentam uma única fase visualmente uniforme." },
              { id: "6ANO-CIEN-F03", p: "Em qual estado físico a água se encontra na forma de gelo?", o: [{t:"Sólido",c:true}, {t:"Líquido",c:false}, {t:"Gasoso",c:false}, {t:"Plasmático",c:false}], pts: 2, exp: "O gelo representa a água em seu estado físico sólido." },
              { id: "6ANO-CIEN-F04", p: "Qual é a função principal do sistema digestório?", o: [{t:"Transformar os alimentos em nutrientes",c:true}, {t:"Transportar oxigênio no sangue",c:false}, {t:"Filtrar a urina do corpo",c:false}, {t:"Comandar os movimentos do corpo",c:false}], pts: 2, exp: "O sistema digestório quebra os alimentos para que o corpo absorva nutrientes." },
              { id: "6ANO-CIEN-F05", p: "Como é chamada a camada de ar que envolve a Terra?", o: [{t:"Atmosfera",c:true}, {t:"Litosfera",c:false}, {t:"Hidrosfera",c:false}, {t:"Biosfera",c:false}], pts: 2, exp: "A atmosfera é a camada gasosa que envolve e protege o planeta Terra." },
              { id: "6ANO-CIEN-F06", p: "O Sol é classificado astronomicamente como uma:", o: [{t:"Estrela",c:true}, {t:"Galáxia",c:false}, {t:"Planeta rochoso",c:false}, {t:"Lua artificial",c:false}], pts: 2, exp: "O Sol é a estrela central do nosso Sistema Solar e produz luz e calor próprios." },
              { id: "6ANO-CIEN-F07", p: "Qual movimento da Terra dá origem ao dia e à noite?", o: [{t:"Rotação",c:true}, {t:"Translação",c:false}, {t:"Precessão",c:false}, {t:"Nutação",c:false}], pts: 2, exp: "A rotação é o giro da Terra em torno do seu próprio eixo, dura 24h e gera dia e noite." },
              { id: "6ANO-CIEN-F08", p: "Qual gás é absorvido pelo nosso corpo durante a inspiração?", o: [{t:"Gás Oxigênio",c:true}, {t:"Gás Carbônico",c:false}, {t:"Metano",c:false}, {t:"Hélio",c:false}], pts: 2, exp: "Na respiração, o organismo capta gás oxigênio do ar e expulsa gás carbônico." },
              { id: "6ANO-CIEN-F09", p: "Qual equipamento é utilizado para observar estruturas microscópicas como as células?", o: [{t:"Microscópio",c:true}, {t:"Telescópio",c:false}, {t:"Lupa de mão simples",c:false}, {t:"Termômetro",c:false}], pts: 2, exp: "O microscópio amplia imagens de estruturas invisíveis a olho nu." },
              { id: "6ANO-CIEN-F10", p: "Quais estruturas sustentam o corpo e atuam junto com os músculos para o movimento?", o: [{t:"Ossos",c:true}, {t:"Veias",c:false}, {t:"Pulmões",c:false}, {t:"Nervos",c:false}], pts: 2, exp: "Os ossos formam o esqueleto que sustenta o corpo e permite a locomoção." },
              { id: "6ANO-CIEN-F11", p: "A mudança da água do estado líquido para o estado gasoso é chamada de:", o: [{t:"Vaporização",c:true}, {t:"Solidificação",c:false}, {t:"Fusão",c:false}, {t:"Condensação",c:false}], pts: 2, exp: "A vaporização ocorre quando a matéria passa da fase líquida para a gasosa." },
              { id: "6ANO-CIEN-F12", p: "A camada sólida superficial da Terra, onde pisamos e cultivamos, é a:", o: [{t:"Crosta terrestre",c:true}, {t:"Núcleo interno",c:false}, {t:"Manto inferior",c:false}, {t:"Atmosfera",c:false}], pts: 2, exp: "A crosta terrestre é a camada rochosa externa e mais fina do planeta." },
              { id: "6ANO-CIEN-F13", p: "Como é chamada a água própria para o consumo humano sem riscos à saúde?", o: [{t:"Água potável",c:true}, {t:"Água salobra",c:false}, {t:"Água destilada",c:false}, {t:"Água poluída",c:false}], pts: 2, exp: "Água potável é limpa, inodora, insípida e segura para o consumo." },
              { id: "6ANO-CIEN-F14", p: "Qual dos cinco sentidos humanos utiliza os olhos como órgãos receptores?", o: [{t:"Visão",c:true}, {t:"Audição",c:false}, {t:"Tato",c:false}, {t:"Olfato",c:false}], pts: 2, exp: "Os olhos captam os estímulos luminosos do ambiente proporcionando a visão." },
              { id: "6ANO-CIEN-F15", p: "Qual órgão muscular é responsável por bombear o sangue por todo o corpo?", o: [{t:"Coração",c:true}, {t:"Fígado",c:false}, {t:"Estômago",c:false}, {t:"Rim",c:false}], pts: 2, exp: "O coração funciona como uma bomba contrátil empurrando o sangue pelos vasos." },
              { id: "6ANO-CIEN-F16", p: "Qual é o planeta mais próximo do Sol no Sistema Solar?", o: [{t:"Mercúrio",c:true}, {t:"Terra",c:false}, {t:"Júpiter",c:false}, {t:"Netuno",c:false}], pts: 2, exp: "Mercúrio é o primeiro planeta a partir do Sol." },
              { id: "6ANO-CIEN-F17", p: "Qual organela presente nas células vegetais realiza a fotossíntese?", o: [{t:"Cloroplasto",c:true}, {t:"Lisossomo",c:false}, {t:"Ribossomo",c:false}, {t:"Centríolo",c:false}], pts: 2, exp: "Os cloroplastos contêm clorofila e captam luz para realizar a fotossíntese." },
              { id: "6ANO-CIEN-F18", p: "Ao misturar água e óleo em um copo, observamos uma mistura:", o: [{t:"Heterogênea",c:true}, {t:"Homogênea",c:false}, {t:"Pura",c:false}, {t:"Solúvel",c:false}], pts: 2, exp: "Água e óleo não se misturam, apresentando duas fases (heterogênea)." },
              { id: "6ANO-CIEN-F19", p: "O movimento de translação da Terra ao redor do Sol leva aproximadamente:", o: [{t:"365 dias (1 ano)",c:true}, {t:"24 horas (1 dia)",c:false}, {t:"28 dias (1 mês)",c:false}, {t:"12 horas",c:false}], pts: 2, exp: "A translação completa dura cerca de 1 ano e gera as estações do ano." },
              { id: "6ANO-CIEN-F20", p: "Qual é a célula principal do sistema nervoso encarregada de transmitir impulsos elétricos?", o: [{t:"Neurônio",c:true}, {t:"Hemácia",c:false}, {t:"Osteócito",c:false}, {t:"Miócito",c:false}], pts: 2, exp: "Os neurônios transmitem sinais elétricos no cérebro e corpo." },

        
        
        
          // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
              { id: "6ANO-CIEN-M01", p: "Qual organela celular é conhecida como a 'usina de energia' por realizar a respiração celular?", o: [{t:"Mitocôndria",c:true}, {t:"Complexo de Golgi",c:false}, {t:"Retículo endoplasmático",c:false}, {t:"Vacúolo",c:false}], pts: 3, exp: "As mitocôndrias produzem energia (ATP) para a célula a partir da glicose e oxigênio." },
              { id: "6ANO-CIEN-M02", p: "Qual método é mais adequado para separar uma mistura de água e areia?", o: [{t:"Filtração",c:true}, {t:"Destilação simples",c:false}, {t:"Catação",c:false}, {t:"Separação magnética",c:false}], pts: 3, exp: "A filtração retém o sólido (areia) no filtro enquanto o líquido (água) passa." },
              { id: "6ANO-CIEN-M03", p: "A principal diferença entre uma célula eucariótica e uma procariótica é:", o: [{t:"A presença de núcleo individualizado delimitado por membrana",c:true}, {t:"A presença de citoplasma fluido",c:false}, {t:"A capacidade de produzir energia",c:false}, {t:"A existência de membrana plasmática",c:false}], pts: 3, exp: "Eucariotos possuem núcleo verdadeiro envolvendo o DNA, enquanto procariotos não têm." },
              { id: "6ANO-CIEN-M04", p: "A propriedade da membrana plasmática de selecionar o que entra e sai da célula chama-se:", o: [{t:"Permeabilidade seletiva",c:true}, {t:"Solubilidade total",c:false}, {t:"Tensão superficial",c:false}, {t:"Capilaridade",c:false}], pts: 3, exp: "A permeabilidade seletiva controla a entrada de substâncias úteis e a saída de resíduos." },
              { id: "6ANO-CIEN-M05", p: "Qual das alternativas representa uma transformação química da matéria?", o: [{t:"Queimar uma folha de papel",c:true}, {t:"Rasgar um pedaço de papel",c:false}, {t:"Derreter um cubo de gelo",c:false}, {t:"Quebrar um copo de vidro",c:false}], pts: 3, exp: "A queima forma novas substâncias (cinzas, fumaça), alterando a composição química." },
              { id: "6ANO-CIEN-M06", p: "Onde ocorrem as trocas gasosas entre o ar inspirado e o sangue dentro dos pulmões?", o: [{t:"Alvéolos pulmonares",c:true}, {t:"Traqueia",c:false}, {t:"Laringe",c:false}, {t:"Fossas nasais",c:false}], pts: 3, exp: "A hematose (troca gasosa) acontece nas paredes microscópicas dos alvéolos pulmonares." },
              { id: "6ANO-CIEN-M07", p: "A camada de ozônio presente na atmosfera é fundamental para a vida pois:", o: [{t:"Filtra os raios ultravioleta (UV) nocivos do Sol",c:true}, {t:"Aumenta a quantidade de oxigênio para respirarmos",c:false}, {t:"Impede que os meteoros atinjam a superfície",c:false}, {t:"Mantém os oceanos em estado líquido",c:false}], pts: 3, exp: "O ozônio (O3) absorve grande parte da radiação UV prejudicial à saúde." },
              { id: "6ANO-CIEN-M08", p: "Como podemos recuperar o sal dissolvido em uma mistura de água e sal de cozinha?", o: [{t:"Evaporação ou destilação",c:true}, {t:"Filtração simples",c:false}, {t:"Peneiramento",c:false}, {t:"Decantação rápida",c:false}], pts: 3, exp: "Como o sal está dissolvido, é necessário evaporar a água para obter o sólido." },
              { id: "6ANO-CIEN-M09", p: "As hemácias (glóbulos vermelhos) do sangue têm como função principal:", o: [{t:"Transportar oxigênio aos tecidos",c:true}, {t:"Defender o corpo contra infecções",c:false}, {t:"Promover a coagulação sanguínea",c:false}, {t:"Digerir proteínas do alimento",c:false}], pts: 3, exp: "A hemoglobina presente nas hemácias liga-se ao oxigênio transportando-o às células." },
              { id: "6ANO-CIEN-M10", p: "Rochas magmáticas ou ígneas são formadas a partir do:", o: [{t:"Resfriamento e petrificação do magma ou lava",c:true}, {t:"Acúmulo e compactação de restos de plantas",c:false}, {t:"Desgaste contínuo provocado pelo vento nas praias",c:false}, {t:"Esmagamento de rochas antigas por alta pressão",c:false}], pts: 3, exp: "O magma resfriado e solidificado origina as rochas magmáticas (ex: basalto e granito)." },
              { id: "6ANO-CIEN-M11", p: "Um eclipse solar total ocorre quando ocorre qual alinhamento celestial?", o: [{t:"A Lua fica entre a Terra e o Sol",c:true}, {t:"A Terra fica entre o Sol e a Lua",c:false}, {t:"O Sol fica entre a Terra e a Lua",c:false}, {t:"Júpiter esconde a luz do Sol",c:false}], pts: 3, exp: "No eclipse solar, a Lua projeta sua sombra sobre a Terra ao passar entre ela e o Sol." },
              { id: "6ANO-CIEN-M12", p: "Qual estrutura do sistema osteomuscular conecta os músculos aos ossos?", o: [{t:"Tendão",c:true}, {t:"Cartilagem de articulação",c:false}, {t:"Medula óssea",c:false}, {t:"Neurônio motor",c:false}], pts: 3, exp: "Os tendões são cordões resistentes que ligam os músculos aos ossos permitindo tração." },
              { id: "6ANO-CIEN-M13", p: "As gotas de água formadas no lado de fora de um copo gelado surgem por:", o: [{t:"Condensação do vapor de água do ar",c:true}, {t:"Vazamento da água através do vidro",c:false}, {t:"Evaporação do suco dentro do copo",c:false}, {t:"Sublimação do gelo no interior",c:false}], pts: 3, exp: "O vapor de água do ar em contato com o vidro frio resfria e passa para o estado líquido." },
              { id: "6ANO-CIEN-M14", p: "O processo de alteração física e química das rochas provocado por água, vento e seres vivos é o:", o: [{t:"Intemperismo",c:true}, {t:"Magnetismo",c:false}, {t:"Efeito estufa",c:false}, {t:"Metamorfismo estelar",c:false}], pts: 3, exp: "O intemperismo desgasta e fragmenta as rochas, auxiliando na formação do solo." },
              { id: "6ANO-CIEN-M15", p: "Quais estruturas presentes nas folhas das plantas controlam as trocas gasosas e a transpiração?", o: [{t:"Estômatos",c:true}, {t:"Xilema",c:false}, {t:"Raízes primárias",c:false}, {t:"Pétalas",c:false}], pts: 3, exp: "Os estômatos abrem e fecham para permitir a entrada de CO2 e liberação de vapor de água e O2." },
              { id: "6ANO-CIEN-M16", p: "Em uma solução de água com açúcar, o açúcar é classificado como:", o: [{t:"Soluto",c:true}, {t:"Solvente",c:false}, {t:"Mistura heterogênea",c:false}, {t:"Fase insolúvel",c:false}], pts: 3, exp: "O soluto é a substância dissolvida (açúcar) e a água atua como solvente." },
              { id: "6ANO-CIEN-M17", p: "O desvio na trajetória da luz ao passar de um meio transparente para outro (como ar para vidro) é a:", o: [{t:"Refração",c:true}, {t:"Reflexão espelhada",c:false}, {t:"Absorção total",c:false}, {t:"Difração de sombra",c:false}], pts: 3, exp: "A refração é a mudança na velocidade e direção da luz ao mudar de meio propício." },
              { id: "6ANO-CIEN-M18", p: "Qual é a função da bile, produzida pelo fígado e armazenada na vesícula biliar?", o: [{t:"Emulsificar gorduras facilitando a digestão",c:true}, {t:"Digerir açúcares e amido na boca",c:false}, {t:"Produzir ácido clorídrico no estômago",c:false}, {t:"Absorver água no intestino grosso",c:false}], pts: 3, exp: "A bile funciona como um detergente natural, quebrando gotas de gordura em menores." },
              { id: "6ANO-CIEN-M19", p: "Em qual fase a Lua deve estar obrigatoriamente para que ocorra um eclipse lunar?", o: [{t:"Lua Cheia",c:true}, {t:"Lua Nova",c:false}, {t:"Quarto Crescente",c:false}, {t:"Quarto Minguante",c:false}], pts: 3, exp: "Eclipses lunares só acontecem na fase de Lua Cheia, quando a Terra fica entre o Sol e a Lua." },
              { id: "6ANO-CIEN-M20", p: "O efeito estufa natural é essencial para a Terra porque:", o: [{t:"Mão mantém a temperatura média do planeta adequada à vida",c:true}, {t:"Bloqueia completamente o calor vindo do Sol",c:false}, {t:"Impede que ocorram chuva e tempestades",c:false}, {t:"Transforma todo o ar da atmosfera em oxigênio",c:false}], pts: 3, exp: "Sem o efeito estufa natural, a Terra seria gelada e inóspita para a maioria dos seres." },

        
          // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
              { id: "6ANO-CIEN-D01", p: "A passagem de água pela membrana celular do meio menos concentrado para o mais concentrado é a:", o: [{t:"Osmose",c:true}, {t:"Fagocitose",c:false}, {t:"Pinocitose",c:false}, {t:"Transporte ativo com gasto de energia",c:false}], pts: 4, exp: "A osmose é um transporte passivo de solvente (água) buscando equilibrar concentrações." },
              { id: "6ANO-CIEN-D02", p: "Para separar os componentes de uma mistura de líquidos miscíveis com diferentes pontos de ebulição usamos a:", o: [{t:"Destilação fracionada",c:true}, {t:"Decantação por funil",c:false}, {t:"Filtração a vácuo",c:false}, {t:"Centrifugação manual",c:false}], pts: 4, exp: "A destilação fracionada aquece a mistura aquecendo e condensando cada líquido na sua temperatura de ebulição." },
              { id: "6ANO-CIEN-D03", p: "O reflexo patelar (involuntário) é uma resposta rápida controlada diretamente pela:", o: [{t:"Medula espinhal",c:true}, {t:"Córtex cerebral consciente",c:false}, {t:"Retina dos olhos",c:false}, {t:"Parede do estômago",c:false}], pts: 4, exp: "Atos reflexos são processados no arco reflexo da medula espinhal antes de chegar à consciência no cérebro." },
              { id: "6ANO-CIEN-D04", p: "Rochas metamórficas resultam da transformação de rochas pré-existentes submetidas a:", o: [{t:"Altas pressões e elevadas temperaturas sem derreter completamente",c:true}, {t:"Processos de erosão causados pela chuva e marés",c:false}, {t:"Resfriamento imediato de lava vulcânica em água fria",c:false}, {t:"Decomposição de fósseis vegetais e animais",c:false}], pts: 4, exp: "O metamorfismo reorganiza os minerais da rocha sob pressão e calor intensos na crosta profunda." },
              { id: "6ANO-CIEN-D05", p: "O modelo heliocêntrico proposto por Copérnico e defendido por Galileu afirma que:", o: [{t:"O Sol está no centro do sistema e os planetas orbitam ao seu redor",c:true}, {t:"A Terra é o centro imóvel de todo o universo conhecido",c:false}, {t:"A Lua é uma estrela que ilumina os outros planetas",c:false}, {t:"Os planetas giram em linhas retas infinitas no espaço",c:false}], pts: 4, exp: "O heliocentrismo substituiu o geocentrismo ao provar que os planetas orbitam em torno do Sol." },
              { id: "6ANO-CIEN-D06", p: "Como são chamadas as contrações musculares involuntárias que empurram o alimento no tubo digestório?", o: [{t:"Movimentos peristálticos",c:true}, {t:"Espasmos voluntários",c:false}, {t:"Sístole e diástole",c:false}, {t:"Impulsos sinápticos",c:false}], pts: 4, exp: "O peristaltismo movimenta o bolo alimentar ao longo do esôfago, estômago e intestinos." },
              { id: "6ANO-CIEN-D07", p: "Para ocorrer a reação de combustão (fogo), são necessários três elementos básicos:", o: [{t:"Combustível, comburente (oxigênio) e calor de ignição",c:true}, {t:"Água, gás carbônico e nitrogênio",c:false}, {t:"Madeira, terra e eletricidade",c:false}, {t:"Sal, luz e hélio",c:false}], pts: 4, exp: "O triângulo do fogo exige combustível, comburente (Gás O2) e energia inicial (calor)." },
              { id: "6ANO-CIEN-D08", p: "Qual é a diferença física fundamental entre os conceitos de massa e peso de um corpo?", o: [{t:"Massa é a quantidade de matéria; peso é a força gravitacional sobre ela",c:true}, {t:"Massa varia com o local; peso é constante em todo o universo",c:false}, {t:"Massa é medida em Newtons; peso é medido em Quilogramas",c:false}, {t:"Não existe diferença, ambos representam a mesma grandeza",c:false}], pts: 4, exp: "A massa (kg) é intrínseca ao corpo; o peso (N) depende da aceleração da gravidade local." },
              { id: "6ANO-CIEN-D09", p: "Qual componente sanguíneo produz anticorpos para combater agentes causadores de doenças?", o: [{t:"Leucócitos (glóbulos brancos)",c:true}, {t:"Plaquetas sanguíneas",c:false}, {t:"Plasma aquoso",c:false}, {t:"Hemácias",c:false}], pts: 4, exp: "Os leucócitos formam o sistema imunológico, identificando e neutralizando invasores." },
              { id: "6ANO-CIEN-D10", p: "O aumento desmedido de gases como o dióxido de carbono na atmosfera intensifica o efeito estufa gerando:", o: [{t:"Aquecimento global",c:true}, {t:"Diminuição do nível dos oceanos",c:false}, {t:"Congelamento das regiões tropicais",c:false}, {t:"Aumento da camada de ozônio",c:false}], pts: 4, exp: "A retenção excessiva de calor na atmosfera provoca a elevação da temperatura média global." },
              { id: "6ANO-CIEN-D11", p: "O fenômeno atmosférico em que uma camada de ar quente retém o ar frio e poluentes próximo ao solo é:", o: [{t:"Inversão térmica",c:true}, {t:"Efeito estufa natural",c:false}, {t:"Cilindro de ar seco",c:false}, {t:"Ciclone extratropical",c:false}], pts: 4, exp: "A inversão térmica impede a circulação de ar vertical, aprisionando poluentes perto das cidades." },
              { id: "6ANO-CIEN-D12", p: "Quando adicionamos sal à água até que ele não se dissolva mais e acumule no fundo, temos uma solução:", o: [{t:"Saturada com de corpo de fundo",c:true}, {t:"Insaturada e diluída",c:false}, {t:"Homogênea perfeita",c:false}, {t:"Volátil e destilada",c:false}], pts: 4, exp: "Atingido o limite de solubilidade (ponto de saturação), o excesso de soluto não se dissolve." },
              { id: "6ANO-CIEN-D13", p: "As estações do ano ocorrem devido à combinação de dois fatores astronômicos principais:", o: [{t:"Movimento de translação e inclinação do eixo da Terra",c:true}, {t:"Movimento de rotação e distância da Lua",c:false}, {t:"Presença da atmosfera e tamanho do Sol",c:false}, {t:"Eclipses solares frequentes e manchas solares",c:false}], pts: 4, exp: "A inclinação de 23,5° aliada à translação faz com que a radiação solar atinja as regiões de forma desigual ao longo do ano." },
              { id: "6ANO-CIEN-D14", p: "Qual tipo de tecido do corpo humano é responsável por revestir superfícies internas e externas?", o: [{t:"Tecido epitelial",c:true}, {t:"Tecido conjuntivo ósseo",c:false}, {t:"Tecido muscular estriado",c:false}, {t:"Tecido nervoso",c:false}], pts: 4, exp: "O tecido epitelial atua no revestimento da pele e cavidades de órgãos e na secreção." },
              { id: "6ANO-CIEN-D15", p: "Qual método é utilizado nas usinas de reciclagem para separar objetos de ferro de outros resíduos?", o: [{t:"Separação magnética",c:true}, {t:"Levigação por água",c:false}, {t:"Ventilação por ar",c:false}, {t:"Centrifugação",c:false}], pts: 4, exp: "Ímãs atrai materiais ferromagnéticos (como o ferro) separando-os de outros materiais." },
              { id: "6ANO-CIEN-D16", p: "Na estrutura do solo, qual camada é mais rica em húmus e matéria orgânica decomposta?", o: [{t:"Horizonte A (camada superficial)",c:true}, {t:"Rocha matriz inalterada (Horizonte R)",c:false}, {t:"Manto superior do planeta",c:false}, {t:"Núcleo de ferro e níquel",c:false}], pts: 4, exp: "As camadas superiores (Horizontes O e A) concentram restos orgânicos decompostos vitais para plantas." },
              { id: "6ANO-CIEN-D17", p: "Em uma Estação de Tratamento de Água (ETA), qual etapa utiliza reagentes para aglutinar sujeiras em flocos?", o: [{t:"Floculação",c:true}, {t:"Cloratação simples",c:false}, {t:"Fluoratação",c:false}, {t:"Destilação",c:false}], pts: 4, exp: "Na floculação, aditivos fazem partículas impuras se juntarem formando flocos maiores que afundam." },
              { id: "6ANO-CIEN-D18", p: "A miopia é um problema de visão em que a imagem se forma antes da retina. Ela é corrigida com lentes:", o: [{t:"Divergentes",c:true}, {t:"Convergentes",c:false}, {t:"Cilíndricas planas",c:false}, {t:"Opacas",c:false}], pts: 4, exp: "Lentes divergentes afastam os raios de luz permitindo focar o ponto distante corretamente na retina." },
              { id: "6ANO-CIEN-D19", p: "A enzima pepsina atua na digestão de proteínas e funciona idealmente em meio ácido localizado no:", o: [{t:"Estômago",c:true}, {t:"Intestino delgado",c:false}, {t:"Boca",c:false}, {t:"Esôfago",c:false}], pts: 4, exp: "A pepsina necessita do meio extremamente ácido do suco gástrico no estômago para digerir proteínas." },
              { id: "6ANO-CIEN-D20", p: "O movimento contínuo das placas tectônicas na crosta terrestre é impulsionado por:", o: [{t:"Correntes de convecção no manto terrestre",c:true}, {t:"Atração gravitacional da Lua sobre as rochas",c:false}, {t:"Ventos solares que atingem a crosta",c:false}, {t:"Força das ondas do mar nas praias",c:false}], pts: 4, exp: "O calor interno da Terra gera correntes de convecção no manto, movimentando as placas tectônicas." }
        
        ]
    },

    // ------------------------------------------
    // 7º ANO
    // ------------------------------------------

    "7": {
        // ==================== MATEMÁTICA ====================
        
        "Matemática": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-MAT-F01", p: "Qual o resultado de 2/5 + 1/5?", o: [{t:"3/10",c:false}, {t:"3/5",c:true}, {t:"2/5",c:false}, {t:"1/5",c:false}], pts: 2, exp: "Com denominadores iguais, somamos os numeradores (2+1 = 3) e mantemos o denominador 5." },
              { id: "7ANO-MAT-F02", p: "Qual é o resultado da adição (-5) + (+8)?", o: [{t:"+3",c:true}, {t:"-3",c:false}, {t:"+13",c:false}, {t:"-13",c:false}], pts: 2, exp: "Sinais diferentes: subtraímos os módulos (8 - 5 = 3) e conservamos o sinal do maior módulo (+3)." },
              { id: "7ANO-MAT-F03", p: "Na reta numérica, qual número inteiro está localizado exatamente 4 unidades à esquerda do zero?", o: [{t:"+4",c:false}, {t:"-4",c:true}, {t:"-8",c:false}, {t:"0",c:false}], pts: 2, exp: "A esquerda do zero representa os números inteiros negativos, portanto -4." },
              { id: "7ANO-MAT-F04", p: "Quais são os três primeiros múltiplos naturais do número 7?", o: [{t:"1, 7, 14",c:false}, {t:"0, 7, 14",c:true}, {t:"7, 14, 21",c:false}, {t:"0, 1, 7",c:false}], pts: 2, exp: "Os múltiplos naturais começam multiplicando por 0, 1 e 2: 7x0=0, 7x1=7, 7x2=14." },
              { id: "7ANO-MAT-F05", p: "Qual das opções apresenta apenas divisores do número 12?", o: [{t:"1, 2, 3, 4, 6, 12",c:true}, {t:"0, 2, 4, 6, 12",c:false}, {t:"1, 3, 5, 12",c:false}, {t:"2, 4, 8, 12",c:false}], pts: 2, exp: "Os divisores de 12 são os números pelos quais 12 pode ser dividido com resto zero: 1, 2, 3, 4, 6 e 12." },
              { id: "7ANO-MAT-F06", p: "O que caracteriza um número primo?", o: [{t:"Possui apenas dois divisores naturais distintos: 1 e ele mesmo.",c:true}, {t:"É todo número ímpar positivo.",c:false}, {t:"Possui mais de quatro divisores.",c:false}, {t:"Termina sempre em 1, 3 ou 7.",c:false}], pts: 2, exp: "Por definição, números primos têm exatamente dois divisores naturais distintos: o 1 e o próprio número." },
              { id: "7ANO-MAT-F07", p: "Qual fração é equivalente a 1/2?", o: [{t:"2/3",c:false}, {t:"3/6",c:true}, {t:"4/6",c:false}, {t:"2/5",c:false}], pts: 2, exp: "Multiplicando numerador e denominador de 1/2 por 3, obtemos 3/6." },
              { id: "7ANO-MAT-F08", p: "Qual é a forma irredutível da fração 10/15?", o: [{t:"1/3",c:false}, {t:"2/3",c:true}, {t:"2/5",c:false}, {t:"5/3",c:false}], pts: 2, exp: "Dividindo o numerador e o denominador pelo MDC(10,15) que é 5, obtemos 2/3." },
              { id: "7ANO-MAT-F09", p: "Qual o resultado de 3,5 + 2,14?", o: [{t:"5,64",c:true}, {t:"5,19",c:false}, {t:"5,54",c:false}, {t:"2,49",c:false}], pts: 2, exp: "Alinhando as vírgulas: 3,50 + 2,14 = 5,64." },
              { id: "7ANO-MAT-F10", p: "Qual o resultado de 10 - 4,25?", o: [{t:"6,25",c:false}, {t:"5,75",c:true}, {t:"6,75",c:false}, {t:"5,25",c:false}], pts: 2, exp: "Alinhando as vírgulas: 10,00 - 4,25 = 5,75." },
              { id: "7ANO-MAT-F11", p: "Quanto é 10% de R$ 150,00?", o: [{t:"R$ 10,00",c:false}, {t:"R$ 15,00",c:true}, {t:"R$ 20,00",c:false}, {t:"R$ 1,50",c:false}], pts: 2, exp: "10% de um valor equivale a dividi-lo por 10: 150 / 10 = 15." },
              { id: "7ANO-MAT-F12", p: "Em matemática, a representação de 50% de uma quantidade equivale a qual fração?", o: [{t:"1/5",c:false}, {t:"1/4",c:false}, {t:"1/2",c:true}, {t:"3/4",c:false}], pts: 2, exp: "50% = 50/100, que simplificado por 50 resulta em 1/2 (a metade)." },
              { id: "7ANO-MAT-F13", p: "Na expressão matemática 'x + 5 = 12', o que a letra 'x' representa?", o: [{t:"Uma constante fixa",c:false}, {t:"Uma incógnita cujo valor deve ser determinado",c:true}, {t:"Uma operação aritmética",c:false}, {t:"Uma unidade de medida",c:false}], pts: 2, exp: "Na equação, a letra 'x' é um valor desconhecido a ser determinado, denominado incógnita." },
              { id: "7ANO-MAT-F14", p: "Um ângulo cuja medida é exatamente igual a 90° é chamado de:", o: [{t:"Ângulo agudo",c:false}, {t:"Ângulo raso",c:false}, {t:"Ângulo reto",c:true}, {t:"Ângulo obtuso",c:false}], pts: 2, exp: "Por definição, ângulos de exatamente 90 graus são chamados de ângulos retos." },
              { id: "7ANO-MAT-F15", p: "Qual é a soma dos ângulos internos de qualquer triângulo?", o: [{t:"90°",c:false}, {t:"180°",c:true}, {t:"270°",c:false}, {t:"360°",c:false}], pts: 2, exp: "A soma das medidas dos ângulos internos de qualquer triângulo é sempre igual a 180°." },
              { id: "7ANO-MAT-F16", p: "Qual o perímetro de um terreno retangular com 10 metros de largura e 15 metros de comprimento?", o: [{t:"25 metros",c:false}, {t:"50 metros",c:true}, {t:"150 metros",c:false}, {t:"100 metros",c:false}], pts: 2, exp: "O perímetro é a soma de todos os lados: 10 + 10 + 15 + 15 = 50 metros." },
              { id: "7ANO-MAT-F17", p: "Qual a área de um retângulo que possui base de 8 cm e altura de 5 cm?", o: [{t:"13 cm²",c:false}, {t:"26 cm²",c:false}, {t:"40 cm²",c:true}, {t:"80 cm²",c:false}], pts: 2, exp: "A área do retângulo é dada por base x altura: 8 x 5 = 40 cm²." },
              { id: "7ANO-MAT-F18", p: "Um recipiente possui capacidade de 1 decímetro cúbico (1 dm³). Isso equivale exatamente a:", o: [{t:"1 mililitro (1 mL)",c:false}, {t:"1 litro (1 L)",c:true}, {t:"10 litros (10 L)",c:false}, {t:"100 litros (100 L)",c:false}], pts: 2, exp: "A equivalência direta de volume e capacidade estabelece que 1 dm³ = 1 litro." },
              { id: "7ANO-MAT-F19", p: "Qual é a média aritmética simples entre os números 12 e 18?", o: [{t:"15",c:true}, {t:"14",c:false}, {t:"16",c:false}, {t:"30",c:false}], pts: 2, exp: "Somamos os valores e dividimos por 2: (12 + 18) / 2 = 30 / 2 = 15." },
              { id: "7ANO-MAT-F20", p: "Em um gráfico de colunas que representa a quantidade de livros lidos no ano, a altura de cada coluna indica:", o: [{t:"O título do livro",c:false}, {t:"A quantidade ou frequência dos livros lidos",c:true}, {t:"O número de páginas de cada livro",c:false}, {t:"O mês de publicação",c:false}], pts: 2, exp: "Em gráficos de colunas, a altura representa o valor numérico ou frequência da variável estudada." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
              { id: "7ANO-MAT-M01", p: "Qual o resultado da multiplicação (-6) x (-7)?", o: [{t:"-42",c:false}, {t:"+42",c:true}, {t:"-13",c:false}, {t:"+13",c:false}], pts: 3, exp: "Na multiplicação de dois números de sinais iguais (negativo x negativo), o resultado é positivo: +42." },
              { id: "7ANO-MAT-M02", p: "Qual o resultado da divisão (-36) : (+4)?", o: [{t:"-9",c:true}, {t:"+9",c:false}, {t:"-32",c:false}, {t:"+32",c:false}], pts: 3, exp: "Na divisão entre sinais diferentes (negativo : positivo), o resultado é negativo: -9." },
              { id: "7ANO-MAT-M03", p: "Qual o Mínimo Múltiplo Comum (MMC) entre os números 6 e 8?", o: [{t:"12",c:false}, {t:"24",c:true}, {t:"48",c:false}, {t:"14",c:false}], pts: 3, exp: "Múltiplos de 6: 0, 6, 12, 18, 24... Múltiplos de 8: 0, 8, 16, 24... O menor múltiplo comum não nulo é 24." },
              { id: "7ANO-MAT-M04", p: "Qual é o Máximo Divisor Comum (MDC) entre os números 18 e 24?", o: [{t:"3",c:false}, {t:"6",c:true}, {t:"12",c:false}, {t:"72",c:false}], pts: 3, exp: "Divisores de 18: 1, 2, 3, 6, 9, 18. Divisores de 24: 1, 2, 3, 4, 6, 8, 12, 24. O maior divisor comum é 6." },
              { id: "7ANO-MAT-M05", p: "Qual o resultado da operação 1/3 + 2/5?", o: [{t:"3/8",c:false}, {t:"11/15",c:true}, {t:"3/15",c:false}, {t:"7/15",c:false}], pts: 3, exp: "MMC(3,5) = 15. Convertendo: 5/15 + 6/15 = 11/15." },
              { id: "7ANO-MAT-M06", p: "Qual o resultado da multiplicação de frações 2/3 x 4/5?", o: [{t:"8/15",c:true}, {t:"6/8",c:false}, {t:"10/12",c:false}, {t:"8/8",c:false}], pts: 3, exp: "Multiplicamos numerador por numerador e denominador por denominador: (2x4)/(3x5) = 8/15." },
              { id: "7ANO-MAT-M07", p: "Qual o resultado da divisão de frações (3/4) : (2/5)?", o: [{t:"6/20",c:false}, {t:"15/8",c:true}, {t:"5/9",c:false}, {t:"8/15",c:false}], pts: 3, exp: "Mantemos a primeira e multiplicamos pelo inverso da segunda: (3/4) x (5/2) = 15/8." },
              { id: "7ANO-MAT-M08", p: "Um produto custava R$ 80,00 e sofreu um acréscimo de 15%. Qual o novo preço do produto?", o: [{t:"R$ 92,00",c:true}, {t:"R$ 95,00",c:false}, {t:"R$ 88,00",c:false}, {t:"R$ 100,00",c:false}], pts: 3, exp: "15% de 80 = (15/100) x 80 = 12. Novo valor: 80 + 12 = R$ 92,00." },
              { id: "7ANO-MAT-M09", p: "Uma roupa de R$ 120,00 foi comprada com 20% de desconto. Quanto o cliente pagou?", o: [{t:"R$ 100,00",c:false}, {t:"R$ 96,00",c:true}, {t:"R$ 90,00",c:false}, {t:"R$ 84,00",c:false}], pts: 3, exp: "20% de 120 = 24. Valor pago: 120 - 24 = R$ 96,00." },
              { id: "7ANO-MAT-M10", p: "Resolva a equação do 1º grau: x + 7 = 15.", o: [{t:"x = 22",c:false}, {t:"x = 8",c:true}, {t:"x = 7",c:false}, {t:"x = -8",c:false}], pts: 3, exp: "Subtraindo 7 de ambos os lados: x = 15 - 7 => x = 8." },
              { id: "7ANO-MAT-M11", p: "Qual a solução da equação 2x - 4 = 10?", o: [{t:"x = 3",c:false}, {t:"x = 7",c:true}, {t:"x = 5",c:false}, {t:"x = 14",c:false}], pts: 3, exp: "2x = 10 + 4 => 2x = 14 => x = 14 / 2 => x = 7." },
              { id: "7ANO-MAT-M12", p: "Qual a razão entre 15 metros e 30 metros, simplificada?", o: [{t:"1/2",c:true}, {t:"2/1",c:false}, {t:"1/3",c:false}, {t:"3/5",c:false}], pts: 3, exp: "A razão é 15/30. Dividindo ambos por 15, encontramos 1/2." },
              { id: "7ANO-MAT-M13", p: "Se 3 cadernos custam R$ 18,00, quanto custarão 5 cadernos do mesmo tipo?", o: [{t:"R$ 24,00",c:false}, {t:"R$ 30,00",c:true}, {t:"R$ 36,00",c:false}, {t:"R$ 28,00",c:false}], pts: 3, exp: "Cada caderno custa 18 / 3 = R$ 6,00. Logo, 5 cadernos custam 5 x 6 = R$ 30,00." },
              { id: "7ANO-MAT-M14", p: "Um triângulo possui ângulos internos medindo 30°, 60° e 90°. Como ele se classifica quanto aos ângulos?", o: [{t:"Acutângulo",c:false}, {t:"Obtusângulo",c:false}, {t:"Retângulo",c:true}, {t:"Equilátero",c:false}], pts: 3, exp: "Como possui um ângulo reto (90°), trata-se de um triângulo retângulo." },
              { id: "7ANO-MAT-M15", p: "De acordo com a condição de existência dos triângulos, é possível construir um triângulo com lados medindo 2 cm, 3 cm e 6 cm?", o: [{t:"Sim, pois todos são números positivos.",c:false}, {t:"Não, pois a soma de dois lados (2+3=5) é menor que o terceiro lado (6).",c:true}, {t:"Sim, pois 6 é o dobro de 3.",c:false}, {t:"Não, pois não há lados iguais.",c:false}], pts: 3, exp: "Em todo triângulo, a soma de dois lados deve ser sempre maior que o terceiro lado. Como 2+3=5 < 6, não existe." },
              { id: "7ANO-MAT-M16", p: "Dois ângulos opostos pelo vértice (OPV) medem (2x) e (80°). Qual o valor de x?", o: [{t:"40°",c:true}, {t:"80°",c:false}, {t:"160°",c:false}, {t:"20°",c:false}], pts: 3, exp: "Ângulos OPV são iguais: 2x = 80° => x = 40°." },
              { id: "7ANO-MAT-M17", p: "Qual é a área de um triângulo que tem 10 cm de base e 6 cm de altura?", o: [{t:"60 cm²",c:false}, {t:"30 cm²",c:true}, {t:"16 cm²",c:false}, {t:"20 cm²",c:false}], pts: 3, exp: "A área do triângulo é (base x altura) / 2 = (10 x 6) / 2 = 60 / 2 = 30 cm²." },
              { id: "7ANO-MAT-M18", p: "Qual o volume de uma caixa em formato de paralelepípedo retângular de dimensão 5 cm x 4 cm x 3 cm?", o: [{t:"12 cm³",c:false}, {t:"60 cm³",c:true}, {t:"30 cm³",c:false}, {t:"20 cm³",c:false}], pts: 3, exp: "O volume do paralelepípedo é dado por V = comprimento x largura x altura = 5 x 4 x 3 = 60 cm³." },
              { id: "7ANO-MAT-M19", p: "Qual o comprimento de uma circunferência de raio r = 5 cm? (Considere π = 3,14)", o: [{t:"15,7 cm",c:false}, {t:"31,4 cm",c:true}, {t:"78,5 cm",c:false}, {t:"62,8 cm",c:false}], pts: 3, exp: "Fórmula C = 2 x π x r = 2 x 3,14 x 5 = 31,4 cm." },
              { id: "7ANO-MAT-M20", p: "Um aluno tirou as seguintes notas nas avaliações: 6,0; 7,0; 8,0 e 7,0. Qual é a sua média aritmética?", o: [{t:"6,5",c:false}, {t:"7,0",c:true}, {t:"7,5",c:false}, {t:"8,0",c:false}], pts: 3, exp: "Soma = 6 + 7 + 8 + 7 = 28. Média = 28 / 4 = 7,0." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-MAT-D01", p: "Qual o valor da expressão numérica: (-3) x [ (+5) - (-2) ] + (-4)?", o: [{t:"-25",c:true}, {t:"-13",c:false}, {t:"+17",c:false}, {t:"-21",c:false}], pts: 4, exp: "Primeiro os colchetes: (+5) - (-2) = 5 + 2 = 7. Depois a multiplicação: (-3) x 7 = -21. Por fim: -21 + (-4) = -25." },
              { id: "7ANO-MAT-D02", p: "Dois ônibus saem do terminal no mesmo horário. O ônibus A passa a cada 12 minutos e o ônibus B a cada 18 minutos. Após quanto tempo eles sairão juntos novamente?", o: [{t:"36 minutos",c:true}, {t:"54 minutos",c:false}, {t:"72 minutos",c:false}, {t:"24 minutos",c:false}], pts: 4, exp: "Calculamos o MMC(12, 18). 12 = 2² x 3, 18 = 2 x 3². MMC = 2² x 3² = 4 x 9 = 36 minutos." },
              { id: "7ANO-MAT-D03", p: "Um professor tem 24 canetas azuis e 36 canetas vermelhas e quer dividi-las em estojos iguais com o maior número possível de canetas de cada cor em cada estojo. Quantos estojos serão montados?", o: [{t:"6 estojos",c:false}, {t:"12 estojos",c:true}, {t:"18 estojos",c:false}, {t:"24 estojos",c:false}], pts: 4, exp: "Calculamos o MDC(24, 36). 24 = 2³ x 3, 36 = 2² x 3². MDC = 2² x 3 = 12 estojos." },
              { id: "7ANO-MAT-D04", p: "Qual o resultado de (3/4 - 1/2) : 0,25?", o: [{t:"1",c:true}, {t:"0,5",c:false}, {t:"2",c:false}, {t:"0,25",c:false}], pts: 4, exp: "Parenteses: 3/4 - 2/4 = 1/4 = 0,25. Divisão: 0,25 : 0,25 = 1." },
              { id: "7ANO-MAT-D05", p: "Um sapato custa R$ 200,00. Teve seu preço aumentado em 10% e, no mês seguinte, o novo valor sofreu outro aumento de 10%. Qual o preço final do sapato?", o: [{t:"R$ 240,00",c:false}, {t:"R$ 242,00",c:true}, {t:"R$ 220,00",c:false}, {t:"R$ 250,00",c:false}], pts: 4, exp: "1º aumento: 200 + 10% = 220. 2º aumento: 220 + 10% de 220 (22) = R$ 242,00." },
              { id: "7ANO-MAT-D06", p: "Qual é a solução da equação 3(x - 2) + 4 = 2x + 5?", o: [{t:"x = 7",c:true}, {t:"x = 5",c:false}, {t:"x = 3",c:false}, {t:"x = 9",c:false}], pts: 4, exp: "Distributiva: 3x - 6 + 4 = 2x + 5 => 3x - 2 = 2x + 5 => 3x - 2x = 5 + 2 => x = 7." },
              { id: "7ANO-MAT-D07", p: "A soma das idades de um pai e seu filho é 48 anos. Sabendo que o pai tem o triplo da idade do filho, qual a idade do filho?", o: [{t:"12 anos",c:true}, {t:"16 anos",c:false}, {t:"10 anos",c:false}, {t:"14 anos",c:false}], pts: 4, exp: "Seja f a idade do filho. Pai = 3f. f + 3f = 48 => 4f = 48 => f = 12 anos." },
              { id: "7ANO-MAT-D08", p: "Se 4 operários constroem um muro em 6 dias, em quantos dias 8 operários, com a mesma capacidade de trabalho, construiriam o mesmo muro?", o: [{t:"12 dias",c:false}, {t:"3 dias",c:true}, {t:"4 dias",c:false}, {t:"2 dias",c:false}], pts: 4, exp: "Grandezas inversamente proporcionais: dobrando o número de operários, o tempo cai pela metade: 6 / 2 = 3 dias." },
              { id: "7ANO-MAT-D09", p: "Dois sócios dividem o lucro de R$ 3.000,00 de forma diretamente proporcional aos seus investimentos de R$ 2.000,00 e R$ 4.000,00. Quanto recebe o sócio com menor investimento?", o: [{t:"R$ 1.000,00",c:true}, {t:"R$ 1.500,00",c:false}, {t:"R$ 2.000,00",c:false}, {t:"R$ 800,00",c:false}], pts: 4, exp: "Proporção de 2 para 4 (ou 1 para 2). O total de partes é 3. Cada parte = 3000 / 3 = 1000. O menor recebe 1 parte = R$ 1.000,00." },
              { id: "7ANO-MAT-D10", p: "Duas retas paralelas são cortadas por uma transversal. Se dois ângulos alternos internos são dados por (3x - 10°) e (x + 30°), qual o valor de x?", o: [{t:"20°",c:true}, {t:"40°",c:false}, {t:"10°",c:false}, {t:"30°",c:false}], pts: 4, exp: "Ângulos alternos internos são iguais: 3x - 10 = x + 30 => 2x = 40 => x = 20°." },
              { id: "7ANO-MAT-D11", p: "Em um triângulo, os ângulos internos medem x, (2x) e (3x). Qual é a medida do maior ângulo desse triângulo?", o: [{t:"30°",c:false}, {t:"60°",c:false}, {t:"90°",c:true}, {t:"120°",c:false}], pts: 4, exp: "x + 2x + 3x = 180° => 6x = 180° => x = 30°. Maior ângulo = 3x = 3 x 30° = 90°." },
              { id: "7ANO-MAT-D12", p: "Qual a área total de uma figura composta por um retângulo de 6 cm x 4 cm unido a um quadrado de lado 3 cm?", o: [{t:"33 cm²",c:true}, {t:"24 cm²",c:false}, {t:"30 cm²",c:false}, {t:"36 cm²",c:false}], pts: 4, exp: "Área do retângulo = 6 x 4 = 24 cm². Área do quadrado = 3 x 3 = 9 cm². Área total = 24 + 9 = 33 cm²." },
              { id: "7ANO-MAT-D13", p: "Uma roda de bicicleta tem comprimento de circunferência igual a 188,4 cm. Qual é o diâmetro dessa roda? (Use π = 3,14)", o: [{t:"30 cm",c:false}, {t:"60 cm",c:true}, {t:"90 cm",c:false}, {t:"45 cm",c:false}], pts: 4, exp: "C = π x d => 188,4 = 3,14 x d => d = 188,4 / 3,14 = 60 cm." },
              { id: "7ANO-MAT-D14", p: "Uma caixa-d'água possui formato cúbico com 2 metros de aresta interna. Quantos litros de água ela é capaz de armazenar quando cheia?", o: [{t:"2.000 litros",c:false}, {t:"4.000 litros",c:false}, {t:"8.000 litros",c:true}, {t:"1.000 litros",c:false}], pts: 4, exp: "Volume = 2m x 2m x 2m = 8 m³. Como 1 m³ = 1.000 L, a capacidade é de 8 x 1.000 = 8.000 litros." },
              { id: "7ANO-MAT-D15", p: "Ao lançar um dado comum de 6 faces, qual a probabilidade de obter um número primo?", o: [{t:"1/6",c:false}, {t:"1/2",c:true}, {t:"1/3",c:false}, {t:"2/3",c:false}], pts: 4, exp: "Os números primos no dado são 2, 3 e 5 (3 casos favoráveis). Probabilidade = 3/6 = 1/2." },
              { id: "7ANO-MAT-D16", p: "Uma urna contém 3 bolas vermelhas, 5 azuis e 2 amarelas. Retirando-se uma bola ao acaso, qual a probabilidade percentual de ela ser azul?", o: [{t:"30%",c:false}, {t:"50%",c:true}, {t:"20%",c:false}, {t:"40%",c:false}], pts: 4, exp: "Total de bolas = 3 + 5 + 2 = 10. Bolas azuis = 5. P = 5/10 = 0,5 = 50%." },
              { id: "7ANO-MAT-D17", p: "Qual é a amplitude do conjunto de dados das temperaturas registradas durante uma semana em uma cidade: 18°C, 22°C, 19°C, 25°C, 21°C e 17°C?", o: [{t:"8°C",c:true}, {t:"7°C",c:false}, {t:"25°C",c:false}, {t:"17°C",c:false}], pts: 4, exp: "A amplitude estatística é a diferença entre o maior e o menor valor: 25 - 17 = 8°C." },
              { id: "7ANO-MAT-D18", p: "Em um mapa desenhado na escala 1 : 100.000, a distância entre duas cidades é de 5 cm. Qual a distância real entre elas em quilômetros?", o: [{t:"5 km",c:true}, {t:"50 km",c:false}, {t:"0,5 km",c:false}, {t:"500 km",c:false}], pts: 4, exp: "Distância real = 5 cm x 100.000 = 500.000 cm. Convertendo para metros: 5.000 m = 5 km." },
              { id: "7ANO-MAT-D19", p: "No plano cartesiano, se multiplicarmos as coordenadas do ponto A(3, -4) por -1, o novo ponto A' estará localizado em qual quadrante?", o: [{t:"1º Quadrante",c:false}, {t:"2º Quadrante",c:true}, {t:"3º Quadrante",c:false}, {t:"4º Quadrante",c:false}], pts: 4, exp: "A'(3 x (-1), -4 x (-1)) = A'(-3, 4). X negativo e Y positivo pertencem ao 2º Quadrante." },
              { id: "7ANO-MAT-D20", p: "Um retângulo tem perímetro igual a 36 cm. Sabendo que o comprimento mede o dobro da largura, qual é a área desse retângulo?", o: [{t:"72 cm²",c:true}, {t:"36 cm²",c:false}, {t:"64 cm²",c:false}, {t:"108 cm²",c:false}], pts: 4, exp: "Seja x a largura e 2x o comprimento. Perímetro = 2(x + 2x) = 6x = 36 => x = 6 cm. Lados: 6 cm e 12 cm. Área = 6 x 12 = 72 cm²." },
        ],



       // ==================== PORTUGUÊS (7º ANO) ====================

        "Português": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-POR-F01", p: "Na oração 'Os alunos estudaram para a prova', qual é o sujeito?", o: [{t:"estudaram",c:false}, {t:"Os alunos",c:true}, {t:"para a prova",c:false}, {t:"a prova",c:false}], pts: 2, exp: "O sujeito é o termo sobre o qual se declara algo. Perguntando 'quem estudou?': Os alunos." },
              { id: "7ANO-POR-F02", p: "Na oração 'O passarinho cantou na janela', qual é o predicado?", o: [{t:"O passarinho",c:false}, {t:"cantou na janela",c:true}, {t:"na janela",c:false}, {t:"passarinho",c:false}], pts: 2, exp: "O predicado é tudo aquilo que se informa sobre o sujeito: 'cantou na janela'." },
              { id: "7ANO-POR-F03", p: "Qual é o núcleo do sujeito na frase 'As meninas inteligentes venceram o campeonato'?", o: [{t:"As",c:false}, {t:"meninas",c:true}, {t:"inteligentes",c:false}, {t:"venceram",c:false}], pts: 2, exp: "O núcleo é a palavra principal do sujeito (substantivo): 'meninas'." },
              { id: "7ANO-POR-F04", p: "A frase 'O vento forte derrubou a árvore' possui qual tipo de sujeito?", o: [{t:"Sujeito simples",c:true}, {t:"Sujeito composto",c:false}, {t:"Sujeito indeterminado",c:false}, {t:"Sujeito oculto",c:false}], pts: 2, exp: "Possui apenas um núcleo ('vento'), classificando-se como sujeito simples." },
              { id: "7ANO-POR-F05", p: "Qual das opções contém um sujeito composto?", o: [{t:"Nós fomos ao cinema ontem.",c:false}, {t:"Pedro e Maria estudaram juntos.",c:true}, {t:"Choveu bastante pela manhã.",c:false}, {t:"Chegaram os alunos atrasados.",c:false}], pts: 2, exp: "O sujeito 'Pedro e Maria' possui dois núcleos (Pedro, Maria), sendo composto." },
              { id: "7ANO-POR-F06", p: "Na frase 'A aluna parecia ansiosa', qual palavra funciona como verbo de ligação?", o: [{t:"aluna",c:false}, {t:"parecia",c:true}, {t:"ansiosa",c:false}, {t:"A",c:false}], pts: 2, exp: "O verbo 'parecia' liga o sujeito à sua característica (predicativo), sendo um verbo de ligação." },
              { id: "7ANO-POR-F07", p: "Qual dos substantivos a seguir é classificado como abstrato?", o: [{t:"Cadeira",c:false}, {t:"Saudade",c:true}, {t:"Caderno",c:false}, {t:"Árvore",c:false}], pts: 2, exp: "Saudade é um sentimento que depende de um ser para existir, logo é um substantivo abstrato." },
              { id: "7ANO-POR-F08", p: "Identifique o adjetivo na frase 'O garoto estudioso passou no teste'.", o: [{t:"garoto",c:false}, {t:"estudioso",c:true}, {t:"passou",c:false}, {t:"teste",c:false}], pts: 2, exp: "'Estudioso' atribui uma característica ao substantivo garoto, funcionando como adjetivo." },
              { id: "7ANO-POR-F09", p: "Qual das opções apresenta um pronome pessoal do caso reto?", o: [{t:"Meu",c:false}, {t:"Eles",c:true}, {t:"Consigo",c:false}, {t:"Aquele",c:false}], pts: 2, exp: "'Eles' é um pronome pessoal do caso reto (3ª pessoa do plural)." },
              { id: "7ANO-POR-F10", p: "Na frase 'Sua mochila está na sala', a palavra 'Sua' é um pronome:", o: [{t:"Demonstrativo",c:false}, {t:"Possessivo",c:true}, {t:"Indefinido",c:false}, {t:"Interrogativo",c:false}], pts: 2, exp: "'Sua' indica posse da mochila, sendo um pronome possessivo." },
              { id: "7ANO-POR-F11", p: "Qual das alternativas traz um par de palavras sinônimas?", o: [{t:"Belo - Feio",c:false}, {t:"Feliz - Contente",c:true}, {t:"Alto - Baixo",c:false}, {t:"Claro - Escuro",c:false}], pts: 2, exp: "'Feliz' e 'contente' possuem significados semelhantes (sinônimos)." },
              { id: "7ANO-POR-F12", p: "Qual sinal de pontuação deve ser utilizado ao final de uma frase interrogativa direta?", o: [{t:"Ponto final",c:false}, {t:"Ponto de interrogação (?)",c:true}, {t:"Ponto de exclamação (!)",c:false}, {t:"Reticências",c:false}], pts: 2, exp: "Perguntas diretas são finalizadas com ponto de interrogação." },
              { id: "7ANO-POR-F13", p: "O ponto final deve ser usado para:", o: [{t:"Indicar surpresa ou emoção",c:false}, {t:"Encerrar uma frase declarativa",c:true}, {t:"Fazer uma pergunta",c:false}, {t:"Separar itens de uma lista",c:false}], pts: 2, exp: "O ponto final encerra a apresentação de um pensamento declarativo completo." },
              { id: "7ANO-POR-F14", p: "Em qual das frases o verbo exprime uma certeza (modo indicativo)?", o: [{t:"Talvez ele venha hoje.",c:false}, {t:"Eu estudo todos os dias.",c:true}, {t:"Se ele estudasse, passaria.",c:false}, {t:"Estude para a prova!",c:false}], pts: 2, exp: "'Eu estudo' expressa uma ação certa e real, característica do modo indicativo." },
              { id: "7ANO-POR-F15", p: "Na frase 'Faça o seu dever de casa agora!', o verbo está no modo:", o: [{t:"Indicativo",c:false}, {t:"Subjuntivo",c:false}, {t:"Imperativo",c:true}, {t:"Infinitivo",c:false}], pts: 2, exp: "O modo imperativo é utilizado para expressar ordens, pedidos ou conselhos." },
              { id: "7ANO-POR-F16", p: "A linguagem que utiliza simultaneamente palavras escritas e imagens (como em tirinhas) é chamada de:", o: [{t:"Linguagem verbal",c:false}, {t:"Linguagem não verbal",c:false}, {t:"Linguagem mista ou multissemiótica",c:true}, {t:"Linguagem formal",c:false}], pts: 2, exp: "Linguagem mista associa o texto escrito (verbal) e as imagens (não verbal)." },
              { id: "7ANO-POR-F17", p: "Qual é o objetivo principal do gênero textual notícia?", o: [{t:"Divertir o leitor com histórias imaginárias",c:false}, {t:"Informar sobre fatos recentes e reais",c:true}, {t:"Ensinar uma receita culinária",c:false}, {t:"Vender um produto ou serviço",c:false}], pts: 2, exp: "A notícia é um texto jornalístico informativo sobre eventos reais e atuais." },
              { id: "7ANO-POR-F18", p: "Em histórias em quadrinhos (HQ), as falas dos personagens são apresentadas em:", o: [{t:"Parágrafos tradicionais",c:false}, {t:"Balões de texto",c:true}, {t:"Notas de rodapé",c:false}, {t:"Tabelas",c:false}], pts: 2, exp: "As HQs utilizam balões de fala para representar o discurso direto dos personagens." },
              { id: "7ANO-POR-F19", p: "Por que a palavra 'café' recebe acento gráfico?", o: [{t:"É uma palavra proparoxítona.",c:false}, {t:"É uma oxítona terminada em 'e'.",c:true}, {t:"É uma paroxítona terminada em 'é'.",c:false}, {t:"É um monossílabo átono.",c:false}], pts: 2, exp: "Pela regra de acentuação, acentuam-se as palavras oxítonas terminadas em a, e, o (seguidas ou não de s)." },
              { id: "7ANO-POR-F20", p: "Qual das palavras a seguir é proparoxítona e, portanto, deve ser obrigatoriamente acentuada?", o: [{t:"Lâmpada",c:true}, {t:"Caráter",c:false}, {t:"Jatobá",c:false}, {t:"Caneta",c:false}], pts: 2, exp: "'Lâm-pa-da' tem a antepenúltima sílaba tônica. Todas as proparoxítonas são acentuadas." },

            // =========== ========= MÉDIAS (20 QUESTAÇÕES) ====================
              { id: "7ANO-POR-M01", p: "Na frase 'Falaram muito bem da sua apresentação', qual a classificação do sujeito?", o: [{t:"Sujeito simples",c:false}, {t:"Sujeito indeterminado",c:true}, {t:"Sujeito oculto (desinencial)",c:false}, {t:"Sujeito inexistente",c:false}], pts: 3, exp: "O verbo na 3ª pessoa do plural, sem referência anterior no texto, indetermina o sujeito." },
              { id: "7ANO-POR-M02", p: "Classifique o predicado na frase: 'Os alunos ficaram felizes'.", o: [{t:"Predicado verbal",c:false}, {t:"Predicado nominal",c:true}, {t:"Predicado verbo-nominal",c:false}, {t:"Predicado indireto",c:false}], pts: 3, exp: "O predicado tem verbo de ligação ('ficaram') e núcleo no predicativo do sujeito ('felizes')." },
              { id: "7ANO-POR-M03", p: "Na frase 'O menino comprou um livro', o verbo 'comprou' é:", o: [{t:"Verbo intransitivo",c:false}, {t:"Verbo transitivo direto (VTD)",c:true}, {t:"Verbo transitivo indireto (VTI)",c:false}, {t:"Verbo de ligação",c:false}], pts: 3, exp: "Exige complemento sem preposição obrigatória ('um livro'), logo é VTD." },
              { id: "7ANO-POR-M04", p: "Na oração 'Gosto de música clássica', qual a função sintática de 'de música clássica'?", o: [{t:"Objeto direto",c:false}, {t:"Objeto indireto",c:true}, {t:"Sujeito",c:false}, {t:"Predicativo do sujeito",c:false}], pts: 3, exp: "O verbo 'gostar' exige complemento preposicionado ('de...'), funcionando como Objeto Indireto." },
              { id: "7ANO-POR-M05", p: "Identifique o Objeto Direto na frase: 'A professora elogiou o aluno'.", o: [{t:"A professora",c:false}, {t:"elogiou",c:false}, {t:"o aluno",c:true}, {t:"professora",c:false}], pts: 3, exp: "'O aluno' completa o sentido do verbo transitivo direto 'elogiou' sem preposição." },
              { id: "7ANO-POR-M06", p: "Qual das opções apresenta um verbo intransitivo (VI)?", o: [{t:"O bebê dormiu.",c:true}, {t:"Maria comprou um carro.",c:false}, {t:"Nós precisamos de ajuda.",c:false}, {t:"Ele enviou a carta.",c:false}], pts: 3, exp: "O verbo 'dormir' tem sentido completo e não exige complemento obrigatório." },
              { id: "7ANO-POR-M07", p: "Na oração 'O entregador enviou o pacote ao cliente', o verbo é:", o: [{t:"Transitivo direto e indireto (VTDI)",c:true}, {t:"Transitivo direto apenas",c:false}, {t:"Transitivo indireto apenas",c:false}, {t:"Intransitivo",c:false}], pts: 3, exp: "Possui dois complementos: objeto direto ('o pacote') e objeto indireto ('ao cliente')." },
              { id: "7ANO-POR-M08", p: "A frase 'O aluno chegou cansado' possui qual tipo de predicado?", o: [{t:"Predicado verbal",c:false}, {t:"Predicado nominal",c:false}, {t:"Predicado verbo-nominal",c:true}, {t:"Predicado direto",c:false}], pts: 3, exp: "Possui dois núcleos: um verbo de ação ('chegou') e um predicativo do sujeito ('cansado')." },
              { id: "7ANO-POR-M09", p: "Em qual frase o verbo expressa uma hipótese ou possibilidade (modo subjuntivo)?", o: [{t:"Nós vencemos o campeonato.",c:false}, {t:"Se nós estudássemos mais, tiraríamos notas melhores.",c:true}, {t:"Venha aqui agora!",c:false}, {t:"Eles compraram os ingressos.",c:false}], pts: 3, exp: "'Se estudássemos' expressa condição/hipótese, marca do modo subjuntivo." },
              { id: "7ANO-POR-M10", p: "Qual a diferença entre os tempos verbais 'cantei' e 'cantava'?", o: [{t:"Ambos são pretéritos perfeitos.",c:false}, {t:"'Cantei' é pretérito perfeito (ação concluída); 'cantava' é pretérito imperfeito (ação contínua no passado).",c:true}, {t:"'Cantava' é futuro do presente.",c:false}, {t:"'Cantei' é modo imperativo.",c:false}], pts: 3, exp: "Pretérito perfeito indica ação pontual finalizada; imperfeito indica hábito ou ação contínua no passado." },
              { id: "7ANO-POR-M11", p: "Qual o pronome demonstrativo adequado para se referir a um objeto que está perto de quem fala?", o: [{t:"Aquele",c:false}, {t:"Esse",c:false}, {t:"Este",c:true}, {t:"Aquilo",c:false}], pts: 3, exp: "Usa-se 'este/esta/isto' para objetos próximos do falante (1ª pessoa)." },
              { id: "7ANO-POR-M12", p: "Na frase 'Ele caminhava vagarosamente', a palavra 'vagarosamente' é um advérbio de:", o: [{t:"Tempo",c:false}, {t:"Modo",c:true}, {t:"Lugar",c:false}, {t:"Intensidade",c:false}], pts: 3, exp: "Indica o modo como ele caminhava (vagarosamente)." },
              { id: "7ANO-POR-M13", p: "Qual a função da preposição em uma frase?", o: [{t:"Substituir um nome",c:false}, {t:"Ligar duas palavras estabelecendo relação de sentido entre elas",c:true}, {t:"Expressar emoções súbitas",c:false}, {t:"Indicar a pessoa do discurso",c:false}], pts: 3, exp: "Preposições são conectivos que ligam termos, criando relações de dependência e sentido." },
              { id: "7ANO-POR-M14", p: "Na frase 'Estudou muito, mas não passou na prova', a palavra 'mas' expressa ideia de:", o: [{t:"Adição",c:false}, {t:"Oposição / Adversidade",c:true}, {t:"Explicação",c:false}, {t:"Conclusão",c:false}], pts: 3, exp: "'Mas' é uma conjunção adversativa, indicando oposição ao resultado esperado." },
              { id: "7ANO-POR-M15", p: "Passando a frase 'O menino disse: — Eu vou ao parque' para o discurso indireto, temos:", o: [{t:"O menino disse que iria ao parque.",c:true}, {t:"O menino disse: vou ao parque.",c:false}, {t:"O menino iria ao parque dizendo.",c:false}, {t:"Eu fui ao parque, disse o menino.",c:false}], pts: 3, exp: "No discurso indireto, o narrador reproduz com suas próprias palavras a fala do personagem." },
              { id: "7ANO-POR-M16", p: "Qual figura de linguagem está presente em 'Aquela criança é um anjo'?", o: [{t:"Metáfora",c:true}, {t:"Comparação",c:false}, {t:"Metonímia",c:false}, {t:"Personificação",c:false}], pts: 3, exp: "Há uma comparação implícita sem o uso do termo comparativo ('como'), caracterizando a metáfora." },
              { id: "7ANO-POR-M17", p: "Na frase 'O vento uivava na noite fria', temos qual figura de linguagem?", o: [{t:"Hipérbole",c:false}, {t:"Personificação (Prosopopeia)",c:true}, {t:"Antítese",c:false}, {t:"Eufemismo",c:false}], pts: 3, exp: "Atribui-se uma ação humana ('uivar') a um elemento inanimado ('o vento')." },
              { id: "7ANO-POR-M18", p: "O recurso da coesão anafórica consiste em:", o: [{t:"Antecipar um termo que ainda será dito",c:false}, {t:"Retomar um termo já citado no texto evitando repetições",c:true}, {t:"Utilizar pontuação excessiva",c:false}, {t:"Criar rimas em poemas",c:false}], pts: 3, exp: "A anáfora é o mecanismo de coesão que retoma uma informação anterior no texto." },
              { id: "7ANO-POR-M19", p: "Identifique a linguagem conotativa (figurada) na frase:", o: [{t:"A água da piscina está gelada.",c:false}, {t:"Aquele homem tem um coração de pedra.",c:true}, {t:"O cachorro latiu no quintal.",c:false}, {t:"A mesa foi feita de madeira.",c:false}], pts: 3, exp: "'Coração de pedra' é usado em sentido figurado (insensível), não literal." },
              { id: "7ANO-POR-M20", p: "Em uma carta de reclamação, o autor pretende:", o: [{t:"NARRAR uma lenda antiga",c:false}, {t:"Manifestar insatisfação e solicitar a solução de um problema",c:true}, {t:"Anunciar um evento festivo",c:false}, {t:"Explicar uma fórmula científica",c:false}], pts: 2, exp: "A carta de reclamação tem caráter persuasivo e reivindicatório junto a um destinatário." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-POR-D01", p: "Qual a diferença sintática entre 'Havia muitos problemas' e 'Existiam muitos problemas'?", o: [{t:"'Havia' é verbo impessoal (oração sem sujeito); 'Existiam' concorda com o sujeito 'muitos problemas'.",c:true}, {t:"Ambas as frases possuem sujeito indeterminado.",c:false}, {t:"'Havia' possui sujeito 'muitos problemas'.",c:false}, {t:"Ambas as frases são orações sem sujeito.",c:false}], pts: 4, exp: "O verbo 'haver' no sentido de existir é impessoal (sem sujeito). O verbo 'existir' é pessoal e flexiona com o sujeito." },
              { id: "7ANO-POR-D02", p: "Na oração 'A professora considerou a resposta correta', qual a função sintática da palavra 'correta'?", o: [{t:"Adjunto adnominal",c:false}, {t:"Predicativo do objeto",c:true}, {t:"Predicativo do sujeito",c:false}, {t:"Objeto direto",c:false}], pts: 4, exp: "'Correta' atribui um estado/qualidade ao objeto direto ('a resposta'), sendo Predicativo do Objeto." },
              { id: "7ANO-POR-D03", p: "Assinale a alternativa em que o uso do 'porquê' está correto:", o: [{t:"Não fui à aula por que estava chovendo.",c:false}, {t:"Você não estudou por quê?",c:true}, {t:"Não sei o porque de tanta confusão.",c:false}, {t:"Por que você está rindo? Porque sim.",c:false}], pts: 4, exp: "Em final de frase interrogativa, utiliza-se 'por quê' isolado com acento circunflexo." },
              { id: "7ANO-POR-D04", p: "Indique a opção que preenche corretamente as lacunas: '___ anos não vejo meu amigo. Daqui ___ dois meses irei visitá-lo.'", o: [{t:"Há / a",c:true}, {t:"A / há",c:false}, {t:"Há / há",c:false}, {t:"A / a",c:false}], pts: 4, exp: "'Há' indica tempo decorrido (passado); 'a' indica tempo futuro ou distância." },
              { id: "7ANO-POR-D05", p: "Se passarmos a frase 'O cientista descobriu a vacina' para a voz passiva analítica, teremos:", o: [{t:"A vacina foi descoberta pelo cientista.",c:true}, {t:"Descobriu-se a vacina pelo cientista.",c:false}, {t:"O cientista tinha descoberto a vacina.",c:false}, {t:"A vacina descobrirá o cientista.",c:false}], pts: 4, exp: "Na voz passiva analítica: Sujeito paciente ('A vacina') + verbo auxiliar no tempo do principal ('foi') + particípio ('descoberta') + agente da passiva ('pelo cientista')." },
              { id: "7ANO-POR-D06", p: "Na frase 'Comprei o livro que o professor indicou', qual a função do pronome relativo 'que'?", o: [{t:"Ligar orações retomando o substantivo 'livro'",c:true}, {t:"Demonstrar posse",c:false}, {t:"Expressar dúvida",c:false}, {t:"Indicar lugar",c:false}], pts: 4, exp: "O 'que' é um pronome relativo anafórico que evita a repetição de 'livro' na segunda oração." },
              { id: "7ANO-POR-D07", p: "Assinale a frase em que há ambiguidade involuntária que prejudica a clareza do texto:", o: [{t:"O menino viu o cachorro do seu vizinho.",c:true}, {t:"A menina leu o livro na biblioteca.",c:false}, {t:"Os alunos entregaram os trabalhos ao professor.",c:false}, {t:"A professora corrigiu a prova atentamente.",c:false}], pts: 4, exp: "'O cachorro do seu vizinho' pode significar o animal de estimação ou ser um xingamento ao vizinho." },
              { id: "7ANO-POR-D08", p: "Qual das opções apresenta regência verbal em conformidade com o padrão culto da língua?", o: [{t:"Assistimos o filme ontem à noite.",c:false}, {t:"Assistimos ao filme ontem à noite.",c:true}, {t:"Chegamos em São Paulo bem cedo.",c:false}, {t:"Prefiro mais doce do que salgado.",c:false}], pts: 4, exp: "O verbo 'assistir' no sentido de ver/presenciar exige preposição 'a' (VTII): 'assistir ao filme'." },
              { id: "7ANO-POR-D09", p: "Assinale a opção em que a concordância verbal está INCORRETA segundo a norma-padrão:", o: [{t:"Faz três anos que não o vejo.",c:false}, {t:"Houve muitos acidentes naquela estrada.",c:false}, {t:"Fazem três anos que não viajo.",c:true}, {t:"Choveram pedidos de desculpas.",c:false}], pts: 4, exp: "O verbo 'fazer' indicando tempo decorrido é impessoal e fica no singular: 'Faz três anos'." },
              { id: "7ANO-POR-D10", p: "Na oração 'A maior parte dos estudantes passou no teste', a concordância verbal no singular deve-se a:", o: [{t:"Regra do sujeito composto",c:false}, {t:"Concordância facultativa com a expressão partitiva 'A maior parte de'",c:true}, {t:"Uso do verbo impessoal",c:false}, {t:"Presença de sujeito oculto",c:false}], pts: 4, exp: "Com expressões partitivas ('a maior parte de', 'a maioria de'), o verbo pode concordar com o núcleo partitivo (singular) ou com o especificador (plural)." },
              { id: "7ANO-POR-D11", p: "Em 'Entregamos o prêmio ao vencedor do concurso', o termo 'ao vencedor do concurso' funciona como:", o: [{t:"Objeto direto",c:false}, {t:"Objeto indireto",c:true}, {t:"Agente da passiva",c:false}, {t:"Predicativo do sujeito",c:false}], pts: 4, exp: "Completa a regência de 'entregar' (quem entrega, entrega algo a alguém) com preposição 'a'." },
              { id: "7ANO-POR-D12", p: "Qual recurso linguístico é predominante no gênero propaganda para convencer o interlocutor?", o: [{t:"Emprego frequente de verbos no modo imperativo e adjetivos expressivos",c:true}, {t:"Linguagem estritamente científica e impessoal",c:false}, {t:"Ausência de recursos visuais",c:false}, {t:"Uso exclusivo de termos arcaicos",c:false}], pts: 4, exp: "A propaganda busca persuadir usando o modo imperativo ('compre', 'faça') e apelo emotivo/adjetivação." },
              { id: "7ANO-POR-D13", p: "Assinale a alternativa que apresenta figura de linguagem denominada Antítese:", o: [{t:"Ele chorou um rio de lágrimas.",c:false}, {t:"O frio e o calor convivem no mesmo ambiente.",c:true}, {t:"O sol sorria para as flores.",c:false}, {t:"Suas palavras soaram como música.",c:false}], pts: 4, exp: "Antítese consiste na aproximação de palavras ou ideias de sentidos opostos ('frio' x 'calor')." },
              { id: "7ANO-POR-D14", p: "Na frase 'Não se deve faltar às aulas sem justificativa', o uso do sinal indicativo de crase em 'às' ocorre devido a:", o: [{t:"Junção da preposição 'a' exigida por 'faltar' com o artigo feminino 'as'",c:true}, {t:"Presença de palavra masculina depois do 'a'",c:false}, {t:"Uso facultativo antes de verbos",c:false}, {t:"Regra geral dos pronomes retos",c:false}], pts: 4, exp: "Quem falta, falta A algum lugar (preposição a) + artigo feminino plural AS de 'aulas' = às." },
              { id: "7ANO-POR-D15", p: "Em 'Eles organizaram a reunião afin de alinhar as metas', há um erro gramatical. Como deveria ser escrita a locução destacada?", o: [{t:"A fim de (separado)",c:true}, {t:"Afin de (junto)",c:false}, {t:"Há fim de",c:false}, {t:"Ah fim de",c:false}], pts: 4, exp: "A locução prepositiva que indica finalidade é 'a fim de' (escrita separadamente)." },
              { id: "7ANO-POR-D16", p: "Qual das frases apresenta variação linguística do tipo geográfica (dialetal)?", o: [{t:"Vossa Mercê deseja algo mais?",c:false}, {t:"O menino disse: 'Oxe, tu viu aquilo, meu rei?'",c:true}, {t:"O paciente apresenta quadro estável.",c:false}, {t:"O réu foi considerado culpado pelo juiz.",c:false}], pts: 4, exp: "Expressões como 'oxe' e 'meu rei' caracterizam variações regionais (geográficas)." },
              { id: "7ANO-POR-D17", p: "No gênero reportagem, o uso de depoimentos de especialistas cumpre a função de:", o: [{t:"Apenas preencher espaço no texto",c:false}, {t:"Conferir autoridade e credibilidade às informações apresentadas",c:true}, {t:"Transformar o texto em um poema",c:false}, {t:"Indeterminar os fatos relatados",c:false}], pts: 4, exp: "Citações de especialistas funcionam como argumento de autoridade na reportagem." },
              { id: "7ANO-POR-D18", p: "Qual das opções apresenta a correta classificação morfológica e sintática da palavra 'muito' em 'Os alunos estudaram muito'?", o: [{t:"Adjetivo / Predicativo",c:false}, {t:"Advérbio de intensidade / Adjunto adverbial",c:true}, {t:"Pronome indefinido / Objeto direto",c:false}, {t:"Substantivo / Núcleo do sujeito",c:false}], pts: 4, exp: "Modifica o verbo 'estudaram' indicando intensidade, funcionando como advérbio e adjunto adverbial." },
              { id: "7ANO-POR-D19", p: "Em relação ao texto literário e não literário, é correto afirmar que:", o: [{t:"O texto literário prioriza a função emotiva/estética e o sentido conotativo da linguagem.",c:true}, {t:"O texto não literário utiliza predominantemente a conotação e a ambiguidade.",c:false}, {t:"Ambos possuem o mesmo objetivo de informar com máxima objetividade.",c:false}, {t:"A literatura rejeita o uso de figuras de linguagem.",c:false}], pts: 4, exp: "Textos literários exploram a subjetividade, conotação e valor estético/artístico das palavras." },
              { id: "7ANO-POR-D20", p: "Assinale a alternativa que apresenta a correta pontuação para isolar o vocativo:", o: [{t:"Alunos prestem atenção, na explicação.",c:false}, {t:"Alunos, prestem atenção na explicação.",c:true}, {t:"Alunos prestem, atenção na explicação.",c:false}, {t:"Alunos prestem atenção na, explicação.",c:false}], pts: 4, exp: "O vocativo (termo de chamamento 'Alunos') deve vir obrigatoriamente isolado por vírgula." },
            
        ],

       // ==================== HISTÓRIA (7º ANO) ====================

        "História": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-HIS-F01", p: "O sistema econômico, político e social predominante na Europa Ocidental durante grande parte da Idade Média ficou conhecido como:", o: [{t:"Capitalismo",c:false}, {t:"Feudalismo",c:true}, {t:"Socialismo",c:false}, {t:"Mercantilismo",c:false}], pts: 2, exp: "O Feudalismo foi a organização socioeconômica e política marcante da Europa medieval." },
              { id: "7ANO-HIS-F02", p: "A sociedade feudal era estamental e dividida tradicionalmente em três ordens principais, representadas por:", o: [{t:"Burgueses, operários e camponeses",c:false}, {t:"Clero (os que rezam), Nobreza (os que lutam) e Servos/Camponeses (os que trabalham)",c:true}, {t:"Rei, senadores e escravos",c:false}, {t:"Comerciantes, artesãos e militares",c:false}], pts: 2, exp: "A divisão clássica medieval compreendia os oratores (clero), bellatores (nobreza) e laboratores (servos)." },
              { id: "7ANO-HIS-F03", p: "Na sociedade feudal, os camponeses presos à terra e sujeitos ao pagamento de impostos aos senhores feudais eram chamados de:", o: [{t:"Cidadãos",c:false}, {t:"Servos",c:true}, {t:"Patrícios",c:false}, {t:"Burgueses",c:false}], pts: 2, exp: "Os servos estavam vinculados ao feudo e deviam obrigações de trabalho e impostos ao senhor." },
              { id: "7ANO-HIS-F04", p: "Qual instituição exerceu grande poder político, econômico e cultural na Europa ocidental durante a Idade Média?", o: [{t:"A Igreja Católica",c:true}, {t:"O Parlamento Inglês",c:false}, {t:"As Corporações de Ofício",c:false}, {t:"As Universidades Americanas",c:false}], pts: 2, exp: "A Igreja Católica era a instituição mais poderosa e unificadora da Europa medieval." },
              { id: "7ANO-HIS-F05", p: "O movimento cultural e artístico ocorrido na Europa entre os séculos XIV e XVI que valorizou a Antiguidade Clássica é chamado de:", o: [{t:"Iluminismo",c:false}, {t:"Renascimento Cultural",c:true}, {t:"Revolução Industrial",c:false}, {t:"Romantismo",c:false}], pts: 2, exp: "O Renascimento buscou inspirar-se nas culturas greco-romanas para renovar artes e ciências." },
              { id: "7ANO-HIS-F06", p: "Uma das principais características do Renascimento que colocava o ser humano no centro das atenções do universo chamava-se:", o: [{t:"Teocentrismo",c:false}, {t:"Antropocentrismo",c:true}, {t:"Feudalismo",c:false}, {t:"Mecenato",c:false}], pts: 2, exp: "O Antropocentrismo substituiu a visão teocêntrica medieval ao valorizar a razão e a figura humana." },
              { id: "7ANO-HIS-F07", p: "A invenção da imprensa de tipos móveis no século XV facilitou a difusão de livros e ideias na Europa. Seu criador foi:", o: [{t:"Leonardo da Vinci",c:false}, {t:"Johannes Gutenberg",c:true}, {t:"Galileu Galilei",c:false}, {t:"Isaac Newton",c:false}], pts: 2, exp: "Gutenberg desenvolveu a imprensa com tipos móveis de metal por volta de 1440." },
              { id: "7ANO-HIS-F08", p: "O processo de expansão marítima europeia nos séculos XV e XVI ficou conhecido como:", o: [{t:"Revolução Urbana",c:false}, {t:"Grandes Navegações",c:true}, {t:"Guerra dos Cem Anos",c:false}, {t:"Invasões Bárbaras",c:false}], pts: 2, exp: "As Grandes Navegações marcaram a exploração e conquista dos oceanos pelos europeus." },
              { id: "7ANO-HIS-F09", p: "Qual era o principal objetivo econômico inicial das navegações portuguesas no século XV?", o: [{t:"Chegar às Índias para comprar especiarias diretamente da fonte",c:true}, {t:"Descobrir o continente americano",c:false}, {t:"Mudar a capital da Europa para a África",c:false}, {t:"Encontrar rotas para a Antártida",c:false}], pts: 2, exp: "O objetivo principal era romper o monopólio italiano/árabe no comércio de especiarias indianas." },
              { id: "7ANO-HIS-F10", p: "Qual país europeu foi o pioneiro no processo das Grandes Navegações marítimas?", o: [{t:"Espanha",c:false}, {t:"Inglaterra",c:false}, {t:"Portugal",c:true}, {t:"França",c:false}], pts: 2, exp: "Portugal foi o pioneiro devido à posição geográfica, paz interna e centralização monárquica precoce." },
              { id: "7ANO-HIS-F11", p: "O monge alemão que iniciou a Reforma Protestante em 1517 ao afixar as 95 Teses foi:", o: [{t:"João Calvino",c:false}, {t:"Martinho Lutero",c:true}, {t:"Henrique VIII",c:false}, {t:"Ignácio de Loyola",c:false}], pts: 2, exp: "Lutero criticou dogmas e abusos da Igreja Católica, dando início à Reforma Protestante." },
              { id: "7ANO-HIS-F12", p: "Uma das principais críticas de Martinho Lutero à Igreja Católica da época referia-se a:", o: [{t:"Tradução da Bíblia para línguas locais",c:false}, {t:"Venda de indulgências (perdão dos pecados em troca de dinheiro)",c:true}, {t:"Criação de escolas rurais",c:false}, {t:"Construção de hospitais públicos",c:false}], pts: 2, exp: "A comercialização de indulgências pela Igreja foi o estopim para as críticas luteranas." },
              { id: "7ANO-HIS-F13", p: "Antes da chegada dos espanhóis, os Maias construíram uma impressionante civilização localizada na região da:", o: [{t:"América do Norte (Canadá)",c:false}, {t:"Mesoamérica (América Central e sul do México)",c:true}, {t:"Cordilheira dos Andes (Peru)",c:false}, {t:"Bacia do Rio da Prata",c:false}], pts: 2, exp: "A civilização Maia desenvolveu-se na Mesoamérica (Guatemala, México, Honduras, etc.)." },
              { id: "7ANO-HIS-F14", p: "A grande capital do Império Asteca, construída sobre um lago onde hoje fica a Cidade do México, chamava-se:", o: [{t:"Cuzco",c:false}, {t:"Tenochtitlán",c:true}, {t:"Machu Picchu",c:false}, {t:"Tikal",c:false}], pts: 2, exp: "Tenochtitlán era uma fascinante cidade construída sobre as águas do lago Texcoco." },
              { id: "7ANO-HIS-F15", p: "O vasto Império Inca estendia-se pela América do Sul ao longo da região geográfica da:", o: [{t:"Mata Atlântica",c:false}, {t:"Cordilheira dos Andes",c:true}, {t:"Amazônia Central",c:false}, {t:"Pampa Gaúcho",c:false}], pts: 2, exp: "Os Incas dominaram a região andina, abrangendo áreas dos atuais Peru, Equador, Bolívia e Chile." },
              { id: "7ANO-HIS-F16", p: "A expedição portuguesa comandada por Pedro Álvares Cabral chegou ao litoral do atual Brasil no ano de:", o: [{t:"1492",c:false}, {t:"1500",c:true}, {t:"1530",c:false}, {t:"1822",c:false}], pts: 2, exp: "A frota cabralina aportou na Bahia em 22 de abril de 1500." },
              { id: "7ANO-HIS-F17", p: "A primeira atividade econômica explorada pelos portugueses no Brasil após a chegada foi a extração de:", o: [{t:"Ouro",c:false}, {t:"Pau-brasil",c:true}, {t:"Café",c:false}, {t:"Algodão",c:false}], pts: 2, exp: "O pau-brasil era explorado pela Coroa para extração de corante vermelho para tecidos." },
              { id: "7ANO-HIS-F18", p: "A troca do trabalho indígena pelo corte do pau-brasil em troca de objetos europeus (espelhos, machados) chamava-se:", o: [{t:"Servidão",c:false}, {t:"Escambo",c:true}, {t:"Tributação",c:false}, {t:"Meação",c:false}], pts: 2, exp: "O escambo consistia na troca direta de mercadorias e trabalho sem uso de moedas." },
              { id: "7ANO-HIS-F19", p: "Na história do continente africano, o próspero Império do Mali ficou famoso por sua riqueza em comércio e:", o: [{t:"Prata",c:false}, {t:"Ouro",c:true}, {t:"Petróleo",c:false}, {t:"Seda",c:false}], pts: 2, exp: "O Mali dominou vastas jazidas e rotas de comércio de ouro na região subsaariana." },
              { id: "7ANO-HIS-F20", p: "A forma de governo na qual o rei concentra em suas mãos quase todos os poderes de Estado é o:", o: [{t:"Absolutismo monárquico",c:true}, {t:"Anarquismo",c:false}, {t:"Feudalismo democrático",c:false}, {t:"Republícanismo parlamentar",c:false}], pts: 2, exp: "O Absolutismo centralizou o poder político nas mãos do monarca na Idade Moderna." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
              { id: "7ANO-HIS-M01", p: "O sistema de obrigações feudais no qual o vassalo jurava fidelidade e serviço militar ao suserano em troca de terras chamava-se:", o: [{t:"Suserania e Vassalagem",c:true}, {t:"Servidão Glebal",c:false}, {t:"Corporação de Ofício",c:false}, {t:"Mercantilismo",c:false}], pts: 3, exp: "As relações de suserania e vassalagem ocorriam exclusivamente entre nobres." },
              { id: "7ANO-HIS-M02", p: "No feudo, a obrigação do servo de trabalhar gratuitamente alguns dias da semana nas terras do senhor chamava-se:", o: [{t:"Talha",c:false}, {t:"Corveia",c:true}, {t:"Banalidade",c:false}, {t:"Tostão de Pedro",c:false}], pts: 3, exp: "A corveia era a prestação de trabalho gratuito no manso senhorial." },
              { id: "7ANO-HIS-M03", p: "As expedições militares organizadas pela cristandade ocidental para retomar Jerusalém dos muçulmanos foram chamadas de:", o: [{t:"Invasões Bárbaras",c:false}, {t:"Cruzadas",c:true}, {t:"Navegações",c:false}, {t:"Guerra dos Cem Anos",c:false}], pts: 3, exp: "As Cruzadas uniram motivações religiosas, econômicas e sociais na Idade Média." },
              { id: "7ANO-HIS-M04", p: "A terrível epidemia que devastou cerca de um terço da população europeia no século XIV ficou conhecida como:", o: [{t:"Gripe Espanhola",c:false}, {t:"Peste Negra (Peste Bubônica)",c:true}, {t:"Cólera",c:false}, {t:"Varíola",c:false}], pts: 3, exp: "A Peste Negra (1347-1351) causou imensa mortalidade e crises no sistema feudal." },
              { id: "7ANO-HIS-M05", p: "O conjunto de práticas econômicas dos Estados Absolutistas caracterizado pelo acúmulo de metais e protecionismo chama-se:", o: [{t:"Mercantilismo",c:true}, {t:"Liberalismo",c:false}, {t:"Fisiocracia",c:false}, {t:"Feudalismo",c:false}], pts: 3, exp: "O Mercantilismo visava enriquecer o Estado absolutista acumulando riqueza e metais." },
              { id: "7ANO-HIS-M06", p: "O Tratado de Tordesilhas, assinado em 1494 entre Portugal e Espanha, tinha o objetivo de:", o: [{t:"Dividir as terras descobertas e por descobrir fora da Europa entre os dois países",c:true}, {t:"Acabar com a escravidão indígena na América",c:false}, {t:"Fundar a Igreja Protestante na América",c:false}, {t:"Unificar os reinos de Portugal e Espanha",c:false}], pts: 3, exp: "Tordesilhas traçou uma linha imaginária dividindo as áreas de domínio ibérico pelo mundo." },
              { id: "7ANO-HIS-M07", p: "A reação da Igreja Católica à expansão do protestantismo, articulada no Concílio de Trento, ficou conhecida como:", o: [{t:"Reforma Luterana",c:false}, {t:"Contrarreforma (ou Reforma Católica)",c:true}, {t:"Iluminismo Religioso",c:false}, {t:"Cisma do Oriente",c:false}], pts: 3, exp: "A Contrarreforma reorganizou a Igreja Católica e combateu a difusão das teses protestantes." },
              { id: "7ANO-HIS-M08", p: "A Ordem religiosa fundada por Inácio de Loyola que teve papel fundamental na catequização dos indígenas no Brasil foi:", o: [{t:"Ordem dos Franciscanos",c:false}, {t:"Companhia de Jesus (Jesuítas)",c:true}, {t:"Ordem dos Benedictinos",c:false}, {t:"Ordem dos Carmelitas",c:false}], pts: 3, exp: "Os jesuítas foram os principais responsáveis pelas missões e catequese na América portuguesa." },
              { id: "7ANO-HIS-M09", p: "O sistema administrativo implantado pela Coroa portuguesa em 1534 dividindo o Brasil em faixas de terra hereditárias chamava-se:", o: [{t:"Governo-Geral",c:false}, {t:"Capitanias Hereditárias",c:true}, {t:"Sesmarias",c:false}, {t:"Vistorias Reais",c:false}], pts: 3, exp: "As Capitanias dividiram o litoral em 15 quinhões doados a donatários da nobreza/burguesia." },
              { id: "7ANO-HIS-M10", p: "Para centralizar a administração do Brasil após o fracasso de grande parte das capitanias, Portugal criou em 1548 o:", o: [{t:"Conselho das Índias",c:false}, {t:"Governo-Geral (com sede em Salvador)",c:true}, {t:"Ministério do Interior",c:false}, {t:"Tribunal da Relação",c:false}], pts: 3, exp: "O Governo-Geral unificou a autoridade política no Brasil colonial a partir de Salvador." },
              { id: "7ANO-HIS-M11", p: "A principal atividade econômica que estruturou a colonização do Nordeste brasileiro no século XVI e XVII foi:", o: [{t:"A extração de ouro",c:false}, {t:"A produção de açúcar nos engenhos",c:true}, {t:"O cultivo do café",c:false}, {t:"A criação de gado no sertão apenas",c:false}], pts: 3, exp: "O açúcar tornou-se o grande produto de exportação da colônia brasileira." },
              { id: "7ANO-HIS-M12", p: "A travessia forçada de milhões de africanos escravizados pelo Oceano Atlântico para a América era feita nos chamados:", o: [{t:"Navios Negreiros (Tumbeiros)",c:true}, {t:"Caravelas de Guerra",c:false}, {t:"Vapores Comerciais",c:false}, {t:"Galeões Espanhóis",c:false}], pts: 3, exp: "Os navios tumbeiros transportavam africanos sob condições desumanas de aprisionamento." },
              { id: "7ANO-HIS-M13", p: "Nas sociedades da África Ocidental, os guardiões da memória e mantenedores das tradições orais são chamados de:", o: [{t:"Xamãs",c:false}, {t:"Griôs (ou Jalis)",c:true}, {t:"Pajés",c:false}, {t:"Sacerdotes Mayas",c:false}], pts: 3, exp: "Os Griôs transmitem oralmente a história, genealogia e valores da comunidade." },
              { id: "7ANO-HIS-M14", p: "Para cultivar alimentos nas encostas íngremes das montanhas andinas, os Incas desenvolveram a técnica de:", o: [{t:"Rotação de culturas em pântanos",c:false}, {t:"Terraços de cultivo (degraus nas montanhas)",c:true}, {t:"Chinampas fluviais",c:false}, {t:"Queimadas extensivas",c:false}], pts: 3, exp: "Os terraços permitiam irrigação eficiente e aproveitavam o relevo acentuado dos Andes." },
              { id: "7ANO-HIS-M15", p: "As ilhas artificiais de cultivo construídas pelos Astecas no lago Texcoco eram chamadas de:", o: [{t:"Quipus",c:false}, {t:"Chinampas",c:true}, {t:"Pueblos",c:false}, {t:"Sesmarias",c:false}], pts: 3, exp: "As chinampas eram hortas flutuantes altamente produtivas sobre a água do lago." },
              { id: "7ANO-HIS-M16", p: "A teoria de autoria de pensadores como Jacques Bossuet que defendia que o poder do rei vinha diretamente de Deus chamava-se:", o: [{t:"Teoria da Vontade Geral",c:false}, {t:"Teoria do Direito Divino dos Reis",c:true}, {t:"Teoria da Luta de Classes",c:false}, {t:"Contrato Social",c:false}], pts: 3, exp: "O Direito Divino justificava a autoridade absoluta do monarca como representante sagrado." },
              { id: "7ANO-HIS-M17", p: "No século XVII, a região de Pernambuco foi invadida e ocupada durante 24 anos por colonizadores oriundos da:", o: [{t:"França",c:false}, {t:"Holanda (Companhia das Índias Occidentais)",c:true}, {t:"Inglaterra",c:false}, {t:"Espanha",c:false}], pts: 3, exp: "A ocupação holandesa (1630-1654) visava controlar a produção e comércio de açúcar." },
              { id: "7ANO-HIS-M18", p: "O maior e mais duradouro refúgio de negros escravizados que fugiram no Brasil colonial foi o:", o: [{t:"Quilombo dos Palmares",c:true}, {t:"Quilombo do Jabaquara",c:false}, {t:"Quilombo de Cabula",c:false}, {t:"Arraial de Canudos",c:false}], pts: 3, exp: "Palmares resistiu por quase um século na Serra da Barriga, tornando-se símbolo de liberdade." },
              { id: "7ANO-HIS-M19", p: "A Confederação dos Tamoios e a Guerra dos Bárbaros foram conflitos motivados pela:", o: [{t:"Disputa do ouro pelas cidades coloniais",c:false}, {t:"Resistência indígena contra a escravização e invasão de suas terras",c:true}, {t:"Luta dos portugueses contra os franceses no sul",c:false}, {t:"Revolta dos escravos urbanos em Salvador",c:false}], pts: 3, exp: "Diferentes povos indígenas uniram-se em armas contra a dominação e escravização portuguesa." },
              { id: "7ANO-HIS-M20", p: "O principal fator demográfico que dizimou a maior parte da população nativa americana no século XVI foi:", o: [{t:"A escassez de alimentos na América",c:false}, {t:"As epidemias trazidas pelos europeus (varíola, gripe, sarampo)",c:true}, {t:"O rigor das temperaturas de inverno",c:false}, {t:"As disputas entre as próprias tribos",c:false}], pts: 3, exp: "As doenças e a falta de imunidade biológica dos nativos provocaram um verdadeiro genocídio epidêmico." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-HIS-D01", p: "A transição do Feudalismo para o Capitalismo comercial na Europa foi impulsionada sobretudo por qual conjunto de fatores?", o: [{t:"Pelo renascimento urbano/comercial, surgimento da burguesia e fortalecimento do poder real",c:true}, {t:"Pela eliminação do uso de moedas e volta ao escambo puro",c:false}, {t:"Pelo isolamento definitivo das cidades europeias",c:false}, {t:"Pela proibição absoluta do comércio na Bacia do Mediterrâneo",c:false}], pts: 4, exp: "A reabertura de rotas, o crescimento das cidades e a aliança rei-burguesia minaram a descentralização feudal." },
              { id: "7ANO-HIS-D02", p: "A Crise do Século XIV na Europa reuniu três elementos trágicos combinados, conhecidos como a tríade:", o: [{t:"Fome, Peste e Guerra",c:true}, {t:"Inundação, Terremoto e Tsunami",c:false}, {t:"Revolução, Seca e Inflação",c:false}, {t:"Inquisição, Cruzadas e Heresia",c:false}], pts: 4, exp: "A escassez de colheitas (fome), a Peste Negra e os conflitos (como a Guerra dos 100 Anos) desestruturaram o mundo medieval." },
              { id: "7ANO-HIS-D03", p: "O Mecenato, prática fundamental para o florescimento artístico do Renascimento, consistia no:", o: [{t:"Financiamento e proteção de artistas e intelectuais por ricos comerciantes, nobres e papas",c:true}, {t:"Monopólio estatal da pintura por ordens militares",c:false}, {t:"Boicote às obras que usassem perspectiva e realismo",c:false}, {t:"Trabalho obrigatório e não remunerado dos pintores nas igrejas",c:false}], pts: 4, exp: "Mecenas (como a família Médici) patrocinavam artistas para projetar prestígio e poder através da arte." },
              { id: "7ANO-HIS-D04", p: "Como a doutrina protestante de João Calvino (Calvinismo) diferenciava-se do Luteranismo em relação à vida econômica?", o: [{t:"Calvino condenava todo e qualquer tipo de lucro comercial como pecado grave",c:false}, {t:"Calvino defendia a Predestinação Absoluta e via o sucesso no trabalho/lucro como sinal de bênção divina",c:true}, {t:"Calvino proibia a leitura da Bíblia pelos fiéis",c:false}, {t:"Calvino submetia sua igreja diretamente à autoridade do Papa",c:false}], pts: 4, exp: "A ética calvinista valorizou o trabalho árduo, a poupança e o lucro, aliando-se aos anseios da burguesia ascendente." },
              { id: "7ANO-HIS-D05", p: "Qual foi o impacto da maciça entrada de ouro e prata vindos da América na economia europeia do século XVI (A 'Revolução dos Preços')?", o: [{t:"Alta generalizada da inflação e perda de poder de compra na Europa",c:true}, {t:"Redução drástica do valor dos alimentos e das terras",c:false}, {t:"Fim definitivo de todas as moedas de papel",c:false}, {t:"Enriquecimento exclusivo da classe camponesa",c:false}], pts: 4, exp: "A abundância de metais precioso provocou uma forte onda inflacionária que desvalorizou as moedas na Europa." },
              { id: "7ANO-HIS-D06", p: "Antes da chegada dos portugueses, o Reino do Congo destacava-se por ser uma estrutura política caracterizada por:", o: [{t:"Um Estado centralizado sob a autoridade do Manicongo com uma rede de províncias e cobrança de tributos",c:true}, {t:"Tribos nômades que desconheciam a metalurgia e o comércio",c:false}, {t:"Cidades sem qualquer tipo de governo ou organização social",c:false}, {t:"Uma colônia pertencente ao Império Otomano",c:false}], pts: 4, exp: "O Congo possuía complexa organização política, com capital em Mbanza Congo e avançada produção artesanal e metálica." },
              { id: "7ANO-HIS-D07", p: "O célebre Império do Mali manteve sua prosperidade no século XIV articulando sua economia principalmente em torno de:", o: [{t:"Rotas de comércio transariano que trocavam ouro e sal, tendo a cidade de Tombuctú como centro cultural",c:true}, {t:"Apenas da pesca no Oceano Atlântico",c:false}, {t:"Monopólio da venda de especiarias asiáticas na Europa",c:false}, {t:"Exportação de vinho para a América",c:false}], pts: 4, exp: "As rotas transarianas conectavam o Mali ao Norte da África, tornando Tombuctú um polo de saber islâmico e comércio." },
              { id: "7ANO-HIS-D08", p: "Como se diferenciava fundamentalmente a escravidão praticada na Antiguidade da escravidão moderna transatlântica?", o: [{t:"A escravidão moderna foi estruturada como um empreendimento mercantil de massa baseado na racialização do negro",c:true}, {t:"A escravidão antiga baseava-se exclusivamente na cor da pele dos prisioneiros",c:false}, {t:"A escravidão moderna proibia o trabalho nas lavouras e minas",c:false}, {t:"Não havia diferença entre as duas formas de escravidão",c:false}], pts: 4, exp: "O tráfico transatlântico mercantilizou corpos africanos em escala global unindo lucro comercial e ideologia de raça." },
              { id: "7ANO-HIS-D09", p: "A União Ibérica (1580-1640), que unificou as Coroas de Espanha e Portugal, provocou como consequência para o Brasil:", o: [{t:"A anulação temporária do Tratado de Tordesilhas e a invasão holandesa no Nordeste açucareiro",c:true}, {t:"A independência imediata do Brasil frente à Europa",c:false}, {t:"A proibição completa do cultivo da cana-de-açúcar",c:false}, {t:"O fechamento de todos os portos coloniais aos navios espanhóis",c:false}], pts: 4, exp: "Como a Espanha era inimiga da Holanda, os holandeses invadiram o Nordeste brasileiro para garantir seu negócio açucareiro." },
              { id: "7ANO-HIS-D10", p: "O governo do conde Maurício de Nassau em Pernambuco (1637-1644) caracterizou-se por:", o: [{t:"Modernização urbana do Recife, tolerância religiosa e financiamento aos engenhos locais",c:true}, {t:"Violência extrema e destruição de todos os engenhos de açúcar",c:false}, {t:"Proibição da presença de artistas e cientistas europeus",c:false}, {t:"Submissão imediata aos pedidos da Coroa Portuguesa",c:false}], pts: 4, exp: "Nassau promoveu obras de infraestrutura, atraiu artistas/cientistas e adotou liberdade de culto no Nordeste holandês." },
              { id: "7ANO-HIS-D11", p: "As expedições conhecidas como Bandeiras de Apreçamento, operando a partir de São Paulo, tinham como foco principal:", o: [{t:"A captura e escravização de populações indígenas para venda nas lavouras",c:true}, {t:"A construção de estradas de ferro pelo interior",c:false}, {t:"A conversão amigável dos índios ao catolicismo",c:false}, {t:"A expulsão de piratas franceses do Litoral do Rio de Janeiro",c:false}], pts: 4, exp: "As bandeiras de apreçamento aprisionavam milhares de nativos (sobretudo nas missões jesuíticas) para trabalho escravo." },
              { id: "7ANO-HIS-D12", p: "O conceito de 'Decolonialidade' no ensino de história propõe:", o: [{t:"Questionar a narrativa eurocêntrica e valorizar as perspectivas e saberes dos povos colonizados (indígenas e africanos)",c:true}, {t:"Estudar apenas a história dos países europeus",c:false}, {t:"Aceitar sem críticas a visão dos conquistadores do século XVI",c:false}, {t:"Apagar a existência de documentos históricos",c:false}], pts: 4, exp: "A Decolonialidade busca desconstruir a hegemonia eurocêntrica dando voz aos sujeitos historicamente marginalizados." },
              { id: "7ANO-HIS-D13", p: "No Brasil colonial, o papel desempenhado pelas mulheres escravizadas e libertas nas cidades envolvia fundamentalmente:", o: [{t:"O trabalho como 'ganhadeiras' (vendedoras ambulantes), costureiras e na manutenção do espaço doméstico e comunitário",c:true}, {t:"O exercício exclusivo de cargos de liderança política no Senado da Câmara",c:false}, {t:"A administração do comércio de exportação com a Europa",c:false}, {t:"A atuação como juízas e magistradas reais",c:false}], pts: 4, exp: "As mulheres negras 'de ganho' eram vitais para a economia e circulação urbana, além de garantirem a sobrevivência familiar." },
              { id: "7ANO-HIS-D14", p: "O Pacto Colonial (ou Exclusivo Metropolitano) determinava que a colônia deveria:", o: [{t:"Vender suas matérias-primas e comprar produtos manufaturados exclusivamente da sua metrópole",c:true}, {t:"Comercializar livremente com qualquer nação do mundo",c:false}, {t:"Cobrar impostos da própria metrópole europeia",c:false}, {t:"Proibir o transporte de mercadorias por navios",c:false}], pts: 4, exp: "O Exclusivo garantiu que os lucros do comércio colonial ficassem monopolizados pelos comerciantes da metrópole." },
              { id: "7ANO-HIS-D15", p: "O Sincretismo Religioso ocorrido no Brasil colonial resultou da:", o: [{t:"Associação de elementos e divindades das religiões africanas aos santos católicos como forma de resistência e preservação cultual",c:true}, {t:"Aceitação passiva e total do catolicismo sem nenhuma alteração pelos africanos",c:false}, {t:"Eliminação de qualquer elemento simbólico de origem católica",c:false}, {t:"Proibição completa das celebrações religiosas na colônia",c:false}], pts: 4, exp: "O sincretismo permitiu que os africanos mantivessem suas devoções originais sob o manto dos santos católicos." },
              { id: "7ANO-HIS-D16", p: "A expansão da monocultura da cana-de-açúcar e da pecuária na colônia provocou qual impacto ambiental duradouro?", o: [{t:"O intenso desmatamento da Mata Atlântica e modificação de ecossistemas fluviais",c:true}, {t:"O reflorestamento natural de florestas nativas",c:false}, {t:"A proteção dos solos contra a erosão",c:false}, {t:"O fim da poluição dos rios coloniais",c:false}], pts: 4, exp: "O modelo predatório de queimadas para o plantio extensivo dizimou grandes faixas da Mata Atlântica." },
              { id: "7ANO-HIS-D17", p: "Como se comparava a organização política entre a civilização Maia e a civilização Asteca?", o: [{t:"Os Maias organizavam-se em Cidades-Estado autônomas; os Astecas formaram um Império centralizado e militarizado",c:true}, {t:"Os Maias tinham um imperador absoluto; os Astecas viviam em tribos isoladas",c:false}, {t:"Ambas eram repúblicas parlamentares",c:false}, {t:"Não possuíam nenhuma forma de organização política",c:false}], pts: 4, exp: "Diferente do Império Asteca que dominou outros povos por tributos, os Maias nunca tiveram um governo central unificado." },
              { id: "7ANO-HIS-D18", p: "A Guerra dos Mascates (1710-1711) em Pernambuco colocou em confronto direto:", o: [{t:"A nobreza açucareira endividada de Olinda e os comerciantes portugueses (mascates) do Recife",c:true}, {t:"Os escravos negros e os bandeirantes paulistas",c:false}, {t:"Os jesuítas e os soldados franceses",c:false}, {t:"Os índios potiguaras e os colonos holandeses",c:false}], pts: 4, exp: "Os senhores de engenho de Olinda opuseram-se à emancipação política do Recife, dominado por comerciantes portugueses." },
              { id: "7ANO-HIS-D19", p: "A Guerra dos Bárbaros (1686-1713), ocorrida no sertão do Nordeste (incluindo o Ceará), caracterizou-se como:", o: [{t:"Uma longa e violenta resistência dos povos indígenas Tapuias contra a expansão da pecuária em suas terras",c:true}, {t:"Uma batalha travada exclusivamente entre espanhóis e portugueses",c:false}, {t:"Uma revolta de marinheiros ingleses no litoral cearense",c:false}, {t:"Um conflito religioso entre católicos e calvinistas",c:false}], pts: 4, exp: "Os povos do interior (Tapuias) enfrentaram ferozmente os criadores de gado e bandeirantes que tomavam seus territórios." },
              { id: "7ANO-HIS-D20", p: "Como a mudança na concepção do tempo (do 'tempo de Deus' para o 'tempo do homem/comerciante') refletiu as transformações do Renascimento?", o: [{t:"O tempo passou a ser medido e valorizado como recurso associado ao trabalho, negócios e lucro",c:true}, {t:"O tempo deixou de ser medido por relógios nas cidades",c:false}, {t:"A Igreja passou a proibir qualquer contagem do tempo",c:false}, {t:"Os calendários foram totalmente abolidos na Europa",c:false}], pts: 4, exp: "Com a burguesia e o relógio mecânico, o tempo ganhou valor econômico ('tempo é dinheiro'), superando a visão contemplativa medieval." },
        ],


       // ==================== CIÊNCIAS (7º ANO) ====================
        "Ciências": [     
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-CIEN-F01", p: "A grandeza física que mede o grau de agitação das moléculas de um corpo é chamada de:", o: [{t:"Calor",c:false}, {t:"Temperatura",c:true}, {t:"Pressão",c:false}, {t:"Massa",c:false}], pts: 2, exp: "A temperatura é a medida direta da energia cinética média (agitação) das partículas de um corpo." },
              { id: "7ANO-CIEN-F02", p: "A unidade de medida de temperatura mais utilizada oficialmente no Brasil é o:", o: [{t:"Kelvin (K)",c:false}, {t:"Fahrenheit (°F)",c:false}, {t:"Grau Celsius (°C)",c:true}, {t:"Joule (J)",c:false}], pts: 2, exp: "O Grau Celsius (°C) é a unidade padrão de temperatura no sistema métrico brasileiro." },
              { id: "7ANO-CIEN-F03", p: "O calor é definido cientificamente como:", o: [{t:"A quantidade de energia armazenada em um corpo frio",c:false}, {t:"A energia térmica em trânsito de um corpo mais quente para outro mais frio",c:true}, {t:"A mesma coisa que a temperatura corporal",c:false}, {t:"A força exercida por partículas em movimento",c:false}], pts: 2, exp: "Calor é energia térmica em trânsito motivada exclusivamente pela diferença de temperatura entre corpos." },
              { id: "7ANO-CIEN-F04", p: "Qual das opções a seguir é um exemplo clássico de máquina simples do tipo alavanca?", o: [{t:"Tesoura",c:true}, {t:"Lâmpada",c:false}, {t:"Termômetro",c:false}, {t:"Pneu",c:false}], pts: 2, exp: "A tesoura funciona com um ponto de apoio, força potente e força resistente, caracterizando uma alavanca." },
              { id: "7ANO-CIEN-F05", p: "A máquina simples formada por uma roda sulcada que gira ao redor de um eixo para erguer objetos com cordas é a:", o: [{t:"Roldana (ou polia)",c:true}, {t:"Plano inclinado",c:false}, {t:"Cunha",c:false}, {t:"Parafuso",c:false}], pts: 2, exp: "A roldana facilita o erguimento de cargas ao alterar a direção e o sentido da força aplicada." },
              { id: "7ANO-CIEN-F06", p: "O conjunto formado pela interação dos seres vivos (fatores bióticos) com o meio ambiente (fatores abióticos) chama-se:", o: [{t:"População",c:false}, {t:"Ecossistema",c:true}, {t:"Comunidade simples",c:false}, {t:"Biosfera fechada",c:false}], pts: 2, exp: "Um ecossistema compreende as relações entre a comunidade viva e o ambiente físico onde habitam." },
              { id: "7ANO-CIEN-F07", p: "Em uma cadeia alimentar, os seres capazes de produzir seu próprio alimento pela fotossíntese são os:", o: [{t:"Consumidores",c:false}, {t:"Produtores",c:true}, {t:"Decompositores",c:false}, {t:"Carnívoros",c:false}], pts: 2, exp: "Os organismos autótrofos (plantas e algas) ocupam o primeiro nível trófico como produtores." },
              { id: "7ANO-CIEN-F08", p: "Os animais que se alimentam diretamente dos produtores em uma cadeia alimentar são chamados de:", o: [{t:"Consumidores primários",c:true}, {t:"Consumidores secundários",c:false}, {t:"Decompositores",c:false}, {t:"Produtores secundários",c:false}], pts: 2, exp: "Consumidores primários são herbívoros ou onívoros que comem os produtores." },
              { id: "7ANO-CIEN-F09", p: "Fungos e bactérias desempenham um papel essencial na natureza reciclando a matéria orgânica. Eles são os:", o: [{t:"Produtores",c:false}, {t:"Decompositores",c:true}, {t:"Consumidores terciários",c:false}, {t:"Predadores de topo",c:false}], pts: 2, exp: "Decompositores quebram a matéria orgânica morta devolvendo nutrientes ao solo e ambiente." },
              { id: "7ANO-CIEN-F10", p: "Uma característica biológica marcante dos vírus é que eles são:", o: [{t:"Organismos pluricelulares complexos",c:false}, {t:"Acelulares e parasitas intracelulares obrigatórios",c:true}, {t:"Bactérias modificadas pelo calor",c:false}, {t:"Fungos microscópicos autótrofos",c:false}], pts: 2, exp: "Vírus não possuem estrutura celular e dependem de uma célula hospedeira para se reproduzirem." },
              { id: "7ANO-CIEN-F11", p: "Qual das doenças a seguir é causada por uma bactéria?", o: [{t:"Gripe",c:false}, {t:"Dengue",c:false}, {t:"Tuberculose",c:true}, {t:"COVID-19",c:false}], pts: 2, exp: "A tuberculose é uma infecção causada pelo bacilo de Koch (bactéria Mycobacterium tuberculosis)." },
              { id: "7ANO-CIEN-F12", p: "As vacinas são importantes ferramentas de saúde pública pois atuam no organismo:", o: [{t:"Estimulando a produção preventiva de anticorpos e memória imunológica",c:true}, {t:"Matando diretamente todos os vírus com veneno",c:false}, {t:"Substituindo o sangue doente",c:false}, {t:"Curando instantaneamente infecções graves em horas",c:false}], pts: 2, exp: "Vacinas estimulam preventivamente o sistema imunológico a reconhecer e combater patógenos." },
              { id: "7ANO-CIEN-F13", p: "O bioma exclusivamente brasileiro, caracterizado pelo clima semiárido e vegetação adaptada à seca, é a:", o: [{t:"Mata Atlântica",c:false}, {t:"Caatinga",c:true}, {t:"Pampa",c:false}, {t:"Pantanal",c:false}], pts: 2, exp: "A Caatinga é um bioma genuinamente nacional adaptado às condições do clima semiárido." },
              { id: "7ANO-CIEN-F14", p: "Qual é o maior bioma brasileiro em extensão territorial, famoso por sua grande biodiversidade e floresta tropical?", o: [{t:"Cerrado",c:false}, {t:"Amazônia",c:true}, {t:"Mata de Araucárias",c:false}, {t:"Caatinga",c:false}], pts: 2, exp: "A Amazônia ocupa a maior parte do território norte do Brasil contendo a maior bacia hidrográfica do mundo." },
              { id: "7ANO-CIEN-F15", p: "A camada de ozônio presente na atmosfera terrestre é fundamental para a vida pois:", o: [{t:"Bloqueia a passagem do oxigênio para o espaço",c:false}, {t:"Filtra os raios ultravioleta (UV) nocivos emitidos pelo Sol",c:true}, {t:"Impede a ocorrência de chuvas fortes",c:false}, {t:"Produz dióxido de carbono para as plantas",c:false}], pts: 2, exp: "O ozônio estratosférico absorve grande parte da radiação UV nociva à saúde e aos ecossistemas." },
              { id: "7ANO-CIEN-F16", p: "Qual das opções apresenta a ordem correta das camadas internas da Terra, da superfície para o centro?", o: [{t:"Crosta terrestre, Manto e Núcleo",c:true}, {t:"Núcleo, Manto e Crosta",c:false}, {t:"Manto, Núcleo e Atmosfera",c:false}, {t:"Hidrosfera, Crosta e Manto",c:false}], pts: 2, exp: "A estrutura interna da Terra divide-se em Crosta (externa), Manto (intermediária) e Núcleo (central)." },
              { id: "7ANO-CIEN-F17", p: "Os tremores de terra (terremotos) ocorrem principalmente devido ao:", o: [{t:"Movimento e choque entre as placas tectônicas na litosfera",c:true}, {t:"Vento forte na superfície",c:false}, {t:"Aquecimento exagerado da água dos oceanos",c:false}, {t:"Movimento de rotação das nuvens",c:false}], pts: 2, exp: "A movimentação e acúmulo de tensão nas bordas das placas tectônicas liberam energia em forma de terremotos." },
              { id: "7ANO-CIEN-F18", p: "A principal característica que diferencia os animais vertebrados dos invertebrados é a presença de:", o: [{t:"Patas articuladas",c:false}, {t:"Coluna vertebral e crânio",c:true}, {t:"Asas e penas",c:false}, {t:"Antenas sensoriais",c:false}], pts: 2, exp: "Vertebrados possuem esqueleto interno estruturado por crânio e coluna vertebral." },
              { id: "7ANO-CIEN-F19", p: "Durante o processo de fotossíntese, as plantas absorvem gás carbônico e luz solar e liberam para a atmosfera o gás:", o: [{t:"Nitrogênio",c:false}, {t:"Oxigênio",c:true}, {t:"Metano",c:false}, {t:"Hélio",c:false}], pts: 2, exp: "Como subproduto da fotossíntese, as plantas liberam oxigênio (O2) na atmosfera." },
              { id: "7ANO-CIEN-F20", p: "O processo de transferência de calor que ocorre diretamente através do contato matéria com matéria (sólidos) chama-se:", o: [{t:"Condução térmica",c:true}, {t:"Convecção térmica",c:false}, {t:"Irradiação térmica",c:false}, {t:"Evaporação",c:false}], pts: 2, exp: "A condução ocorre partícula por partícula através de um meio material, principalmente nos sólidos." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
              { id: "7ANO-CIEN-M01", p: "Em um líquido em aquecimento no fogão, a água quente sobe e a água fria desce. Esse processo de transferência de calor chama-se:", o: [{t:"Condução",c:false}, {t:"Convecção",c:true}, {t:"Radiação",c:false}, {t:"Sublimação",c:false}], pts: 3, exp: "Convecção ocorre em fluidos devido a diferenças de densidade geradas pela variação de temperatura." },
              { id: "7ANO-CIEN-M02", p: "A energia do Sol chega até a Terra atravessando o vácuo do espaço por meio da:", o: [{t:"Condução",c:false}, {t:"Convecção",c:false}, {t:"Radiação (ou irradiação) eletromagnética",c:true}, {t:"Condensação",c:false}], pts: 3, exp: "A radiação não necessita de meio material para se propagar, transmitindo calor através de ondas eletromagnéticas." },
              { id: "7ANO-CIEN-M03", p: "Quando dois corpos de temperaturas diferentes são colocados em contato e, após certo tempo, atingem a mesma temperatura, dizemos que alcançaram o:", o: [{t:"Calor latente",c:false}, {t:"Equilíbrio térmico",c:true}, {t:"Ponto de ebulição",c:false}, {t:"Zero absoluto",c:false}], pts: 3, exp: "O equilíbrio térmico é o estado em que cessam as trocas de calor por igualdade de temperatura." },
              { id: "7ANO-CIEN-M04", p: "A gangorra e o abridor de garrafas são alavancas. A alavanca que possui o ponto de apoio situado entre a força potente e a força resistente é classificada como:", o: [{t:"Interfixa",c:true}, {t:"Interresistente",c:false}, {t:"Interpotente",c:false}, {t:"Plano inclinado",c:false}], pts: 3, exp: "Alavanca interfixa tem o ponto de apoio (fixo) localizado no meio (ex: gangorra, tesoura)." },
              { id: "7ANO-CIEN-M05", p: "A diferença fundamental entre uma cadeia alimentar e uma teia alimentar é que a teia:", o: [{t:"Representa uma sequência linear única de alimentação",c:false}, {t:"Consiste na interconexão de várias cadeias alimentares de um ecossistema",c:true}, {t:"Mostra apenas os animais predadores de grande porte",c:false}, {t:"Não inclui seres decompositores",c:false}], pts: 3, exp: "A teia alimentar reflete as múltiplas e complexas relações alimentares entre os organismos na natureza." },
              { id: "7ANO-CIEN-M06", p: "A relação ecológica entre os fungos e algas formando os líquens, na qual ambos os seres se beneficiam e dependem um do outro, é o:", o: [{t:"Parasitismo",c:false}, {t:"Mutualismo",c:true}, {t:"Predatismo",c:false}, {t:"Competição",c:false}], pts: 3, exp: "Mutualismo é uma relação harmônica interespecífica obrigatória com vantagens para ambas as espécies." },
              { id: "7ANO-CIEN-M07", p: "A relação em que o carrapato se fixa na pele de um cachorro para sugar seu sangue e lhe causar prejuízos é o:", o: [{t:"Comensalismo",c:false}, {t:"Parasitismo",c:true}, {t:"Mutualismo",c:false}, {t:"Inquilinisimo",c:false}], pts: 3, exp: "No parasitismo, o parasita retira nutrientes do hospedeiro, prejudicando-o." },
              { id: "7ANO-CIEN-M08", p: "Qual das opções descreve uma relação ecológica desarmônica de predatismo?", o: [{t:"Um gavião caçando e alimentando-se de um réptil",c:true}, {t:"Duas aves disputando um ninho",c:false}, {t:"Rêmoras aderidas ao corpo de um tubarão",c:false}, {t:"Bactérias vivendo no intestino humano",c:false}], pts: 3, exp: "Predatismo ocorre quando um indivíduo predador mata outro de espécie diferente (presa) para se alimentar." },
              { id: "7ANO-CIEN-M09", p: "As bactérias são microorganismos unicelulares que não possuem núcleo celular delimitado por membrana, sendo classificadas como:", o: [{t:"Eucariontes",c:false}, {t:"Procariontes",c:true}, {t:"Acelulares",c:false}, {t:"Pluricelulares",c:false}], pts: 3, exp: "Células procariontes possuem material genético disperso no citoplasma sem carioteca." },
              { id: "7ANO-CIEN-M10", p: "O corpo dos fungos pluricelulares (como os cogumelos) é formado por filamentos microscópicos chamados de:", o: [{t:"Hifas (que juntas formam o micélio)",c:true}, {t:"Cílios de queratina",c:false}, {t:"Raízes fibrosas",c:false}, {t:"Tecidos vasculares",c:false}], pts: 3, exp: "Fungos são constituídos por hifas. O emaranhado de hifas forma o micélio do fungo." },
              { id: "7ANO-CIEN-M11", p: "Diferente da vacina, o SORO imunológico é aplicado em casos de emergência (como picada de cobra) pois contém:", o: [{t:"Antígenos mortos para criar memória",c:false}, {t:"Anticorpos prontos produzidos por outro organismo",c:true}, {t:"Antibióticos de largo espectro",c:false}, {t:"Vitaminas de ação rápida",c:false}], pts: 3, exp: "O soro fornece anticorpos prontos para imunização passiva e imediata contra toxinas." },
              { id: "7ANO-CIEN-M12", p: "As plantas da Caatinga que possuem folhas modificadas em espinhos e caules que armazenam água são chamadas de:", o: [{t:"Higrófitas",c:false}, {t:"Xerófitas",c:true}, {t:"Epífitas",c:false}, {t:"Aquáticas",c:false}], pts: 3, exp: "Plantas xerófitas possuem adaptações morfológicas para sobreviver em ambientes secos." },
              { id: "7ANO-CIEN-M13", p: "O bioma Cerrado caracteriza-se por uma vegetação marcada por:", o: [{t:"Árvores de galhos e troncos tortuosos com cascas grossas",c:true}, {t:"Pinheiros de grandes alturas em solo congelado",c:false}, {t:"Florestas densas sem incidência de luz",c:false}, {t:"Plantas aquáticas rasteiras de clima frio",c:false}], pts: 3, exp: "O Cerrado apresenta árvores cascudas e tortuosas adaptadas ao fogo natural e solos ácidos." },
              { id: "7ANO-CIEN-M14", p: "Nas zonas de encontro onde duas placas tectônicas se chocam (limite convergente), é comum a formação de:", o: [{t:"Dunas de areia",c:false}, {t:"Cadeias de montanhas e dobramentos modernos",c:true}, {t:"Rios subterrâneos de água doce",c:false}, {t:"Planícies de deserto",c:false}], pts: 3, exp: "O choque convergente faz com que a crosta dobre e se eleve, formando grandes cordilheiras." },
              { id: "7ANO-CIEN-M15", p: "Os anfíbios (como sapos e rãs) dependem obrigatoriamente do meio aquático para:", o: [{t:"Manter a cor de suas escamas",c:false}, {t:"A reprodução e postura de ovos sem casca impermeável",c:true}, {t:"Conseguir enxergar o alimento",c:false}, {t:"Produzir seu próprio calor interno",c:false}], pts: 3, exp: "Ovos de anfíbios não têm casca protetora contra o dessecação, exigindo água para o desenvolvimento larval." },
              { id: "7ANO-CIEN-M16", p: "Qual grande conquista evolutiva permitiu aos répteis a independência completa da água para a reprodução?", o: [{t:"Ovo com casca protetora rígida e anexos embrionários",c:true}, {t:"Desenvolvimento de asas com penas",c:false}, {t:"Respiração exclusivamente cutânea",c:false}, {t:"Presença de nadadeiras dorsais",c:false}], pts: 3, exp: "O ovo amniótico com casca impediu a desidratação, permitindo a conquista definitiva do ambiente terrestre." },
              { id: "7ANO-CIEN-M17", p: "A principal estrutura que auxilia as aves no voo, tornando seu esqueleto mais leve, são os:", o: [{t:"Dentes maciços",c:false}, {t:"Ossos pneumáticos (com cavidades de ar)",c:true}, {t:"Músculos abdominais rígidos",c:false}, {t:"Membros posteriores pesados",c:false}], pts: 3, exp: "Ossos pneumáticos reduzem o peso corporal das aves facilitando a aerodinâmica do voo." },
              { id: "7ANO-CIEN-M18", p: "Os mamíferos são animais endotérmicos que possuem como características exclusivas do grupo:", o: [{t:"Presença de penas e bico córneo",c:false}, {t:"Presença de glândulas mamárias e pelos no corpo",c:true}, {t:"Pele escamosa e fria",c:false}, {t:"Corpo segmentado por anéis",c:false}], pts: 3, exp: "Mamíferos alimentam seus filhotes com leite (glândulas mamárias) e possuem pelos protetores." },
              { id: "7ANO-CIEN-M19", p: "A capacidade de répteis, aves e mamíferos de manter a temperatura corporal interna ou depender do meio divide-os em:", o: [{t:"Ectotérmicos (répteis) e Endotérmicos (aves e mamíferos)",c:true}, {t:"Invertebrados e Vertebrados simples",c:false}, {t:"Autótrofos e Heterótrofos",c:false}, {t:"Aquáticos e Terrestres",c:false}], pts: 3, exp: "Endotérmicos usam o metabolismo interno para controlar a temperatura; ectotérmicos dependem de fontes externas de calor." },
              { id: "7ANO-CIEN-M20", p: "Qual o nome da camada de ar que envolve a Terra e protege o planeta contra o frio extremo do espaço?", o: [{t:"Litosfera",c:false}, {t:"Atmosfera",c:true}, {t:"Biosfera",c:false}, {t:"Hidrosfera",c:false}], pts: 3, exp: "A atmosfera é a camada gasosa retida pela gravidade que regula o clima e a temperatura terrestre." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
              { id: "7ANO-CIEN-D01", p: "Enquanto uma substância pura está mudando de estado físico (ex: água fervendo a 100°C), a energia em forma de calor absorvida é chamada de:", o: [{t:"Calor sensível (que altera apenas a temperatura)",c:false}, {t:"Calor latente (que altera o estado físico sem mudar a temperatura)",c:true}, {t:"Calor radiante secundário",c:false}, {t:"Capacidade térmica nula",c:false}], pts: 4, exp: "O calor latente é consumido para romper ou formar ligações intermoleculares na mudança de estado sem alterar a temperatura." },
              { id: "7ANO-CIEN-D02", p: "Em pontes e trilhos de trem, deixam-se pequenas fendas chamadas juntas de dilatação. Esse recurso engenharil previne acidentes causados pelo fenômeno da:", o: [{t:"Dilatação térmica dos sólidos quando expostos ao calor",c:true}, {t:"Contração térmica no verão",c:false}, {t:"Evaporação do metal",c:false}, {t:"Sublimação por atrito",c:false}], pts:4, exp: "Com o aumento da temperatura os metais se dilatam. As juntas evitam que os trilhos e vigas empenem ou rompam." },
              { id: "7ANO-CIEN-D03", p: "Um sistema formado por uma roldana fixa e uma roldana móvel reduz a força necessária para erguer um peso pesado pela metade. Isso ocorre porque:", o: [{t:"A roldana móvel divide a força resistente entre os segmentos de corda que a sustentam",c:true}, {t:"A roldana móvel elimina a gravidade do objeto",c:false}, {t:"A roldana fixa multiplica a massa do objeto por dois",c:false}, {t:"Não há vantagem mecânica em usar roldanas móveis",c:false}], pts: 4, exp: "Cada roldana móvel no sistema divide o esforço exigido pela metade (Vantagem Mecânica = 2^n)." },
              { id: "7ANO-CIEN-D04", p: "As máquinas a vapor desenvolvidas na Revolução Industrial revolucionaram os transportes transformando:", o: [{t:"Energia mecânica diretamente em energia eólica",c:false}, {t:"Energia térmica (calor do vapor) em energia mecânica (movimento)",c:true}, {t:"Energia elétrica em calor latente",c:false}, {t:"Energia nuclear em trabalho de rotação",c:false}], pts: 4, exp: "Máquinas térmicas convertem a energia liberada na queima do combustível (calor) em trabalho mecânico." },
              { id: "7ANO-CIEN-D05", p: "O fenômeno do acúmulo progressivo de produtos químicos não biodegradáveis (como mercúrio) ao longo dos níveis tróficos de uma cadeia alimentar é a:", o: [{t:"Eutrofização artificial",c:false}, {t:"Magnificação trófica (ou Bioacumulação)",c:true}, {t:"Fotosserção secundária",c:false}, {t:"Decomposição acelerada",c:false}], pts: 4, exp: "Toxinas não biodegradáveis concentram-se cada vez mais nos organismos dos topo de cadeia (magnificação trófica)." },
              { id: "7ANO-CIEN-D06", p: "Nos ecossistemas, enquanto a MATÉRIA circula de forma cíclica, a ENERGIA comporta-se de forma:", o: [{t:"Unidirecional, diminuindo a cada nível trófico que passa",c:true}, {t:"Cíclica, aumentando no topo da cadeia",c:false}, {t:"Infinita, sem qualquer perda no ambiente",c:false}, {t:"Exclusivamente retida nos decompositores",c:false}], pts: 4, exp: "A energia entra pelo Sol, é dissipada como calor a cada nível trófico e não se recicla (fluxo unidirecional)." },
              { id: "7ANO-CIEN-D07", p: "Por que os antibióticos receitados pelos médicos são ineficazes no tratamento de doenças como Gripe, Dengue e COVID-19?", o: [{t:"Porque antibióticos atuam exclusivamente combatendo bactérias, não afetando vírus",c:true}, {t:"Porque esses vírus possuem parede celular super-resistente",c:false}, {t:"Porque os antibióticos destroem o sistema imunológico",c:false}, {t:"Porque vacinas anulam o efeito dos antibióticos",c:false}], pts: 4, exp: "Antibióticos atacam estruturas celulares bacterianas (parede celular, ribossomos). Vírus são acelulares e insensíveis a eles." },
              { id: "7ANO-CIEN-D08", p: "O uso indiscriminado e incorreto de antibióticos por conta própria pode levar ao surgimento de 'superbactérias' devido ao processo de:", o: [{t:"Seleção natural de bactérias mutantes resistentes",c:true}, {t:"Transformação das bactérias em vírus nocivos",c:false}, {t:"Destruição imediata das defesas do sangue",c:false}, {t:"Criação de novas espécies de fungos",c:false}], pts: 4, exp: "O antibiótico elimina as sensíveis, permitindo que cepas naturalmente resistentes sobrevivam e se multipliquem (seleção natural)." },
              { id: "7ANO-CIEN-D09", p: "A resposta imunológica secundária (acionada quando entramos em contato com um patógeno após já termos sido vacinados) é:", o: [{t:"Mais lenta e fraca que a primeira",c:false}, {t:"Mais rápida, intensa e eficaz devido à memória imunológica dos linfócitos",c:true}, {t:"Completamente inútil para o corpo",c:false}, {t:"Responsável por destruir nossas próprias células saudáveis",c:false}], pts: 4, exp: "Células de memória reconhecem o antígeno imediatamente e produzem anticorpos com rápida eficiência." },
              { id: "7ANO-CIEN-D10", p: "O desmatamento desenfreado da Floresta Amazônica impacta o clima de regiões distantes do Brasil pois reduz o fenômeno dos 'Rios Voadores', que dependem da:", o: [{t:"Evapotranspiração de bilhões de árvores lançando vapor de água na atmosfera",c:true}, {t:"Poluição gerada pelas queimadas urbanas",c:false}, {t:"Infiltração de água no subsolo das cidades",c:false}, {t:"Passagem de correntes marinhas frias",c:false}], pts: 4, exp: "A floresta lança massivas quantidades de umidade no ar via evapotranspiração, transportadas pelo vento como 'rios voadores'." },
              { id: "7ANO-CIEN-D11", p: "O processo de degradação ambiental no bioma Caatinga que transforma solos férteis em áreas áridas e improdutivas pela ação humana e queimadas é a:", o: [{t:"Arenização de dunas",c:false}, {t:"Desertificação",c:true}, {t:"Eutrofização dos açudes",c:false}, {t:"Inversion térmica",c:false}], pts: 4, exp: "Desertificação é o esgotamento grave do solo em regiões aridas e semiáridas causado por queimadas e desmatamento." },
              { id: "7ANO-CIEN-D12", p: "A Teoria da Deriva Continental, proposta por Alfred Wegener no início do século XX, afirmava que no passado todos os continentes estavam unidos em um supercontinente chamado:", o: [{t:"Gondwana central",c:false}, {t:"Pangrestart",c:false}, {t:"Pangeia",c:true}, {t:"Laurásia do Sul",c:false}], pts: 4, exp: "Wegener propôs que há 200 milhões de anos havia um único supercontinente (Pangeia) que se fragmentou." },
              { id: "7ANO-CIEN-D13", p: "As rochas formadas pelo resfriamento e solidificação do magma vulcânico são chamadas de:", o: [{t:"Rochas sedimentares",c:false}, {t:"Rochas magmáticas (ou ígneas)",c:true}, {t:"Rochas metamórficas",c:false}, {t:"Fósseis calcários",c:false}], pts: 4, exp: "Rochas magmáticas (como basalto e granito) originam-se do resfriamento e cristalização do magma." },
              { id: "7ANO-CIEN-D14", p: "O Efeito Estufa é um fenômeno natural essencial para a vida na Terra. Contudo, seu agravamento e o aquecimento global são causados pelo aumento de:", o: [{t:"Gases estufa (como CO2 e CH4) decorrentes da queima de combustíveis fósseis e desmatamento",c:true}, {t:"Oxigênio puro na atmosfera",c:false}, {t:"Camadas de gelo nos polos",c:false}, {t:"Poeira das estradas terrestres",c:false}], pts: 4, exp: "O acúmulo excessivo de CO2 e metano retém mais radiação infravermelha, elevando a temperatura do planeta." },
              { id: "7ANO-CIEN-D15", p: "Nos peixes ósseos, o órgão sensorial lateral responsável por captar vibrações e variações de pressão na água é a:", o: [{t:"Bexiga natatória",c:false}, {t:"Linha lateral",c:true}, {t:"Brânquia opérculo",c:false}, {t:"Nadadeira anal",c:false}], pts: 4, exp: "A linha lateral capta movimentações da água auxiliando na orientação, caça e fuga de predadores." },
              { id: "7ANO-CIEN-D16", p: "O fóssil famoso de Archaeopteryx é um marco para a biologia evolutiva pois apresenta características intermediárias entre:", o: [{t:"Peixes e anfíbios",c:false}, {t:"Répteis dinossauros e aves",c:true}, {t:"Mamíferos e anfíbios",c:false}, {t:"Insetos e crustáceos",c:false}], pts: 4, exp: "Archaeopteryx possui dentes e cauda óssea (répteis) aliados a penas e asas (aves)." },
              { id: "7ANO-CIEN-D17", p: "A extinção em massa de abelhas causaria um grave colapso nos ecossistemas e agricultura pois elas atuam como essenciais:", o: [{t:"Decompositores de folhas secas",c:false}, {t:"Agentes polinizadores na reprodução das angiospermas (plantas com flores)",c:true}, {t:"Predadores de grande porte",c:false}, {t:"Dispersores de sementes subterrâneas",c:false}], pts: 4, exp: "A polinização promovida por abelhas garante a fertilização e produção de frutos de grande parte das plantas." },
              { id: "7ANO-CIEN-D18", p: "Infecções transmitidas naturalmente entre animais vertebrados e seres humanos (como a Raiva e a Febre Amarela) são cientificamente chamadas de:", o: [{t:"Zoonoses",c:true}, {t:"Micoses cutâneas",c:false}, {t:"Virose sintomática",c:false}, {t:"Parasitoses clonais",c:false}], pts: 4, exp: "Zoonoses são doenças infecciosas transmissíveis entre animais e humanos." },
              { id: "7ANO-CIEN-D19", p: "A garrafa térmica consegue manter líquidos quentes ou frios por longos períodos pois sua estrutura com ampola de vidro espelhado e vácuo evita:", o: [{t:"As três formas de transmissão de calor (condução, convecção e radiação)",c:true}, {t:"Apenas o processo de condução metálica",c:false}, {t:"A ocorrência do equilíbrio térmico externo",c:false}, {t:"A alteração da densidade da água",c:false}], pts: 4, exp: "O vácuo impede condução e convecção; a parede espelhada reflete as ondas de calor evitando a radiação." },
              { id: "7ANO-CIEN-D20", p: "O relevo brasileiro é caracterizado por formações antigas sem dobramentos modernos ativos recentes pois o Brasil situa-se:", o: [{t:"Exatamente sobre a borda divergente de duas placas tectônicas",c:false}, {t:"No centro estável da Placa Sul-Americana, longe das bordas tectônicas ativas",c:true}, {t:"Na junção de três placas vulcânicas",c:false}, {t:"Em uma fenda tectônica profunda",c:false}], pts: 4, exp: "Por estar localizado no centro da placa tectônica, o Brasil possui estabilidade geológica sem vulcões ativos ou dobramentos recentes." }


        ]
    },




    // ------------------------------------------
    // 8º ANO
    // ------------------------------------------
    "8": {
        "Matemática": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-MAT-F01", p: "Qual o resultado de 10^3?", o: [{t:"100",c:false}, {t:"1000",c:true}, {t:"30",c:false}, {t:"10000",c:false}], pts: 2, exp: "10 elevado à terceira potência é igual a 10 x 10 x 10 = 1000." },
                { id: "8ANO-MAT-F02", p: "Como se escreve o número 5000 em notação científica?", o: [{t:"5 x 10^2",c:false}, {t:"5 x 10^3",c:true}, {t:"50 x 10^2",c:false}, {t:"0,5 x 10^4",c:false}], pts: 2, exp: "5000 equivale a 5 multiplicado por 10^3." },
                { id: "8ANO-MAT-F03", p: "Qual o valor numérico da expressão 2x + 3 para x = 4?", o: [{t:"11",c:true}, {t:"9",c:false}, {t:"14",c:false}, {t:"24",c:false}], pts: 2, exp: "Substituindo x por 4: 2(4) + 3 = 8 + 3 = 11." },
                { id: "8ANO-MAT-F04", p: "Qual a raiz quadrada exata de 81?", o: [{t:"7",c:false}, {t:"8",c:false}, {t:"9",c:true}, {t:"81",c:false}], pts: 2, exp: "Pois 9 x 9 = 81." },
                { id: "8ANO-MAT-F05", p: "Quanto é 20% de 150?", o: [{t:"15",c:false}, {t:"20",c:false}, {t:"30",c:true}, {t:"45",c:false}], pts: 2, exp: "20% de 150 = (20/100) x 150 = 30." },
                { id: "8ANO-MAT-F06", p: "Qual dos números abaixo é uma dízima periódica simples?", o: [{t:"0,5",c:false}, {t:"0,333...",c:true}, {t:"3,14159...",c:false}, {t:"1,25",c:false}], pts: 2, exp: "0,333... possui período 3 logo após a vírgula, sendo dízima periódica simples." },
                { id: "8ANO-MAT-F07", p: "Qual fração é equivalente a 1/2 com denominador 10?", o: [{t:"2/10",c:false}, {t:"5/10",c:true}, {t:"1/10",c:false}, {t:"10/2",c:false}], pts: 2, exp: "Multiplicando numerador e denominador por 5, temos 5/10." },
                { id: "8ANO-MAT-F08", p: "Qual a área de um quadrado cujo lado mede 6 cm?", o: [{t:"12 cm²",c:false}, {t:"24 cm²",c:false}, {t:"36 cm²",c:true}, {t:"18 cm²",c:false}], pts: 2, exp: "A área do quadrado é lado x lado = 6 x 6 = 36 cm²." },
                { id: "8ANO-MAT-F09", p: "Qual o perímetro de um retângulo de lados 5 cm e 8 cm?", o: [{t:"13 cm",c:false}, {t:"26 cm",c:true}, {t:"40 cm",c:false}, {t:"20 cm",c:false}], pts: 2, exp: "Perímetro = 2 x (5 + 8) = 2 x 13 = 26 cm." },
                { id: "8ANO-MAT-F10", p: "Um ângulo reto mede exatamente:", o: [{t:"45°",c:false}, {t:"90°",c:true}, {t:"180°",c:false}, {t:"360°",c:false}], pts: 2, exp: "O ângulo reto possui medida igual a 90 graus." },
                { id: "8ANO-MAT-F11", p: "A soma dos ângulos internos de qualquer triângulo é igual a:", o: [{t:"90°",c:false}, {t:"180°",c:true}, {t:"360°",c:false}, {t:"270°",c:false}], pts: 2, exp: "A soma das medidas dos ângulos internos de um triângulo é sempre 180°." },
                { id: "8ANO-MAT-F12", p: "Qual o valor de x na equação x + 7 = 15?", o: [{t:"7",c:false}, {t:"8",c:true}, {t:"22",c:false}, {t:"105",c:false}], pts: 2, exp: "Subtraindo 7 de ambos os lados: x = 15 - 7 = 8." },
                { id: "8ANO-MAT-F13", p: "Qual o volume de um bloco retangular com dimensões 2 cm, 3 cm e 4 cm?", o: [{t:"9 cm³",c:false}, {t:"24 cm³",c:true}, {t:"14 cm³",c:false}, {t:"20 cm³",c:false}], pts: 2, exp: "Volume = comprimento x largura x altura = 2 x 3 x 4 = 24 cm³." },
                { id: "8ANO-MAT-F14", p: "Em uma sequência numérica 2, 4, 6, 8, ..., qual é o próximo termo?", o: [{t:"9",c:false}, {t:"10",c:true}, {t:"12",c:false}, {t:"14",c:false}], pts: 2, exp: "A sequência aumenta de 2 em 2, portanto o próximo termo é 8 + 2 = 10." },
                { id: "8ANO-MAT-F15", p: "Qual expressão algébrica representa 'o dobro de um número x somado a 5'?", o: [{t:"x + 10",c:false}, {t:"2x + 5",c:true}, {t:"2(x + 5)",c:false}, {t:"x² + 5",c:false}], pts: 2, exp: "Dobro de x é 2x, somado a 5 resulta em 2x + 5." },
                { id: "8ANO-MAT-F16", p: "Qual a raiz quadrada exata de 144?", o: [{t:"10",c:false}, {t:"11",c:false}, {t:"12",c:true}, {t:"14",c:false}], pts: 2, exp: "Pois 12 x 12 = 144." },
                { id: "8ANO-MAT-F17", p: "Quanto é 2 elevado à quarta potência (2^4)?", o: [{t:"8",c:false}, {t:"16",c:true}, {t:"12",c:false}, {t:"64",c:false}], pts: 2, exp: "2^4 = 2 x 2 x 2 x 2 = 16." },
                { id: "8ANO-MAT-F18", p: "O gráfico mais indicado para representar partes de um todo em porcentagem é o gráfico de:", o: [{t:"Linhas",c:false}, {t:"Setores",c:true}, {t:"Dispersão",c:false}, {t:"Área",c:false}], pts: 2, exp: "Gráficos de setores (ou pizza) são ideais para comparar partes proporcionalmente ao todo." },
                { id: "8ANO-MAT-F19", p: "O número decimal 0,25 em forma de fração simplificada é:", o: [{t:"1/2",c:false}, {t:"1/4",c:true}, {t:"2/5",c:false}, {t:"1/5",c:false}], pts: 2, exp: "0,25 = 25/100, dividindo numerador e denominador por 25 obtemos 1/4." },
                { id: "8ANO-MAT-F20", p: "Se x / 2 = 6, qual o valor de x?", o: [{t:"3",c:false}, {t:"8",c:false}, {t:"12",c:true}, {t:"4",c:false}], pts: 2, exp: "Multiplicando ambos os lados por 2: x = 6 x 2 = 12." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "8ANO-MAT-M01", p: "Como se escreve o número 0,00045 em notação científica?", o: [{t:"4,5 x 10^-4",c:true}, {t:"4,5 x 10^-3",c:false}, {t:"45 x 10^-5",c:false}, {t:"0,45 x 10^-3",c:false}], pts: 3, exp: "A vírgula anda 4 casas para a direita, resultando em 4,5 x 10^-4." },
                { id: "8ANO-MAT-M02", p: "Qual a simplificação de a^5 * a^3?", o: [{t:"a^15",c:false}, {t:"a^8",c:true}, {t:"a^2",c:false}, {t:"2a^8",c:false}], pts: 3, exp: "Na multiplicação de potências de mesma base, mantém-se a base e somam-se os expoentes: 5 + 3 = 8." },
                { id: "8ANO-MAT-M03", p: "Qual a fração geratriz da dízima periódica 0,444...?", o: [{t:"4/10",c:false}, {t:"4/9",c:true}, {t:"4/5",c:false}, {t:"2/5",c:false}], pts: 3, exp: "O período é 4 (um dígito), logo a fração geratriz é 4/9." },
                { id: "8ANO-MAT-M04", p: "Qual o valor numérico de x^2 - 3x + 2 para x = 3?", o: [{t:"0",c:false}, {t:"2",c:true}, {t:"5",c:false}, {t:"11",c:false}], pts: 3, exp: "3^2 - 3(3) + 2 = 9 - 9 + 2 = 2." },
                { id: "8ANO-MAT-M05", p: "Quais são as soluções da equação x^2 = 49?", o: [{t:"Apenas 7",c:false}, {t:"7 e -7",c:true}, {t:"Apenas -7",c:false}, {t:"14 e -14",c:false}], pts: 3, exp: "x = ±√49 = ±7." },
                { id: "8ANO-MAT-M06", p: "No sistema { x + y = 10, x - y = 4 }, quais são os valores de x e y?", o: [{t:"x = 6, y = 4",c:false}, {t:"x = 7, y = 3",c:true}, {t:"x = 8, y = 2",c:false}, {t:"x = 5, y = 5",c:false}], pts: 3, exp: "Somando as duas equações: 2x = 14 => x = 7. Substituindo: 7 + y = 10 => y = 3." },
                { id: "8ANO-MAT-M07", p: "Uma pessoa possui 3 camisetas e 4 calças. De quantas maneiras diferentes ela pode se vestir?", o: [{t:"7",c:false}, {t:"12",c:true}, {t:"10",c:false}, {t:"14",c:false}], pts: 3, exp: "Pelo princípio multiplicativo: 3 x 4 = 12 combinações." },
                { id: "8ANO-MAT-M08", p: "Aumentando um produto de R$ 80,00 em 15%, qual será o novo preço?", o: [{t:"R$ 92,00",c:true}, {t:"R$ 95,00",c:false}, {t:"R$ 88,00",c:false}, {t:"R$ 90,00",c:false}], pts: 3, exp: "15% de 80 = 12. Novo preço: 80 + 12 = R$ 92,00." },
                { id: "8ANO-MAT-M09", p: "Qual a área de um círculo com raio de 3 cm? (Use π = 3,14)", o: [{t:"18,84 cm²",c:false}, {t:"28,26 cm²",c:true}, {t:"9,42 cm²",c:false}, {t:"37,68 cm²",c:false}], pts: 3, exp: "Área = π x r² = 3,14 x 3² = 3,14 x 9 = 28,26 cm²." },
                { id: "8ANO-MAT-M10", p: "Dois ângulos são suplementares. Se um deles mede 70°, quanto mede o outro?", o: [{t:"20°",c:false}, {t:"110°",c:true}, {t:"90°",c:false}, {t:"180°",c:false}], pts: 3, exp: "Ângulos suplementares somam 180°. Logo: 180° - 70° = 110°." },
                { id: "8ANO-MAT-M11", p: "Qual a média aritmética simples dos números 12, 16, 20 e 24?", o: [{t:"18",c:true}, {t:"16",c:false}, {t:"20",c:false}, {t:"72",c:false}], pts: 3, exp: "Média = (12 + 16 + 20 + 24) / 4 = 72 / 4 = 18." },
                { id: "8ANO-MAT-M12", p: "O valor numérico da potência com expoente negativo 2^-3 é igual a:", o: [{t:"-8",c:false}, {t:"1/8",c:true}, {t:"-6",c:false}, {t:"1/6",c:false}], pts: 3, exp: "2^-3 = (1/2)^3 = 1/8." },
                { id: "8ANO-MAT-M13", p: "Qual o valor de x na sequência aritmética 3, 7, 11, x, 19?", o: [{t:"13",c:false}, {t:"15",c:true}, {t:"14",c:false}, {t:"16",c:false}], pts: 3, exp: "A razão da sequência é 4. Portanto x = 11 + 4 = 15." },
                { id: "8ANO-MAT-M14", p: "Dois triângulos são congruentes pelo caso LAL se possuem:", o: [{t:"Três lados iguais",c:false}, {t:"Dois lados e o ângulo compreendido entre eles respectivamente iguais",c:true}, {t:"Dois ângulos e um lado qualquer iguais",c:false}, {t:"Três ângulos iguais",c:false}], pts: 3, exp: "LAL significa Lado - Ângulo compreendido - Lado correspondente." },
                { id: "8ANO-MAT-M15", p: "A capacidade de um reservatório em formato cúbico com 1 metro de aresta é de:", o: [{t:"100 L",c:false}, {t:"1000 L",c:true}, {t:"10000 L",c:false}, {t:"10 L",c:false}], pts: 3, exp: "Volume = 1 m³ = 1000 dm³ = 1000 Litros." },
                { id: "8ANO-MAT-M16", p: "Qual a dízima periódica resultante da fração 7/9?", o: [{t:"0,7",c:false}, {t:"0,777...",c:true}, {t:"0,79",c:false}, {t:"0,977...",c:false}], pts: 3, exp: "7 dividido por 9 dá 0,777..." },
                { id: "8ANO-MAT-M17", p: "Se x e y são inversamente proporcionais e x = 4 quando y = 6, qual o valor de y quando x = 8?", o: [{t:"12",c:false}, {t:"3",c:true}, {t:"4",c:false}, {t:"2",c:false}], pts: 3, exp: "Produto constante: 4 x 6 = 24. Assim, 8 x y = 24 => y = 3." },
                { id: "8ANO-MAT-M18", p: "A soma das medidas dos ângulos internos de um quadrilátero qualquer é:", o: [{t:"180°",c:false}, {t:"360°",c:true}, {t:"540°",c:false}, {t:"720°",c:false}], pts: 3, exp: "Qualquer quadrilátero pode ser dividido em dois triângulos: 2 x 180° = 360°." },
                { id: "8ANO-MAT-M19", p: "Qual a solução da equação 3(x - 2) = 12?", o: [{t:"x = 4",c:false}, {t:"x = 6",c:true}, {t:"x = 8",c:false}, {t:"x = 2",c:false}], pts: 3, exp: "3x - 6 = 12 => 3x = 18 => x = 6." },
                { id: "8ANO-MAT-M20", p: "Qual a mediana do conjunto de dados {3, 5, 7, 9, 12}?", o: [{t:"5",c:false}, {t:"7",c:true}, {t:"7,2",c:false}, {t:"9",c:false}], pts: 3, exp: "A mediana é o valor central em um conjunto ordenado com número ímpar de elementos (7)." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-MAT-D01", p: "Qual o resultado de (2,5 x 10^4) x (3 x 10^-2) expresso em notação científica?", o: [{t:"7,5 x 10^2",c:true}, {t:"7,5 x 10^6",c:false}, {t:"75 x 10^1",c:false}, {t:"0,75 x 10^3",c:false}], pts: 4, exp: "(2,5 x 3) x (10^4 x 10^-2) = 7,5 x 10^(4-2) = 7,5 x 10^2." },
                { id: "8ANO-MAT-D02", p: "Como fica a expressão √[3]{x^2} escrita na forma de potência com expoente fracionário?", o: [{t:"x^(3/2)",c:false}, {t:"x^(2/3)",c:true}, {t:"x^6",c:false}, {t:"x^-1",c:false}], pts: 4, exp: "O expoente do radicando (2) vira numerador e o índice do radical (3) vira denominador: x^(2/3)." },
                { id: "8ANO-MAT-D03", p: "Qual a fração geratriz simplificada da dízima periódica composta 0,1666...?", o: [{t:"1/6",c:true}, {t:"16/99",c:false}, {t:"15/90",c:false}, {t:"1/5",c:false}], pts: 4, exp: "x = 0,166... => 10x = 1,66... => 100x = 16,66... => 90x = 15 => x = 15/90 = 1/6." },
                { id: "8ANO-MAT-D04", p: "No sistema { 2x + 3y = 18, x - y = 4 }, qual o produto x * y?", o: [{t:"12",c:true}, {t:"24",c:false}, {t:"8",c:false}, {t:"10",c:false}], pts: 4, exp: "De x - y = 4 => x = y + 4. Na 1ª eq: 2(y + 4) + 3y = 18 => 5y + 8 = 18 => y = 2 e x = 6. Logo x*y = 12." },
                { id: "8ANO-MAT-D05", p: "Quais as raízes da equação do 2º grau incompleta 2x^2 - 50 = 0?", o: [{t:"5 e -5",c:true}, {t:"25 e -25",c:false}, {t:"Apenas 5",c:false}, {t:"10 e -10",c:false}], pts: 4, exp: "2x^2 = 50 => x^2 = 25 => x = ±5." },
                { id: "8ANO-MAT-D06", p: "Uma piscina de 8 m de comprimento, 4 m de largura e 1,5 m de profundidade tem qual capacidade em litros?", o: [{t:"48000 L",c:true}, {t:"4800 L",c:false}, {t:"24000 L",c:false}, {t:"480 L",c:false}], pts: 4, exp: "Volume = 8 x 4 x 1,5 = 48 m³ = 48000 dm³ = 48000 Litros." },
                { id: "8ANO-MAT-D07", p: "Um produto de R$ 100,00 sofreu um desconto de 10% e, em seguida, um novo desconto de 20%. Qual o preço final?", o: [{t:"R$ 70,00",c:false}, {t:"R$ 72,00",c:true}, {t:"R$ 68,00",c:false}, {t:"R$ 75,00",c:false}], pts: 4, exp: "Após 10%: R$ 90,00. Novo desconto de 20% sobre 90 (R$ 18,00): 90 - 18 = R$ 72,00." },
                { id: "8ANO-MAT-D08", p: "Qual a área de um trapézio que possui bases medindo 8 cm e 12 cm e altura de 5 cm?", o: [{t:"50 cm²",c:true}, {t:"100 cm²",c:false}, {t:"40 cm²",c:false}, {t:"60 cm²",c:false}], pts: 4, exp: "Área = [(B + b) * h] / 2 = [(12 + 8) * 5] / 2 = (20 * 5) / 2 = 50 cm²." },
                { id: "8ANO-MAT-D09", p: "Se dobrarmos a medida do raio de um círculo, a sua área será multiplicada por:", o: [{t:"2",c:false}, {t:"4",c:true}, {t:"8",c:false}, {t:"6",c:false}], pts: 4, exp: "Área original = π r^2. Nova área = π (2r)^2 = 4 π r^2 (quadruplica)." },
                { id: "8ANO-MAT-D10", p: "Quantos números pares de 3 algarismos distintos podemos formar usando os algarismos 1, 2, 3, 4 e 5?", o: [{t:"24",c:true}, {t:"60",c:false}, {t:"12",c:false}, {t:"30",c:false}], pts: 4, exp: "Para ser par, a unidade deve ser 2 ou 4 (2 opções). Para as outras duas posições restam 4 e 3 opções: 4 x 3 x 2 = 24." },
                { id: "8ANO-MAT-D11", p: "Em um triângulo retângulo, as projeções dos catetos sobre a hipotenusa medem 4 cm e 9 cm. A altura relativa à hipotenusa mede:", o: [{t:"6 cm",c:true}, {t:"13 cm",c:false}, {t:"36 cm",c:false}, {t:"5 cm",c:false}], pts: 4, exp: "Pela relação métrica h^2 = m * n => h^2 = 4 x 9 = 36 => h = 6 cm." },
                { id: "8ANO-MAT-D12", p: "Sabendo que x + y = 12 e x * y = 35, qual o valor de x^2 + y^2?", o: [{t:"74",c:true}, {t:"144",c:false}, {t:"109",c:false}, {t:"70",c:false}], pts: 4, exp: "(x + y)^2 = x^2 + 2xy + y^2 => 12^2 = x^2 + y^2 + 2(35) => 144 = x^2 + y^2 + 70 => x^2 + y^2 = 74." },
                { id: "8ANO-MAT-D13", p: "Em um conjunto de dados ordenados {2, 4, 4, 6, 9}, qual a diferença entre a média e a moda?", o: [{t:"1",c:true}, {t:"2",c:false}, {t:"0",c:false}, {t:"3",c:false}], pts: 4, exp: "Média = (2+4+4+6+9)/5 = 25/5 = 5. Moda = 4 (mais frequente). Diferença: 5 - 4 = 1." },
                { id: "8ANO-MAT-D14", p: "A bissetriz de um ângulo de 120° divide esse ângulo em dois ângulos adjacentes de:", o: [{t:"60° cada",c:true}, {t:"90° e 30°",c:false}, {t:"45° cada",c:false}, {t:"120° cada",c:false}], pts: 4, exp: "A bissetriz divide o ângulo ao meio: 120° / 2 = 60°." },
                { id: "8ANO-MAT-D15", p: "A expressão x^2 - 16 pode ser fatorada pela diferença de dois quadrados como:", o: [{t:"(x - 4)(x + 4)",c:true}, {t:"(x - 4)^2",c:false}, {t:"(x - 8)(x + 2)",c:false}, {t:"x(x - 16)",c:false}], pts: 4, exp: "Diferença de quadrados: a^2 - b^2 = (a - b)(a + b). Logo, x^2 - 4^2 = (x - 4)(x + 4)." },
                { id: "8ANO-MAT-D16", p: "Um capital aplicado a juros simples de 2% ao mês durante 5 meses rendeu R$ 100,00 de juros. Qual foi o capital investido?", o: [{t:"R$ 1.000,00",c:true}, {t:"R$ 500,00",c:false}, {t:"R$ 2.000,00",c:false}, {t:"R$ 10.000,00",c:false}], pts: 4, exp: "J = C * i * t => 100 = C * 0,02 * 5 => 100 = C * 0,1 => C = 100 / 0,1 = R$ 1.000,00." },
                { id: "8ANO-MAT-D17", p: "O número 0,000000038 escrito em notação científica é:", o: [{t:"3,8 x 10^-8",c:true}, {t:"3,8 x 10^-7",c:false}, {t:"38 x 10^-9",c:false}, {t:"0,38 x 10^-7",c:false}], pts: 4, exp: "A vírgula se desloca 8 casas para a direita: 3,8 x 10^-8." },
                { id: "8ANO-MAT-D18", p: "O comprimento de uma circunferência de raio igual a 5 cm é aproximadamente: (Use π = 3,14)", o: [{t:"31,4 cm",c:true}, {t:"15,7 cm",c:false}, {t:"78,5 cm",c:false}, {t:"62,8 cm",c:false}], pts: 4, exp: "C = 2 * π * r = 2 * 3,14 * 5 = 31,4 cm." },
                { id: "8ANO-MAT-D19", p: "Em um gráfico de setores, uma categoria que representa 25% do total corresponde a um ângulo central de:", o: [{t:"90°",c:true}, {t:"45°",c:false}, {t:"180°",c:false}, {t:"120°",c:false}], pts: 4, exp: "25% de 360° = 0,25 * 360° = 90°." },
                { id: "8ANO-MAT-D20", p: "A soma dos ângulos internos de um hexágono convexo (6 lados) é:", o: [{t:"720°",c:true}, {t:"540°",c:false}, {t:"360°",c:false}, {t:"1080°",c:false}], pts: 4, exp: "S = (n - 2) * 180° = (6 - 2) * 180° = 4 * 180° = 720°." }

        ],
        "Português": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-POR-F01", p: "Qual das opções apresenta uma oração coordenada assindética?", o: [{t:"Vim, vi, venci.",c:true}, {t:"Estudei, mas não passei.",c:false}, {t:"Ela canta e dança.",c:false}, {t:"Quer venha, quer fique.",c:false}], pts: 2, exp: "Orações assindéticas são ligadas sem o uso de conjunção." },
                { id: "8ANO-POR-F02", p: "Identifique o sujeito na frase: 'Chegaram os novos livros da biblioteca.'", o: [{t:"Os novos livros da biblioteca",c:true}, {t:"Chegaram",c:false}, {t:"Biblioteca",c:false}, {t:"Indeterminado",c:false}], pts: 2, exp: "O termo que realiza a ação e concorda com o verbo é 'Os novos livros da biblioteca'." },
                { id: "8ANO-POR-F03", p: "Em 'O aluno que estudou tirou nota dez', a oração sublinhada é uma subordinada adjetiva:", o: [{t:"Restritiva",c:true}, {t:"Explicativa",c:false}, {t:"Substantiva",c:false}, {t:"Adverbial",c:false}], pts: 2, exp: "Não está separada por vírgulas e restringe o sentido de 'aluno'." },
                { id: "8ANO-POR-F04", p: "Qual figura de linguagem está presente em 'Seu olhar é um farol na escuridão'?", o: [{t:"Metáfora",c:true}, {t:"Metonímia",c:false}, {t:"Antítese",c:false}, {t:"Hipérbole",c:false}], pts: 2, exp: "Metáfora é uma comparação implícita, sem conectivo comparativo." },
                { id: "8ANO-POR-F05", p: "A frase que necessita de vírgula para separar o vocativo é:", o: [{t:"Maria, venha almoçar agora.",c:true}, {t:"Maria foi ao mercado de manhã.",c:false}, {t:"O garoto comprou Maria mole.",c:false}, {t:"Eles conhecem a Maria.",c:false}], pts: 2, exp: "O vocativo 'Maria' deve ser isolado por vírgula por ser um chamamento." },
                { id: "8ANO-POR-F06", p: "O predicado da oração 'Os alunos continuam ansiosos' é:", o: [{t:"Nominal",c:true}, {t:"Verbal",c:false}, {t:"Verbo-nominal",c:false}, {t:"Direto",c:false}], pts: 2, exp: "Apresenta verbo de ligação ('continuam') e predicativo do sujeito ('ansiosos')." },
                { id: "8ANO-POR-F07", p: "Qual das conjunções abaixo é adversativa?", o: [{t:"Mas",c:true}, {t:"E",c:false}, {t:"Porque",c:false}, {t:"Portanto",c:false}], pts: 2, exp: "'Mas' expressa ideia de oposição ou contraste." },
                { id: "8ANO-POR-F08", p: "A frase na voz passiva é:", o: [{t:"O bolo foi feito pela avó.",c:true}, {t:"A avó fez o bolo.",c:false}, {t:"A avó sorriu feliz.",c:false}, {t:"Fizemos um bolo delicioso.",c:false}], pts: 2, exp: "O sujeito 'O bolo' recebe a ação praticada pelo agente da passiva 'pela avó'." },
                { id: "8ANO-POR-F09", p: "Assinale a alternativa em que o uso do 'porquê' está correto:", o: [{t:"Não fui à aula porque estava doente.",c:true}, {t:"Por que você não comeu nada por que?",c:false}, {t:"Gostaria de saber o por que de tudo.",c:false}, {t:"Você não veio por que estava chovendo.",c:false}], pts: 2, exp: "'Porque' junto e sem acento é usado em respostas e explicações." },
                { id: "8ANO-POR-F10", p: "Qual frase apresenta concordância verbal CORRETA?", o: [{t:"Faz três anos que não o vejo.",c:true}, {t:"Fazem três anos que não o vejo.",c:false}, {t:"Houveram muitos problemas no evento.",c:false}, {t:"Sobrou muitas vagas no curso.",c:false}], pts: 2, exp: "O verbo 'fazer' indicando tempo decorrido é impessoal (fica no singular)." },
                { id: "8ANO-POR-F11", p: "Qual das palavras abaixo é um substantivo abstrato?", o: [{t:"Saudade",c:true}, {t:"Cadeira",c:false}, {t:"Livro",c:false}, {t:"Caneta",c:false}], pts: 2, exp: "'Saudade' nomeia um sentimento, necessitando de um ser para existir." },
                { id: "8ANO-POR-F12", p: "A função sintática de um termo que caracteriza diretamente um substantivo é:", o: [{t:"Adjunto adnominal",c:true}, {t:"Complemento nominal",c:false}, {t:"Objeto direto",c:false}, {t:"Agente da passiva",c:false}], pts: 2, exp: "O adjunto adnominal acompanha e caracteriza o substantivo." },
                { id: "8ANO-POR-F13", p: "Em 'A cidade foi destruída pelo fogo', o termo 'pelo fogo' é:", o: [{t:"Agente da passiva",c:true}, {t:"Objeto indireto",c:false}, {t:"Adjunto adverbial",c:false}, {t:"Sujeito",c:false}], pts: 2, exp: "'Pelo fogo' pratica a ação na voz passiva." },
                { id: "8ANO-POR-F14", p: "Qual oração possui sujeito indeterminado?", o: [{t:"Procuraram você por toda parte.",c:true}, {t:"Choveu muito ontem à noite.",c:false}, {t:"Os meninos jogaram futebol.",c:false}, {t:"Eu vi o acidente.",c:false}], pts: 2, exp: "Verbo na 3ª pessoa do plural sem sujeito explícito ou contexto indetermina o sujeito." },
                { id: "8ANO-POR-F15", p: "O gênero textual que tem como principal objetivo defender uma tese/opinião é o:", o: [{t:"Artigo de opinião",c:true}, {t:"Conto de fadas",c:false}, {t:"Poema lírico",c:false}, {t:"Manual de instrução",c:false}], pts: 2, exp: "O artigo de opinião é um texto dissertativo-argumentativo." },
                { id: "8ANO-POR-F16", p: "A crônica é um gênero textual caracterizado por:", o: [{t:"Tratar de fatos do cotidiano com linguagem leve e reflexiva",c:true}, {t:"Apresentar notícias científicas complexas",c:false}, {t:"Descrever experimentos de laboratório",c:false}, {t:"Contar a história de heróis mitológicos",c:false}], pts: 2, exp: "A crônica inspira-se no dia a dia cotidiano." },
                { id: "8ANO-POR-F17", p: "Qual o antônimo da palavra 'efêmero'?", o: [{t:"Duradouro",c:true}, {t:"Passageiro",c:false}, {t:"Fugaz",c:false}, {t:"Curto",c:false}], pts: 2, exp: "Efêmero significa passageiro; seu oposto é duradouro ou permanente." },
                { id: "8ANO-POR-F18", p: "A linguagem denotativa é aquela empregada com sentido:", o: [{t:"Literal e dicionarizado",c:true}, {t:"Figurado e poético",c:false}, {t:"Ambíguo e subjetivo",c:false}, {t:"Metafórico",c:false}], pts: 2, exp: "Denotação refere-se ao sentido real, objetivo e dicionarizado." },
                { id: "8ANO-POR-F19", p: "Qual pontuação é utilizada para introduzir uma citação ou fala de personagem?", o: [{t:"Dois-pontos",c:true}, {t:"Ponto e vírgula",c:false}, {t:"Reticências",c:false}, {t:"Ponto final",c:false}], pts: 2, exp: "Os dois-pontos anunciam uma enumeração, citação ou fala." },
                { id: "8ANO-POR-F20", p: "Na frase 'Comprei maçãs, bananas e laranjas', a vírgula foi usada para:", o: [{t:"Separar elementos de uma enumeração",c:true}, {t:"Isolar o vocativo",c:false}, {t:"Separar o aposto",c:false}, {t:"Indicar omissão do verbo",c:false}], pts: 2, exp: "Elementos de mesma função sintática em enumeração são separados por vírgula." },

                // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "8ANO-POR-M01", p: "Em 'Desejo que todos passem no exame', a oração sublinhada é subordinada substantiva:", o: [{t:"Objetiva direta",c:true}, {t:"Subjetiva",c:false}, {t:"Completiva nominal",c:false}, {t:"Predicativa",c:false}], pts: 3, exp: "Funciona como objeto direto do verbo transitivo direto 'Desejo'." },
                { id: "8ANO-POR-M02", p: "Em 'É necessário que você estude', a oração subordinada funciona como:", o: [{t:"Sujeito (subjetiva)",c:true}, {t:"Objeto direto",c:false}, {t:"Predicativo do sujeito",c:false}, {t:"Aposto",c:false}], pts: 3, exp: "'É necessário' é uma oração principal sem sujeito explícito; a oração subordinada é o sujeito dela." },
                { id: "8ANO-POR-M03", p: "Na frase 'Ele tinha certeza de que venceria', a oração destacada é subordinada substantiva:", o: [{t:"Completiva nominal",c:true}, {t:"Objetiva indireta",c:false}, {t:"Subjetiva",c:false}, {t:"Apositiva",c:false}], pts: 3, exp: "Completa o sentido do nome/substantivo 'certeza', exigindo preposição." },
                { id: "8ANO-POR-M04", p: "Em 'Embora estivesse chovendo, fomos ao parque', a conjunção expressa ideia de:", o: [{t:"Concessão",c:true}, {t:"Causa",c:false}, {t:"Consequência",c:false}, {t:"Condição",c:false}], pts: 3, exp: "'Embora' introduz uma oração subordinada adverbial concessiva." },
                { id: "8ANO-POR-M05", p: "Aponte a alternativa em que o termo sublinhado é um COMPLEMENTO NOMINAL:", o: [{t:"Ele tem amor à pátria.",c:true}, {t:"A casa de madeira é antiga.",c:false}, {t:"Comprei o livro de História.",c:false}, {t:"O carro do meu pai quebrou.",c:false}], pts: 3, exp: "'À pátria' completa o sentido do substantivo abstrato 'amor' (sentido passivo)." },
                { id: "8ANO-POR-M06", p: "Diferencie: 'Os alunos, que estudaram, passaram' de 'Os alunos que estudaram passaram'. A primeira indica que:", o: [{t:"Todos os alunos estudaram e passaram",c:true}, {t:"Apenas alguns alunos estudaram",c:false}, {t:"Nenhum aluno passou",c:false}, {t:"Os alunos não estudaram",c:false}], pts: 3, exp: "Com vírgulas, a oração adjetiva é explicativa e se refere à totalidade dos alunos." },
                { id: "8ANO-POR-M07", p: "Qual das frases exige o uso do sinal indicativo de crase?", o: [{t:"Entreguei o trabalho à professora.",c:true}, {t:"Fui a uma festa ontem.",c:false}, {t:"Comecei a estudar cedo.",c:false}, {t:"Ele se referia a pessoas importantes.",c:false}], pts: 3, exp: "Preposição 'a' (exigida por 'entreguei') + artigo definido feminino 'a' (de professora) = 'à'." },
                { id: "8ANO-POR-M08", p: "Na frase 'Lemos a obra de Machado de Assis, autor do Realismo', a expressão sublinhada é:", o: [{t:"Aposto",c:true}, {t:"Vocativo",c:false}, {t:"Adjunto adverbial",c:false}, {t:"Predicativo do objeto",c:false}], pts: 3, exp: "'autor do Realismo' explica/identifica Machado de Assis, funcionando como aposto." },
                { id: "8ANO-POR-M09", p: "Em 'O fazendeiro tinha muitos bois; vendeu a cabeça por um bom preço', ocorre a figura de linguagem:", o: [{t:"Metonímia",c:true}, {t:"Metáfora",c:false}, {t:"Hipérbole",c:false}, {t:"Antítese",c:false}], pts: 3, exp: "Metonímia por substituição da parte pelo todo ('cabeça' por 'cabeça de gado')." },
                { id: "8ANO-POR-M10", p: "Qual verbo possui regência variante conforme o sentido, significando 'ver/observar' quando exige preposição 'a'?", o: [{t:"Assistir",c:true}, {t:"Aspirar",c:false}, {t:"Querer",c:false}, {t:"Chegar",c:false}], pts: 3, exp: "'Assistir' no sentido de ver/presenciar exige preposição 'a' (ex: assistir ao jogo)." },
                { id: "8ANO-POR-M11", p: "Transformando a frase 'O vento derrubou as árvores' para a voz passiva, obtém-se:", o: [{t:"As árvores foram derrubadas pelo vento.",c:true}, {t:"Derrubaram-se as árvores.",c:false}, {t:"O vento tinha derrubado as árvores.",c:false}, {t:"As árvores derrubaram o vento.",c:false}], pts: 3, exp: "O objeto direto virou sujeito paciente e o verbo foi para a forma analítica 'foram derrubadas'." },
                { id: "8ANO-POR-M12", p: "Na oração 'Ela chegou exausta', o verbo e o predicativo formam um predicado:", o: [{t:"Verbo-nominal",c:true}, {t:"Nominal",c:false}, {t:"Verbal",c:false}, {t:"Direto",c:false}], pts: 3, exp: "Combina um verbo de ação (chegou) com um predicativo do sujeito (exausta)." },
                { id: "8ANO-POR-M13", p: "Qual a colocação pronominal correta de acordo com a norma-padrão em 'Não __ diga nada'?", o: [{t:"me",c:true}, {t:"diga-me",c:false}, {t:"dir-me-á",c:false}, {t:"diga-me-á",c:false}], pts: 3, exp: "A palavra negativa 'Não' atrai obrigatoriamente o pronome (próclise)." },
                { id: "8ANO-POR-M14", p: "Em 'Fizemos o teste como o professor orientou', a oração sublinhada é adverbial:", o: [{t:"Conformativa",c:true}, {t:"Causal",c:false}, {t:"Comparativa",c:false}, {t:"Consecutiva",c:false}], pts: 3, exp: "A conjunção 'como' indica conformidade com a orientação dada." },
                { id: "8ANO-POR-M15", p: "Na frase 'Choveu tanto que as ruas alagaram', a oração sublinhada expressa:", o: [{t:"Consequência",c:true}, {t:"Causa",c:false}, {t:"Condição",c:false}, {t:"Finalidade",c:false}], pts: 3, exp: "A intensidade 'tanto' aliada a 'que' introduz uma oração subordinada consecutiva." },
                { id: "8ANO-POR-M16", p: "Qual das opções apresenta concordância nominal CORRETA?", o: [{t:"A porta e o portão estão abertos.",c:true}, {t:"A porta e o portão está aberto.",c:false}, {t:"Seguem anexo as documentações.",c:false}, {t:"É proibido a entrada de estranhos.",c:false}], pts: 3, exp: "Adjetivo referente a substantivos de gêneros diferentes vai para o masculino plural." },
                { id: "8ANO-POR-M17", p: "Qual frase apresenta pleonasmo vicioso?", o: [{t:"Ele subiu para cima bem rápido.",c:true}, {t:"Choveram pétalas de rosa.",c:false}, {t:"Ouvi com meus próprios ouvidos.",c:false}, {t:"Vi o sol nascer.",c:false}], pts: 3, exp: "'Subir para cima' é uma redundância viciosa e desnecessária." },
                { id: "8ANO-POR-M18", p: "Em 'Comprei livros, cadernos, canetas', a omissão de conjunção aditiva caracteriza a figura:", o: [{t:"Assíndeto",c:true}, {t:"Polissíndeto",c:false}, {t:"Hipérbato",c:false}, {t:"Elipse",c:false}], pts: 3, exp: "Assíndeto é a ausência de conectivos de ligação entre orações ou termos." },
                { id: "8ANO-POR-M19", p: "O conector 'portanto' estabelece uma relação semântica de:", o: [{t:"Conclusão",c:true}, {t:"Explicação",c:false}, {t:"Adição",c:false}, {t:"Oposição",c:false}], pts: 3, exp: "'Portanto' é uma conjunção coordenativa conclusiva." },
                { id: "8ANO-POR-M20", p: "Identifique a frase em que o verbo 'haver' está empregado INCORRETAMENTE segundo a norma-padrão:", o: [{t:"Houveram muitos acidentes na rodovia.",c:true}, {t:"Há muitos anos não venho aqui.",c:false}, {t:"Havia pessoas interessadas na vaga.",c:false}, {t:"Deve haver motivos para isso.",c:false}], pts: 3, exp: "O verbo 'haver' no sentido de existir/ocorrer é impessoal e não vai para o plural." },

                // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-POR-D01", p: "Assinale a opção em que o termo sublinhado funciona como COMPLEMENTO NOMINAL e não como adjunto adnominal:", o: [{t:"A destruição do meio ambiente é preocupante.",c:true}, {t:"A crítica do jornalista foi ácida.",c:false}, {t:"A leitura do aluno foi excelente.",c:false}, {t:"O conselho do pai ajudou o jovem.",c:false}], pts: 4, exp: "'Do meio ambiente' sofre a ação de ser destruído (paciente), logo é complemento nominal." },
                { id: "8ANO-POR-D02", p: "Qual a classificação correta da oração reduzida sublinhada em 'É fundamental sabermos a verdade'?", o: [{t:"Subordinada substantiva subjetiva reduzida de infinitivo",c:true}, {t:"Subordinada substantiva objetiva direta reduzida de gerúndio",c:false}, {t:"Subordinada adjetiva explicativa reduzida de particípio",c:false}, {t:"Subordinada adverbial final reduzida de infinitivo",c:false}], pts: 4, exp: "Eqüivale a 'que saibamos a verdade' (sujeito da oração principal 'É fundamental')." },
                { id: "8ANO-POR-D03", p: "Assinale a alternativa em que a regência do verbo e o uso da crase estão ambos CORRETOS:", o: [{t:"Aspirava ao cargo de diretor e obedeceu às regras da empresa.",c:true}, {t:"Aspirava o cargo de diretor e obedeceu as regras da empresa.",c:false}, {t:"Aspirava ao cargo de diretor e obedeceu as regras da empresa.",c:false}, {t:"Aspirava o cargo de diretor e obedeceu às regras da empresa.",c:false}], pts: 4, exp: "'Aspirar' (pretender) exige 'a'; 'obedecer' exige 'a'. Logo 'ao cargo' e 'às regras'." },
                { id: "8ANO-POR-D04", p: "Em relação à concordância verbal, assinale a opção inteiramente CORRETA:", o: [{t:"Mais de um estudante faltou à prova, mas ambos justificaram.",c:false}, {t:"Fomos nós quem fez a apresentação de abertura.",c:true}, {t:"Fazem dez anos que a empresa foi fundada.",c:false}, {t:"A maioria dos cidadãos votaram contra o projeto.",c:false}], pts: 4, exp: "Com o pronome 'quem', o verbo pode concordar na 3ª pessoa do singular ('fez')." },
                { id: "8ANO-POR-D05", p: "Na oração 'Alugam-se salas comerciais', a função da palavra 'se' é de:", o: [{t:"Partícula apassivadora",c:true}, {t:"Índice de indeterminação do sujeito",c:false}, {t:"Pronome reflexivo",c:false}, {t:"Conjunção subordinada condicional",c:false}], pts: 4, exp: "Com verbo transitivo direto na 3ª pessoa do plural, 'se' apassiva o sujeito paciente ('salas comerciais')." },
                { id: "8ANO-POR-D06", p: "Identifique a figura de sintaxe presente em 'No mar, tanta tempestade e tanto estrago':", o: [{t:"Zeugma / Elipse",c:true}, {t:"Anacoluto",c:false}, {t:"Hipérbato",c:false}, {t:"Pleonasmo",c:false}], pts: 4, exp: "Ocorre a omissão (elipse/zeugma) do verbo 'há' ou 'existe'." },
                { id: "8ANO-POR-D07", p: "A frase que apresenta ambiguidade estrutural é:", o: [{t:"O pai falou com o filho sentado na varanda.",c:true}, {t:"O pai falou com o filho enquanto este estava sentado.",c:false}, {t:"Sentado na varanda, o pai falou com o filho.",c:false}, {t:"O pai e o filho conversaram na varanda.",c:false}], pts: 4, exp: "Não fica claro quem estava sentado na varanda (se o pai ou o filho)." },
                { id: "8ANO-POR-D08", p: "Em 'Trabalhou tanto quanto seu irmão', a oração sublinhada é subordinada adverbial:", o: [{t:"Comparativa",c:true}, {t:"Consecutiva",c:false}, {t:"Causal",c:false}, {t:"Proporcional",c:false}], pts: 4, exp: "Estabelece uma comparação de igualdade com a oração principal." },
                { id: "8ANO-POR-D09", p: "Qual o valor semântico do elemento coesivo sublinhado em 'À medida que subíamos a montanha, o ar ficava rarefeito'?", o: [{t:"Proporcionalidade",c:true}, {t:"Conformidade",c:false}, {t:"Temporalidade",c:false}, {t:"Causalidade",c:false}], pts: 4, exp: "'À medida que' é uma locução conjuntiva proporcional." },
                { id: "8ANO-POR-D10", p: "Marque a opção que apresenta incorreção na colocação pronominal segundo a norma culta:", o: [{t:"Me me empresta o caneta, por favor?",c:true}, {t:"Nunca me disseram a verdade.",c:false}, {t:"Oferecer-lhe-iam uma nova oportunidade.",c:false}, {t:"Espero que se sintam acolhidos.",c:false}], pts: 4, exp: "Não se inicia oração com pronome oblíquo átono na norma-padrão." },
                { id: "8ANO-POR-D11", p: "Na oração 'Ela falou friamente e saiu rápida', o termo 'fria e rapidamente' contém:", o: [{t:"Advérbio de modo omitindo o sufixo na primeira palavra",c:true}, {t:"Dois adjetivos em função de adjunto adnominal",c:false}, {t:"Apenas um predicativo do sujeito",c:false}, {t:"Uso incorreto da regra de adjetivação",c:false}], pts: 4, exp: "Na coordenação de advérbios em '-mente', o sufixo pode ser mantido apenas no último." },
                { id: "8ANO-POR-D12", p: "Em 'Precisa-se de atendentes qualificados', o termo 'de atendentes qualificados' é:", o: [{t:"Objeto indireto",c:true}, {t:"Sujeito paciente",c:false}, {t:"Agente da passiva",c:false}, {t:"Complemento nominal",c:false}], pts: 4, exp: "O 'se' é índice de indeterminação do sujeito (VTI); o termo preposicionado é objeto indireto." },
                { id: "8ANO-POR-D13", p: "Aponte a oração com desvio quanto à crase:", o: [{t:"Refiro-me àquela situação constrangedora.",c:false}, {t:"Chegamos à uma hora da tarde.",c:true}, {t:"Dirigiu-se à secretaria da escola.",c:false}, {t:"Ele pintava à moda de Picasso.",c:false}], pts: 4, exp: "Não se usa crase antes do artigo indefinido 'uma'." },
                { id: "8ANO-POR-D14", p: "Em 'Cheguei, vi, venci', a omissão das conjunções gera um efeito de sentido de:", o: [{t:"Rapidez e dinamicidade nos fatos",c:true}, {t:"Hesitação e dúvida",c:false}, {t:"Lentidão e monotonia",c:false}, {t:"Causalidade e explicação",c:false}], pts: 4, exp: "O assíndeto confere agilidade e dinamicidade ao texto." },
                { id: "8ANO-POR-D15", p: "Na oração 'Ninguém sabia se ele viria', o termo 'se' classifica-se como:", o: [{t:"Conjunção subordinada integrante",c:true}, {t:"Conjunção subordinada condicional",c:false}, {t:"Pronome reflexivo",c:false}, {t:"Partícula apassivadora",c:false}], pts: 4, exp: "Introduz oração subordinada substantiva objetiva direta ('Ninguém sabia ISSO')." },
                { id: "8ANO-POR-D16", p: "Assinale a alternativa em que a concordância nominal está incorreta:", o: [{t:"A aluna estava meia confusa com a explicação.",c:true}, {t:"Seguem anexos os documentos solicitados.",c:false}, {t:"É necessária a atenção de todos.",c:false}, {t:"Elas mesmas resolveram o problema.",c:false}], pts: 4, exp: "'Meio' como advérbio é invariável: 'meio confusa'." },
                { id: "8ANO-POR-D17", p: "A frase 'O jovem parecia um leão defendendo suas ideias' contém:", o: [{t:"Comparação explícita",c:false}, {t:"Metáfora",c:true}, {t:"Metonímia",c:false}, {t:"Prosopopeia",c:false}], pts: 4, exp: "'parecia um leão' constitui uma metáfora (atribuição direta de características do leão ao jovem)." },
                { id: "8ANO-POR-D18", p: "Qual o papel sintático do pronome relativo 'que' em 'O livro que comprei é excelente'?", o: [{t:"Objeto direto",c:true}, {t:"Sujeito",c:false}, {t:"Objeto indireto",c:false}, {t:"Predicativo do sujeito",c:false}], pts: 4, exp: "Na oração adjetiva 'que comprei', 'que' equivale a 'o livro' e é objeto direto de 'comprei'." },
                { id: "8ANO-POR-D19", p: "O uso dos parênteses na frase 'O novo diretor (eleito na semana passada) assumiu o cargo' serve para:", o: [{t:"Inserir uma explicação ou informação acessória",c:true}, {t:"Isolar um vocativo",c:false}, {t:"Marcar a fala do personagem",c:false}, {t:"Indicar dúvida do autor",c:false}], pts: 4, exp: "Parênteses são usados para intercalar dados informativos ou explicativos." },
                { id: "8ANO-POR-D20", p: "Na frase 'Estudou tanto que passou em primeiro lugar', a oração sublinhada classifica-se como:", o: [{t:"Subordinada adverbial consecutiva",c:true}, {t:"Subordinada adverbial causal",c:false}, {t:"Subordinada adverbial comparativa",c:false}, {t:"Subordinada substantiva completiva",c:false}], pts: 4, exp: "Expressa o resultado/consequência da ação de estudar intensamente." }
        ],
        "História": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-HIS-F01", p: "O Iluminismo foi um movimento intelectual e filosófico que se desenvolveu no século XVIII destacando o uso da:", o: [{t:"Razão",c:true}, {t:"Fé cega",c:false}, {t:"Tradição medieval",c:false}, {t:"Alquimia",c:false}], pts: 2, exp: "O Iluminismo defendia o uso do pensamento racional contra o absolutismo e a ignorância." },
                { id: "8ANO-HIS-F02", p: "Em qual país teve início a Primeira Revolução Industrial no século XVIII?", o: [{t:"Inglaterra",c:true}, {t:"França",c:false}, {t:"Alemanha",c:false}, {t:"Brasil",c:false}], pts: 2, exp: "A Inglaterra pioneirou a Revolução Industrial devido ao acúmulo de capital e jazidas de carvão." },
                { id: "8ANO-HIS-F03", p: "O evento que marcou o início da Revolução Francesa em 1789 foi a:", o: [{t:"Queda da Bastilha",c:true}, {t:"Batalha de Waterloo",c:false}, {t:"Proclamação da República",c:false}, {t:"Independência das Colônias",c:false}], pts: 2, exp: "A tomada da Bastilha simbolizou o fim do absolutismo francês." },
                { id: "8ANO-HIS-F04", p: "Em que ano foi declarada a Independência dos Estados Unidos da América?", o: [{t:"1776",c:true}, {t:"1789",c:false}, {t:"1822",c:false}, {t:"1500",c:false}], pts: 2, exp: "A Declaração de Independência dos EUA ocorreu em 4 de julho de 1776." },
                { id: "8ANO-HIS-F05", p: "Quem proclamou a Independência do Brasil em 7 de setembro de 1822?", o: [{t:"Dom Pedro I",c:true}, {t:"Dom Pedro II",c:false}, {t:"Tiradentes",c:false}, {t:"Marechal Deodoro",c:false}], pts: 2, exp: "Dom Pedro I declarou a independência do Brasil às margens do rio Ipiranga." },
                { id: "8ANO-HIS-F06", p: "A primeira Constituição do Brasil independente foi outorgada em qual ano?", o: [{t:"1824",c:true}, {t:"1822",c:false}, {t:"1889",c:false}, {t:"1988",c:false}], pts: 2, exp: "A Constituição de 1824 foi outorgada por Dom Pedro I em março de 1824." },
                { id: "8ANO-HIS-F07", p: "O período da história do Brasil compreendido entre a abdicação de D. Pedro I (1831) e o Golpe da Maioridade (1840) é chamado de:", o: [{t:"Período Regencial",c:true}, {t:"Primeiro Reinado",c:false}, {t:"Segundo Reinado",c:false}, {t:"República Velha",c:false}], pts: 2, exp: "Foi governado por regentes enquanto D. Pedro II era menor de idade." },
                { id: "8ANO-HIS-F08", p: "Qual imperador governou o Brasil durante o Segundo Reinado (1840-1889)?", o: [{t:"Dom Pedro II",c:true}, {t:"Dom Pedro I",c:false}, {t:"Dom João VI",c:false}, {t:"Marechal Floriano",c:false}], pts: 2, exp: "Dom Pedro II assumiu após o Golpe da Maioridade em 1840." },
                { id: "8ANO-HIS-F09", p: "A Lei Áurea, que aboliu a escravidão no Brasil em 1888, foi assinada por:", o: [{t:"Princesa Isabel",c:true}, {t:"Dom Pedro II",c:false}, {t:"Marquês de Pombal",c:false}, {t:"Duque de Caxias",c:false}], pts: 2, exp: "A Princesa Isabel assinou a Lei Áurea em 13 de maio de 1888." },
                { id: "8ANO-HIS-F10", p: "Filósofo iluminista famoso pela teoria da divisão dos três poderes (Executivo, Legislativo e Judiciário):", o: [{t:"Montesquieu",c:true}, {t:"Rousseau",c:false}, {t:"Voltaire",c:false}, {t:"Descartes",c:false}], pts: 2, exp: "Montesquieu defendeu a separação dos poderes em sua obra 'O Espírito das Leis'." },
                { id: "8ANO-HIS-F11", p: "O mártir e figura símbolo da Inconfidência Mineira (1789) foi:", o: [{t:"Tiradentes",c:true}, {t:"Zumbi dos Palmares",c:false}, {t:"Frei Caneca",c:false}, {t:"Bento Gonçalves",c:false}], pts: 2, exp: "Joaquim José da Silva Xavier, o Tiradentes, foi o único executado do grupo." },
                { id: "8ANO-HIS-F12", p: "A Conjuração Baiana (1798) também ficou conhecida como:", o: [{t:"Revolta dos Alfaiates",c:true}, {t:"Guerra dos Mascates",c:false}, {t:"Revolução Praieira",c:false}, {t:"Sabinada",c:false}], pts: 2, exp: "Teve forte participação popular e de alfaiates populares de Salvador." },
                { id: "8ANO-HIS-F13", p: "A Família Real Portuguesa transferiu-se para o Brasil no ano de:", o: [{t:"1808",c:true}, {t:"1500",c:false}, {t:"1822",c:false}, {t:"1889",c:false}], pts: 2, exp: "Fugindo das tropas napoleônicas, D. João VI chegou ao Brasil em 1808." },
                { id: "8ANO-HIS-F14", p: "O maior conflito armado ocorrido na América do Sul no século XIX foi a:", o: [{t:"Guerra do Paraguai",c:true}, {t:"Guerra dos Farrapos",c:false}, {t:"Guerra da Cisplatina",c:false}, {t:"Guerra de Secessão",c:false}], pts: 2, exp: "A Guerra do Paraguai envolveu o Paraguai contra a Tríplice Aliança." },
                { id: "8ANO-HIS-F15", p: "A dominação e exploração das potências europeias sobre a África e Ásia no século XIX é chamada de:", o: [{t:"Imperialismo / Neocolonialismo",c:true}, {t:"Feudalismo",c:false}, {t:"Mercantilismo",c:false}, {t:"Globalização",c:false}], pts: 2, exp: "O Imperialismo buscou matérias-primas e novos mercados consumidores na África e Ásia." },
                { id: "8ANO-HIS-F16", p: "A lei brasileira que proibia o tráfico transatlântico de escravizados em 1850 foi a:", o: [{t:"Lei Eusébio de Queirós",c:true}, {t:"Lei do Ventre Livre",c:false}, {t:"Lei dos Sexagenários",c:false}, {t:"Lei Áurea",c:false}], pts: 2, exp: "A Lei Eusébio de Queirós encerrou o tráfico negreiro internacional para o Brasil." },
                { id: "8ANO-HIS-F17", p: "A Lei do Ventre Livre (1871) determinava que:", o: [{t:"Os filhos nascidos de mães escravizadas seriam livres",c:true}, {t:"Todos os escravizados com mais de 60 anos estavam libertos",c:false}, {t:"A escravidão terminava imediatamente",c:false}, {t:"O tráfico negreiro seria permitido",c:false}], pts: 2, exp: "Garantia liberdade às crianças nascidas de mães escravizadas a partir daquela data." },
                { id: "8ANO-HIS-F18", p: "Quais países formavam a Tríplice Aliança na Guerra do Paraguai?", o: [{t:"Brasil, Argentina e Uruguai",c:true}, {t:"Brasil, Paraguai e Bolívia",c:false}, {t:"Argentina, Chile e Peru",c:false}, {t:"Inglaterra, Brasil e Paraguai",c:false}], pts: 2, exp: "Brasil, Argentina e Uruguai uniram-se contra o Paraguai liderado por Solano López." },
                { id: "8ANO-HIS-F19", p: "O sistema político criticado pelos iluministas, caracterizado pelo poder absoluto dos reis, era o:", o: [{t:"Absolutismo",c:true}, {t:"Anarquismo",c:false}, {t:"Comunismo",c:false}, {t:"Socialismo",c:false}], pts: 2, exp: "O Absolutismo concentrava o poder total nas mãos do monarca." },
                { id: "8ANO-HIS-F20", p: "A principal atividade econômica e produto de exportação do Brasil no Segundo Reinado foi o:", o: [{t:"Café",c:true}, {t:"Açúcar",c:false}, {t:"Ouro",c:false}, {t:"Algodão",c:false}], pts: 2, exp: "O café tornou-se o grande motor econômico da elite cafeeira no século XIX." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "8ANO-HIS-M01", p: "O Iluminista Rousseau defendia em sua obra 'O Contrato Social' a ideia de que:", o: [{t:"O poder político pertence ao povo (soberania popular)",c:true}, {t:"O rei governa por direito divino",c:false}, {t:"A escravidão é natural e necessária",c:false}, {t:"A Igreja deve controlar a política",c:false}], pts: 3, exp: "Rousseau afirmava que a vontade geral do povo é a base da legitimidade do poder." },
                { id: "8ANO-HIS-M02", p: "Qual das alternativas expressa uma consequência social da Primeira Revolução Industrial?", o: [{t:"Surgimento do operariado urbano e péssimas condições de trabalho",c:true}, {t:"Fim definitivo das classes sociais",c:false}, {t:"Valorização do trabalho artesanal e familiar",c:false}, {t:"Diminuição da população nas grandes cidades",c:false}], pts: 3, exp: "A industrialização gerou o proletariado, marcado por jornadas exaustivas e insalubridade." },
                { id: "8ANO-HIS-M03", p: "A divisão da sociedade francesa no Antigo Regime antes da Revolução de 1789 compreendia:", o: [{t:"1º Estado (Clero), 2º Estado (Nobreza) e 3º Estado (Povo e Burguesia)",c:true}, {t:"1º Estado (Burguesia), 2º Estado (Povo) e 3º Estado (Nobreza)",c:false}, {t:"1º Estado (Rei), 2º Estado (Senhores) e 3º Estado (Servos)",c:false}, {t:"Não havia divisão em estados",c:false}], pts: 3, exp: "O 3º Estado arcava com os impostos que sustentavam o privilégio dos dois primeiros." },
                { id: "8ANO-HIS-M04", p: "O Bloqueio Continental decretado por Napoleão Bonaparte em 1806 visava prejudicar qual país?", o: [{t:"Inglaterra",c:true}, {t:"Rússia",c:false}, {t:"Espanha",c:false}, {t:"Portugal",c:false}], pts: 3, exp: "Proibia os países europeus de comercializarem com a Grã-Bretanha." },
                { id: "8ANO-HIS-M05", p: "A Constituição brasileira de 1824 instituiu, além dos três poderes tradicionais, o Poder:", o: [{t:"Moderador",c:true}, {t:"Executivo Extra",c:false}, {t:"Senatorial",c:false}, {t:"Imperial",c:false}], pts: 3, exp: "O Poder Moderador era exclusivo do Imperador para intervir nos demais poderes." },
                { id: "8ANO-HIS-M06", p: "A Confederação do Equador (1824), ocorrida em Pernambuco, foi uma resposta contra:", o: [{t:"O autoritarismo e o centralismo de Dom Pedro I",c:true}, {t:"A abolição imediata da escravidão",c:false}, {t:"A chegada da Família Real ao Brasil",c:false}, {t:"A invasão de tropas argentinas",c:false}], pts: 3, exp: "Insurgiu-se contra a outorga da Constituição autoritária de 1824." },
                { id: "8ANO-HIS-M07", p: "A Revolta da Cabanagem (1835-1840), marcada por intensa participação popular, ocorreu na província do:", o: [{t:"Grão-Pará",c:true}, {t:"Rio Grande do Sul",c:false}, {t:"Maranhão",c:false}, {t:"Bahia",c:false}], pts: 3, exp: "Os cabanos (população ribeirinha e indígena) tomaram o poder no Pará." },
                { id: "8ANO-HIS-M08", p: "A Tarifa Alves Branco (1844) teve como principal objetivo econômico no Brasil:", o: [{t:"Aumentar os impostos sobre produtos importados para proteger a economia interna",c:true}, {t:"Isentar de impostos os produtos trazidos da Inglaterra",c:false}, {t:"Proibir a produção de café no país",c:false}, {t:"Subsidiar a vinda de imigrantes europeus",c:false}], pts: 3, exp: "Aumentou as taxas alfandegárias sobre importados para até 60%." },
                { id: "8ANO-HIS-M09", p: "O sistema de trabalho com imigrantes europeus nas fazendas de café conhecido como 'Parceria' falhou principalmente devido:", o: [{t:"Aos endividamentos excessivos e maus tratos impostos pelos fazendeiros aos imigrantes",c:true}, {t:"À recusa dos europeus em trabalhar com agricultura",c:false}, {t:"Ao salário elevado pago aos trabalhadores",c:false}, {t:"À proibição do governo italiano",c:false}], pts: 3, exp: "Os fazendeiros cobravam juros abusivos sobre transporte e suprimentos, gerando revoltas." },
                { id: "8ANO-HIS-M10", p: "A Revolta dos Farrapos (1835-1845) no Rio Grande do Sul teve como uma das motivações principais:", o: [{t:"Os altos impostos sobre o charque gaúcho em comparação ao charque importado",c:true}, {t:"O desejo de restaurar o domínio de Portugal",c:false}, {t:"A aliança dos gaúchos com o governo do Paraguai",c:false}, {t:"A defesa da abolição imediata da escravidão",c:false}], pts: 3, exp: "Os estancieiros revoltaram-se contra as tarifas que favoreciam o charque platino." },
                { id: "8ANO-HIS-M11", p: "A Revolta dos Malês, ocorrida em Salvador em 1835, foi organizada por:", o: [{t:"Escravizados e libertos de religião muçulmana",c:true}, {t:"Militares e elite cafeeira",c:false}, {t:"Comerciantes portugueses ricos",c:false}, {t:"Indígenas catequizados",c:false}], pts: 3, exp: "Liderada por africanos muçulmanos (malês) em busca de liberdade religiosa e fim da escravidão." },
                { id: "8ANO-HIS-M12", p: "O líder revolucionário Simón Bolívar destacou-se nos processos de independência de diversos países na:", o: [{t:"América Espanhola",c:true}, {t:"América do Norte",c:false}, {t:"América Portuguesa",c:false}, {t:"África Central",c:false}], pts: 3, exp: "Bolívar foi o 'Libertador' de países como Venezuela, Colômbia, Equador, Peru e Bolívia." },
                { id: "8ANO-HIS-M13", p: "O decreto da Abertura dos Portos às Nações Amigas (1808) assinado por D. João VI pôs fim ao:", o: [{t:"Pacto Colonial (monopólio comercial)",c:true}, {t:"Tráfico negreiro",c:false}, {t:"Período Regencial",c:false}, {t:"Tratado de Tordesilhas",c:false}], pts: 3, exp: "Permitiu ao Brasil comerciar diretamente com outros países, terminando o monopólio português." },
                { id: "8ANO-HIS-M14", p: "A Doutrina Monroe (1823), sintetizada no bordão 'A América para os americanos', opunha-se a:", o: [{t:"Qualquer tentativa de recolonização europeia no continente americano",c:true}, {t:"Independência do Brasil e da Argentina",c:false}, {t:"Abolição da escravidão nos Estados Unidos",c:false}, {t:"Livre comércio entre os países americanos",c:false}], pts: 3, exp: "Os EUA combatiam a intervenção da Santa Aliança europeia nas Américas." },
                { id: "8ANO-HIS-M15", p: "Durante a Guerra de Secessão dos EUA (1861-1865), os Estados do Norte e do Sul divergiam sobre:", o: [{t:"Modelos econômicos e a manutenção da escravidão",c:true}, {t:"A escolha do rei da nação",c:false}, {t:"A anexação do México",c:false}, {t:"A religião oficial do estado",c:false}], pts: 3, exp: "O Norte industrializado defendia o trabalho livre e tarifas protecionistas; o Sul agroexportador defendia a escravidão." },
                { id: "8ANO-HIS-M16", p: "A Lei dos Sexagenários (1885) libertava os escravizados que atingissem a idade de:", o: [{t:"60 anos",c:true}, {t:"50 anos",c:false}, {t:"65 anos",c:false}, {t:"70 anos",c:false}], pts: 3, exp: "Concedia alforria aos escravizados com 60 anos ou mais (mediante indenização de trabalho)." },
                { id: "8ANO-HIS-M17", p: "O conflito diplomático entre o Brasil e o Reino Unido na década de 1860, motivado pelo naufrágio de um navio e prisão de oficiais, ficou conhecido como:", o: [{t:"Questão Christie",c:true}, {t:"Questão Religiosa",c:false}, {t:"Questão Militar",c:false}, {t:"Questão Platina",c:false}], pts: 3, exp: "Envolveu o embaixador britânico William Christie e levou ao rompimento diplomático temporário." },
                { id: "8ANO-HIS-M18", p: "A Proclamação da República no Brasil, em 15 de novembro de 1889, foi liderada pelo:", o: [{t:"Marechal Deodoro da Fonseca",c:true}, {t:"Barão de Mauá",c:false}, {t:"Duque de Caxias",c:false}, {t:"Rui Barbosa",c:false}], pts: 3, exp: "Deodoro da Fonseca chefiou o golpe militar que pôs fim ao Segundo Reinado." },
                { id: "8ANO-HIS-F19", p: "A 'Enciclopédia', obra símbolo do Iluminismo desenvolvida para reunir todo o saber humano, foi organizada por:", o: [{t:"Diderot e D'Alembert",c:true}, {t:"Voltaire e John Locke",c:false}, {t:"Newton e Galileu",c:false}, {t:"Adam Smith e Ricardo",c:false}], pts: 3, exp: "Denis Diderot e Jean le Rond d'Alembert coordenaram a publicação da Enciclopédia." },
                { id: "8ANO-HIS-M20", p: "O movimento de trabalhadores ingleses que destruía máquinas como forma de protesto durante a Revolução Industrial foi o:", o: [{t:"Ludismo",c:true}, {t:"Cartismo",c:false}, {t:"Socialismo",c:false}, {t:"Iluminismo",c:false}], pts: 3, exp: "Os ludistas (seguidores de 'Ned Ludd') responsabilizavam as máquinas pelo desemprego e maus salários." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-HIS-D01", p: "O Liberalismo Econômico proposto por Adam Smith em 'A Riqueza das Nações' defendia:", o: [{t:"A não intervenção do Estado na economia e o livre mercado regido pela 'mão invisível'",c:true}, {t:"O controle estatal absoluto sobre preços e mercadorias",c:false}, {t:"O fortalecimento do sistema mercantilista e das corporações de ofício",c:false}, {t:"A proibição do comércio internacional",c:false}], pts: 4, exp: "Adam Smith advogava a livre concorrência e a autorregulação do mercado pela lei da oferta e da procura." },
                { id: "8ANO-HIS-D02", p: "A 'Declaração dos Direitos do Homem e do Cidadão' (1789) aprovada na Revolução Francesa influenciou o mundo moderno, mas apresentava a contradição de:", o: [{t:"Excluir as mulheres e não abolir de imediato a escravidão nas colônias",c:true}, {t:"Defender o retorno do absolutismo monarchico",c:false}, {t:"Garantir voto apenas para os servos camponeses",c:false}, {t:"Proibir a propriedade privada",c:false}], pts: 4, exp: "Apesar do discurso universal, os direitos civis e políticos plenos não foram estendidos às mulheres e colonizados." },
                { id: "8ANO-HIS-D03", p: "Diferente de outros processos de independência na América, a Revolução Haitiana (1791-1804) destacou-se por ter sido liderada por:", o: [{t:"População escravizada e negros libertos que estabeleceram uma república",c:true}, {t:"Elite criolla descendente de espanhóis",c:false}, {t:"Autoridades enviadas pela Coroa Francesa",c:false}, {t:"Comerciantes britânicos instalados na ilha",c:false}], pts: 4, exp: "Sob liderança de Toussaint Louverture e Jean-Jacques Dessalines, escravizados libertaram o Haiti e aboliram a escravidão." },
                { id: "8ANO-HIS-D04", p: "O projeto de Constituição de 1823 no Brasil, apelidado de 'Constituição da Mandioca', caracterizava-se por:", o: [{t:"Exigir renda mínima baseada na produção de mandioca para votar, favorecendo os latifundiários locais",c:true}, {t:"Dar direito de voto universal e secreto a todos os cidadãos",c:false}, {t:"Submeter o poder do imperador à autoridade do Papa",c:false}, {t:"Garantir a libertação de escravizados que fossem alfabetizados",c:false}], pts: 4, exp: "O critério censitário baseado na mandioca visava limitar o poder de portugueses e conceder controle aos grandes proprietários rurais." },
                { id: "8ANO-HIS-D05", p: "Após o término da Guerra do Paraguai (1870), o Exército Brasileiro emergiu como uma força política que passou a defender:", o: [{t:"O fim da escravidão, o positivismo e a implantação da República",c:true}, {t:"O fortalecimento do absolutismo de D. Pedro II",c:false}, {t:"A união definitiva entre o Brasil e Portugal",c:false}, {t:"A proibição do ingresso de estrangeiros no país",c:false}], pts: 4, exp: "Fortalecido e profissionalizado, o oficialato aderiu às ideias positivistas e republicanas, afastando-se do trono." },
                { id: "8ANO-HIS-D06", p: "A Lei de Terras no Brasil (1850) determinou que o acesso à terra devoluta só poderia ocorrer por meio de:", o: [{t:"Compra e venda em dinheiro, inviabilizando o acesso a ex-escravizados e imigrantes pobres",c:true}, {t:"Doação gratuita do governo a quem nela produzisse",c:false}, {t:"Sorteio público anual conduzido pela Igreja",c:false}, {t:"Ocupação direta por posseiros sem custo",c:false}], pts: 4, exp: "A lei garantiu a concentração fundiária ao exigir pagamento em dinheiro para a obtenção de terras públicas." },
                { id: "8ANO-HIS-D07", p: "A Revolução Praieira (1848) em Pernambuco, último grande movimento insurrecional do Império, trazia em seu 'Manifesto ao Mundo' reivindicações como:", o: [{t:"Voto livre e universal, liberdade de imprensa e fim do monopólio do comércio a retalho por portugueses",c:true}, {t:"Restauração do absolutismo e apoio à Santa Aliança",c:false}, {t:"Anexação do Uruguai e volta do tráfico de escravos",c:false}, {t:"Divisão do Brasil em dez repúblicas independentes",c:false}], pts: 4, exp: "Influenciada pelas revoluções liberais europeias de 1848 ('Primavera dos Povos'), tinha caráter social e liberal radical." },
                { id: "8ANO-HIS-D08", p: "O sistema 'Parlamentarismo às Avessas' ocorrido no Segundo Reinado caracterizava-se pelo fato de que:", o: [{t:"O Imperador nomeava o Primeiro-Ministro através do Poder Moderador, controlando as eleições",c:true}, {t:"O Parlamento detinha poder absoluto e podia depor o imperador a qualquer momento",c:false}, {t:"Os cidadãos escolhiam diretamente o Primeiro-Ministro por voto secreto",c:false}, {t:"Havia apenas um partido político autorizado a funcionar",c:false}], pts: 4, exp: "Diferente do modelo inglês, o Imperador controlava a nomeação do Gabinete e a dissolução da Câmara dos Deputados." },
                { id: "8ANO-HIS-D09", p: "O Tratado de Aliança com a Inglaterra assinado por Portugal em 1810 concedia aos produtos britânicos uma tarifa alfandegária preferencial de:", o: [{t:"15%, menor do que a cobrada dos próprios produtos portugueses (16%)",c:true}, {t:"50%, desestimulando a entrada de tecidos ingleses",c:false}, {t:"Isenção total de impostos para sempre",c:false}, {t:"30%, igual à cobrada de todas as nações europeias",c:false}], pts: 4, exp: "A tarifa privilégio de 15% consolidou a hegemonia econômica britânica sobre o mercado brasileiro." },
                { id: "8ANO-HIS-D10", p: "A vertente política jacobina durante a fase da Convenção Nacional na Revolução Francesa (1792-1794) destacou-se por:", o: [{t:"Representar a pequena burguesia/camadas populares e implementar a fase do 'Terror' sob comando de Robespierre",c:true}, {t:"Defender os interesses da alta burguesia e apoiar o rei Luís XVI",c:false}, {t:"Restaurar o feudalismo e reabrir os mosteiros",c:false}, {t:"Entregar o poder militar diretamente a Napoleão Bonaparte",c:false}], pts: 4, exp: "Os jacobinos radicalizaram a revolução com medidas sociais arrojadas e perseguição violenta aos opositores na guilhotina." },
                { id: "8ANO-HIS-D11", p: "A crise da Monarquia brasileira no final do século XIX foi acelerada pela perda de sustentação de seus três pilares tradicionais:", o: [{t:"Igreja (Questão Religiosa), Exército (Questão Militar) e Barões do Café escravocratas (Abolição)",c:true}, {t:"Inglaterra, França e Estados Unidos",c:false}, {t:"Marinha, Aeronáutica e Guarda Nacional",c:false}, {t:"Comerciantes portugueses, banqueiros e operários",c:false}], pts: 4, exp: "A perda do apoio da Igreja, dos militares e da elite agrária tradicional isolou o trono imperial." },
                { id: "8ANO-HIS-D12", p: "O Congresso do Panamá (1826), organizado por Simón Bolívar, visava concretizar a ideia do 'Pan-americanismo', que consistia em:", o: [{t:"Promover a união e cooperação política entre as repúblicas recém-libertadas da América Latina",c:true}, {t:"Anexar todos os territórios ao Império do Brasil",c:false}, {t:"Entregar o controle das Américas aos Estados Unidos",c:false}, {t:"Restaurar o domínio da Coroa Espanhola na região",c:false}], pts: 4, exp: "Bolívar sonhava com uma grande confederação de nações hispano-americanas unidas para resistir ao imperialismo." },
                { id: "8ANO-HIS-D13", p: "O Socialismo Científico formulado por Karl Marx e Friedrich Engels no século XIX defendia que a história humana é movida pela:", o: [{t:"Luta de classes entre exploradores e explorados (burguesia vs proletariado)",c:true}, {t:"Vontade dos reis e imperadores iluminados",c:false}, {t:"Harmonia natural garantida pelo livre mercado",c:false}, {t:"Predestinação divina de certos povos",c:false}], pts: 4, exp: "O materialismo histórico dialético aponta a luta de classes como motor da transformação social." },
                { id: "8ANO-HIS-D14", p: "Qual o impacto da Unificação Alemã (1871) sob a liderança do chanceler Otto von Bismarck na geopolítica europeia?", o: [{t:"Alterou o equilíbrio de poder europeu e acirrou as rivalidades imperialistas que levaram à Primeira Guerra Mundial",c:true}, {t:"Causou o fim imediato de todos os impérios colonialistas",c:false}, {t:"Trouxe a paz duradoura para o continente europeu por mais de um século",c:false}, {t:"Provocou a dissolução da Inglaterra como potência industrial",c:false}], pts: 4, exp: "A rápida industrialização e o expansionismo do novo Império Alemão abalaram a hegemonia europeia." },
                { id: "8ANO-HIS-D15", p: "A Guarda Nacional criada em 1831 durante o Período Regencial brasileiro teve como consequência social o:", o: [{t:"Fortalecimento do poder dos grandes fazendeiros locais que receberam o título de 'coronéis'",c:true}, {t:"Fim definitivo do coronelismo nas áreas rurais",c:false}, {t:"Desarmamento total de milícias privadas no campo",c:false}, {t:"Aumento da influência dos militares profissionais no governo",c:false}], pts: 4, exp: "Ao conceder postos de oficiais aos latifundiários, a Guarda Nacional consolidou o poder coronelista no interior." },
                { id: "8ANO-HIS-D16", p: "A Restauração Meiji ocorrida no Japão a partir de 1868 caracterizou-se por:", o: [{t:"Centralização do poder no Imperador e rápida modernização industrial e militar de molde ocidental",c:true}, {t:"Fechamento definitivo dos portos japoneses ao comércio exterior",c:false}, {t:"Adoção do sistema feudal baseado nos xoguns e samurais",c:false}, {t:"Anexação do Japão pelos Estados Unidos",c:false}], pts: 4, exp: "O Japão aboliu o feudalismo dos xoguns, industrializou-se rapidamente e tornou-se uma potência imperialista na Ásia." },
                { id: "8ANO-HIS-D17", p: "Na Inglaterra do século XIX, o movimento 'Cartista' (Chartism) destacou-se por reivindicar:", o: [{t:"Direitos políticos para os trabalhadores, como voto secreto e sufrágio universal masculino na 'Carta do Povo'",c:true}, {t:"A destruição de todas as fábricas inglesas",c:false}, {t:"A restauração do absolutismo da dinastia Stuart",c:false}, {t:"O aumento das tarifas de importação sobre grãos",c:false}], pts: 4, exp: "Os cartistas enviaram petições ao Parlamento solicitando reformas eleitorais e direitos políticos operários." },
                { id: "8ANO-HIS-D18", p: "A Conferência de Berlim (1884-1885) organizada pelas potências europeias teve como objetivo principal:", o: [{t:"Partilhar o continente africano entre as potências imperialistas europeias",c:true}, {t:"Abolir a escravidão e o tráfico na África",c:false}, {t:"Garantir a independência dos reinos africanos",c:false}, {t:"Dividir o território da Ásia e Oceania",c:false}], pts: 4, exp: "Estabeleceu regras para a ocupação territorial efetiva da África pelas nações europeias, desrespeitando fronteiras étnicas." },
                { id: "8ANO-HIS-D19", p: "No contexto da imigração no Oeste Paulista, o sistema de 'Subvenção' implantado pelo governo provincial diferenciava-se da 'Parceria' porque:", o: [{t:"O Estado financiava as passagens dos imigrantes e garantia contrato de trabalho assalariado inicial",c:true}, {t:"Os imigrantes tornavam-se proprietários automáticos das terras cultivadas",c:false}, {t:"Os cafeicultores assumiam sozinhos os custos de viagem sem ajuda governamental",c:false}, {t:"Trabalhadores eram obrigados a pagar pelo transporte com trabalho escravo",c:false}], pts: 4, exp: "A subvenção estatal facilitou o fluxo migratório em massa, cobrindo os custos de passagem e atraindo milhares de europeus." },
                { id: "8ANO-HIS-D20", p: "O conceito de 'Darwinismo Social' utilizado por ideólogos imperialistas no século XIX fundamentava-se na:", o: [{t:"Aplicação distorcida das teorias da evolução biológica para justificar a superioridade da 'raça branca' europeia",c:true}, {t:"Defesa da igualdade de direitos entre todas as culturas humanas",c:false}, {t:"Teoria de que os povos colonizados eram biologicamente mais desenvolvidos",c:false}, {t:"Ideia de que todas as sociedades humanas progridem sem necessidade de tecnologia",c:false}], pts: 4, exp: "A ideologia pseudocientífica serviu de pretexto para a 'missão civilizadora' e dominação imperialista." }
        ],
        "Ciências": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-CIE-F01", p: "Qual das opções abaixo apresenta apenas fontes de energia renováveis?", o: [{t:"Solar, eólica e hídrica",c:true}, {t:"Petróleo, carvão mineral e gás natural",c:false}, {t:"Nuclear, petróleo e solar",c:false}, {t:"Gasolina, carvão e eólica",c:false}], pts: 2, exp: "Energias solar, eólica e hídrica regeneram-se naturalmente sem esgotamento rápido." },
                { id: "8ANO-CIE-F02", p: "A unidade de medida utilizada para medir o consumo mensal de energia elétrica na conta de luz é o:", o: [{t:"Kilowatt-hora (kWh)",c:true}, {t:"Volt (V)",c:false}, {t:"Ampère (A)",c:false}, {t:"Joule por segundo",c:false}], pts: 2, exp: "O kWh mede a quantidade de energia elétrica consumida ao longo do tempo." },
                { id: "8ANO-CIE-F03", p: "Em um circuito elétrico simples, o componente responsável por interromper ou permitir a passagem da corrente é o:", o: [{t:"Interruptor",c:true}, {t:"Gerador / Bateria",c:false}, {t:"Fio condutor",c:false}, {t:"Resistor / Lâmpada",c:false}], pts: 2, exp: "O interruptor abre ou fecha o circuito elétrico." },
                { id: "8ANO-CIE-F04", p: "Qual dos materiais abaixo é considerado um BOM condutor de eletricidade?", o: [{t:"Cobre",c:true}, {t:"Borracha",c:false}, {t:"Plástico",c:false}, {t:"Vidro",c:false}], pts: 2, exp: "Metais como o cobre possuem elétrons livres que facilitam a condução de corrente elétrica." },
                { id: "8ANO-CIE-F05", p: "Quantas fases principais a Lua possui ao longo de seu ciclo?", o: [{t:"4 fases (Nova, Crescente, Cheia e Minguante)",c:true}, {t:"2 fases",c:false}, {t:"7 fases",c:false}, {t:"12 fases",c:false}], pts: 2, exp: "As quatro fases principais são Nova, Crescente, Cheia e Minguante." },
                { id: "8ANO-CIE-F06", p: "O movimento que a Terra realiza ao redor de si mesma, responsável pela alternância entre dia e noite, é o de:", o: [{t:"Rotação",c:true}, {t:"Translação",c:false}, {t:"Nutação",c:false}, {t:"Precessão",c:false}], pts: 2, exp: "A rotação dura aproximadamente 24 horas e origina os dias e as noites." },
                { id: "8ANO-CIE-F07", p: "As estações do ano ocorrem devido ao movimento de translação combinado com:", o: [{t:"A inclinação do eixo de rotação da Terra",c:true}, {t:"A variação da distância da Terra ao Sol",c:false}, {t:"As fases da Lua",c:false}, {t:"A rotação acelerada da Terra",c:false}], pts: 2, exp: "A inclinação do eixo terrestre faz com que os hemisférios recebam luz solar de forma desigual ao longo do ano." },
                { id: "8ANO-CIE-F08", p: "Um eclipse solar ocorre quando:", o: [{t:"A Lua se posiciona entre a Terra e o Sol",c:true}, {t:"A Terra se posiciona entre o Sol e a Lua",c:false}, {t:"O Sol fica entre a Terra e a Lua",c:false}, {t:"A Terra projeta sua sombra sobre a Lua",c:false}], pts: 2, exp: "A Lua bloqueia total ou parcialmente a luz do Sol direcionada à Terra." },
                { id: "8ANO-CIE-F09", p: "Os órgãos responsáveis pela produção de espermatozoides no sistema reprodutor masculino são os:", o: [{t:"Testículos",c:true}, {t:"Rins",c:false}, {t:"Ovários",c:false}, {t:"Próstata",c:false}], pts: 2, exp: "Os testículos produzem os gametas masculinos e a testosterona." },
                { id: "8ANO-CIE-F10", p: "Os órgãos que produzem os óvulos (oócitos) no sistema reprodutor feminino são os:", o: [{t:"Ovários",c:true}, {t:"Útero",c:false}, {t:"Tubas uterinas",c:false}, {t:"Uretra",c:false}], pts: 2, exp: "Os ovários produzem os gametas femininos e hormônios como estrogênio e progesterona." },
                { id: "8ANO-CIE-F11", p: "A união do espermatozoide com o óvulo é chamada de:", o: [{t:"Fecundação",c:true}, {t:"Ovulação",c:false}, {t:"Menstruação",c:false}, {t:"Gestações",c:false}], pts: 2, exp: "Fecundação gera o zigoto (primeira célula do novo indivíduo)." },
                { id: "8ANO-CIE-F12", p: "A fase de transição entre a infância e a fase adulta, marcada por alterações corporais e hormonais, é a:", o: [{t:"Puberdade",c:true}, {t:"Senectude",c:false}, {t:"Menopausa",c:false}, {t:"Infância",c:false}], pts: 2, exp: "Na puberdade ocorrem o amadurecimento sexual e alterações físicas." },
                { id: "8ANO-CIE-F13", p: "O método contraceptivo que também protege contra Infecções Sexualmente Transmissíveis (ISTs) é o/a:", o: [{t:"Preservativo (camisinha)",c:true}, {t:"Pílula anticoncepcional",c:false}, {t:"Dioptria",c:false}, {t:"DIU de cobre",c:false}], pts: 2, exp: "O preservativo atua como barreira física contra agentes patogênicos." },
                { id: "8ANO-CIE-F14", p: "O efeito estufa natural é um fenômeno importante para a Terra porque:", o: [{t:"Mantém a temperatura do planeta adequada para a vida",c:true}, {t:"Causa o derretimento imediato dos polos",c:false}, {t:"Impede a passagem da luz do Sol",c:false}, {t:"Destrói a camada de ozônio",c:false}], pts: 2, exp: "Sem o efeito estufa natural, a Terra seria gelada e inóspita." },
                { id: "8ANO-CIE-F15", p: "A camada de ozônio localizada na atmosfera tem a função de proteger os seres vivos contra:", o: [{t:"Os raios ultravioleta (UV) do Sol",c:true}, {t:"A chuva ácida",c:false}, {t:"Os meteoritos e asteroides",c:false}, {t:"O vento solar",c:false}], pts: 2, exp: "O ozônio estratosférico absorve a maior parte da radiação UV prejudicial." },
                { id: "8ANO-CIE-F16", p: "A condição das variáveis atmosféricas (chuva, vento, temperatura) em um momento específico é o:", o: [{t:"Tempo atmosférico",c:true}, {t:"Clima",c:false}, {t:"Aquecimento global",c:false}, {t:"Efeito estufa",c:false}], pts: 2, exp: "Tempo é o estado momentâneo da atmosfera; clima é o padrão observado por décadas." },
                { id: "8ANO-CIE-F17", p: "Qual vírus é o causador da AIDS (Síndrome da Imunodeficiência Adquirida)?", o: [{t:"HIV",c:true}, {t:"HPV",c:false}, {t:"Influenza",c:false}, {t:"Coronavírus",c:false}], pts: 2, exp: "O HIV ataca as células de defesa do sistema imunológico humano." },
                { id: "8ANO-CIE-F18", p: "A eliminação do endométrio com sangue pela vagina quando não ocorre a fecundação é a:", o: [{t:"Menstruação",c:true}, {t:"Ovulação",c:false}, {t:"Gestação",c:false}, {t:"Fecundação",c:false}], pts: 2, exp: "Sem a nidação do embrião, a camada do endométrio se descama, originando a menstruação." },
                { id: "8ANO-CIE-F19", p: "Chuveiros elétricos e ferros de passar roupas transformam energia elétrica principalmente em energia:", o: [{t:"Térmica",c:true}, {t:"Luminosa",c:false}, {t:"Sonora",c:false}, {t:"Química",c:false}], pts: 2, exp: "Pelo Efeito Joule, a corrente elétrica ao passar por uma resistência gera calor." },
                { id: "8ANO-CIE-F20", p: "A principal fonte de energia que movimenta o ciclo da água e o clima na Terra é o:", o: [{t:"Sol",c:true}, {t:"Vento",c:false}, {t:"Núcleo terrestre",c:false}, {t:"Oceano",c:false}], pts: 2, exp: "O Sol aquece o planeta e fornece a radiação necessária para a evaporação e os ventos." },

                // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "8ANO-CIE-M01", p: "Nas usinas hidrelétricas, a energia potencial gravitacional da água represada transforma-se sequencialmente em energia:", o: [{t:"Cinética e depois Elétrica",c:true}, {t:"Térmica e depois Química",c:false}, {t:"Nuclear e depois Luminosa",c:false}, {t:"Eólica e depois Mecânica",c:false}], pts: 3, exp: "Água cai (potencial -> cinética) e gira as turbinas do gerador (cinética -> elétrica)." },
                { id: "8ANO-CIE-M02", p: "Um aparelho de 2000 W (2 kW) ligado por 3 horas consome quanta energia elétrica?", o: [{t:"6 kWh",c:true}, {t:"2000 kWh",c:false}, {t:"600 kWh",c:false}, {t:"1,5 kWh",c:false}], pts: 3, exp: "Energia = Potência (kW) x Tempo (h) = 2 kW x 3 h = 6 kWh." },
                { id: "8ANO-CIE-M03", p: "O hormônio responsável pelo surgimento dos caracteres sexuais secundários masculinos (voz grave, pelos) é a:", o: [{t:"Testosterona",c:true}, {t:"Progesterona",c:false}, {t:"Insulina",c:false}, {t:"Adrenalina",c:false}], pts: 3, exp: "A testosterona impulsiona o desenvolvimento das características sexuais masculinas." },
                { id: "8ANO-CIE-M04", p: "A liberação do óvulo (oócito) pelo ovário ocorre na metade do ciclo menstrual e é chamada de:", o: [{t:"Ovulação",c:true}, {t:"Nidação",c:false}, {t:"Fecundação",c:false}, {t:"Menarca",c:false}], pts: 3, exp: "A ovulação ocorre geralmente por volta do 14º dia de um ciclo padrão de 28 dias." },
                { id: "8ANO-CIE-M05", p: "Dentre os métodos contraceptivos abaixo, qual é considerado definitivo por cirurgia no homem?", o: [{t:"Vasectomia",c:true}, {t:"Laqueadura",c:false}, {t:"DIU",c:false}, {t:"Preservativo",c:false}], pts: 3, exp: "A vasectomia corta os canais deferentes, impedindo a saída de espermatozoides." },
                { id: "8ANO-CIE-M06", p: "As marés altas e baixas que ocorrem nos oceanos são causadas principalmente pela atração gravitacional:", o: [{t:"Da Lua e do Sol sobre a Terra",c:true}, {t:"Do centro da Terra apenas",c:false}, {t:"Dos ventos marítimos",c:false}, {t:"Dos vulcões submersos",c:false}], pts: 3, exp: "A força gravitacional exercida pela Lua (e em menor escala pelo Sol) atrai as massas de água." },
                { id: "8ANO-CIE-M07", p: "Nos dias de Equinócio, ocorridos em março e setembro, a duração do dia e da noite é:", o: [{t:"Exatamente igual (12 horas cada)",c:true}, {t:"O dia é mais longo que a noite",c:false}, {t:"A noite é mais longa que o dia",c:false}, {t:"O dia dura 24 horas nos polos",c:false}], pts: 3, exp: "No equinócio, a iluminação solar atinge igualmente os dois hemisférios." },
                { id: "8ANO-CIE-M08", p: "Dentre as ISTs listadas, qual delas é causada por uma BACTÉRIA e apresenta como sintoma inicial uma ferida indolor (cancro duro)?", o: [{t:"Sífilis",c:true}, {t:"AIDS",c:false}, {t:"HPV",c:false}, {t:"Herpes genital",c:false}], pts: 3, exp: "A sífilis é causada pela bactéria Treponema pallidum e inicia com o cancro duro." },
                { id: "8ANO-CIE-M09", p: "O aumento não natural do efeito estufa e consequente aquecimento global decorrem principalmente da emissão de:", o: [{t:"Dióxido de carbono (CO2) e Metano (CH4)",c:true}, {t:"Oxigênio (O2) e Nitrogênio (N2)",c:false}, {t:"Hélio (He) e Água (H2O)",c:false}, {t:"Argônio (Ar) e Ozônio (O3)",c:false}], pts: 3, exp: "A queima de combustíveis fósseis e o desmatamento aumentam a concentração de CO2 e CH4." },
                { id: "8ANO-CIE-M10", p: "Os gases CFCs (clorofluorcarbonetos), antes usados em aerossóis e geladeiras, provocaram:", o: [{t:"A destruição da camada de ozônio",c:true}, {t:"O aumento das chuvas ácidas",c:false}, {t:"A diminuição do efeito estufa",c:false}, {t:"O esfriamento do núcleo da Terra",c:false}], pts: 3, exp: "Os radicais de cloro libertados pelos CFCs destroem as moléculas de ozônio na estratosfera." },
                { id: "8ANO-CIE-M11", p: "Em um circuito elétrico em SÉRIE com três lâmpadas iguais, se uma das lâmpadas queimar:", o: [{t:"Todas as outras lâmpadas se apagam",c:true}, {t:"As outras permanecem acesas normalmente",c:false}, {t:"As outras brilham mais forte",c:false}, {t:"O circuito entra em curto-circuito",c:false}], pts: 3, exp: "No circuito em série há apenas um caminho para a corrente; ao quebrar uma, o circuito abre." },
                { id: "8ANO-CIE-M12", p: "A grandeza física elétrica associada à oposição que um material oferece à passagem da corrente é a:", o: [{t:"Resistência elétrica (Ohm)",c:true}, {t:"Tensão elétrica (Volt)",c:false}, {t:"Corrente elétrica (Ampère)",c:false}, {t:"Potência elétrica (Watt)",c:false}], pts: 3, exp: "A resistência (medida em Ohms) mede a dificuldade de passagem dos elétrons." },
                { id: "8ANO-CIE-M13", p: "A fecundação humana ocorre normalmente em qual estrutura do sistema genital feminino?", o: [{t:"Tubas uterinas",c:true}, {t:"Útero",c:false}, {t:"Vagina",c:false}, {t:"Ovários",c:false}], pts: 3, exp: "O encontro do espermatozoide com o oócito ocorre na ampola da tuba uterina." },
                { id: "8ANO-CIE-M14", p: "Quantos cromossomos sexuais um ser humano herda normalmente de seus pais ao todo?", o: [{t:"2 cromossomos sexuais (XX ou XY)",c:true}, {t:"46 cromossomos sexuais",c:false}, {t:"1 cromossomo sexual",c:false}, {t:"23 cromossomos sexuais",c:false}], pts: 3, exp: "Recebe 1 cromossomo sexual da mãe (X) e 1 do pai (X ou Y), totalizando 2 sexuais (de 46 totais)." },
                { id: "8ANO-CIE-M15", p: "O fenômeno atmosférico no qual uma camada de ar quente aprisiona uma camada de ar frio e poluído próximo ao solo é a:", o: [{t:"Inversão térmica",c:true}, {t:"Chuva ácida",c:false}, {t:"Efeito estufa",c:false}, {t:"Tornado",c:false}], pts: 3, exp: "A inversão térmica impede a dispersão de poluentes em cidades durante o inverno." },
                { id: "8ANO-CIE-M16", p: "Os ventos ocorrem na atmosfera devido a diferenças de:", o: [{t:"Pressão e temperatura do ar entre regiões",c:true}, {t:"Umididade do solo apenas",c:false}, {t:"Campo magnético terrestre",c:false}, {t:"Fases da Lua",c:false}], pts: 3, exp: "O ar se desloca das zonas de alta pressão (mais frio/denso) para baixa pressão (mais quente/rarefeito)." },
                { id: "8ANO-CIE-M17", p: "A vacina contra o HPV (Papilomavírus Humano) é fundamental na prevenção de:", o: [{t:"Câncer do colo do útero e verrugas genitais",c:true}, {t:"Hepatite B e C",c:false}, {t:"Sífilis primária",c:false}, {t:"Aids e gonorreia",c:false}], pts: 3, exp: "O HPV é o principal fator causador de câncer de colo uterino." },
                { id: "8ANO-CIE-M18", p: "O DIU (Dispositivo Intrauterino) de cobre atua como método contraceptivo ao:", o: [{t:"Impedir a sobrevivência dos espermatozoides no útero por ação espermicida/inflamatória",c:true}, {t:"Impedir a ovulação através de hormônios",c:false}, {t:"Bloquear a entrada de ar no útero",c:false}, {t:"Destruir os ovários",c:false}], pts: 3, exp: "O cobre libera íons que afetam a mobilidade e viabilidade dos espermatozoides." },
                { id: "8ANO-CIE-M19", p: "A queima de combustíveis fósseis em usinas termoelétricas apresenta como desvantagem ambiental:", o: [{t:"A grande emissão de gases do efeito estufa e poluentes atmosféricos",c:true}, {t:"O consumo excessivo de radiação solar",c:false}, {t:"A geração de lixo nuclear radiativo",c:false}, {t:"A dependência do regime de ventos",c:false}], pts: 3, exp: "Termoelétricas a carvão ou gás liberam altas quantidades de CO2 e fuligem." },
                { id: "8ANO-CIE-M20", p: "Em relação aos circuitos em PARALELO nas residências, uma vantagem é que:", o: [{t:"Cada aparelho funciona de forma independente com a mesma tensão elétrica",c:true}, {t:"Se um aparelho for desligado, todos os outros desligam",c:false}, {t:"A corrente elétrica é dividida igualmente e diminui a tensão",c:false}, {t:"Não necessita de fios condutores",c:false}], pts: 3, exp: "Na ligação em paralelo, todos os eletrodomésticos recebem a mesma d.d.p. (ex: 110V ou 220V) independente." },

                // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "8ANO-CIE-D01", p: "Um ar-condicionado de 1500 W (1,5 kW) é usado 8 horas por dia durante 30 dias. Com tarifa de R$ 0,80 por kWh, qual o custo de energia?", o: [{t:"R$ 288,00",c:true}, {t:"R$ 360,00",c:false}, {t:"R$ 144,00",c:false}, {t:"R$ 96,00",c:false}], pts: 4, exp: "Energia = 1,5 kW x 8 h/dia x 30 dias = 360 kWh. Custo = 360 x R$ 0,80 = R$ 288,00." },
                { id: "8ANO-CIE-D02", p: "Se dois resistores de 6 Ω estão associados em PARALELO, a resistência equivalente da associação é de:", o: [{t:"3 Ω",c:true}, {t:"12 Ω",c:false}, {t:"1 Ω",c:false}, {t:"36 Ω",c:false}], pts: 4, exp: "Req para resistores iguais em paralelo: R / n = 6 / 2 = 3 Ω." },
                { id: "8ANO-CIE-D03", p: "No ciclo reprodutivo feminino, o pico do hormônio luteinizante (LH) por volta do 14º dia provoca diretamente a:", o: [{t:"Ovulação",c:true}, {t:"Menstruação",c:false}, {t:"Nidação",c:false}, {t:"Descamação do endométrio",c:false}], pts: 4, exp: "O surto de LH induz o rompimento do folículo ovariano e liberação do oócito (ovulação)." },
                { id: "8ANO-CIE-D04", p: "O dimensionamento de fusíveis e disjuntores no quadro elétrico residencial visa proteger a fiação contra:", o: [{t:"Sobrecargas e curtos-circuitos provocados por corrente excessiva",c:true}, {t:"Quedas na tensão fornecida pela concessionária",c:false}, {t:"Aumento do consumo de energia em kWh",c:false}, {t:"Vazamentos de água nos eletrodomésticos",c:false}], pts: 4, exp: "Disjuntores desligam o circuito quando a corrente supera o limite seguro da fiação." },
                { id: "8ANO-CIE-D05", p: "As estações do ano são opostas nos dois hemisférios (ex: Verão no Sul e Inverno no Norte) porque:", o: [{t:"O eixo de rotação da Terra é inclinado em relação ao plano de translação",c:true}, {t:"A Terra está mais próxima do Sol em dezembro",c:false}, {t:"O Hemisfério Norte possui mais continentes que o Sul",c:false}, {t:"A rotação da Terra gira em sentido horário",c:false}], pts: 4, exp: "A inclinação de 23,5° faz com que um hemisfério receba incidência solar mais direta que o outro." },
                { id: "8ANO-CIE-D06", p: "A 'pílula do dia seguinte' é um contraceptivo de emergência que deve ser utilizado com cautela porque:", o: [{t:"Contém alta dosagem hormonal que altera o ciclo e não protege contra ISTs",c:true}, {t:"Causa aborto de gestações avançadas",c:false}, {t:"Garante proteção permanente contra gravidez",c:false}, {t:"Substitui o preservativo nas relações",c:false}], pts: 4, exp: "Possui altíssima dose de hormônios para inibir/atrasar a ovulação; não é método de rotina nem previne ISTs." },
                { id: "8ANO-CIE-D07", p: "Se não tratada, a Sífilis pode evoluir para a fase terciária e causar comprometimentos graves no/na:", o: [{t:"Sistema cardiovascular e sistema nervoso central",c:true}, {t:"Sistema digestório apenas",c:false}, {t:"Visão periférica sem afetar órgãos",c:false}, {t:"Sistema esquelético das mãos",c:false}], pts: 4, exp: "A sífilis terciária traz lesões neurológicas (neurossífilis) e cardiovasculares graves." },
                { id: "8ANO-CIE-D08", p: "O Protocolo de Montreal (1987) foi um acordo internacional de sucesso que visou banir a produção de:", o: [{t:"Clorofluorcarbonetos (CFCs) para recuperar a camada de ozônio",c:true}, {t:"Gás carbônico de automóveis",c:false}, {t:"Plásticos descartáveis nos oceanos",c:false}, {t:"Usinas de energia nuclear",c:false}], pts: 4, exp: "O acordo eliminou o uso de CFCs que destruíam a camada de ozônio." },
                { id: "8ANO-CIE-D09", p: "Nos dias de Solstício de Verão no Hemisfério Sul (por volta de 21 de dezembro), ocorre:", o: [{t:"O dia mais longo do ano e a noite mais curta no Hemisfério Sul",c:true}, {t:"O dia e a noite com durações exatamente iguais",c:false}, {t:"A noite mais longa do ano no Hemisfério Sul",c:false}, {t:"O eclipse total do Sol na linha do Equador",c:false}], pts: 4, exp: "No solstício de verão, o hemisfério sul atinge a máxima iluminação solar do ano." },
                { id: "8ANO-CIE-D10", p: "Durante a segunda metade do ciclo menstrual (fase lútea), o corpo lúteo produz elevadas taxas de:", o: [{t:"Progesterona, mantendo o endométrio espesso para a nidação",c:true}, {t:"FSH, provocando nova ovulação",c:false}, {t:"Testosterona, destruindo a parede uterina",c:false}, {t:"Prolactina, impedindo a menstruação",c:false}], pts: 4, exp: "A progesterona prepara e mantém a parede interna do útero (endométrio) irrigada para receber o embrião." },
                { id: "8ANO-CIE-D11", p: "O mecanismo de transferência de calor por CONVECÇÃO ocorre em fluidos (líquidos e gases) através de:", o: [{t:"Movimentos de massas quentes (menos densas que sobem) e frias (mais densas que descem)",c:true}, {t:"Ondas eletromagnéticas no vácuo sem matéria",c:false}, {t:"Contato direto entre moléculas sólidas sem movimento de massa",c:false}, {t:"Transformação de energia química em elétrica",c:false}], pts: 4, exp: "A variação de densidade com a temperatura gera correntes de convecção em fluidos." },
                { id: "8ANO-CIE-D12", p: "Nas usinas nucleares, a energia elétrica é gerada a partir da:", o: [{t:"Fissão de núcleos de urânio que aquece água criando vapor para girar turbinas",c:true}, {t:"Fusão de átomos de hidrogênio gerando eletricidade direta",c:false}, {t:"Combustão do urânio em salas fechadas",c:false}, {t:"Reação química entre plutônio e oxigênio",c:false}], pts: 4, exp: "A fissão nuclear libera calor intenso, fervendo água que gera vapor em alta pressão para mover turbinas." },
                { id: "8ANO-CIE-D13", p: "Gêmeos monozigóticos (univitelinos) originam-se de:", o: [{t:"Um único óvulo fecundado por um único espermatozoide, que se divide em dois embriões",c:true}, {t:"Dois óvulos diferentes fecundados por dois espermatozoides distintos",c:false}, {t:"Um óvulo fecundado por dois espermatozoides simultaneamente",c:false}, {t:"Dois óvulos fecundados por um único espermatozoide",c:false}], pts: 4, exp: "Monozigóticos possuem exatamente o mesmo patrimônio genético por virem da mesma célula-ovo." },
                { id: "8ANO-CIE-D14", p: "O ozônio troposférico (próximo ao solo) difere do ozônio estratosférico porque o troposférico é:", o: [{t:"Um poluente tóxico irritante para o sistema respiratório humano",c:true}, {t:"O principal responsável por proteger contra radiação UV",c:false}, {t:"Um gás inerte e benéfico para a respiração",c:false}, {t:"Produzido diretamente pela fotossíntese das plantas",c:false}], pts: 4, exp: "Na troposfera, o ozônio atua como poluente secundário tóxico (smog fitoquímico)." },
                { id: "8ANO-CIE-D15", p: "O Selo Procel presente em eletrodomésticos serve para indicar ao consumidor:", o: [{t:"O nível de eficiência energética do aparelho (sendo 'A' o mais eficiente)",c:true}, {t:"O tempo de garantia contra defeitos de fábrica",c:false}, {t:"Se o produto é reciclável ou não",c:false}, {t:"A voltagem máxima suportada",c:false}], pts: 4, exp: "Indica aparelhos de maior eficiência energética que consomem menos energia." },
                { id: "8ANO-CIE-D16", p: "O fenômeno climático El Niño caracteriza-se pelo:", o: [{t:"Aquecimento anormal das águas superficiais do Oceano Pacífico Equatorial",c:true}, {t:"Resfriamento anormal do Oceano Atlântico Norte",c:false}, {t:"Aumento da camada de gelo na Antártida",c:false}, {t:"Enfraquecimento do efeito estufa mundial",c:false}], pts: 4, exp: "O aquecimento das águas do Pacífico altera os padrões globais de precipitação e temperatura." },
                { id: "8ANO-CIE-D17", p: "A estratégia de 'dupla proteção' em saúde sexual consiste na combinação de:", o: [{t:"Camisinha (prevenção de ISTs) com outro método contraceptivo (evitar gravidez)",c:true}, {t:"Dois tipos de pílulas anticoncepcionais juntas",c:false}, {t:"Uso simultâneo de duas camisinhas masculinas",c:false}, {t:"Vasectomia combinada com pílula do dia seguinte",c:false}], pts: 4, exp: "Combina barreira física contra ISTs com alta eficácia contraceptiva." },
                { id: "8ANO-CIE-D18", p: "As 'marés de sizígia' (marés de grande amplitude) ocorrem quando Sol, Terra e Lua estão alinhados nas fases de Lua:", o: [{t:"Nova e Cheia",c:true}, {t:"Crescente e Minguante",c:false}, {t:"Apenas na Lua Nova",c:false}, {t:"Apenas na Lua Minguante",c:false}], pts: 4, exp: "O alinhamento gravitacional do Sol e da Lua soma forças, criando marés mais altas." },
                { id: "8ANO-CIE-D19", p: "O dispositivo 'fio terra' em instalações elétricas tem a função de:", o: [{t:"Desviar correntes de fuga ou descargas elétricas para o solo, evitando choques",c:true}, {t:"Aumentar a voltagem fornecida aos aparelhos",c:false}, {t:"Desligar a luz automaticamente à noite",c:false}, {t:"Medir a quantidade de energia em kWh",c:false}], pts: 4, exp: "O aterramento conduz desvios elétricos da carcaça dos aparelhos em segurança para a terra." },
                { id: "8ANO-CIE-D20", p: "A construção de grandes usinas hidrelétricas causa como principal impacto socioambiental:", o: [{t:"Alagamento de grandes áreas, destruição de ecossistemas e deslocamento de populações",c:true}, {t:"Emissão maciça de cinzas de carvão na atmosfera",c:false}, {t:"Vazamento de resíduos radioativos em rios",c:false}, {t:"Aumento da camada de ozônio local",c:false}], pts: 4, exp: "A formação do reservatório inunda florestas e cidades, exigindo reassentamentos e perdas ecológicas." }
        ]
    },

    // ------------------------------------------
    // 9º ANO
    // ------------------------------------------
    "9": {
        "Matemática": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-MAT-F01", p: "Qual o resultado da soma de frações 2/5 + 1/5?", o: [{t:"3/10",c:false}, {t:"3/5",c:true}, {t:"2/5",c:false}, {t:"1/5",c:false}], pts: 2, exp: "Com denominadores iguais, somamos os numeradores (2+1 = 3) e mantemos o denominador." },
                { id: "9ANO-MAT-F02", p: "Em um triângulo retângulo com catetos medindo 3 cm e 4 cm, qual a medida da hipotenusa?", o: [{t:"5 cm",c:true}, {t:"6 cm",c:false}, {t:"7 cm",c:false}, {t:"25 cm",c:false}], pts: 2, exp: "Pelo Teorema de Pitágoras: a² = 3² + 4² = 9 + 16 = 25 => a = 5 cm." },
                { id: "9ANO-MAT-F03", p: "Qual é a raiz quadrada exata de 100?", o: [{t:"5",c:false}, {t:"10",c:true}, {t:"20",c:false}, {t:"50",c:false}], pts: 2, exp: "Pois 10 x 10 = 100." },
                { id: "9ANO-MAT-F04", p: "Qual o valor positivo de x na equação do 2º grau incompleta x² = 16?", o: [{t:"2",c:false}, {t:"4",c:true}, {t:"8",c:false}, {t:"16",c:false}], pts: 2, exp: "x = √16 = 4." },
                { id: "9ANO-MAT-F05", p: "Quanto é 10% de 250?", o: [{t:"25",c:true}, {t:"2,5",c:false}, {t:"50",c:false}, {t:"250",c:false}], pts: 2, exp: "10% de 250 = (10/100) x 250 = 25." },
                { id: "9ANO-MAT-F06", p: "Como se escreve o número 30.000 em notação científica?", o: [{t:"3 x 10³",c:false}, {t:"3 x 10⁴",c:true}, {t:"30 x 10³",c:false}, {t:"0,3 x 10⁵",c:false}], pts: 2, exp: "30.000 = 3 multiplicado por 10 elevado a 4." },
                { id: "9ANO-MAT-F07", p: "Qual o desenvolvimento do produto notável (x + 2)²?", o: [{t:"x² + 4",c:false}, {t:"x² + 4x + 4",c:true}, {t:"x² + 2x + 4",c:false}, {t:"x² + 4x + 2",c:false}], pts: 2, exp: "(x + 2)² = x² + 2(x)(2) + 2² = x² + 4x + 4." },
                { id: "9ANO-MAT-F08", p: "Um ângulo cuja medida é menor do que 90° é classificado como:", o: [{t:"Agudo",c:true}, {t:"Obtuso",c:false}, {t:"Raso",c:false}, {t:"Reto",c:false}], pts: 2, exp: "Ângulos menores que 90° são chamados de agudos." },
                { id: "9ANO-MAT-F09", p: "Qual é o valor de x na equação simples 2x = 10?", o: [{t:"2",c:false}, {t:"5",c:true}, {t:"8",c:false}, {t:"20",c:false}], pts: 2, exp: "x = 10 / 2 = 5." },
                { id: "9ANO-MAT-F10", p: "Qual a área de um triângulo com base de 6 cm e altura de 4 cm?", o: [{t:"24 cm²",c:false}, {t:"12 cm²",c:true}, {t:"10 cm²",c:false}, {t:"8 cm²",c:false}], pts: 2, exp: "Área = (base x altura) / 2 = (6 x 4) / 2 = 12 cm²." },
                { id: "9ANO-MAT-F11", p: "Qual a raiz quadrada de 0,04?", o: [{t:"0,02",c:false}, {t:"0,2",c:true}, {t:"2",c:false}, {t:"0,4",c:false}], pts: 2, exp: "Pois 0,2 x 0,2 = 0,04." },
                { id: "9ANO-MAT-F12", p: "O valor aproximado da constante Pi (π) frequentemente utilizado em cálculos é:", o: [{t:"2,14",c:false}, {t:"3,14",c:true}, {t:"4,13",c:false}, {t:"3,00",c:false}], pts: 2, exp: "O valor irracional do pi é arredondado comumente para 3,14." },
                { id: "9ANO-MAT-F13", p: "Ao lançar uma moeda não viciada, qual a probabilidade de obter a face 'cara'?", o: [{t:"1/4",c:false}, {t:"1/2",c:true}, {t:"1/3",c:false}, {t:"1/6",c:false}], pts: 2, exp: "Há 1 caso favorável em 2 possíveis (1/2 ou 50%)." },
                { id: "9ANO-MAT-F14", p: "Qual o perímetro de um quadrado de lado 5 cm?", o: [{t:"10 cm",c:false}, {t:"20 cm",c:true}, {t:"25 cm",c:false}, {t:"15 cm",c:false}], pts: 2, exp: "Perímetro = 4 x lado = 4 x 5 = 20 cm." },
                { id: "9ANO-MAT-F15", p: "A fatoração da diferença de dois quadrados x² - 9 resulta em:", o: [{t:"(x - 3)²",c:false}, {t:"(x - 3)(x + 3)",c:true}, {t:"(x + 3)²",c:false}, {t:"x(x - 9)",c:false}], pts: 2, exp: "a² - b² = (a - b)(a + b), logo x² - 3² = (x - 3)(x + 3)." },
                { id: "9ANO-MAT-F16", p: "Qual é a mediana do conjunto ordenado de dados {1, 3, 5}?", o: [{t:"1",c:false}, {t:"3",c:true}, {t:"5",c:false}, {t:"9",c:false}], pts: 2, exp: "O elemento central do conjunto ordenado é 3." },
                { id: "9ANO-MAT-F17", p: "Qual o valor do seno de um ângulo de 30°?", o: [{t:"1/2",c:true}, {t:"√3/2",c:false}, {t:"√2/2",c:false}, {t:"1",c:false}], pts: 2, exp: "O seno de 30° é um ângulo notável e vale 1/2 (ou 0,5)." },
                { id: "9ANO-MAT-F18", p: "Em qualquer triângulo retângulo, o lado oposto ao ângulo reto é chamado de:", o: [{t:"Cateto oposto",c:false}, {t:"Cateto adjacente",c:false}, {t:"Hipotenusa",c:true}, {t:"Bissetriz",c:false}], pts: 2, exp: "A hipotenusa é o maior lado do triângulo retângulo e fica oposta ao ângulo reto." },
                { id: "9ANO-MAT-F19", p: "Qual o resultado de (2³)²?", o: [{t:"12",c:false}, {t:"32",c:false}, {t:"64",c:true}, {t:"16",c:false}], pts: 2, exp: "Potência de potência: conserva a base e multiplica os expoentes 2^(3x2) = 2⁶ = 64." },
                { id: "9ANO-MAT-F20", p: "Qual das opções apresenta uma equação do 2º grau na forma reduzida?", o: [{t:"2x + 5 = 0",c:false}, {t:"x² - 5x + 6 = 0",c:true}, {t:"x³ + x = 0",c:false}, {t:"3x - 1 = x",c:false}], pts: 2, exp: "A equação possui o maior expoente de x igual a 2 (ax² + bx + c = 0)." },

                // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "9ANO-MAT-M01", p: "Quais são as raízes da equação do 2º grau x² - 5x + 6 = 0?", o: [{t:"1 e 6",c:false}, {t:"2 e 3",c:true}, {t:"-2 e -3",c:false}, {t:"0 e 5",c:false}], pts: 3, exp: "Δ = (-5)² - 4(1)(6) = 25 - 24 = 1. Raízes: (5 ± 1)/2 => x1 = 3 e x2 = 2." },
                { id: "9ANO-MAT-M02", p: "Pelo Teorema de Tales, três retas paralelas cortam duas transversais. Se os segmentos de uma são 3 e 4, e da outra são x e 8, qual o valor de x?", o: [{t:"6",c:true}, {t:"5",c:false}, {t:"7",c:false}, {t:"12",c:false}], pts: 3, exp: "Proporção: 3/4 = x/8 => 4x = 24 => x = 6." },
                { id: "9ANO-MAT-M03", p: "Em um triângulo retângulo, a altura relativa à hipotenusa divide-a em segmentos m = 2 cm e n = 8 cm. Qual a medida dessa altura?", o: [{t:"4 cm",c:true}, {t:"10 cm",c:false}, {t:"16 cm",c:false}, {t:"6 cm",c:false}], pts: 3, exp: "Pela relação métrica h² = m x n => h² = 2 x 8 = 16 => h = 4 cm." },
                { id: "9ANO-MAT-M04", p: "Qual a medida da diagonal de um quadrado cujo lado mede 5 cm?", o: [{t:"5√2 cm",c:true}, {t:"10 cm",c:false}, {t:"5√3 cm",c:false}, {t:"25 cm",c:false}], pts: 3, exp: "A diagonal do quadrado é dada por d = L√2 = 5√2 cm." },
                { id: "9ANO-MAT-M05", p: "Qual o zero (raiz) da função afim f(x) = 2x - 4?", o: [{t:"x = 2",c:true}, {t:"x = -2",c:false}, {t:"x = 4",c:false}, {t:"x = 0",c:false}], pts: 3, exp: "Fazendo f(x) = 0: 2x - 4 = 0 => 2x = 4 => x = 2." },
                { id: "9ANO-MAT-M06", p: "Qual o valor do cosseno de 60°?", o: [{t:"1/2",c:true}, {t:"√3/2",c:false}, {t:"√2/2",c:false}, {t:"1",c:false}], pts: 3, exp: "O cosseno de 60° é um valor notável igual a 1/2 (0,5)." },
                { id: "9ANO-MAT-M07", p: "A simplificação do radical √50 resulta em:", o: [{t:"5√2",c:true}, {t:"2√5",c:false}, {t:"25√2",c:false}, {t:"10√5",c:false}], pts: 3, exp: "Fatorando 50: √(25 x 2) = √25 x √2 = 5√2." },
                { id: "9ANO-MAT-M08", p: "Quais são as soluções da equação incompleta x² - 9x = 0?", o: [{t:"0 e 9",c:true}, {t:"3 e -3",c:false}, {t:"Apenas 9",c:false}, {t:"1 e 9",c:false}], pts: 3, exp: "Fatorando: x(x - 9) = 0 => x = 0 ou x = 9." },
                { id: "9ANO-MAT-M09", p: "Qual a área de um círculo de raio igual a 5 cm? (Considere π = 3,14)", o: [{t:"78,5 cm²",c:true}, {t:"31,4 cm²",c:false}, {t:"15,7 cm²",c:false}, {t:"314 cm²",c:false}], pts: 3, exp: "Área = π r² = 3,14 x 5² = 3,14 x 25 = 78,5 cm²." },
                { id: "9ANO-MAT-M10", p: "Dois triângulos são semelhantes. O primeiro tem lados 3 cm, 4 cm e 5 cm. O segundo tem lados x, 8 cm e 10 cm. Qual o valor de x?", o: [{t:"6 cm",c:true}, {t:"5 cm",c:false}, {t:"7 cm",c:false}, {t:"9 cm",c:false}], pts: 3, exp: "A razão de semelhança é 8/4 = 2. Logo, x = 3 x 2 = 6 cm." },
                { id: "9ANO-MAT-M11", p: "Qual o valor do discriminante (delta) na equação x² - 4x + 4 = 0?", o: [{t:"0",c:true}, {t:"16",c:false}, {t:"8",c:false}, {t:"-16",c:false}], pts: 3, exp: "Δ = b² - 4ac = (-4)² - 4(1)(4) = 16 - 16 = 0." },
                { id: "9ANO-MAT-M12", p: "Qual é a soma das raízes da equação do 2º grau x² - 7x + 10 = 0?", o: [{t:"7",c:true}, {t:"-7",c:false}, {t:"10",c:false}, {t:"-10",c:false}], pts: 3, exp: "Pela relação de Girard, a soma das raízes é S = -b/a = -(-7)/1 = 7." },
                { id: "9ANO-MAT-M13", p: "Qual é o produto das raízes da equação do 2º grau x² - 7x + 10 = 0?", o: [{t:"10",c:true}, {t:"7",c:false}, {t:"-10",c:false}, {t:"5",c:false}], pts: 3, exp: "Pela relação de Girard, o produto das raízes é P = c/a = 10/1 = 10." },
                { id: "9ANO-MAT-M14", p: "Ao lançar um dado não viciado de 6 faces, qual a probabilidade de obter um número primo?", o: [{t:"1/2",c:true}, {t:"1/3",c:false}, {t:"2/3",c:false}, {t:"1/6",c:false}], pts: 3, exp: "Números primos no dado: {2, 3, 5} (3 casos). Probabilidade = 3/6 = 1/2." },
                { id: "9ANO-MAT-M15", p: "Desenvolvendo o produto notável do quadrado da diferença (x - 3)², obtemos:", o: [{t:"x² - 6x + 9",c:true}, {t:"x² - 9",c:false}, {t:"x² + 6x + 9",c:false}, {t:"x² - 3x + 9",c:false}], pts: 3, exp: "(x - 3)² = x² - 2(x)(3) + 3² = x² - 6x + 9." },
                { id: "9ANO-MAT-M16", p: "Racionalizando o denominador da fração 1 / √2, encontramos:", o: [{t:"√2 / 2",c:true}, {t:"√2",c:false}, {t:"2 / √2",c:false}, {t:"1 / 2",c:false}], pts: 3, exp: "Multiplicando numerador e denominador por √2: (1 x √2) / (√2 x √2) = √2 / 2." },
                { id: "9ANO-MAT-M17", p: "Qual o valor da raiz cúbica de 27?", o: [{t:"3",c:true}, {t:"9",c:false}, {t:"81",c:false}, {t:"3√3",c:false}], pts: 3, exp: "Pois 3 x 3 x 3 = 27." },
                { id: "9ANO-MAT-M18", p: "Como se escreve o decimal 0,000072 em notação científica?", o: [{t:"7,2 x 10^-5",c:true}, {t:"7,2 x 10^-4",c:false}, {t:"72 x 10^-6",c:false}, {t:"0,72 x 10^-4",c:false}], pts: 3, exp: "Deslocando a vírgula 5 casas para a direita: 7,2 x 10^-5." },
                { id: "9ANO-MAT-M19", p: "Qual a altura de um triângulo equilátero de lado igual a 6 cm?", o: [{t:"3√3 cm",c:true}, {t:"6√3 cm",c:false}, {t:"3 cm",c:false}, {t:"9 cm",c:false}], pts: 3, exp: "Fórmula da altura h = (L√3)/2 = (6√3)/2 = 3√3 cm." },
                { id: "9ANO-MAT-M20", p: "Qual o volume de um cilindro reto de raio da base 2 cm e altura 5 cm? (Considere π = 3,14)", o: [{t:"62,8 cm³",c:true}, {t:"31,4 cm³",c:false}, {t:"20 cm³",c:false}], pts: 3, exp: "Volume = π r² h = 3,14 x 2² x 5 = 3,14 x 4 x 5 = 62,8 cm³." },

                // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-MAT-D01", p: "Quais são as quatro raízes reais da equação biquadrada x⁴ - 13x² + 36 = 0?", o: [{t:"±2 e ±3",c:true}, {t:"±4 e ±9",c:false}, {t:"2, 3, 4 e 9",c:false}, {t:"±1 e ±6",c:false}], pts: 4, exp: "Fazendo y = x² => y² - 13y + 36 = 0 => y=4 ou y=9. Como x = ±√y => x = ±2 e x = ±3." },
                { id: "9ANO-MAT-D02", p: "Qual o vértice (Xv, Yv) da parábola dada pela função quadrática y = x² - 6x + 5?", o: [{t:"(3, -4)",c:true}, {t:"(-3, 4)",c:false}, {t:"(6, 5)",c:false}, {t:"(3, 4)",c:false}], pts: 4, exp: "Xv = -b/(2a) = 6/2 = 3. Yv = f(3) = 3² - 6(3) + 5 = 9 - 18 + 5 = -4." },
                { id: "9ANO-MAT-D03", p: "Qual a área de um setor circular de raio 6 cm correspondente a um ângulo central de 60°? (Use π)", o: [{t:"6π cm²",c:true}, {t:"36π cm²",c:false}, {t:"12π cm²",c:false}, {t:"3π cm²",c:false}], pts: 4, exp: "Área do setor = (60°/360°) x π r² = (1/6) x π x 36 = 6π cm²." },
                { id: "9ANO-MAT-D04", p: "Em um triângulo retângulo, a hipotenusa mede 13 cm e um dos catetos mede 12 cm. Qual a medida do outro cateto?", o: [{t:"5 cm",c:true}, {t:"1 cm",c:false}, {t:"25 cm",c:false}, {t:"7 cm",c:false}], pts: 4, exp: "13² = 12² + c² => 169 = 144 + c² => c² = 25 => c = 5 cm." },
                { id: "9ANO-MAT-D05", p: "No sistema não linear { x + y = 7, x * y = 12 }, quais são os valores positivos do par (x, y)?", o: [{t:"(3, 4) ou (4, 3)",c:true}, {t:"(2, 5) ou (5, 2)",c:false}, {t:"(1, 6) ou (6, 1)",c:false}, {t:"(0, 7) ou (7, 0)",c:false}], pts: 4, exp: "Trata-se de encontrar dois números cuja soma é 7 e produto é 12, que são 3 e 4." },
                { id: "9ANO-MAT-D06", p: "A sombra de um prédio mede 12 m no mesmo instante em que a sombra de um bastão vertical de 2 m mede 1,5 m. Qual a altura do prédio?", o: [{t:"16 m",c:true}, {t:"18 m",c:false}, {t:"9 m",c:false}, {t:"24 m",c:false}], pts: 4, exp: "Semelhança de triângulos: H / 12 = 2 / 1,5 => 1,5 H = 24 => H = 16 m." },
                { id: "9ANO-MAT-D07", p: "Simplificando a expressão com radicais √18 + √50 - √8, obtém-se:", o: [{t:"6√2",c:true}, {t:"10√2",c:false}, {t:"4√2",c:false}, {t:"3√2",c:false}], pts: 4, exp: "3√2 + 5√2 - 2√2 = (3 + 5 - 2)√2 = 6√2." },
                { id: "9ANO-MAT-D08", p: "Sabendo que uma das raízes da equação x² - kx + 12 = 0 é igual a 3, qual o valor do coeficiente k?", o: [{t:"7",c:true}, {t:"4",c:false}, {t:"-7",c:false}, {t:"12",c:false}], pts: 4, exp: "Substituindo x = 3: 3² - 3k + 12 = 0 => 9 - 3k + 12 = 0 => 21 = 3k => k = 7." },
                { id: "9ANO-MAT-D09", p: "Qual o valor da tangente de um ângulo de 45°?", o: [{t:"1",c:true}, {t:"0",c:false}, {t:"√3",c:false}, {t:"√3/3",c:false}], pts: 4, exp: "tg(45°) = sen(45°)/cos(45°) = (√2/2) / (√2/2) = 1." },
                { id: "9ANO-MAT-D10", p: "Uma circunferência tem comprimento de 31,4 cm. Qual a medida do seu raio? (Considere π = 3,14)", o: [{t:"5 cm",c:true}, {t:"10 cm",c:false}, {t:"2,5 cm",c:false}, {t:"15,7 cm",c:false}], pts: 4, exp: "C = 2 π r => 31,4 = 2 x 3,14 x r => 31,4 = 6,28 r => r = 5 cm." },
                { id: "9ANO-MAT-D11", p: "Qual a probabilidade de se obter uma soma igual a 7 no lançamento simultâneo de dois dados não viciados?", o: [{t:"1/6",c:true}, {t:"1/36",c:false}, {t:"7/36",c:false}, {t:"1/12",c:false}], pts: 4, exp: "Pares favoráveis: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) -> 6 casos em 36 => 6/36 = 1/6." },
                { id: "9ANO-MAT-D12", p: "Fatorando completamente o trinômio 2x² + 8x + 8, encontramos:", o: [{t:"2(x + 2)²",c:true}, {t:"(2x + 4)²",c:false}, {t:"2(x - 2)²",c:false}, {t:"(x + 4)²",c:false}], pts: 4, exp: "Colocando 2 em evidência: 2(x² + 4x + 4) = 2(x + 2)²." },
                { id: "9ANO-MAT-D13", p: "Qual é o valor MÁXIMO assumido pela função quadrática f(x) = -x² + 4x - 3?", o: [{t:"1",c:true}, {t:"2",c:false}, {t:"3",c:false}, {t:"-3",c:false}], pts: 4, exp: "Yv = -Δ / (4a). Δ = 16 - 12 = 4. Yv = -4 / (4 * -1) = 1." },
                { id: "9ANO-MAT-D14", p: "Qual a distância entre os pontos A(1, 2) e B(4, 6) no plano cartesiano?", o: [{t:"5",c:true}, {t:"7",c:false}, {t:"√7",c:false}, {t:"25",c:false}], pts: 4, exp: "d = √[(4-1)² + (6-2)²] = √[3² + 4²] = √[9 + 16] = √25 = 5." },
                { id: "9ANO-MAT-D15", p: "Qual é a relação fundamental da trigonometria para qualquer ângulo x?", o: [{t:"sen²(x) + cos²(x) = 1",c:true}, {t:"sen(x) + cos(x) = 1",c:false}, {t:"tg(x) = sen(x) * cos(x)",c:false}, {t:"sen²(x) - cos²(x) = 1",c:false}], pts: 4, exp: "A identidade fundamental trigonométrica estabelece que sen²(x) + cos²(x) = 1." },
                { id: "9ANO-MAT-D16", p: "A soma dos ângulos internos de um polígono convexo é 1080°. Quantos lados tem esse polígono?", o: [{t:"8 lados (Octógono)",c:true}, {t:"6 lados (Hexágono)",c:false}, {t:"10 lados (Decágono)",c:false}, {t:"7 lados (Heptágono)",c:false}], pts: 4, exp: "S = (n - 2) x 180° => 1080 = (n - 2) x 180 => n - 2 = 6 => n = 8." },
                { id: "9ANO-MAT-D17", p: "Qual o volume de uma esfera de raio 3 cm? (Considere π = 3,14 e V = 4/3 π r³)", o: [{t:"113,04 cm³",c:true}, {t:"36 cm³",c:false}, {t:"314 cm³",c:false}, {t:"84,78 cm³",c:false}], pts: 4, exp: "V = (4/3) x 3,14 x 3³ = (4/3) x 3,14 x 27 = 4 x 3,14 x 9 = 113,04 cm³." },
                { id: "9ANO-MAT-D18", p: "Racionalizando a expressão 6 / (√3 + 1), obtém-se:", o: [{t:"3(√3 - 1)",c:true}, {t:"6(√3 - 1)",c:false}, {t:"3(√3 + 1)",c:false}, {t:"√3 - 1",c:false}], pts: 4, exp: "Multiplica por (√3 - 1): 6(√3 - 1) / (3 - 1) = 6(√3 - 1) / 2 = 3(√3 - 1)." },
                { id: "9ANO-MAT-D19", p: "Em um triângulo retângulo, sabendo que a tangente de um ângulo agudo x é 3/4, qual o valor de sen(x)?", o: [{t:"3/5",c:true}, {t:"4/5",c:false}, {t:"3/4",c:false}, {t:"5/3",c:false}], pts: 4, exp: "Cateto oposto = 3, adjacente = 4. Hipotenusa = √(3²+4²) = 5. Logo, sen(x) = 3/5." },
                { id: "9ANO-MAT-D20", p: "Um capital de R$ 1.000,00 aplicado a juros compostos de 10% ao ano durante 2 anos resulta em qual montante final?", o: [{t:"R$ 1.210,00",c:true}, {t:"R$ 1.200,00",c:false}, {t:"R$ 1.100,00",c:false}, {t:"R$ 1.300,00",c:false}], pts: 4, exp: "M = C(1 + i)^t = 1000 x (1,1)² = 1000 x 1,21 = R$ 1.210,00." }
        ],
        "Português": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-POR-F01", p: "Qual das opções apresenta uma oração coordenada assindética?", o: [{t:"Vim, vi, venci.",c:true}, {t:"Estudei, mas não passei.",c:false}, {t:"Ela canta e dança.",c:false}, {t:"Quer venha, quer fique.",c:false}], pts: 2, exp: "Orações assindéticas são ligadas sem o uso de conjunções." },
                { id: "9ANO-POR-F02", p: "Identifique a oração subordinada substantiva em: 'É necessário que você venha.'", o: [{t:"que você venha",c:true}, {t:"É necessário",c:false}, {t:"você venha",c:false}, {t:"necessário que",c:false}], pts: 2, exp: "'que você venha' é uma oração subordinada substantiva subjetiva." },
                { id: "9ANO-POR-F03", p: "A pontuação adequada para isolar um aposto explicativo em uma frase é:", o: [{t:"Vírgula",c:true}, {t:"Ponto e vírgula",c:false}, {t:"Ponto final",c:false}, {t:"Interrogação",c:false}], pts: 2, exp: "O aposto explicativo vem isolado por vírgulas (ou travessões/parênteses)." },
                { id: "9ANO-POR-F04", p: "Qual figura de linguagem consiste na aproximação de palavras de sentidos opostos, como 'dia e noite'?", o: [{t:"Antítese",c:true}, {t:"Metáfora",c:false}, {t:"Hipérbole",c:false}, {t:"Eufemismo",c:false}], pts: 2, exp: "Antítese é a aproximação de termos de sentidos contrários." },
                { id: "9ANO-POR-F05", p: "A oração sublinhada em 'O aluno que estuda aprende' é subordinada adjetiva:", o: [{t:"Restritiva",c:true}, {t:"Explicativa",c:false}, {t:"Adverbial",c:false}, {t:"Substantiva",c:false}], pts: 2, exp: "Não está separada por vírgulas e restringe o sentido do substantivo 'aluno'." },
                { id: "9ANO-POR-F06", p: "Qual das frases abaixo apresenta sujeito indeterminado?", o: [{t:"Precisa-se de funcionários.",c:true}, {t:"Choveu muito ontem.",c:false}, {t:"O menino correu rápido.",c:false}, {t:"Fomos ao cinema juntos.",c:false}], pts: 2, exp: "Verbo transitivo indireto + 'se' (índice de indeterminação do sujeito)." },
                { id: "9ANO-POR-F07", p: "Qual das conjunções abaixo é classificativa de oposição (adversativa)?", o: [{t:"Porém",c:true}, {t:"Portanto",c:false}, {t:"Porque",c:false}, {t:"E",c:false}], pts: 2, exp: "'Porém' introduz uma oração coordenada adversativa." },
                { id: "9ANO-POR-F08", p: "A frase 'O livro foi lido pelo estudante' está na voz:", o: [{t:"Passiva analítica",c:true}, {t:"Ativa",c:false}, {t:"Reflexiva",c:false}, {t:"Passiva sintética",c:false}], pts: 2, exp: "Apresenta verbo auxiliar (foi) + particípio (lido) e agente da passiva (pelo estudante)." },
                { id: "9ANO-POR-F09", p: "O pronome relativo 'onde' deve ser utilizado exclusivamente para se referir a:", o: [{t:"Lugares físicos estáticos",c:true}, {t:"Pessoas",c:false}, {t:"Momentos no tempo",c:false}, {t:"Acontecimentos",c:false}], pts: 2, exp: "Na norma culta, 'onde' só retoma termos que indicam lugar físico." },
                { id: "9ANO-POR-F10", p: "O termo que serve para chamar ou interpelar o interlocutor na frase é o:", o: [{t:"Vocativo",c:true}, {t:"Aposto",c:false}, {t:"Sujeito",c:false}, {t:"Predicativo",c:false}], pts: 2, exp: "O vocativo é um termo independente usado para chamar o ouvinte." },
                { id: "9ANO-POR-F11", p: "O sentido literal, objetivo e dicionarizado de uma palavra é chamado de:", o: [{t:"Denotação",c:true}, {t:"Conotação",c:false}, {t:"Figurado",c:false}, {t:"Subjetivo",c:false}], pts: 2, exp: "Denotação é o uso real/literal da linguagem." },
                { id: "9ANO-POR-F12", p: "O sentido figurado, poético e subjetivo de uma palavra é chamado de:", o: [{t:"Conotação",c:true}, {t:"Denotação",c:false}, {t:"Dicionarizado",c:false}, {t:"Objetivo",c:false}], pts: 2, exp: "Conotação é o sentido figurado atribuído no contexto." },
                { id: "9ANO-POR-F13", p: "Qual conectivo introduz uma oração coordenada explicativa?", o: [{t:"Pois (antes do verbo)",c:true}, {t:"Embora",c:false}, {t:"Contudo",c:false}, {t:"Portanto",c:false}], pts: 2, exp: "'Pois' antes do verbo funciona como conjunção explicativa." },
                { id: "9ANO-POR-F14", p: "Qual das opções apresenta um sinônimo para a palavra 'efêmero'?", o: [{t:"Passageiro",c:true}, {t:"Eterno",c:false}, {t:"Duradouro",c:false}, {t:"Firme",c:false}], pts: 2, exp: "Efêmero significa algo de curta duração, passageiro." },
                { id: "9ANO-POR-F15", p: "O pronome que introduz orações subordinadas adjetivas é o pronome:", o: [{t:"Relativo",c:true}, {t:"Demonstrativo",c:false}, {t:"Indefinido",c:false}, {t:"Pessoal",c:false}], pts: 2, exp: "Pronomes relativos (que, quem, cujo, onde) introduzem orações adjetivas." },
                { id: "9ANO-POR-F16", p: "Um predicado cujo núcleo é um verbo de ação é classificado como:", o: [{t:"Predicado verbal",c:true}, {t:"Predicado nominal",c:false}, {t:"Predicado verbo-nominal",c:false}, {t:"Predicado indireto",c:false}], pts: 2, exp: "Predicado verbal possui verbo nocional/significativo de ação." },
                { id: "9ANO-POR-F17", p: "A relação de dependência entre um nome (substantivo, adjetivo, advérbio) e seus termos regidos é a:", o: [{t:"Regência nominal",c:true}, {t:"Regência verbal",c:false}, {t:"Concordância verbal",c:false}, {t:"Concordância nominal",c:false}], pts: 2, exp: "Regência nominal estuda as preposições exigidas por nomes." },
                { id: "9ANO-POR-F18", p: "O fenômeno do encontro da preposição 'a' com o artigo feminino 'a' resulta na:", o: [{t:"Crase",c:true}, {t:"Apostrofação",c:false}, {t:"Aglutinação",c:false}, {t:"Sinalefa",c:false}], pts: 2, exp: "A fusão de duas vogais 'a' idênticas indica-se com o acento grave (crase)." },
                { id: "9ANO-POR-F19", p: "O gênero textual narrativo curto que aborda acontecimentos simples do dia a dia é a:", o: [{t:"Crônica",c:true}, {t:"Tese acadêmica",c:false}, {t:"Romance épico",c:false}, {t:"Edital",c:false}], pts: 2, exp: "A crônica inspira-se no cotidiano com tom leve ou reflexivo." },
                { id: "9ANO-POR-F20", p: "O termo que realiza a ação verbal na voz passiva analítica é o:", o: [{t:"Agente da passiva",c:true}, {t:"Objeto direto",c:false}, {t:"Sujeito indeterminado",c:false}, {t:"Complemento nominal",c:false}], pts: 2, exp: "O agente da passiva indica quem pratica a ação recebida pelo sujeito." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "9ANO-POR-M01", p: "Em 'Desejo que você vença', a oração sublinhada é subordinada substantiva:", o: [{t:"Objetiva direta",c:true}, {t:"Subjetiva",c:false}, {t:"Completiva nominal",c:false}, {t:"Predicativa",c:false}], pts: 3, exp: "Funciona como objeto direto do verbo 'Desejo' (Desejo ISSO)." },
                { id: "9ANO-POR-M02", p: "Em 'Tenho certeza de que seremos aprovados', a oração sublinhada funciona como:", o: [{t:"Completiva nominal",c:true}, {t:"Objetiva indireta",c:false}, {t:"Apositiva",c:false}, {t:"Subjetiva",c:false}], pts: 3, exp: "Completa o sentido do substantivo abstrato 'certeza' com preposição." },
                { id: "9ANO-POR-M03", p: "A oração 'O homem, que é um ser racional, pensa' é subordinada adjetiva:", o: [{t:"Explicativa",c:true}, {t:"Restritiva",c:false}, {t:"Adverbial",c:false}, {t:"Substantiva",c:false}], pts: 3, exp: "Vem isolada por vírgulas e atribui uma explicação geral ao termo antecedente." },
                { id: "9ANO-POR-M04", p: "Em 'Embora chovesse, fomos ao parque', a conjunção 'Embora' introduz ideia de:", o: [{t:"Concessão",c:true}, {t:"Condição",c:false}, {t:"Causa",c:false}, {t:"Consequência",c:false}], pts: 3, exp: "Concessão expressa um fato contrário que não impede a ação principal." },
                { id: "9ANO-POR-M05", p: "Qual a regência correta do verbo 'assistir' no sentido de 'presenciar/ver' segundo a norma culta?", o: [{t:"Exige preposição 'a' (Assistimos ao filme)",c:true}, {t:"Não exige preposição (Assistimos o filme)",c:false}, {t:"Exige preposição 'de' (Assistimos do filme)",c:false}, {t:"Exige preposição 'em' (Assistimos em filme)",c:false}], pts: 3, exp: "Assistir no sentido de ver é transitivo indireto e exige preposição 'a'." },
                { id: "9ANO-POR-M06", p: "Assinale a opção em que a próclise é OBRIGATÓRIA devido à palavra atrativa:", o: [{t:"Não me disseram a verdade.",c:true}, {t:"Disseram-me a verdade.",c:false}, {t:"Dir-me-ão a verdade.",c:false}, {t:"Ele disse me tudo.",c:false}], pts: 3, exp: "Palavras de sentido negativo ('Não') atraem obrigatoriamente o pronome oblíquo." },
                { id: "9ANO-POR-M07", p: "Qual expressão exige o uso do sinal indicativo de crase?", o: [{t:"À medida que o tempo passa",c:true}, {t:"A medida que foi tomada",c:false}, {t:"Ele foi a pé",c:false}, {t:"Entregou a ela",c:false}], pts: 3, exp: "'À medida que' é uma locução conjuntiva proporcional feminina." },
                { id: "9ANO-POR-M08", p: "Em relação à concordância com sujeito composto posposto ao verbo, assinale a opção CORRETA:", o: [{t:"Chegou o professor e os alunos. / Chegaram o professor e os alunos.",c:true}, {t:"Apenas: Chegaram o professor e os alunos.",c:false}, {t:"Apenas: Chegou o professor e os alunos.",c:false}, {t:"Chegaram o professor e o aluno.",c:false}], pts: 3, exp: "Verbo antes do sujeito composto pode concordar com o núcleo mais próximo ou ir ao plural." },
                { id: "9ANO-POR-M09", p: "A colocação pronominal em 'Dir-lhe-ei toda a verdade' é um exemplo de:", o: [{t:"Mesóclise",c:true}, {t:"Próclise",c:false}, {t:"Ênclise",c:false}, {t:"Neologismo",c:false}], pts: 3, exp: "Mesóclise ocorre quando o pronome é intercalado no meio do verbo no futuro." },
                { id: "9ANO-POR-M10", p: "Em 'Ele gritou tanto que ficou rouco', a oração sublinhada expressa ideia de:", o: [{t:"Consequência",c:true}, {t:"Causa",c:false}, {t:"Comparação",c:false}, {t:"Finalidade",c:false}], pts: 3, exp: "'tanto... que' introduz oração subordinada adverbial consecutiva." },
                { id: "9ANO-POR-M11", p: "A figura de linguagem que consiste no exagero intencional de uma ideia é a:", o: [{t:"Hipérbole",c:true}, {t:"Metonímia",c:false}, {t:"Ironia",c:false}, {t:"Prosopopeia",c:false}], pts: 3, exp: "Hipérbole é a expressão exagerada para dar ênfase (ex: morri de rir)." },
                { id: "9ANO-POR-M12", p: "A oração 'Meu desejo é este: que tenhamos paz' é subordinada substantiva:", o: [{t:"Apositiva",c:true}, {t:"Predicativa",c:false}, {t:"Subjetiva",c:false}, {t:"Objetiva direta",c:false}], pts: 3, exp: "Funciona como aposto esclarecendo o termo antecedente após dois-pontos." },
                { id: "9ANO-POR-M13", p: "Na frase 'Comprei livro e caneta novos', o adjetivo 'novos' concorda com:", o: [{t:"Ambos os substantivos, indo para o masculino plural",c:true}, {t:"Apenas o último substantivo no feminino",c:false}, {t:"Apenas o primeiro substantivo",c:false}, {t:"Permanece no singular invariável",c:false}], pts: 3, exp: "Adjetivo pós-posto a substantivos de gêneros diferentes pode ir ao masculino plural." },
                { id: "9ANO-POR-M14", p: "O termo 'à pátria' em 'Amor à pátria' exerce a função sintática de:", o: [{t:"Complemento nominal",c:true}, {t:"Adjunto adnominal",c:false}, {t:"Objeto indireto",c:false}, {t:"Agente da passiva",c:false}], pts: 3, exp: "Completa o sentido do substantivo abstrato 'amor' exigindo preposição." },
                { id: "9ANO-POR-M15", p: "A coesão textual feita por pronomes que retomam termos já ditos é chamada de coesão:", o: [{t:"Anafórica",c:true}, {t:"Catafórica",c:false}, {t:"Sequencial",c:false}, {t:"Ellíptica",c:false}], pts: 3, exp: "Anáfora retoma um elemento citado anteriormente no texto." },
                { id: "9ANO-POR-M16", p: "Segundo a norma culta, a regência correta do verbo 'preferir' é:", o: [{t:"Prefiro futebol a basquete",c:true}, {t:"Prefiro mais futebol do que basquete",c:false}, {t:"Prefiro futebol do que basquete",c:false}, {t:"Prefiro mil vezes futebol a basquete",c:false}], pts: 3, exp: "'Preferir' rege dois objetos: prefere-se algo (OD) A outro algo (OI)." },
                { id: "9ANO-POR-M17", p: "Em 'Se você estudar, passará na prova', a oração sublinhada expressa:", o: [{t:"Condição",c:true}, {t:"Concessão",c:false}, {t:"Tempo",c:false}, {t:"Causa",c:false}], pts: 3, exp: "'Se' introduz uma oração subordinada adverbial condicional." },
                { id: "9ANO-POR-M18", p: "A repetição desnecessária e redundante de um termo com a mesma ideia é um pleonasmo:", o: [{t:"Vicioso",c:true}, {t:"Literário",c:false}, {t:"Sintático",c:false}, {t:"Estilístico",c:false}], pts: 3, exp: "Pleonasmo vicioso é um vício de linguagem desnecessário (ex: subir para cima)." },
                { id: "9ANO-POR-M19", p: "Os travessões podem ser utilizados em um texto para:", o: [{t:"Isolar explicações ou comentários intercalados",c:true}, {t:"Indicar fim de frase declarativa",c:false}, {t:"Substituir a interrogação",c:false}, {t:"Separar sujeito do verbo",c:false}], pts: 3, exp: "Par de travessões cumpre papel semelhante aos parênteses ou vírgulas explicativas." },
                { id: "9ANO-POR-M20", p: "A frase 'Vendem-se casas' apresenta o pronome 'se' como:", o: [{t:"Partícula apassivadora",c:true}, {t:"Índice de indeterminação do sujeito",c:false}, {t:"Pronome reflexivo",c:false}, {t:"Conjunção condicional",c:false}], pts: 3, exp: "Verbo transitivo direto no plural + 'se' apassiva o sujeito paciente 'casas'." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-POR-D01", p: "Qual a classificação correta da oração reduzida sublinhada em 'Terminando o treino, fomos para casa'?", o: [{t:"Subordinada adverbial temporal reduzida de gerúndio",c:true}, {t:"Subordinada substantiva subjetiva reduzida de infinitivo",c:false}, {t:"Subordinada adjetiva reduzida de particípio",c:false}, {t:"Subordinada adverbial concessiva reduzida de gerúndio",c:false}], pts: 4, exp: "Equivale a 'Assim que terminamos o treino' (tempo), com verbo no gerúndio." },
                { id: "9ANO-POR-D02", p: "A oração reduzida sublinhada em 'É fundamental praticar atividades físicas' classifica-se como:", o: [{t:"Subordinada substantiva subjetiva reduzida de infinitivo",c:true}, {t:"Subordinada substantiva objetiva direta reduzida de infinitivo",c:false}, {t:"Subordinada adjetiva restritiva",c:false}, {t:"Subordinada adverbial final",c:false}], pts: 4, exp: "Equivale a 'que se pratiquem atividades' (sujeito da oração principal 'É fundamental')." },
                { id: "9ANO-POR-D03", p: "Assinale a opção em que o termo preposicionado é um ADJUNTO ADNOMINAL e não um complemento nominal:", o: [{t:"A resposta do aluno foi convincente.",c:true}, {t:"A resposta ao aluno foi rápida.",c:false}, {t:"A construção do prédio demorou.",c:false}, {t:"O amor à pátria é nobre.",c:false}], pts: 4, exp: "'Do aluno' é agente da resposta (o aluno respondeu), logo funciona como adjunto adnominal." },
                { id: "9ANO-POR-D04", p: "Na oração 'Minha esperança é que todos sejam aprovados', a oração subordinada é:", o: [{t:"Substantiva predicativa",c:true}, {t:"Substantiva subjetiva",c:false}, {t:"Substantiva objetiva direta",c:false}, {t:"Substantiva completiva nominal",c:false}], pts: 4, exp: "Funciona como predicativo do sujeito 'Minha esperança' por meio do verbo de ligação 'é'." },
                { id: "9ANO-POR-D05", p: "Qual frase apresenta a regência do verbo 'aspirar' inteiramente CORRETA de acordo com a norma culta?", o: [{t:"Aspirava ao cargo de gerente com todas as forças.",c:true}, {t:"Aspirava o cargo de gerente com todas as forças.",c:false}, {t:"Aspirava do cargo de gerente com todas as forças.",c:false}, {t:"Aspirava pelo cargo de gerente com todas as forças.",c:false}], pts: 4, exp: "'Aspirar' no sentido de desejar/almejar exige preposição 'a' (transitivo indireto)." },
                { id: "9ANO-POR-D06", p: "Qual das opções apresenta a concordância do verbo 'haver' CORRETA segundo a norma-padrão?", o: [{t:"Havia muitos problemas a resolver.",c:true}, {t:"Haviam muitos problemas a resolver.",c:false}, {t:"Houveram muitos problemas a resolver.",c:false}, {t:"Hão de haver muitos problemas a resolver.",c:false}], pts: 4, exp: "O verbo 'haver' no sentido de existir é impessoal e deve permanecer no singular." },
                { id: "9ANO-POR-D07", p: "Marque a alternativa com desvio na colocação pronominal segundo a norma culta:", o: [{t:"Me empresta o livro agora?",c:true}, {t:"Empresta-me o livro agora.",c:false}, {t:"Não me empreste o livro.",c:false}, {t:"Espero que me empreste o livro.",c:false}], pts: 4, exp: "Não se deve iniciar frases com pronome oblíquo átono na norma culta." },
                { id: "9ANO-POR-D08", p: "A frase 'O pai conversou com o filho em seu quarto' apresenta o seguinte problema de construção:", o: [{t:"Ambiguidade estrutural",c:true}, {t:"Pleonasmo vicioso",c:false}, {t:"Eco fonético",c:false}, {t:"Anacoluto",c:false}], pts: 4, exp: "O pronome 'seu' gera dúvida sobre de quem é o quarto (se do pai ou do filho)." },
                { id: "9ANO-POR-D09", p: "Em 'À proporção que estudava, aprendia mais', a oração sublinhada é adverbial:", o: [{t:"Proporcional",c:true}, {t:"Comparativa",c:false}, {t:"Consecutiva",c:false}, {t:"Causal",c:false}], pts: 4, exp: "'À proporção que' é uma locução conjuntiva proporcional." },
                { id: "9ANO-POR-D10", p: "Em 'Precisa-se de técnicos especializados', o termo 'de técnicos especializados' funciona como:", o: [{t:"Objeto indireto",c:true}, {t:"Sujeito paciente",c:false}, {t:"Agente da passiva",c:false}, {t:"Adjunto adnominal",c:false}], pts: 4, exp: "O verbo é VTI, o 'se' é índice de indeterminação e o termo preposicionado é objeto indireto." },
                { id: "9ANO-POR-D11", p: "Em 'Ele bebeu dois copos de leite', ocorre a figura de linguagem metonímia por substituição do:", o: [{t:"Continente pelo conteúdo",c:true}, {t:"Parte pelo todo",c:false}, {t:"Efeito pela causa",c:false}, {t:"Autor pela obra",c:false}], pts: 4, exp: "Bebeu-se o leite (conteúdo) que estava dentro dos copos (continente)." },
                { id: "9ANO-POR-D12", p: "A quebra da estrutura sintática em 'Eu, que era um jovem sonhador, a vida me ensinou tudo' caracteriza a figura:", o: [{t:"Anacoluto",c:true}, {t:"Sepsia",c:false}, {t:"Hipérbato",c:false}, {t:"Elipse",c:false}], pts: 4, exp: "Anacoluto é a interrupção da sequência sintática deixando um termo sem função direta." },
                { id: "9ANO-POR-D13", p: "Assinale a opção em que a regência do verbo 'esquecer' está CORRETA:", o: [{t:"Ele se esqueceu do compromisso.",c:true}, {t:"Ele esqueceu do compromisso.",c:false}, {t:"Ele se esqueceu o compromisso.",c:false}, {t:"Ele esqueceu-se o compromisso.",c:false}], pts: 4, exp: "Quando pronominal ('esquecer-se'), o verbo exige a preposição 'de'." },
                { id: "9ANO-POR-D14", p: "Assinale a opção em que a concordância nominal está incorreta:", o: [{t:"Ela estava meia nervosa no exame.",c:true}, {t:"Seguem anexos os relatórios.",c:false}, {t:"A porta estava meio aberta.",c:false}, {t:"Elas mesmas fizeram o trabalho.",c:false}], pts: 4, exp: "'Meio' com sentido de 'um pouco' é advérbio e deve permanecer invariável (meio nervosa)." },
                { id: "9ANO-POR-D15", p: "A falta de equivalência nas estruturas coordenadas em 'Ele gosta de nadar e de caminhadas' fere a regra de:", o: [{t:"Paralelismo sintático",c:true}, {t:"Concordância nominal",c:false}, {t:"Colocação pronominal",c:false}, {t:"Regência nominal",c:false}], pts: 4, exp: "O correto para manter o paralelismo seria 'de nadar e de caminhar' (dois verbos)." },
                { id: "9ANO-POR-D16", p: "Na oração 'O filme a que assisti foi premiado', o pronome relativo 'que' vem precedido da preposição 'a' porque:", o: [{t:"O verbo 'assistir' exige a preposição 'a'",c:true}, {t:"O substantivo 'filme' exige preposição",c:false}, {t:"A regência do verbo 'premiar' é indireta",c:false}, {t:"É uma exigência opcional da crase",c:false}], pts: 4, exp: "A regência do verbo 'assistir' (ver) exige preposição 'a', que deve anteceder o pronome relativo." },
                { id: "9ANO-POR-D17", p: "Na frase 'Ele prefere café; eu, chá', a omissão do verbo 'prefiro' na segunda oração é uma figura de sintaxe chamada:", o: [{t:"Zeugma",c:true}, {t:"Pleonasmo",c:false}, {t:"Anacoluto",c:false}, {t:"Hipérbole",c:false}], pts: 4, exp: "Zeugma é a omissão de um termo previamente mencionado no texto." },
                { id: "9ANO-POR-D18", p: "Em 'Ele correu como um atleta profissional corre', a oração sublinhada é subordinada adverbial:", o: [{t:"Comparativa",c:true}, {t:"Conformativa",c:false}, {t:"Causal",c:false}, {t:"Moda",c:false}], pts: 4, exp: "Estabelece uma comparação explícita de ação." },
                { id: "9ANO-POR-D19", p: "A utilização das vírgulas na frase 'O diretor, disse o secretário, chegará em breve' serve para:", o: [{t:"Isolar uma oração intercalada ou explicativa",c:true}, {t:"Separar o sujeito do predicado",c:false}, {t:"Isolar o aposto especificativo",c:false}, {t:"Marcar a voz passiva",c:false}], pts: 4, exp: "Orações intercaladas devem ser obrigatoriamente isoladas por vírgulas." },
                { id: "9ANO-POR-D20", p: "O vocábulo 'que' funciona como conjunção integrante em qual das frases abaixo?", o: [{t:"Sei que você conseguirá.",c:true}, {t:"O livro que li é excelente.",c:false}, {t:"Que dia lindo!",c:false}, {t:"Teve que estudar muito.",c:false}], pts: 4, exp: "Introduz a oração subordinada substantiva objetiva direta ('Sei ISSO')." }
        ],
        "História": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-HIS-F01", p: "A Proclamação da República no Brasil ocorreu no ano de:", o: [{t:"1889",c:true}, {t:"1822",c:false}, {t:"1500",c:false}, {t:"1930",c:false}], pts: 2, exp: "Em 15 de novembro de 1889, Marechal Deodoro proclamou a República no Brasil." },
                { id: "9ANO-HIS-F02", p: "A Primeira Guerra Mundial ocorreu no intervalo de anos entre:", o: [{t:"1914 e 1918",c:true}, {t:"1939 e 1945",c:false}, {t:"1917 e 1922",c:false}, {t:"1900 e 1910",c:false}], pts: 2, exp: "O primeiro conflito mundial estendeu-se de 1914 a 1918." },
                { id: "9ANO-HIS-F03", p: "O estopim para o início da Primeira Guerra Mundial foi o assassinato de:", o: [{t:"Francisco Ferdinando",c:true}, {t:"Adolf Hitler",c:false}, {t:"Winston Churchill",c:false}, {t:"Tzar Nicolau II",c:false}], pts: 2, exp: "O assassinato do arquiduque Francisco Ferdinando em Sarajevo deu início à guerra." },
                { id: "9ANO-HIS-F04", p: "A Revolução Russa de 1917 resultou na implantação do primeiro estado baseado no regime:", o: [{t:"Socialista",c:true}, {t:"Capitalista",c:false}, {t:"Anarquista",c:false}, {t:"Monárquico",c:false}], pts: 2, exp: "Liderada pelos bolcheviques, a Revolução Russa criou um estado socialista." },
                { id: "9ANO-HIS-F05", p: "A grande crise econômica mundial ocorrida em 1929 teve início com a quebra da Bolsa de Valores de:", o: [{t:"Nova York",c:true}, {t:"Londres",c:false}, {t:"Tóquio",c:false}, {t:"Paris",c:false}], pts: 2, exp: "A superprodução e especulação levaram ao colapso de Wall Street em Nova York." },
                { id: "9ANO-HIS-F06", p: "A Era Vargas teve início no Brasil a partir da Revolução de:", o: [{t:"1930",c:true}, {t:"1922",c:false}, {t:"1964",c:false}, {t:"1889",c:false}], pts: 2, exp: "Getúlio Vargas assumiu o poder após a Revolução de 1930." },
                { id: "9ANO-HIS-F07", p: "A Segunda Guerra Mundial transcorreu entre os anos de:", o: [{t:"1939 e 1945",c:true}, {t:"1914 e 1918",c:false}, {t:"1950 e 1953",c:false}, {t:"1964 e 1985",c:false}], pts: 2, exp: "A Segunda Guerra iniciou com a invasão da Polônia em 1939 e terminou em 1945." },
                { id: "9ANO-HIS-F08", p: "Qual evento motivou a entrada direta dos Estados Unidos na Segunda Guerra Mundial em 1941?", o: [{t:"Ataque japonês a Pearl Harbor",c:true}, {t:"Bomba atômica sobre Hiroshima",c:false}, {t:"Invasão da França",c:false}, {t:"Batalha de Stalingrado",c:false}], pts: 2, exp: "O ataque surpresa japonês à base naval de Pearl Harbor levou os EUA à guerra." },
                { id: "9ANO-HIS-F09", p: "A disputa ideológica, econômica e militar indireta entre EUA e URSS após a 2ª Guerra foi a:", o: [{t:"Guerra Fria",c:true}, {t:"Guerra dos Cem Anos",c:false}, {t:"Guerra de Secessão",c:false}, {t:"Guerra do Golfo",c:false}], pts: 2, exp: "A Guerra Fria dividiu o mundo entre o bloco capitalista (EUA) e socialista (URSS)." },
                { id: "9ANO-HIS-F10", p: "O símbolo físico da divisão do mundo na Guerra Fria que caiu em 1989 foi o:", o: [{t:"Muro de Berlim",c:true}, {t:"Muro das Lamentações",c:false}, {t:"Muralha da China",c:false}, {t:"Muro de Varsóvia",c:false}], pts: 2, exp: "A queda do Muro de Berlim simbolizou o colapso do bloco socialista europeu." },
                { id: "9ANO-HIS-F11", p: "O regime ditatorial militar no Brasil teve seu início com o golpe de estado de:", o: [{t:"1964",c:true}, {t:"1930",c:false}, {t:"1985",c:false}, {t:"1937",c:false}], pts: 2, exp: "Em 31 de março de 1964, os militares depuseram o presidente João Goulart." },
                { id: "9ANO-HIS-F12", p: "O presidente brasileiro responsável pelo plano desenvolvimentista e pela construção de Brasília foi:", o: [{t:"Juscelino Kubitschek",c:true}, {t:"Getúlio Vargas",c:false}, {t:"Jânio Quadros",c:false}, {t:"Eurico Gaspar Dutra",c:false}], pts: 2, exp: "JK inaugurou a nova capital, Brasília, no DF em 1960." },
                { id: "9ANO-HIS-F13", p: "O grande movimento popular brasileiro (1983-1984) que reivindicava eleições diretas para presidente foi o:", o: [{t:"Diretas Já",c:true}, {t:"Caras-Pintadas",c:false}, {t:"Passe Livre",c:false}, {t:"Marcha da Família",c:false}], pts: 2, exp: "A campanha 'Diretas Já' mobilizou milhões pelo voto direto na redemocratização." },
                { id: "9ANO-HIS-F14", p: "A atual Constituição brasileira, apelidada de 'Constituição Cidadã', foi promulgada em:", o: [{t:"1988",c:true}, {t:"1934",c:false}, {t:"1967",c:false}, {t:"1824",c:false}], pts: 2, exp: "Elaborada após o fim da ditadura militar, foi promulgada em 5 de outubro de 1988." },
                { id: "9ANO-HIS-F15", p: "O genocídio sistemático de 6 milhões de judeus promovido pelo nazismo durante a Segunda Guerra é o:", o: [{t:"Holocausto",c:true}, {t:"Apartheid",c:false}, {t:"Gulag",c:false}, {t:"Pogrom",c:false}], pts: 2, exp: "O Holocausto foi o assassinato em massa promovido pelo regime nazista." },
                { id: "9ANO-HIS-F16", p: "A 'Política do Café com Leite' na Primeira República brasileira envolvia a alternância de poder entre:", o: [{t:"São Paulo e Minas Gerais",c:true}, {t:"Rio de Janeiro e Bahia",c:false}, {t:"Rio Grande do Sul e Ceará",c:false}, {t:"Pernambuco e São Paulo",c:false}], pts: 2, exp: "São Paulo (produtor de café) e Minas Gerais (produtor de leite/café) alternavam presidentes." },
                { id: "9ANO-HIS-F17", p: "O regime político de caráter autoritário e ultranacionalista surgido na Itália sob comando de Benito Mussolini foi o:", o: [{t:"Fascismo",c:true}, {t:"Comunismo",c:false}, {t:"Anarquismo",c:false}, {t:"Liberalismo",c:false}], pts: 2, exp: "Mussolini fundou o fascismo na Itália nos anos 1920." },
                { id: "9ANO-HIS-F18", p: "O líder do Partido Nazista na Alemanha que assumiu o poder como Chanceler e Führer foi:", o: [{t:"Adolf Hitler",c:true}, {t:"Joseph Stalin",c:false}, {t:"Francisco Franco",c:false}, {t:"Otto von Bismarck",c:false}], pts: 2, exp: "Hitler estabeleceu a ditadura nazista do Terceiro Reich na Alemanha." },
                { id: "9ANO-HIS-F19", p: "O colapso oficial e a dissolução da União Soviética (URSS) ocorreram no ano de:", o: [{t:"1991",c:true}, {t:"1989",c:false}, {t:"1945",c:false}, {t:"2000",c:false}], pts: 2, exp: "Em dezembro de 1991, a URSS foi oficialmente extinta." },
                { id: "9ANO-HIS-F20", p: "A Revolta da Vacina (1904) ocorreu na cidade do Rio de Janeiro devido à vacinação obrigatória contra:", o: [{t:"Varíola",c:true}, {t:"Peste negra",c:false}, {t:"Febre amarela",c:false}, {t:"Gripe espanhola",c:false}], pts: 2, exp: "A campanha sanitarista de Oswaldo Cruz contra a varíola gerou revolta popular." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "9ANO-HIS-M01", p: "O sistema de dominação política local na República Velha baseado na troca de favores e fraude eleitoral era o:", o: [{t:"Coronelismo",c:true}, {t:"Feudalismo",c:false}, {t:"Absolutismo",c:false}, {t:"Anarquismo",c:false}], pts: 3, exp: "Os 'coronéis' controlavam o voto de cabresto da população rural." },
                { id: "9ANO-HIS-M02", p: "O Tratado de Versalhes (1919), assinado ao fim da 1ª Guerra Mundial, impôs severas punições à:", o: [{t:"Alemanha",c:true}, {t:"Inglaterra",c:false}, {t:"França",c:false}, {t:"Rússia",c:false}], pts: 3, exp: "A Alemanha foi considerada culpada pela guerra, perdendo territórios e pagando reparações." },
                { id: "9ANO-HIS-M03", p: "O programa de recuperação econômica norte-americano 'New Deal', criado por Franklin Roosevelt, baseava-se em:", o: [{t:"Intervenção do Estado na economia para gerar empregos e obras públicas",c:true}, {t:"Livre mercado total sem interferência estatal",c:false}, {t:"Privatização de todas as indústrias nacionais",c:false}, {t:"Abolição da moeda de papel",c:false}], pts: 3, exp: "O New Deal utilizou a intervenção estatal para combater a crise de 1929." },
                { id: "9ANO-HIS-M04", p: "A fase ditatorial da Era Vargas (1937-1945), iniciada com a outorga da Constituição de 1937, ficou conhecida como:", o: [{t:"Estado Novo",c:true}, {t:"Governo Provisório",c:false}, {t:"Governo Constitucional",c:false}, {t:"República de Caudilhos",c:false}], pts: 3, exp: "O Estado Novo foi marcado pela censura (DIP), centralização e fechamento do Congresso." },
                { id: "9ANO-HIS-M05", p: "A Consolidação das Leis do Trabalho (CLT), um marco dos direitos trabalhistas no Brasil, foi promulgada em 1943 por:", o: [{t:"Getúlio Vargas",c:true}, {t:"Juscelino Kubitschek",c:false}, {t:"Jânio Quadros",c:false}, {t:"Eurico Gaspar Dutra",c:false}], pts: 3, exp: "Vargas regulamentou o salário mínimo, carteira de trabalho e férias remuneradas." },
                { id: "9ANO-HIS-M06", p: "A Guerra da Coreia (1950-1953) resultou na divisão permanente da península no paralelo 38° em:", o: [{t:"Coreia do Norte (comunista) e Coreia do Sul (capitalista)",c:true}, {t:"Coreia do Leste e Coreia do Oeste",c:false}, {t:"Uma única nação unificada",c:false}, {t:"Anexação total pela China",c:false}], pts: 3, exp: "A guerra consolidou a divisão ideológica entre o norte socialista e o sul capitalista." },
                { id: "9ANO-HIS-M07", p: "O decreto autoritário mais duro emitido durante a ditadura militar brasileira em 1968 foi o:", o: [{t:"Ato Institucional Nº 5 (AI-5)",c:true}, {t:"Ato Institucional Nº 1 (AI-1)",c:false}, {t:"Código Civil",c:false}, {t:"Manifesto aos Brasileiros",c:false}], pts: 3, exp: "O AI-5 fechou o Congresso, cassou mandatos e suspendeu o habeas corpus." },
                { id: "9ANO-HIS-M08", p: "A Revolta da Chibata (1910), ocorrida nos navios da Marinha no Rio de Janeiro, foi liderada por João Cândido para protestar contra:", o: [{t:"Os castigos físicos (chibatadas) e maus tratos dados aos marinheiros negros e pobres",c:true}, {t:"A vacinação obrigatória no país",c:false}, {t:"A entrada do Brasil na 1ª Guerra",c:false}, {t:"O fim da monarquia",c:false}], pts: 3, exp: "Os marinheiros rebelaram-se contra os chicotagems e a alimentação precária." },
                { id: "9ANO-HIS-M09", p: "A Crise dos Mísseis em Cuba (1962) foi um momento crítico da Guerra Fria decorrente de mísseis nucleares instalados pela:", o: [{t:"União Soviética em território cubano",c:true}, {t:"Estados Unidos em território mexicano",c:false}, {t:"China na Argentina",c:false}, {t:"Alemanha no Brasil",c:false}], pts: 3, exp: "EUA e URSS quase chegaram a um confronto nuclear direto durante a crise." },
                { id: "9ANO-HIS-M10", p: "O conflito do Vietnã terminou na década de 1970 com a vitória do:", o: [{t:"Vietnã do Norte e reunificação sob regime socialista",c:true}, {t:"Vietnã do Sul com apoio duradouro dos EUA",c:false}, {t:"França",c:false}, {t:"Divisão permanente em quatro países",c:false}], pts: 3, exp: "Após a retirada das tropas americanas, o Vietnã foi reunificado sob o socialismo." },
                { id: "9ANO-HIS-M11", p: "O Plano de Metas do presidente Juscelino Kubitschek tinha como lema propagandístico:", o: [{t:"50 anos de progresso em 5 anos de governo",c:true}, {t:"Ordem e Progresso para todos",c:false}, {t:"Brasil, ame-o ou deixe-o",c:false}, {t:"Trabalho e Justiça social",c:false}], pts: 3, exp: "O Plano focado em energia, transporte e industrialização prometia avançar 50 anos em 5." },
                { id: "9ANO-HIS-M12", p: "O Plano Marshall criado pelos EUA após a Segunda Guerra Mundial visava:", o: [{t:"Conceder ajuda financeira para a reconstrução dos países da Europa Ocidental",c:true}, {t:"Desenvolver bombas atômicas na América do Sul",c:false}, {t:"Criar a União Europeia",c:false}, {t:"Financiar o exército soviético",c:false}], pts: 3, exp: "O plano visava reconstruir a economia europeia e evitar o avanço do comunismo." },
                { id: "9ANO-HIS-M13", p: "A Guerra de Canudos (1896-1897), no sertão baiano, foi um movimento messiânico e comunitário liderado por:", o: [{t:"Antônio Conselheiro",c:true}, {t:"Padre Cícero",c:false}, {t:"Lampião",c:false}, {t:"Chico Rei",c:false}], pts: 3, exp: "Conselheiro atraiu milhares de sertanejos pobres, sendo destruído pelo exército." },
                { id: "9ANO-HIS-M14", p: "O Pacto Germânico-Soviético (Molotov-Ribbentrop) assinado em 1939 consistia em:", o: [{t:"Um acordo de não agressão entre a Alemanha Nazista e a União Soviética",c:true}, {t:"Uma aliança militar para atacar os EUA",c:false}, {t:"Um tratado de rendição da Alemanha",c:false}, {t:"A criação do Bloco Oriental",c:false}], pts: 3, exp: "Hitler e Stalin assinaram o pacto de não agressão que previa a divisão da Polônia." },
                { id: "9ANO-HIS-M15", p: "A campanha popular 'O Petróleo é Nosso' culminou na criação da estatal Petrobras em 1953 durante o governo de:", o: [{t:"Getúlio Vargas (2º governo)",c:true}, {t:"Eurico Gaspar Dutra",c:false}, {t:"Juscelino Kubitschek",c:false}, {t:"João Goulart",c:false}], pts: 3, exp: "Vargas sancionou a criação da Petrobras garantindo o monopólio estatal da extração." },
                { id: "9ANO-HIS-F16", p: "A Organização das Nações Unidas (ONU) foi criada em 1945, logo após a Segunda Guerra, com o objetivo de:", o: [{t:"Manter a paz e a segurança internacionais prevenindo novos conflitos mundiais",c:true}, {t:"Promover o comércio exclusivo de armas",c:false}, {t:"Dividir o mundo entre nações ricas",c:false}, {t:"Substituir os governos locais",c:false}], pts: 3, exp: "A ONU substituiu a Liga das Nações com o objetivo principal de manter a paz." },
                { id: "9ANO-HIS-M17", p: "A política externa norte-americana criada para conter a expansão do comunismo durante a Guerra Fria foi a:", o: [{t:"Doutrina Truman",c:true}, {t:"Doutrina Monroe",c:false}, {t:"Politica da Boa Vizinhança",c:false}, {t:"Destino Manifesto",c:false}], pts: 3, exp: "Truman comprometeu-se a apoiar nações livres contra a coerção soviética." },
                { id: "9ANO-HIS-M18", p: "A 'Marcha da Família com Deus pela Liberdade' realizada em março de 1964 consistiu em uma manifestação:", o: [{t:"Conservadora contra as Reformas de Base do presidente João Goulart",c:true}, {t:"Comunista favorável à reforma agrária",c:false}, {t:"Estudantil contra o regime militar",c:false}, {t:"De marinheiros exigindo aumentos",c:false}], pts: 3, exp: "Reuniu setores conservadores e a Igreja preparando o clima social para o golpe de 1964." },
                { id: "9ANO-HIS-M19", p: "O processo de independência das colônias europeias na África e Ásia acelerou-se principalmente após o fim da:", o: [{t:"Segunda Guerra Mundial",c:true}, {t:"Primeira Guerra Mundial",c:false}, {t:"Guerra Fria",c:false}, {t:"Revolução Francesa",c:false}], pts: 3, exp: "As potências coloniais europeias saíram enfraquecidas do conflito mundial." },
                { id: "9ANO-HIS-M20", p: "A Revolução Constitucionalista de 1932 em São Paulo foi um movimento armado que exigia de Getúlio Vargas:", o: [{t:"A promulgação de uma nova Constituição e o fim do governo provisório",c:true}, {t:"A volta do Imperador Dom Pedro II",c:false}, {t:"A abolição das leis trabalhistas",c:false}, {t:"A separação definitiva do Estado de SP",c:false}], pts: 3, exp: "Os paulistas exigiam a reconstitucionalização do país, alcançada em 1934." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-HIS-D01", p: "Os Planos Quinquenais implantados por Joseph Stalin na União Soviética a partir de 1928 focavam em:", o: [{t:"Industrialização pesada acelerada e coletivização forçada do campo",c:true}, {t:"Abertura ao capital privado estrangeiro no comércio livre",c:false}, {t:"Privatização de fazendas e incentivo ao consumo",c:false}, {t:"Restauração do czarismo",c:false}], pts: 4, exp: "Stalin eliminou a economia de mercado e impôs metas estatais rígidas na indústria e agricultura." },
                { id: "9ANO-HIS-D02", p: "A Intentona Comunista ocorrida no Brasil em 1935 foi organizada pela ANL (Aliança Nacional Libertadora) sob liderança de:", o: [{t:"Luís Carlos Prestes",c:true}, {t:"Plínio Salgado",c:false}, {t:"Oswaldo Aranha",c:false}, {t:"Carlos Lacerda",c:false}], pts: 4, exp: "Prestes liderou o levante frustrado contra o governo Vargas, que serviu de pretexto para maior repressão." },
                { id: "9ANO-HIS-D03", p: "O fictício 'Plano Cohen', divulgado pelo governo Vargas em 1937 para justificar o golpe do Estado Novo, denunciava:", o: [{t:"Uma suposta conspiração comunista para tomar o poder no Brasil",c:true}, {t:"Uma invasão iminente de tropas nazistas na Bahia",c:false}, {t:"Um plano de golpe organizado pela Marinha",c:false}, {t:"Uma revolta de cafeicultores paulistas",c:false}], pts: 4, exp: "Foi um documento forjado pelo capitão Olímpio Mourão para incitar o medo do comunismo." },
                { id: "9ANO-HIS-D04", p: "A 'Noite dos Cristais' (Kristallnacht) ocorrida na Alemanha em novembro de 1938 marcou:", o: [{t:"O início da violência física e destruição estatal organizada contra sinagogas e comércios judeus",c:true}, {t:"A assinatura da rendição alemã na 1ª Guerra",c:false}, {t:"O fim das perseguições nazistas",c:false}, {t:"A vitória de Hitler nas eleições presidenciais",c:false}], pts: 4, exp: "Pogrom violento que assinalou a escalada da perseguição nazista aos judeus." },
                { id: "9ANO-HIS-D05", p: "A Guerra do Contestado (1912-1916) envolveu disputas territoriais e sociais na fronteira entre Santa Catarina e Paraná motivadas por:", o: [{t:"Desapropriações de camponeses para construção de ferrovia por empresa americana e exploração de madeira",c:true}, {t:"Invasões de tropas argentinas buscando anexar o Sul",c:false}, {t:"Conflitos entre produtores de café e mineradores",c:false}, {t:"Revolta da população contra o fim da escravidão",c:false}], pts: 4, exp: "Milhares de posseiros messiânicos foram expulsos de suas terras para a passagem da Southern Brazil Lumber." },
                { id: "9ANO-HIS-D06", p: "O otimismo cultural e a modernização urbana que marcaram o governo JK no final dos anos 1950 ficaram conhecidos como:", o: [{t:"Anos Dourados e a consolidação da Bossa Nova",c:true}, {t:"Belle Époque Tropical",c:false}, {t:"Milagre Econômico",c:false}, {t:"Decada Perdida",c:false}], pts: 4, exp: "Período marcado pelo crescimento industrial, consumo de eletrodomésticos, Bossa Nova e o otimismo de Brasília." },
                { id: "9ANO-HIS-D07", p: "A Operação Condor, estruturada nas décadas de 1970 nas Américas, consistiu em:", o: [{t:"Uma rede clandestina de cooperação entre as ditaduras militares do Cone Sul para reprimir opositores",c:true}, {t:"Um plano econômico de ajuda e fomento dos EUA para a Amazônia",c:false}, {t:"Uma manobra militar soviética para invadir a América Central",c:false}, {t:"Uma aliança entre os países andinos para o livre comércio",c:false}], pts: 4, exp: "Troca de informações e ações repressivas coordenadas entre Brasil, Argentina, Chile, Uruguai, etc." },
                { id: "9ANO-HIS-D08", p: "A expressão 'Década Perdida' refere-se aos anos 1980 na América Latina devido à:", o: [{t:"Grave crise econômica caracterizada por hiperinflação, estagnação do PIB e crise da dívida externa",c:true}, {t:"Perda de territórios para potências europeias",c:false}, {t:"Ausência total de eleições em todos os países",c:false}, {t:"Redução drástica da população urbana",c:false}], pts: 4, exp: "A alta dos juros internacionais levou a América Latina a uma grave recessão e inflação galopante." },
                { id: "9ANO-HIS-D09", p: "As reformas introduzidas por Mikhail Gorbachev na URSS no fim dos anos 1980 foram a Glasnost e a Perestroika, significando:", o: [{t:"Transparência política (Glasnost) e reestruturação econômica (Perestroika)",c:true}, {t:"Censura total (Glasnost) e estatização absoluta (Perestroika)",c:false}, {t:"Fechamento do partido (Glasnost) e expansão militar (Perestroika)",c:false}, {t:"Aliança com a China (Glasnost) e fim do exército (Perestroika)",c:false}], pts: 4, exp: "Tentativas de modernizar o socialismo soviético que acabaram acelerando o fim da URSS." },
                { id: "9ANO-HIS-D10", p: "O movimento do 'Queremismo' surgido em 1945 defendia a:", o: [{t:"Permanência de Getúlio Vargas no poder com a convocação de uma Assembleia Constituinte",c:true}, {t:"Deposição imediata de Vargas e prisão dos seus ministros",c:false}, {t:"Entrada do Brasil no bloco socialista",c:false}, {t:"Restauração da República Velha",c:false}], pts: 4, exp: "Movimento popular focado no bordão 'Queremos Getúlio'." },
                { id: "9ANO-HIS-D11", p: "A Conferência de Bandung (1955) na Indonésia é historicamente relevante por ter sido:", o: [{t:"O marco inicial do Movimento dos Países Não Alinhados (Terceiro Mundo)",c:true}, {t:"A reunião que dividiu a Alemanha em duas zonas",c:false}, {t:"O tratado de paz que encerrou a Guerra do Vietnã",c:false}, {t:"A conferência onde se criou a União Europeia",c:false}], pts: 4, exp: "Países asiáticos e africanos afirmaram neutralidade frente ao conflito entre EUA e URSS." },
                { id: "9ANO-HIS-D12", p: "A crise financeira do 'Encilhamento', ocorrida nos primeiros anos da República brasileira, foi desencadeada por:", o: [{t:"Emissão descontrolada de moeda promovida por Ruy Barbosa gerando especulação e inflação",c:true}, {t:"Confisco dos depósitos bancários pela ditadura",c:false}, {t:"Queda drástica do preço da borracha amazônica",c:false}, {t:"Falta total de papel moeda em circulação",c:false}], pts: 4, exp: "A facilitação do crédito e emissão monetária gerou uma bolha especulativa na bolsa de valores." },
                { id: "9ANO-HIS-D13", p: "O Massacre da Floresta de Katyn (1940) envolveu a execução de milhares de oficiais poloneses por tropas:", o: [{t:"Soviéticas (NKVD)",c:true}, {t:"Nazistas alemãs",c:false}, {t:"Norte-americanas",c:false}, {t:"Fascistas italianas",c:false}], pts: 4, exp: "A URSS executou cerca de 22 mil oficiais e intelectuais poloneses em Katyn." },
                { id: "9ANO-HIS-D14", p: "O Convênio de Taubaté (1906) foi um acordo firmado entre os governadores do Sudeste para:", o: [{t:"Garantir o preço do café comprando os excedentes com empréstimos externos",c:true}, {t:"Proibir a produção de açúcar no Nordeste",c:false}, {t:"Abolir o trabalho imigrante nas lavouras",c:false}, {t:"Construir a primeira rodovia ligando SP ao RJ",c:false}], pts: 4, exp: "Política estatal de valorização artificial do café que socializava os prejuízos dos cafeicultores." },
                { id: "9ANO-HIS-D15", p: "A Coluna Prestes (1925-1927) foi um movimento tenentista que:", o: [{t:"Percorreu milhares de quilômetros pelo interior do Brasil denunciando a oligarquia da República Velha",c:true}, {t:"Tomou o poder no Rio de Janeiro e instaurou o comunismo",c:false}, {t:"Apoiou a candidatura de Washington Luís à presidência",c:false}, {t:"Combateu a vacinação obrigatória no Nordeste",c:false}], pts: 4, exp: "Coluna militar rebelde que marchou mais de 25.000 km propondo o voto secreto e reformas sociais." },
                { id: "9ANO-HIS-D16", p: "A Revolução dos Cravos (1974) em Portugal teve como consequência imediata:", o: [{t:"O fim da ditadura do Estado Novo salazarista e a aceleração da descolonização na África portuguesa",c:true}, {t:"A entrada de Portugal na Segunda Guerra Mundial",c:false}, {t:"A unificação de Portugal com a Espanha",c:false}, {t:"A implantação de um regime fascista",c:false}], pts: 4, exp: "O golpe militar democrático pôs fim ao Salazarismo e libertou colônias como Angola e Moçambique." },
                { id: "9ANO-HIS-D17", p: "O chamado 'Milagre Econômico' (1969-1973) durante o regime militar brasileiro caracterizou-se por:", o: [{t:"Alto crescimento do PIB acompanhado de forte concentração de renda e endividamento externo",c:true}, {t:"Distribuição de renda igualitária e redução da dívida externa",c:false}, {t:"Fim da inflação e erradicação do analfabetismo",c:false}, {t:"Estatização completa do setor agrícola",c:false}], pts: 4, exp: "O crescimento expressivo favoreceu a expansão industrial, mas aumentou a desigualdade social." },
                { id: "9ANO-HIS-D18", p: "O regime do Apartheid na África do Sul, oficializado em 1948, caracterizou-se por:", o: [{t:"Segregação racial oficializada por lei da minoria branca sobre a maioria negra",c:true}, {t:"Igualdade de direitos entre brancos e negros",c:false}, {t:"Ditadura comunista apoiada pela URSS",c:false}, {t:"Guerra civil entre protestantes e católicos",c:false}], pts: 4, exp: "SISTEMA de discriminação racial legalizada derrubado apenas nos anos 1990 sob liderança de Mandela." },
                { id: "9ANO-HIS-D19", p: "A Primeira Crise do Petróleo (1973) foi motivada por:", o: [{t:"Embargo e aumento drástico nos preços imposto pela OPEP devido à Guerra do Yom Kippur",c:true}, {t:"Esgotamento total das reservas mundiais de petróleo",c:false}, {t:"Invasão dos EUA aos poços de petróleo da Arábia Saudita",c:false}, {t:"Descobrimento de novas energias renováveis baratas",c:false}], pts: 4, exp: "Países árabes exportadores retiveram a produção em protesto ao apoio ocidental a Israel." },
                { id: "9ANO-HIS-D20", p: "O impeachment do presidente Fernando Collor de Mello em 1992 foi impulsionado pelo movimento jovem dos:", o: [{t:"Caras-Pintadas",c:true}, {t:"Tenentes",c:false}, {t:"Cabanos",c:false}, {t:"Integragralistas",c:false}], pts: 4, exp: "Estudantes foram às ruas com o rosto pintado exigindo o afastamento do presidente acusado de corrupção." }
        ],
        "Ciências": [
            // ==================== FÁCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-CIE-F01", p: "A partícula subatômica localizada no núcleo do átomo e que possui carga elétrica positiva é o:", o: [{t:"Próton",c:true}, {t:"Elétron",c:false}, {t:"Nêutron",c:false}, {t:"Fóton",c:false}], pts: 2, exp: "Prótons possuem carga positiva e ficam localizados no núcleo atômico." },
                { id: "9ANO-CIE-F02", p: "A partícula subatômica que orbita ao redor do núcleo e possui carga elétrica negativa é o:", o: [{t:"Elétron",c:true}, {t:"Próton",c:false}, {t:"Nêutron",c:false}, {t:"Quark",c:false}], pts: 2, exp: "Elétrons possuem carga negativa e situam-se na eletrosfera." },
                { id: "9ANO-CIE-F03", p: "A partícula subatômica presente no núcleo do átomo que não possui carga elétrica é o:", o: [{t:"Nêutron",c:true}, {t:"Próton",c:false}, {t:"Elétron",c:false}, {t:"Íon",c:false}], pts: 2, exp: "Os nêutrons possuem carga elétrica nula/neutra." },
                { id: "9ANO-CIE-F04", p: "A Tabela Periódica atual organiza os elementos químicos em ordem crescente de:", o: [{t:"Número atômico (Z)",c:true}, {t:"Massa atômica (A)",c:false}, {t:"Volume atômico",c:false}, {t:"Ano de descoberta",c:false}], pts: 2, exp: "Os elementos são dispostos sequencialmente pelo número atômico (quantidade de prótons)." },
                { id: "9ANO-CIE-F05", p: "Quais são os três estados físicos fundamentais da matéria?", o: [{t:"Sólido, líquido e gasoso",c:true}, {t:"Fogo, terra e ar",c:false}, {t:"Plasma, vapor e gelo",c:false}, {t:"Atomizado, denso e expansivo",c:false}], pts: 2, exp: "A matéria apresenta-se comumente nos estados sólido, líquido e gasoso." },
                { id: "9ANO-CIE-F06", p: "A mudança direta do estado sólido para o estado gasoso sem passar pelo líquido é a:", o: [{t:"Sublimação",c:true}, {t:"Evaporação",c:false}, {t:"Condensação",c:false}, {t:"Fusão",c:false}], pts: 2, exp: "Sublimação é a transição direta entre o estado sólido e o gasoso." },
                { id: "9ANO-CIE-F07", p: "A unidade de medida de força no Sistema Internacional de Unidades (SI) é o:", o: [{t:"Newton (N)",c:true}, {t:"Joule (J)",c:false}, {t:"Watt (W)",c:false}, {t:"Pascal (Pa)",c:false}], pts: 2, exp: "Força é medida em Newtons (N) no sistema internacional." },
                { id: "9ANO-CIE-F08", p: "Como se calcula a velocidade média de um objeto em movimento?", o: [{t:"Divisão do deslocamento pelo tempo (Δs / Δt)",c:true}, {t:"Multiplicação da massa pela aceleração",c:false}, {t:"Soma da distância com o tempo",c:false}, {t:"Divisão da força pela área",c:false}], pts: 2, exp: "Velocidade média v = Δs / Δt." },
                { id: "9ANO-CIE-F09", p: "O cientista considerado o 'Pai da Genética' por suas pesquisas com ervilhas foi:", o: [{t:"Gregor Mendel",c:true}, {t:"Charles Darwin",c:false}, {t:"Jean-Baptiste Lamarck",c:false}, {t:"Isaac Newton",c:false}], pts: 2, exp: "Mendel descobriu os princípios básicos da hereditariedade." },
                { id: "9ANO-CIE-F10", p: "A unidade fundamental da hereditariedade contida no DNA responsável por uma característica é o:", o: [{t:"Gene",c:true}, {t:"Cromossomo",c:false}, {t:"Ribossomo",c:false}, {t:"Gameta",c:false}], pts: 2, exp: "Um gene é um trecho de DNA codificante de características hereditárias." },
                { id: "9ANO-CIE-F11", p: "A teoria evolucionista que propôs a Seleção Natural como mecanismo principal da evolução foi formulada por:", o: [{t:"Charles Darwin",c:true}, {t:"Lamarck",c:false}, {t:"Mendel",c:false}, {t:"Louis Pasteur",c:false}], pts: 2, exp: "Darwin publicou 'A Origem das Espécies' fundamentando a seleção natural." },
                { id: "9ANO-CIE-F12", p: "A hipótese do 'Uso e Desuso' e da 'Transmissão dos Caracteres Adquiridos' foi proposta por:", o: [{t:"Lamarck",c:true}, {t:"Darwin",c:false}, {t:"Linneu",c:false}, {t:"Mendel",c:false}], pts: 2, exp: "Lamarck acreditava que órgãos desenvolvidos pelo uso seriam transmitidos aos descendentes." },
                { id: "9ANO-CIE-F13", p: "No Sistema Internacional (SI), a massa de um corpo é medida em:", o: [{t:"Quilogramas (kg)",c:true}, {t:"Newtons (N)",c:false}, {t:"Lítros (L)",c:false}, {t:"Metros (m)",c:false}], pts: 2, exp: "A unidade padrão de massa no SI é o quilograma." },
                { id: "9ANO-CIE-F14", p: "A fórmula química da molécula de gás oxigênio vital para a nossa respiração é:", o: [{t:"O2",c:true}, {t:"CO2",c:false}, {t:"H2O",c:false}, {t:"N2",c:false}], pts: 2, exp: "O2 é o gás oxigênio diatômico presente na atmosfera." },
                { id: "9ANO-CIE-F15", p: "A fórmula química da substância água é:", o: [{t:"H2O",c:true}, {t:"CO2",c:false}, {t:"NaCl",c:false}, {t:"H2SO4",c:false}], pts: 2, exp: "Formada por dois átomos de hidrogênio e um de oxigênio." },
                { id: "9ANO-CIE-F16", p: "Os átomos buscam realizar ligações químicas para alcançar a estabilidade eletrônica semelhante à dos:", o: [{t:"Gases nobres",c:true}, {t:"Metais alcalinos",c:false}, {t:"Halogênios",c:false}, {t:"Ametais",c:false}], pts: 2, exp: "A regra do octeto afirma que os átomos buscam 8 elétrons na camada de valência como os gases nobres." },
                { id: "9ANO-CIE-F17", p: "Qual é a estrela central responsável por fornecer energia e luz ao nosso Sistema Solar?", o: [{t:"Sol",c:true}, {t:"Alfa Centauri",c:false}, {t:"Betelgeuse",c:false}, {t:"Lua",c:false}], pts: 2, exp: "O Sol é a estrela em torno da qual orbitam os planetas do sistema solar." },
                { id: "9ANO-CIE-F18", p: "A Primeira Lei de Newton também é amplamente conhecida como o princípio da:", o: [{t:"Inércia",c:true}, {t:"Ação e Reação",c:false}, {t:"Gravitação",c:false}, {t:"Conservação de energia",c:false}], pts: 2, exp: "Inércia é a tendência dos corpos de manter seu estado de repouso ou movimento retilíneo uniforme." },
                { id: "9ANO-CIE-F19", p: "Um corpo em movimento que possui aceleração está alterando sua:", o: [{t:"Velocidade ao longo do tempo",c:true}, {t:"Massa ao longo do tempo",c:false}, {t:"Carga elétrica",c:false}, {t:"Densidade",c:false}], pts: 2, exp: "Aceleração é a taxa de variação da velocidade em relação ao tempo." },
                { id: "9ANO-CIE-F20", p: "As ondas sonoras necessitam obrigatoriamente de um meio material para se propagar, sendo classificadas como ondas:", o: [{t:"Mecânicas",c:true}, {t:"Eletromagnéticas",c:false}, {t:"Luminosas",c:false}, {t:"Transversais no vácuo",c:false}], pts: 2, exp: "Ondas mecânicas dependem de matéria para propagar vibrações." },

            // ==================== MÉDIAS (20 QUESTAÇÕES) ====================
                { id: "9ANO-CIE-M01", p: "A Lei de Lavoisier (Lei da Conservação das Massas) em reações em sistema fechado estabelece que:", o: [{t:"A soma das massas dos reagentes é igual à soma das massas dos produtos",c:true}, {t:"A massa dos produtos é sempre maior que a dos reagentes",c:false}, {t:"A massa desaparece durante a reação",c:false}, {t:"Os átomos são destruídos na reação",c:false}], pts: 3, exp: "'Na natureza nada se cria, nada se perde, tudo se transforma.'" },
                { id: "9ANO-CIE-M02", p: "A ligação química que ocorre com a transferência definitiva de elétrons de um metal para um ametal é a:", o: [{t:"Ligação iônica",c:true}, {t:"Ligação covalente",c:false}, {t:"Ligação metálica",c:false}, {t:"Ponte de hidrogênio",c:false}], pts: 3, exp: "Ligação iônica ocorre por atração eletrostática após a transferência de elétrons." },
                { id: "9ANO-CIE-M03", p: "A ligação química na qual os átomos compartilham pares de elétrons entre si é a:", o: [{t:"Ligação covalente",c:true}, {t:"Ligação iônica",c:false}, {t:"Ligação metálica",c:false}, {t:"Ligação iônica dupla",c:false}], pts: 3, exp: "Acontece principalmente entre ametais através do compartilhamento de elétrons." },
                { id: "9ANO-CIE-M04", p: "A Segunda Lei de Newton estabelece que a força resultante aplicada a um corpo é igual ao produto de sua:", o: [{t:"Massa pela aceleração (F = m * a)",c:true}, {t:"Velocidade pelo tempo",c:false}, {t:"Massa pela velocidade",c:false}, {t:"Energia pela distância",c:false}], pts: 3, exp: "F = m x a exprime a relação fundamental da dinâmica." },
                { id: "9ANO-CIE-M05", p: "A Terceira Lei de Newton (Ação e Reação) afirma que para toda força de ação existe uma reação de:", o: [{t:"Mesmo módulo, mesma direção e sentido oposto",c:true}, {t:"Módulo maior e mesmo sentido",c:false}, {t:"Direção diferente e mesmo sentido",c:false}, {t:"Módulo nulo",c:false}], pts: 3, exp: "Forças de ação e reação atuam em corpos diferentes, com igual intensidade e sentidos opostos." },
                { id: "9ANO-CIE-M06", p: "Qual o valor aproximado da aceleração da gravidade na superfície da Terra?", o: [{t:"9,8 m/s²",c:true}, {t:"1,6 m/s²",c:false}, {t:"300.000 m/s²",c:false}, {t:"0 m/s²",c:false}], pts: 3, exp: "A aceleração da gravidade terrestre é aproximadamente 9,8 m/s² (frequentemente arredondada para 10 m/s²)." },
                { id: "9ANO-CIE-M07", p: "O número atômico (Z) de um átomo neutro é sempre numericamente igual à quantidade de:", o: [{t:"Prótons no núcleo",c:true}, {t:"Nêutrons no núcleo",c:false}, {t:"Prótons somados aos nêutrons",c:false}, {t:"Camadas eletrônicas",c:false}], pts: 3, exp: "Z representa o número de prótons, definindo o elemento químico." },
                { id: "9ANO-CIE-M08", p: "Átomos que possuem o mesmo número de prótons (número atômico), mas diferentes números de nêutrons, são chamados de:", o: [{t:"Isótopos",c:true}, {t:"Isóbaros",c:false}, {t:"Isótonos",c:false}, {t:"Isômeros",c:false}], pts: 3, exp: "Isótopos pertencem ao mesmo elemento e possuem o mesmo Z." },
                { id: "9ANO-CIE-M09", p: "Na 1ª Lei de Mendel, o cruzamento entre dois indivíduos heterozigotos (Aa x Aa) gera uma proporção genotípica de:", o: [{t:"1 AA : 2 Aa : 1 aa",c:true}, {t:"3 AA : 1 aa",c:false}, {t:"100% Aa",c:false}, {t:"1 Aa : 1 aa",c:false}], pts: 3, exp: "O quadro de Punnett resulta em 25% AA, 50% Aa e 25% aa." },
                { id: "9ANO-CIE-M10", p: "O conjunto de características físicas e biológicas observáveis de um indivíduo resultante da interação do genótipo com o meio é o:", o: [{t:"Fenótipo",c:true}, {t:"Genótipo",c:false}, {t:"Cariótipo",c:false}, {t:"Genoma",c:false}], pts: 3, exp: "Fenótipo = Genótipo + Influência do Meio Ambiente." },
                { id: "9ANO-CIE-M11", p: "A quantidade de oscilações completas efetuadas por uma onda em um intervalo de um segundo é medida em:", o: [{t:"Hertz (Hz)",c:true}, {t:"Metros (m)",c:false}, {t:"Segundos (s)",c:false}, {t:"Joules (J)",c:false}], pts: 3, exp: "Frequência é medida em Hertz (Hz) no SI." },
                { id: "9ANO-CIE-M12", p: "Qual é a velocidade de propagação da luz no vácuo?", o: [{t:"300.000 km/s",c:true}, {t:"340 m/s",c:false}, {t:"1.000 km/h",c:false}, {t:"100.000 m/s",c:false}], pts: 3, exp: "A velocidade da luz no vácuo é de c ≈ 3 x 10⁸ m/s ou 300.000 km/s." },
                { id: "9ANO-CIE-M13", p: "Uma solução homogênea caracterizada por apresentar uma única fase visual uniforme é exemplificada por:", o: [{t:"Água totalmente misturada com sal dissolvido",c:true}, {t:"Água e óleo",c:false}, {t:"Água e areia",c:false}, {t:"Granito",c:false}], pts: 3, exp: "Misturas homogêneas possuem aspecto uniforme de fase única." },
                { id: "9ANO-CIE-M14", p: "O método físico de separação de misturas homogêneas baseado nos diferentes pontos de ebulição dos líquidos é a:", o: [{t:"Destilação fracionada",c:true}, {t:"Filtração",c:false}, {t:"Decantação",c:false}, {t:"Catação",c:false}], pts: 3, exp: "Usada na indústria para separar componentes do petróleo em torres de fracionamento." },
                { id: "9ANO-CIE-M15", p: "O modelo atômico que comparava o átomo a um 'pudim de passas' com cargas negativas encravadas em massa positiva foi criado por:", o: [{t:"Thomson",c:true}, {t:"Dalton",c:false}, {t:"Rutherford",c:false}, {t:"Bohr",c:false}], pts: 3, exp: "J.J. Thomson descobriu o elétron e propôs o modelo de carga positiva com elétrons encravados." },
                { id: "9ANO-CIE-M16", p: "O experimento com a lâmina de ouro que provou a existência do núcleo atômico denso e positivo foi realizado por:", o: [{t:"Rutherford",c:true}, {t:"Dalton",c:false}, {t:"Thomson",c:false}, {t:"Chadwick",c:false}], pts: 3, exp: "Rutherford concluiu que o átomo é em grande parte espaço vazio com núcleo central positivo." },
                { id: "9ANO-CIE-M17", p: "A integração dos conceitos de seleção natural de Darwin com as descobertas da genética e mutações é chamada de:", o: [{t:"Neodarwinismo (Teoria Sintética da Evolução)",c:true}, {t:"Lamarckismo",c:false}, {t:"Criacionismo",c:false}, {t:"Fixismo",c:false}], pts: 3, exp: "O neodarwinismo explica a variabilidade genética através de mutações e recombinação." },
                { id: "9ANO-CIE-M18", p: "Alterações espontâneas no código genético do DNA que introduzem novas variações em uma espécie são chamadas de:", o: [{t:"Mutações",c:true}, {t:"Clonagens",c:false}, {t:"Adaptações comportamentais",c:false}, {t:"Transcrições",c:false}], pts: 3, exp: "Mutações são a fonte primária de nova variabilidade genética nas populações." },
                { id: "9ANO-CIE-M19", p: "Como se calcula a Força Peso de um corpo na superfície terrestre?", o: [{t:"Multiplicando a massa pela gravidade (P = m * g)",c:true}, {t:"Dividindo a massa pela gravidade",c:false}, {t:"Multiplicando a velocidade pela massa",c:false}, {t:"Somando a massa com a altura",c:false}], pts: 3, exp: "Peso P = m x g, sendo uma força atrativa direcionada ao centro da Terra." },
                { id: "9ANO-CIE-M20", p: "Um automóvel percorre uma distância total de 120 km em um intervalo de tempo de 2 horas. Sua velocidade média é:", o: [{t:"60 km/h",c:true}, {t:"240 km/h",c:false}, {t:"100 km/h",c:false}, {t:"50 km/h",c:false}], pts: 3, exp: "Velocidade média = 120 km / 2 h = 60 km/h." },

            // ==================== DIFÍCEIS (20 QUESTAÇÕES) ====================
                { id: "9ANO-CIE-D01", p: "Balanceando a equação de síntese Fe + O2 -> Fe2O3, os coeficientes estequiométricos inteiros mínimos são:", o: [{t:"4 Fe + 3 O2 -> 2 Fe2O3",c:true}, {t:"2 Fe + O2 -> Fe2O3",c:false}, {t:"1 Fe + 2 O2 -> 1 Fe2O3",c:false}, {t:"2 Fe + 3 O2 -> 2 Fe2O3",c:false}], pts: 4, exp: "Contando os átomos: 4 de Fe e 6 de O em ambos os lados da equação." },
                { id: "9ANO-CIE-D02", p: "Um carro partindo do repouso acelera uniformemente a 2 m/s² durante 5 segundos. Qual sua velocidade final?", o: [{t:"10 m/s",c:true}, {t:"25 m/s",c:false}, {t:"7 m/s",c:false}, {t:"2,5 m/s",c:false}], pts: 4, exp: "v = v0 + a t => v = 0 + (2 x 5) = 10 m/s." },
                { id: "9ANO-CIE-D03", p: "No cruzamento de dois indivíduos heterozigotos para o albinismo (Aa x Aa), qual a probabilidade do casal ter um filho albino (aa)?", o: [{t:"25% (1/4)",c:true}, {t:"50% (1/2)",c:false}, {t:"75% (3/4)",c:false}, {t:"100%",c:false}], pts: 4, exp: "Cruzamento Aa x Aa gera: AA, Aa, Aa, aa. O fenótipo albino é aa (1 em 4 = 25%)." },
                { id: "9ANO-CIE-D04", p: "Em um heredograma, a representação de um indivíduo do sexo masculino afetado por uma anomalia é feita por:", o: [{t:"Um quadrado totalmente preenchido",c:true}, {t:"Um círculo em branco",c:false}, {t:"Um quadrado em branco",c:false}, {t:"Um círculo preenchido",c:false}], pts: 4, exp: "Quadrados representam homens e figuras preenchidas indicam afetados." },
                { id: "9ANO-CIE-D05", p: "O modelo atômico que introduziu o conceito de órbitas quantizadas com níveis de energia para os elétrons foi proposto por:", o: [{t:"Niels Bohr",c:true}, {t:"John Dalton",c:false}, {t:"J.J. Thomson",c:false}, {t:"Ernest Rutherford",c:false}], pts: 4, exp: "Bohr aprimorou o modelo de Rutherford inserindo os níveis discretos de energia." },
                { id: "9ANO-CIE-D06", p: "Qual a equação fundamental da ondulatória que relaciona velocidade (v), comprimento de onda (λ) e frequência (f)?", o: [{t:"v = λ * f",c:true}, {t:"f = v * λ",c:false}, {t:"λ = v * f",c:false}, {t:"v = f / λ",c:false}], pts: 4, exp: "A velocidade da onda é o produto do comprimento de onda pela frequência (v = λ f)." },
                { id: "9ANO-CIE-D07", p: "Uma onda possui frequência de 100 Hz e propaga-se com velocidade de 300 m/s. Qual o seu comprimento de onda (λ)?", o: [{t:"3 metros",c:true}, {t:"30.000 metros",c:false}, {t:"0,33 metros",c:false}, {t:"30 metros",c:false}], pts: 4, exp: "v = λ f => 300 = λ x 100 => λ = 3 metros." },
                { id: "9ANO-CIE-D08", p: "A Teoria da Relatividade Restrita, que demonstrou a equivalência entre massa e energia (E = m c²), foi publicada por:", o: [{t:"Albert Einstein",c:true}, {t:"Isaac Newton",c:false}, {t:"Galileu Galilei",c:false}, {t:"Max Planck",c:false}], pts: 4, exp: "Einstein formulou a relação entre energia e massa em 1905." },
                { id: "9ANO-CIE-D09", p: "Um bloco de 5 kg é empurrado por uma força de 20 N para a direita e freado por um atrito de 5 N. Qual sua aceleração?", o: [{t:"3 m/s²",c:true}, {t:"4 m/s²",c:false}, {t:"5 m/s²",c:false}, {t:"1 m/s²",c:false}], pts: 4, exp: "Fres = 20 - 5 = 15 N. Aceleração a = Fres / m = 15 / 5 = 3 m/s²." },
                { id: "9ANO-CIE-D10", p: "Átomos de elementos químicos diferentes que possuem o mesmo número de massa (A), mas números atômicos (Z) distintos são:", o: [{t:"Isóbaros",c:true}, {t:"Isótopos",c:false}, {t:"Isótonos",c:false}, {t:"Isoeletrônicos",c:false}], pts: 4, exp: "Isóbaros têm o mesmo número de massa A." },
                { id: "9ANO-CIE-D11", p: "Mimetismo e camuflagem são estratégias evolutivas resultantes da seleção natural que garantem:", o: [{t:"Maior probabilidade de sobrevivência e reprodução no ambiente",c:true}, {t:"Transformação instantânea de genes do indivíduo",c:false}, {t:"Aumento no número de cromossomos",c:false}, {t:"Imunidade contra toxinas químicas",c:false}], pts: 4, exp: "Aumentam o valor adaptativo do indivíduo reduzindo a predação." },
                { id: "9ANO-CIE-D12", p: "Na Tabela Periódica, o raio atômico dos elementos varia e cresce no sentido:", o: [{t:"De cima para baixo nas famílias e da direita para a esquerda nos períodos",c:true}, {t:"De baixo para cima nas famílias e da esquerda para a direita nos períodos",c:false}, {t:"De forma totalmente aleatória",c:false}, {t:"Exclusivamente da esquerda para a direita",c:false}], pts: 4, exp: "O raio cresce com o aumento das camadas (para baixo) e menor carga nuclear efetiva (para esquerda)." },
                { id: "9ANO-CIE-D13", p: "Em um ecossistema equilibrado, a transferência de energia ao longo das cadeias alimentares é caracterizada por ser:", o: [{t:"Unidirecional e decrescente a cada nível trófico",c:true}, {t:"Cíclica e infinita",c:false}, {t:"Crescente dos produtores aos decompositores",c:false}, {t:"Bidirecional entre predador e presa",c:false}], pts: 4, exp: "A energia dissipa-se na forma de calor em cada nível, diminuindo do produtor ao consumidor final." },
                { id: "9ANO-CIE-D14", p: "A energia mecânica total de um sistema conservativo é dada pela soma da:", o: [{t:"Energia cinética com a energia potencial",c:true}, {t:"Energia térmica com a energia luminosa",c:false}, {t:"Energia eólica com a energia química",c:false}, {t:"Energia elétrica com a energia atômica",c:false}], pts: 4, exp: "Em sistemas conservativos: Emec = Ec + Ep." },
                { id: "9ANO-CIE-D15", p: "Qual o trabalho (W) realizado por uma força constante de 50 N para deslocar um objeto por 4 metros na mesma direção da força?", o: [{t:"200 Joules",c:true}, {t:"12,5 Joules",c:false}, {t:"54 Joules",c:false}, {t:"400 Joules",c:false}], pts: 4, exp: "Trabalho W = F x d = 50 x 4 = 200 J." },
                { id: "9ANO-CIE-D16", p: "A separação dos cromossomos homólogos é um evento marcante que ocorre especificamente na:", o: [{t:"Anáfase I da Meiose",c:true}, {t:"Anáfase II da Meiose",c:false}, {t:"Metáfase da Mitose",c:false}, {t:"Prófase da Mitose",c:false}], pts: 4, exp: "Na Anáfase I da meiose ocorre a separação dos pares de homólogos." },
                { id: "9ANO-CIE-D17", p: "A transferência de calor que pode ocorrer no vácuo através de ondas eletromagnéticas (como a luz solar) é a:", o: [{t:"Irradiação térmica",c:true}, {t:"Condução térmica",c:false}, {t:"Convecção térmica",c:false}, {t:"Atrito térmico",c:false}], pts: 4, exp: "A radiação infravermelha/eletromagnética se propaga sem necessidade de meio material." },
                { id: "9ANO-CIE-D18", p: "Ao realizar um cruzamento-teste de um indivíduo dominante com um recessivo (aa), se 100% da prole for dominante, o genótipo testado era:", o: [{t:"Homozigoto dominante (AA)",c:true}, {t:"Heterozigoto (Aa)",c:false}, {t:"Homozigoto recessivo (aa)",c:false}, {t:"Mutante estéril",c:false}], pts: 4, exp: "AA x aa resulta em 100% Aa (fenótipo dominante)." },
                { id: "9ANO-CIE-D19", p: "Um elemento químico que apresenta distribuição eletrônica 1s² 2s² 2p⁶ 3s² 3p⁵ possui número atômico igual a:", o: [{t:"17 (Cloro)",c:true}, {t:"15 (Fósforo)",c:false}, {t:"18 (Argônio)",c:false}, {t:"35 (Bromo)",c:false}], pts: 4, exp: "Somando os elétrons: 2 + 2 + 6 + 2 + 5 = 17." },
                { id: "9ANO-CIE-D20", p: "O Teorema do Impulso afirma que a variação da quantidade de movimento (momento linear) de um corpo é igual ao:", o: [{t:"Impulso da força resultante exercida sobre ele",c:true}, {t:"Trabalho total realizado pelo corpo",c:false}, {t:"Produto da massa pela velocidade inicial",c:false}, {t:"Dobro da energia cinética acumulada",c:false}], pts: 4, exp: "I = Δp, ou seja, Impulso é igual à variação da quantidade de movimento." }
        ]
    }
};